/** 待定教师：To Be Confirmed；可占位安排并生效，后续替换为真实教师；不参与授课确认（默认已确认） */
const OFFERING_TBC_TEACHER_STAFF_ID = 'TBC';
const OFFERING_TBC_TEACHER_NAME = 'TBC';
const OFFERING_TBC_TEACHER_DISPLAY = 'TBC';

function isOfferingTbcTeacher(staffIdOrTeacher) {
  const id = typeof staffIdOrTeacher === 'object' && staffIdOrTeacher
    ? String(staffIdOrTeacher.staffId || '').trim()
    : String(staffIdOrTeacher || '').trim();
  return id.toUpperCase() === OFFERING_TBC_TEACHER_STAFF_ID;
}

function getOfferingTbcTeacherPickerEntry() {
  return {
    key: `${OFFERING_TBC_TEACHER_STAFF_ID}|tbc`,
    staffId: OFFERING_TBC_TEACHER_STAFF_ID,
    name: OFFERING_TBC_TEACHER_NAME,
    teacherType: 'TBC',
    gender: '—',
    departmentCode: '',
    isTbc: true
  };
}

function formatOfferingTeacherNameForDisplay(teacherOrStaffId, fallbackName = '') {
  if (isOfferingTbcTeacher(teacherOrStaffId)) return OFFERING_TBC_TEACHER_DISPLAY;
  if (typeof teacherOrStaffId === 'object' && teacherOrStaffId) {
    return teacherOrStaffId.name || teacherOrStaffId.staffId || fallbackName || '—';
  }
  return fallbackName || String(teacherOrStaffId || '') || '—';
}

function ensureOfferingTbcInTeacherPickerPool(pool) {
  if (!Array.isArray(pool)) return pool;
  if (pool.some(t => isOfferingTbcTeacher(t))) return pool;
  pool.unshift(getOfferingTbcTeacherPickerEntry());
  return pool;
}

function matchesOfferingTbcTeacherSearch(query) {
  const q = String(query || '').trim().toLowerCase();
  if (!q) return true;
  return ['tbc', '待确认', 'to be confirmed', '待定'].some(token => token.includes(q) || q.includes(token));
}

/** 开课学院内教师：由教师类型（teacherType）映射主讲/助教；非开课学院教师为 Support */
function resolveTeacherTeachingRoleFromType(teacherType) {
  const code = String(teacherType || '').trim();
  if (!code) return '主讲';
  if (code === 'TBC') return '主讲';
  if (code.startsWith('RE')) return '助教';
  // if (code === 'PT' || code.startsWith('IN')) return 'Support'; // 原仅按类型判 Support，改优先按是否开课学院
  if (code.startsWith('AC') || code.startsWith('AD')) return '主讲';
  return '主讲';
}

function resolveTeacherTeachingRole(staffId, teacherType) {
  if (teacherType) return resolveTeacherTeachingRoleFromType(teacherType);
  const pick = buildMockTeacherPickerPool().find(t => t.staffId === staffId);
  return resolveTeacherTeachingRoleFromType(pick?.teacherType);
}

function resolveTeacherTeachingRoleForSection(sec, teacher) {
  const offeringUnit = resolveMajorOfferingSectionOfferingUnit(sec);
  const poolPick = buildMockTeacherPickerPool().find(p => p.staffId === teacher?.staffId);
  const departmentCode = teacher?.departmentCode || poolPick?.departmentCode || '';
  if (offeringUnit && departmentCode && departmentCode !== offeringUnit) {
    return 'Support';
  }
  const teacherType = teacher?.teacherType || poolPick?.teacherType || '';
  return resolveTeacherTeachingRoleFromType(teacherType);
}

function enrichGroupAssignFormTeacher(t, sec) {
  if (isOfferingTbcTeacher(t)) {
    return {
      ...t,
      staffId: OFFERING_TBC_TEACHER_STAFF_ID,
      name: OFFERING_TBC_TEACHER_NAME,
      teacherType: 'TBC',
      departmentCode: '',
      role: '主讲',
      isCoordinator: false,
      isTbc: true
    };
  }
  const poolPick = buildMockTeacherPickerPool().find(p => p.staffId === t?.staffId);
  const teacherType = t?.teacherType || poolPick?.teacherType || '';
  const departmentCode = t?.departmentCode || poolPick?.departmentCode || '';
  return {
    ...t,
    teacherType,
    departmentCode,
    // role: resolveTeacherTeachingRoleFromType(teacherType) // 原仅按教师类型，改结合开课学院
    role: sec ? resolveTeacherTeachingRoleForSection(sec, { staffId: t?.staffId, teacherType, departmentCode }) : resolveTeacherTeachingRoleFromType(teacherType),
    isCoordinator: !!t?.isCoordinator
  };
}

function getGroupAssignTeacherDisplayRole(t, sec) {
  if (sec) return resolveTeacherTeachingRoleForSection(sec, t);
  return t?.role || resolveTeacherTeachingRole(t?.staffId, t?.teacherType) || '—';
}

function isGroupAssignTeacherSupport(sec, teacher) {
  if (!sec || !teacher) return false;
  return resolveTeacherTeachingRoleForSection(sec, teacher) === 'Support';
}

function formatGroupAssignTeacherSupportDisplay(sec, teacher) {
  return isGroupAssignTeacherSupport(sec, teacher) ? '是' : '否';
}

function normalizeMajorOfferingSupportHistory(val) {
  if (val === 'Y' || val === 'yes') return 'Y';
  if (val === 'N' || val === 'no') return 'N';
  return 'N';
}

const MAJOR_OFFERING_SUPPORT_HISTORY_TIP =
  '来自「特殊课程设置」的 Support 历史（Y/N）：该课历史上是否有过 Support；未在特殊课程设置中维护的课号为 N';

function formatMajorOfferingSupportHistoryDisplay(sec) {
  if (sec?.code && typeof resolveSpecialCourseSupportHistory === 'function') {
    return resolveSpecialCourseSupportHistory(sec.code);
  }
  return normalizeMajorOfferingSupportHistory(sec?.supportHistory);
}

function getOfferingSectionCategoryDisplay(sec) {
  const stored = String(sec?.category || '').trim();
  if (stored && stored !== '专业课' && stored !== '—') return stored;
  const codeNorm = typeof normalizeOfferingCourseCode === 'function'
    ? normalizeOfferingCourseCode(sec?.code)
    : String(sec?.code || '').trim().toUpperCase();
  const cat = (Array.isArray(COURSE_CATALOG) ? COURSE_CATALOG : []).find(c => c.id === sec?.catalogId)
    || (codeNorm
      ? (Array.isArray(COURSE_CATALOG) ? COURSE_CATALOG : []).find(c =>
        (typeof normalizeOfferingCourseCode === 'function'
          ? normalizeOfferingCourseCode(c.code)
          : String(c.code || '').trim().toUpperCase()) === codeNorm
      )
      : null);
  const fromCat = String(cat?.classification || '').trim();
  if (fromCat) return fromCat;
  if (sec?.offeringType === 'ge') return 'General Elective';
  if (stored && stored !== '—') return stored;
  return '—';
}

function collectMajorOfferingSectionAssignedTeachers(sec) {
  const seen = new Set();
  const teachers = [];
  const pushTeacher = raw => {
    if (!raw?.staffId || seen.has(raw.staffId)) return;
    seen.add(raw.staffId);
    teachers.push(enrichGroupAssignFormTeacher(raw, sec));
  };
  (sec?.teacherAssignments || []).forEach(pushTeacher);
  (sec?.groupAssignments || []).forEach(row => {
    (row.teachers || []).forEach(pushTeacher);
    if (row.staffId) {
      pushTeacher({
        staffId: row.staffId,
        name: row.teacher,
        teacherType: row.teacherType,
        departmentCode: row.departmentCode
      });
    }
  });
  return teachers;
}

function collectMajorOfferingSectionTaskArrangementTeachers(sec) {
  const seen = new Set();
  const teachers = [];
  const pushTeacher = raw => {
    if (!raw?.staffId || seen.has(raw.staffId)) return;
    seen.add(raw.staffId);
    teachers.push(enrichGroupAssignFormTeacher(raw, sec));
  };
  (sec?.groupAssignments || []).forEach(row => {
    (row.teachers || []).forEach(pushTeacher);
    if (row.staffId) {
      pushTeacher({
        staffId: row.staffId,
        name: row.teacher,
        teacherType: row.teacherType,
        departmentCode: row.departmentCode
      });
    }
  });
  return teachers;
}

function getMajorOfferingSectionSupportColleges(sec) {
  const fromTeachers = collectMajorOfferingSectionAssignedTeachers(sec)
    .filter(t => isGroupAssignTeacherSupport(sec, t))
    .map(t => t.departmentCode)
    .filter(Boolean);
  const applied = getMajorOfferingSectionSupportUnits(sec);
  return [...new Set([...applied, ...fromTeachers])];
}

function formatMajorOfferingSupportCollegeDisplay(sec) {
  const codes = getMajorOfferingSectionSupportColleges(sec);
  return codes.length ? codes.join('、') : '—';
}

/** 任务安排列表：已安排授课教师姓名（去重） */
function formatMajorOfferingSectionTeachersDisplay(sec) {
  const names = collectMajorOfferingSectionTaskArrangementTeachers(sec)
    .map(t => String(t?.name || '').trim())
    .filter(Boolean);
  return names.length ? [...new Set(names)].join('、') : '—';
}
