/** 课程班字段修改记录（任务安排「修改记录」新窗口） */
const SECTION_CHANGE_LOG_POPUP_STORAGE_KEY = 'pyfa-scl-popup-bootstrap';
const SECTION_CHANGE_TYPE_CREATE = '新增';
const SECTION_CHANGE_TYPE_UPDATE = '编辑';
const SECTION_CHANGE_TYPE_DELETE = '删除';
const SECTION_CHANGE_TYPE_IMPORT = '导入';
let sectionChangeLogStore = [];
let sectionChangeLogFocusSectionId = '';
let sectionChangeLogOpenedAsPopup = false;

function formatSectionChangeLogClassName(sec) {
  if (!sec) return '—';
  const base = sec.name || sec.courseName || sec.code || '课程班';
  const group = (sec.groups || [])[0];
  if (group?.name) return formatMajorOfferingGroupName(base, group.name);
  if (sec.className) return String(sec.className);
  return String(base);
}

function formatSectionChangeLogProgrammeName(sec) {
  if (!sec) return '—';
  const metas = typeof getSectionLineMetas === 'function' ? getSectionLineMetas(sec) : [];
  const programmeKey = sec.programmeKey || metas[0]?.programmeKey || '';
  const p = PROGRAMMES[programmeKey];
  const progName = p?.name || getSectionMergedProgrammeDisplayFull(sec);
  const intake = sec.intake || metas[0]?.intake || '';
  const intakeLabel = intake
    ? formatIntakeDisplay(intake)
    : getSectionMergedIntakeDisplayFull(sec);
  if (progName && progName !== '—' && intakeLabel && intakeLabel !== '—') {
    return `Course Structure of ${progName}(${intakeLabel} Version)`;
  }
  if (progName && progName !== '—') return `Course Structure of ${progName}`;
  return sec.programmeName || sec.curriculumName || '—';
}

function formatSectionChangeLogCourseName(sec) {
  return sec?.name || sec?.courseName || sec?.code || '—';
}

function seedSectionChangeLogDemoIfEmpty() {
  if (sectionChangeLogStore.length) return;
  ensureCourseOfferingPlan();
  const sections = (COURSE_OFFERING_PLAN_STORE?.sections || []).filter(s => s.offeringType === 'major');
  const operators = [
    'Khairun Nisa Khiruddin',
    'Dr. Lim Chee Hoong',
    'Admin User',
    '张敏',
    'Wang Lei',
    'Chang Wan Jin'
  ];
  const fieldSamples = [
    { field: 'kkjh_rl', before: '0', after: '2' },
    { field: 'Lecturer', before: '—', after: 'Dr. Lim Chee Hoong' },
    { field: 'Teaching Week', before: '1-14', after: '1-12' },
    { field: 'Capacity', before: '40', after: '45' },
    { field: '小组数', before: '1', after: '2' },
    { field: '备注', before: '', after: '合班调整' }
  ];
  const rows = [];
  let seq = 1;
  sections.slice(0, 8).forEach((sec, idx) => {
    const className = formatSectionChangeLogClassName(sec);
    const programmeName = formatSectionChangeLogProgrammeName(sec);
    const courseName = formatSectionChangeLogCourseName(sec);
    const createdAt = `2026-01-${String(20 + (idx % 8)).padStart(2, '0')} ${String(10 + (idx % 8)).padStart(2, '0')}:${String(15 + idx).padStart(2, '0')}`;
    rows.push({
      id: `scl-${seq++}`,
      sectionId: sec.id,
      operator: operators[idx % operators.length],
      changedAt: idx === 0 ? '2026-01-23 14:44' : createdAt,
      changeType: idx % 3 === 0 ? SECTION_CHANGE_TYPE_IMPORT : SECTION_CHANGE_TYPE_UPDATE,
      className: idx === 0 ? (className.includes('Group') ? className : `${className} (Group 1)`) : className,
      programmeName,
      courseName,
      field: fieldSamples[idx % fieldSamples.length].field,
      before: fieldSamples[idx % fieldSamples.length].before,
      after: fieldSamples[idx % fieldSamples.length].after
    });
    if (idx % 2 === 0) {
      const sample = fieldSamples[idx % fieldSamples.length];
      rows.push({
        id: `scl-${seq++}`,
        sectionId: sec.id,
        operator: operators[(idx + 1) % operators.length],
        changedAt: `2026-01-${String(22 + (idx % 6)).padStart(2, '0')} ${String(9 + idx).padStart(2, '0')}:30`,
        changeType: SECTION_CHANGE_TYPE_UPDATE,
        className,
        programmeName,
        courseName,
        field: sample.field,
        before: sample.before,
        after: sample.after
      });
    }
    if (idx === 3) {
      rows.push({
        id: `scl-${seq++}`,
        sectionId: sec.id,
        operator: operators[2],
        changedAt: '2026-01-18 11:05',
        changeType: SECTION_CHANGE_TYPE_DELETE,
        className,
        programmeName,
        courseName,
        field: '课程班',
        before: className,
        after: ''
      });
    }
  });
  if (!rows.length) {
    rows.push({
      id: 'scl-demo-1',
      sectionId: '',
      operator: 'Khairun Nisa Khiruddin',
      changedAt: '2026-01-23 14:44',
      changeType: SECTION_CHANGE_TYPE_UPDATE,
      className: '3D Modeling',
      programmeName: 'Course Structure of Digital Media Technology(202309 Version)',
      courseName: '3D Modeling',
      field: 'kkjh_rl',
      before: '0',
      after: '2'
    });
  }
  sectionChangeLogStore = rows;
}

function getSectionChangeLogFilterValues() {
  return {
    operator: (document.getElementById('section-change-log-filter-operator')?.value || '').trim().toLowerCase(),
    changeType: (document.getElementById('section-change-log-filter-type')?.value || '').trim()
  };
}

function getFilteredSectionChangeLogRows() {
  const focusId = String(sectionChangeLogFocusSectionId || '');
  const { operator, changeType } = getSectionChangeLogFilterValues();
  return sectionChangeLogStore.filter(row => {
    if (focusId && String(row.sectionId || '') !== focusId) return false;
    if (operator && !(row.operator || '').toLowerCase().includes(operator)) return false;
    if (changeType) {
      const rowType = String(row.changeType || '');
      if (changeType === '编辑' || changeType === '修改') {
        if (rowType !== '编辑' && rowType !== '修改') return false;
      } else if (rowType !== changeType) {
        return false;
      }
    }
    return true;
  });
}

function syncSectionChangeLogFilterOptions() {
  const operatorSel = document.getElementById('section-change-log-filter-operator');
  if (!operatorSel) return;
  const focusId = String(sectionChangeLogFocusSectionId || '');
  const names = [...new Set(
    sectionChangeLogStore
      .filter(row => !focusId || String(row.sectionId || '') === focusId)
      .map(row => row.operator)
      .filter(Boolean)
  )].sort((a, b) => a.localeCompare(b, 'zh'));
  const current = operatorSel.value;
  operatorSel.innerHTML = '<option value="">全部用户</option>'
    + names.map(name => `<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`).join('');
  if (current && names.includes(current)) operatorSel.value = current;
}

function querySectionChangeLogList() {
  resetListPage('courseSectionChangeLog');
  renderCourseSectionChangeLogPage();
}

function resetSectionChangeLogFilters() {
  const operatorSel = document.getElementById('section-change-log-filter-operator');
  const typeSel = document.getElementById('section-change-log-filter-type');
  if (operatorSel) operatorSel.value = '';
  if (typeSel) typeSel.value = '';
  resetListPage('courseSectionChangeLog');
  renderCourseSectionChangeLogPage();
}

function renderSectionChangeTypeCell(changeType) {
  const type = changeType || '—';
  let cls = 'section-change-type';
  if (type === SECTION_CHANGE_TYPE_CREATE) cls += ' is-create';
  else if (type === SECTION_CHANGE_TYPE_UPDATE || type === '修改') cls += ' is-update';
  else if (type === SECTION_CHANGE_TYPE_DELETE) cls += ' is-delete';
  else if (type === SECTION_CHANGE_TYPE_IMPORT) cls += ' is-update';
  return `<span class="${cls}">${escapeHtml(type)}</span>`;
}

function renderCourseSectionChangeLogPage() {
  const tbody = document.getElementById('course-section-change-log-body');
  if (!tbody) return;
  seedSectionChangeLogDemoIfEmpty();
  syncSectionChangeLogFilterOptions();
  const subtitle = document.getElementById('section-change-log-subtitle');
  if (subtitle) {
    const focusId = String(sectionChangeLogFocusSectionId || '');
    const sec = focusId
      ? COURSE_OFFERING_PLAN_STORE?.sections?.find(s => s.id === focusId)
      : null;
    subtitle.textContent = sec
      ? `${sec.code || ''} ${sec.name || ''} · 专业开课计划修改记录`.trim()
      : '查看专业开课计划字段变更历史';
  }
  const titleEl = document.querySelector('#page-course-section-change-log h1');
  if (titleEl) titleEl.textContent = '专业开课计划修改记录';
  const list = [...getFilteredSectionChangeLogRows()].sort((a, b) =>
    (b.changedAt || '').localeCompare(a.changedAt || '')
    || (a.courseName || a.className || '').localeCompare(b.courseName || b.className || '')
  );
  const paged = paginateListItems(list, 'courseSectionChangeLog');
  tbody.innerHTML = paged.items.length
    ? paged.items.map(row => `<tr>
        <td>${escapeHtml(row.operator || '—')}</td>
        <td class="col-center col-nowrap">${escapeHtml(row.changedAt || '—')}</td>
        <td class="col-center">${renderSectionChangeTypeCell(row.changeType)}</td>
        <td>${escapeHtml(row.programmeName || '—')}</td>
        <td>${escapeHtml(row.courseName || row.className || '—')}</td>
        <td>${escapeHtml(row.field || '')}</td>
        <td>${escapeHtml(row.before || '')}</td>
        <td>${escapeHtml(row.after || '')}</td>
      </tr>`).join('')
    : '<tr><td colspan="8" class="text-muted" style="text-align:center;padding:24px">暂无修改记录</td></tr>';
  renderListPagination('course-section-change-log-pagination', 'courseSectionChangeLog', paged.total);
}

function buildSectionChangeLogPopupDocument(sectionId) {
  const focusId = String(sectionId || '');
  ensureCourseOfferingPlan();
  seedSectionChangeLogDemoIfEmpty();
  const sec = COURSE_OFFERING_PLAN_STORE?.sections?.find(s => s.id === focusId);
  const rows = sectionChangeLogStore
    .filter(r => !focusId || String(r.sectionId || '') === focusId)
    .sort((a, b) => (b.changedAt || '').localeCompare(a.changedAt || ''));
  const operators = [...new Set(rows.map(r => r.operator).filter(Boolean))]
    .sort((a, b) => a.localeCompare(b, 'zh'));
  const subtitle = sec
    ? `${sec.code || ''} ${sec.name || ''}`.trim()
    : '查看专业开课计划字段变更历史';
  const cssHref = new URL('styles.css', location.href).href;
  const rowsJson = JSON.stringify(rows).replace(/</g, '\\u003c');
  const operatorOptions = operators
    .map(name => `<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`)
    .join('');
  return `<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>专业开课计划修改记录</title>
  <link rel="stylesheet" href="${escapeHtml(cssHref)}">
  <style>
    body { margin: 0; background: #f1f5f9; }
    .scl-shell { max-width: 1280px; margin: 0 auto; padding: 20px 24px 32px; }
    .scl-header {
      display: flex; align-items: center; justify-content: space-between;
      gap: 16px; margin-bottom: 12px;
    }
    .scl-header h1 { margin: 0 0 4px; font-size: 22px; color: #15803d; }
    .scl-header .subtitle { margin: 0; color: #64748b; font-size: 13px; }
    .scl-toolbar {
      display: flex; flex-wrap: wrap; align-items: flex-end; gap: 12px 16px;
      margin-bottom: 12px; padding: 12px 14px; background: #fff;
      border: 1px solid #e2e8f0; border-radius: 8px;
    }
    .scl-toolbar .field { display: flex; flex-direction: column; gap: 4px; min-width: 160px; }
    .scl-toolbar label { font-size: 12px; color: #64748b; }
    .scl-toolbar .actions { display: inline-flex; gap: 8px; margin-left: auto; }
    .scl-card {
      background: #fff; border: 1px solid #e2e8f0; border-radius: 8px; overflow: hidden;
    }
    .scl-card .table-scroll { overflow: auto; }
    .scl-card table { width: 100%; }
    .section-change-type.is-create { color: #dc2626; font-weight: 600; }
    .section-change-type.is-update { color: #2563eb; font-weight: 600; }
    .section-change-type.is-delete { color: #b45309; font-weight: 600; }
    .scl-empty { text-align: center; padding: 24px; color: #94a3b8; }
  </style>
</head>
<body>
  <div class="scl-shell">
    <div class="scl-header">
      <div>
        <h1>专业开课计划修改记录</h1>
        <p class="subtitle">${escapeHtml(subtitle)}</p>
      </div>
      <button class="btn btn-outline btn-sm" type="button" id="scl-btn-back">返回</button>
    </div>
    <div class="scl-toolbar">
      <div class="field">
        <label for="scl-filter-operator">用户名</label>
        <select class="input input-sm" id="scl-filter-operator">
          <option value="">全部用户</option>
          ${operatorOptions}
        </select>
      </div>
      <div class="field">
        <label for="scl-filter-type">类型</label>
        <select class="input input-sm" id="scl-filter-type">
          <option value="">全部类型</option>
          <option value="新增">新增</option>
          <option value="编辑">编辑</option>
          <option value="修改">修改</option>
          <option value="导入">导入</option>
          <option value="删除">删除</option>
        </select>
      </div>
      <div class="actions">
        <button class="btn btn-primary btn-sm" type="button" id="scl-btn-query">查询</button>
        <button class="btn btn-outline btn-sm" type="button" id="scl-btn-reset">重置</button>
      </div>
    </div>
    <div class="scl-card">
      <div class="table-scroll">
        <table class="data-table course-offering-table">
          <thead>
            <tr>
              <th>姓名</th>
              <th class="col-center">修改时间</th>
              <th class="col-center">类型</th>
              <th>培养方案名称</th>
              <th>课程名称</th>
              <th>修改字段</th>
              <th>修改前</th>
              <th>修改后</th>
            </tr>
          </thead>
          <tbody id="scl-body"></tbody>
        </table>
      </div>
    </div>
  </div>
  <script>
    const ROWS = ${rowsJson};
    function esc(s) {
      return String(s ?? '').replace(/[&<>"']/g, ch => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
      })[ch]);
    }
    function typeCell(t) {
      let cls = 'section-change-type';
      if (t === '新增' || t === '导入') cls += ' is-create';
      else if (t === '修改' || t === '编辑') cls += ' is-update';
      else if (t === '删除') cls += ' is-delete';
      return '<span class="' + cls + '">' + esc(t || '—') + '</span>';
    }
    function getFiltered() {
      const op = (document.getElementById('scl-filter-operator').value || '').trim().toLowerCase();
      const type = (document.getElementById('scl-filter-type').value || '').trim();
      return ROWS.filter(r => {
        if (op && !(r.operator || '').toLowerCase().includes(op)) return false;
        if (type) {
          const rowType = String(r.changeType || '');
          if (type === '编辑' || type === '修改') {
            if (rowType !== '编辑' && rowType !== '修改') return false;
          } else if (rowType !== type) {
            return false;
          }
        }
        return true;
      });
    }
    function render() {
      const list = getFiltered();
      const body = document.getElementById('scl-body');
      body.innerHTML = list.length
        ? list.map(r => '<tr>'
          + '<td>' + esc(r.operator || '—') + '</td>'
          + '<td class="col-center">' + esc(r.changedAt || '—') + '</td>'
          + '<td class="col-center">' + typeCell(r.changeType) + '</td>'
          + '<td>' + esc(r.programmeName || '—') + '</td>'
          + '<td>' + esc(r.courseName || r.className || '—') + '</td>'
          + '<td>' + esc(r.field || '') + '</td>'
          + '<td>' + esc(r.before || '') + '</td>'
          + '<td>' + esc(r.after || '') + '</td>'
          + '</tr>').join('')
        : '<tr><td colspan="8" class="scl-empty">暂无修改记录</td></tr>';
    }
    document.getElementById('scl-btn-back').onclick = function () { window.close(); };
    document.getElementById('scl-btn-query').onclick = render;
    document.getElementById('scl-btn-reset').onclick = function () {
      document.getElementById('scl-filter-operator').value = '';
      document.getElementById('scl-filter-type').value = '';
      render();
    };
    document.getElementById('scl-filter-operator').onchange = render;
    document.getElementById('scl-filter-type').onchange = render;
    render();
  </script>
</body>
</html>`;
}

/** 任务安排「修改记录」：新窗口呈现，原列表页不跳转 */
function openSectionChangeLogInNewWindow(sectionId) {
  const id = String(sectionId || '');
  if (!id) return false;
  let win = null;
  try {
    win = window.open('', `pyfa-scl-${id}`);
  } catch (_) {
    win = null;
  }
  if (!win || win === window) {
    alert('浏览器拦截了新窗口，请允许弹窗后重试。原页面保持不变。');
    return false;
  }
  try {
    const html = buildSectionChangeLogPopupDocument(id);
    win.document.open();
    win.document.write(html);
    win.document.close();
    win.focus();
  } catch (err) {
    console.warn('openSectionChangeLogInNewWindow failed', err);
    try { win.close(); } catch (_) { /* ignore */ }
    alert('无法打开修改记录窗口，请检查弹窗权限后重试。原页面保持不变。');
    return false;
  }
  return true;
}

/** 专业开课计划列表「操作记录 → 查看」入口（与课程班修改记录同窗） */
function openMajorOfferingPlanChangeLogInNewWindow(sectionId) {
  return openSectionChangeLogInNewWindow(sectionId);
}

function openSectionChangeLogPage(sectionId) {
  sectionChangeLogFocusSectionId = String(sectionId || '');
  sectionChangeLogOpenedAsPopup = false;
  resetListPage('courseSectionChangeLog');
  goPage('course-section-change-log');
}

function closeSectionChangeLogPage() {
  if (sectionChangeLogOpenedAsPopup) {
    try { window.close(); } catch (_) { /* ignore */ }
    // 若浏览器不允许脚本关窗，退回任务安排样式二
    if (!window.closed) {
      sectionChangeLogOpenedAsPopup = false;
      goPage('course-major-offering-task-style2');
    }
    return;
  }
  goPage('course-major-offering-task-style2');
}

function parseSectionChangeLogPopupHash() {
  const raw = String(location.hash || '').replace(/^#/, '');
  if (!raw) return null;
  const params = new URLSearchParams(raw);
  if (params.get('sclPopup') !== '1') return null;
  const sectionId = params.get('sectionId') || '';
  if (!sectionId) return null;
  return { sectionId };
}

function tryBootstrapSectionChangeLogPopup() {
  const fromHash = parseSectionChangeLogPopupHash();
  if (!fromHash?.sectionId) return false;
  const sectionId = fromHash.sectionId;
  let payload = null;
  try {
    const scoped = sessionStorage.getItem(`${SECTION_CHANGE_LOG_POPUP_STORAGE_KEY}:${sectionId}`);
    const raw = scoped || sessionStorage.getItem(SECTION_CHANGE_LOG_POPUP_STORAGE_KEY);
    if (raw) payload = JSON.parse(raw);
  } catch (_) { /* ignore */ }
  if (payload?.planByTerm && typeof payload.planByTerm === 'object') {
    COURSE_OFFERING_PLAN_BY_TERM = payload.planByTerm;
    const term = payload.activeTerm || Object.keys(COURSE_OFFERING_PLAN_BY_TERM)[0] || '';
    if (term) syncCourseOfferingPlanStoreFromTerm(term);
  } else {
    ensureCourseOfferingPlan();
  }
  if (Array.isArray(payload?.changeLogs) && payload.changeLogs.length) {
    sectionChangeLogStore = payload.changeLogs;
  } else {
    seedSectionChangeLogDemoIfEmpty();
  }
  sectionChangeLogOpenedAsPopup = true;
  sectionChangeLogFocusSectionId = sectionId;
  document.querySelector('.app')?.classList.remove('portal-mode');
  setActiveModule('course');
  resetListPage('courseSectionChangeLog');
  goPage('course-section-change-log');
  try { history.replaceState(null, '', `${location.pathname}${location.search}`); } catch (_) { /* ignore */ }
  return true;
}

// ── 授课教师确认（系统内；非邮件） ──
const TEACHER_COURSE_CONFIRMATION_BY_TERM = {};
const TEACHER_COURSE_CONFIRMATION_DEMO_VERSION = 'v5';
let teacherCourseConfirmationFocusStaffId = '';
let teacherCourseConfirmationPortalTeacherId = '';
/** 教师端 Tab：pending=待确认，history=历史 */
let teacherCourseConfirmationPortalTab = 'pending';
/** 教师端当前筛选开课学期（默认当前开课学期） */
let teacherCourseConfirmationPortalTermCode = '';
/** 管理端当前操作学院（仅可查看/下发本院教师；全部=所有学院） */
let teacherCourseConfirmationAdminCollege = '';
/** 管理端当前筛选开课学期（默认当前开课学期） */
let teacherCourseConfirmationAdminTermCode = '';
/** 管理端检索：教师名 / 工号 / 课程号 */
let teacherCourseConfirmationAdminNameQuery = '';
let teacherCourseConfirmationAdminStaffIdQuery = '';
let teacherCourseConfirmationAdminCourseCodeQuery = '';
/** 教师端决策弹窗：指定课程班（行内「授课确认」）；为空则按勾选/全部待确认 */
let teacherCourseConfirmationDecisionSectionIds = null;
/** 开课任务「管理」弹窗：当前课程班 sectionId */
let teacherCourseConfirmationSectionManageSectionId = '';

const TEACHER_COURSE_CONFIRMATION_ADMIN_COLLEGE_ALL = '__all__';

function getTeacherCourseConfirmationCollegeCodes() {
  return [...(typeof OFFERING_UNIT_CODES !== 'undefined' ? OFFERING_UNIT_CODES : SCHOOL_CODES || [])].sort();
}

function getTeacherCourseConfirmationAdminTermCodes() {
  return [...new Set((typeof COURSE_TIME_SETTINGS !== 'undefined' ? COURSE_TIME_SETTINGS : [])
    .map(r => r?.termCode)
    .filter(Boolean))].sort();
}

function resolveTeacherCourseConfirmationAdminTermCode() {
  const codes = getTeacherCourseConfirmationAdminTermCodes();
  if (teacherCourseConfirmationAdminTermCode && codes.includes(teacherCourseConfirmationAdminTermCode)) {
    return teacherCourseConfirmationAdminTermCode;
  }
  const fallback = getDefaultOfferingTermCode() || codes[codes.length - 1] || '';
  teacherCourseConfirmationAdminTermCode = fallback;
  return fallback;
}

function onTeacherCourseConfirmationAdminTermChange(value) {
  teacherCourseConfirmationAdminTermCode = String(value || '').trim();
  teacherCourseConfirmationFocusStaffId = '';
  resetListPage('teacherCourseConfirmationAdmin');
  refreshTeacherCourseConfirmationViews();
}

function queryTeacherCourseConfirmationAdminList() {
  teacherCourseConfirmationAdminNameQuery = document.getElementById('tcc-admin-name-input')?.value || '';
  teacherCourseConfirmationAdminStaffIdQuery = document.getElementById('tcc-admin-staff-id-input')?.value || '';
  teacherCourseConfirmationAdminCourseCodeQuery = document.getElementById('tcc-admin-course-code-input')?.value || '';
  const termEl = document.getElementById('tcc-admin-term-select');
  const collegeEl = document.getElementById('tcc-admin-college-select');
  if (termEl) teacherCourseConfirmationAdminTermCode = String(termEl.value || '').trim();
  if (collegeEl) {
    const next = String(collegeEl.value || '').trim();
    teacherCourseConfirmationAdminCollege = next === TEACHER_COURSE_CONFIRMATION_ADMIN_COLLEGE_ALL
      ? TEACHER_COURSE_CONFIRMATION_ADMIN_COLLEGE_ALL
      : next;
  }
  teacherCourseConfirmationFocusStaffId = '';
  resetListPage('teacherCourseConfirmationAdmin');
  refreshTeacherCourseConfirmationViews();
}

function resetTeacherCourseConfirmationAdminFilters() {
  teacherCourseConfirmationAdminNameQuery = '';
  teacherCourseConfirmationAdminStaffIdQuery = '';
  teacherCourseConfirmationAdminCourseCodeQuery = '';
  teacherCourseConfirmationAdminCollege = TEACHER_COURSE_CONFIRMATION_ADMIN_COLLEGE_ALL;
  teacherCourseConfirmationFocusStaffId = '';
  const codes = getTeacherCourseConfirmationAdminTermCodes();
  teacherCourseConfirmationAdminTermCode = getDefaultOfferingTermCode() || codes[codes.length - 1] || '';
  resetListPage('teacherCourseConfirmationAdmin');
  refreshTeacherCourseConfirmationViews();
}

function restoreTeacherCourseConfirmationAdminSearchFocus(inputId) {
  const el = document.getElementById(inputId);
  if (!el) return;
  const len = el.value.length;
  el.focus();
  try { el.setSelectionRange(len, len); } catch (_) { /* ignore */ }
}

function filterTeacherCourseConfirmationAdminRows(rows) {
  const nameQ = teacherCourseConfirmationAdminNameQuery.trim().toLowerCase();
  const idQ = teacherCourseConfirmationAdminStaffIdQuery.trim().toLowerCase();
  const codeQ = teacherCourseConfirmationAdminCourseCodeQuery.trim().toLowerCase();
  if (!nameQ && !idQ && !codeQ) return rows || [];
  return (rows || []).filter(row => {
    const teacherName = String(row.teacherName || row.name || '').toLowerCase();
    const staffId = String(row.staffId || '').toLowerCase();
    const courseCode = String(row.code || '').toLowerCase();
    if (nameQ && !teacherName.includes(nameQ)) return false;
    if (idQ && !staffId.includes(idQ)) return false;
    if (codeQ && !courseCode.includes(codeQ)) return false;
    return true;
  });
}

function resolveTeacherCourseConfirmationPortalTermCode() {
  const codes = getTeacherCourseConfirmationAdminTermCodes();
  if (teacherCourseConfirmationPortalTermCode && codes.includes(teacherCourseConfirmationPortalTermCode)) {
    return teacherCourseConfirmationPortalTermCode;
  }
  const fallback = getDefaultOfferingTermCode() || codes[codes.length - 1] || '';
  teacherCourseConfirmationPortalTermCode = fallback;
  return fallback;
}

function onTeacherCourseConfirmationPortalTermChange(value) {
  teacherCourseConfirmationPortalTermCode = String(value || '').trim();
  teacherCourseConfirmationPortalTab = '';
  resetListPage('teacherCourseConfirmationPortal');
  renderTeacherCourseConfirmationPortalPage();
}

function getTeacherDepartmentCode(staffId) {
  const id = String(staffId || '').trim();
  if (!id) return '';
  const fromPool = buildMockTeacherPickerPool().find(t => t.staffId === id);
  if (fromPool?.departmentCode) return fromPool.departmentCode;
  const term = resolveTeacherCourseConfirmationTermCode();
  for (const sec of getOfferingSectionsForTerm(term)) {
    const hit = collectSectionAssignTeachers(sec).find(t => t.staffId === id);
    if (hit?.departmentCode) return hit.departmentCode;
  }
  return '';
}

function resolveTeacherCourseConfirmationAdminCollege() {
  const codes = getTeacherCourseConfirmationCollegeCodes();
  if (teacherCourseConfirmationAdminCollege === TEACHER_COURSE_CONFIRMATION_ADMIN_COLLEGE_ALL) {
    return TEACHER_COURSE_CONFIRMATION_ADMIN_COLLEGE_ALL;
  }
  if (teacherCourseConfirmationAdminCollege && codes.includes(teacherCourseConfirmationAdminCollege)) {
    return teacherCourseConfirmationAdminCollege;
  }
  const sec = typeof getOfferingGroupingSection === 'function' ? getOfferingGroupingSection() : null;
  const fromSec = sec ? resolveMajorOfferingSectionOfferingUnit(sec) : '';
  if (fromSec && codes.includes(fromSec)) {
    teacherCourseConfirmationAdminCollege = fromSec;
    return fromSec;
  }
  const focusDept = teacherCourseConfirmationFocusStaffId
    ? getTeacherDepartmentCode(teacherCourseConfirmationFocusStaffId)
    : '';
  if (focusDept && codes.includes(focusDept)) {
    teacherCourseConfirmationAdminCollege = focusDept;
    return focusDept;
  }
  teacherCourseConfirmationAdminCollege = codes[0] || TEACHER_COURSE_CONFIRMATION_ADMIN_COLLEGE_ALL;
  return teacherCourseConfirmationAdminCollege;
}

function isTeacherCourseConfirmationAdminCollegeAll(collegeCode = resolveTeacherCourseConfirmationAdminCollege()) {
  return collegeCode === TEACHER_COURSE_CONFIRMATION_ADMIN_COLLEGE_ALL || collegeCode == null || collegeCode === '';
}

function isTeacherInCourseConfirmationAdminCollege(staffId, collegeCode = resolveTeacherCourseConfirmationAdminCollege()) {
  if (!staffId) return false;
  if (isTeacherCourseConfirmationAdminCollegeAll(collegeCode)) return true;
  return getTeacherDepartmentCode(staffId) === collegeCode;
}

function assertTeacherCourseConfirmationAdminScope(staffId) {
  const college = resolveTeacherCourseConfirmationAdminCollege();
  if (isTeacherInCourseConfirmationAdminCollege(staffId, college)) return true;
  alert(`仅可对本院（${college || '—'}）教师下发或代确认授课确认。`);
  return false;
}

function onTeacherCourseConfirmationAdminCollegeChange(value) {
  const next = String(value || '').trim();
  teacherCourseConfirmationAdminCollege = next === TEACHER_COURSE_CONFIRMATION_ADMIN_COLLEGE_ALL
    ? TEACHER_COURSE_CONFIRMATION_ADMIN_COLLEGE_ALL
    : next;
  teacherCourseConfirmationFocusStaffId = '';
  resetListPage('teacherCourseConfirmationAdmin');
  refreshTeacherCourseConfirmationViews();
}

function ensureTeacherCourseConfirmationTermStore(termCode) {
  const code = String(termCode || '').trim();
  if (!code) return null;
  if (!TEACHER_COURSE_CONFIRMATION_BY_TERM[code]) {
    TEACHER_COURSE_CONFIRMATION_BY_TERM[code] = { packages: {}, demoVersion: null };
  }
  return TEACHER_COURSE_CONFIRMATION_BY_TERM[code];
}

function resolveTeacherCourseConfirmationTermCode() {
  const sec = typeof getOfferingGroupingSection === 'function' ? getOfferingGroupingSection() : null;
  const fromSec = sec ? resolveSectionOfferingTermCode(sec) : '';
  if (fromSec) return fromSec;
  if (typeof getMajorOfferingOfferingTermCode === 'function') {
    const major = getMajorOfferingOfferingTermCode();
    if (major) return major;
  }
  return getDefaultOfferingTermCode() || '';
}

function getTeacherCourseConfirmationPackage(teacherId, termCode) {
  const id = String(teacherId || '').trim();
  const term = String(termCode || '').trim();
  if (!id || !term) return null;
  const store = ensureTeacherCourseConfirmationTermStore(term);
  return store?.packages?.[id] || null;
}

function ensureTeacherCourseConfirmationPackage(teacherId, termCode) {
  const id = String(teacherId || '').trim();
  const term = String(termCode || '').trim();
  if (!id || !term) return null;
  const store = ensureTeacherCourseConfirmationTermStore(term);
  if (!store) return null;
  if (!store.packages[id]) {
    store.packages[id] = {
      teacherId: id,
      teacherName: resolveOfferingTeacherDisplayName(id),
      termCode: term,
      status: 'draft',
      confirmedBy: null,
      confirmedAt: null,
      proxyBy: null,
      snapshotHash: '',
      rows: [],
      sectionStates: {},
      feedback: '',
      history: []
    };
  }
  if (!store.packages[id].sectionStates || typeof store.packages[id].sectionStates !== 'object') {
    store.packages[id].sectionStates = {};
  }
  return store.packages[id];
}

function ensureTeacherCourseConfirmationSectionStates(pkg) {
  if (!pkg) return {};
  if (!pkg.sectionStates || typeof pkg.sectionStates !== 'object') pkg.sectionStates = {};
  return pkg.sectionStates;
}

/** 旧版整包状态迁移为按课程班状态（仅在尚无 sectionStates 时） */
function migrateTeacherCourseConfirmationPackageSectionStates(pkg) {
  if (!pkg) return;
  const states = ensureTeacherCourseConfirmationSectionStates(pkg);
  if (Object.keys(states).length) return;
  if (!pkg.status || pkg.status === 'draft' || !pkg.rows?.length) return;
  const mapped = pkg.status === 'confirmed' && pkg.confirmedBy === 'admin-proxy'
    ? 'admin-proxy'
    : pkg.status;
  pkg.rows.forEach(row => {
    if (!row?.sectionId) return;
    states[row.sectionId] = {
      status: mapped,
      confirmedBy: pkg.confirmedBy || null,
      confirmedAt: pkg.confirmedAt || null,
      proxyBy: pkg.proxyBy || null,
      feedback: pkg.feedback || '',
      snapshotHash: computeTeacherCourseConfirmationSnapshotHash([row])
    };
  });
}

function getTeacherCourseConfirmationSectionState(pkg, sectionId) {
  if (!pkg || !sectionId) return { status: 'draft' };
  migrateTeacherCourseConfirmationPackageSectionStates(pkg);
  return ensureTeacherCourseConfirmationSectionStates(pkg)[sectionId] || { status: 'draft' };
}

function isTeacherCourseConfirmationSectionSnapshotCurrent(pkg, sectionId) {
  if (!pkg || !sectionId) return false;
  const st = getTeacherCourseConfirmationSectionState(pkg, sectionId);
  if (!st?.snapshotHash) return false;
  const live = buildTeacherCourseConfirmationRows(pkg.teacherId, pkg.termCode)
    .find(r => r.sectionId === sectionId);
  if (!live) return false;
  // 仅比对本人安排指纹；共同授课/协调人展示变化不视为须重新确认
  return getTeacherCourseConfirmationArrangementFingerprint(live)
    === getTeacherCourseConfirmationArrangementFingerprintFromSnapshot(st.snapshotHash);
}

/** 授课确认「安排是否变更」指纹：不含共同授课、协调人等展示字段 */
function getTeacherCourseConfirmationArrangementFingerprint(row) {
  if (!row) return '';
  return JSON.stringify({
    sectionId: row.sectionId,
    code: row.code,
    name: row.name,
    classification: row.classification,
    credits: row.credits,
    teachingWeeks: row.teachingWeeks,
    weekRange: row.weekRange,
    teachingMethod: row.teachingMethod,
    combinedClass: row.combinedClass,
    groupCount: row.groupCount,
    combinedGroupsCount: row.combinedGroupsCount,
    hoursCombinedWithCode: row.hoursCombinedWithCode || '',
    totalStudentNo: row.totalStudentNo,
    weeklyHours: row.weeklyHours,
    totalTeachingHours: row.totalTeachingHours
  });
}

function getTeacherCourseConfirmationArrangementFingerprintFromSnapshot(snapshotHash) {
  if (!snapshotHash) return '';
  try {
    const parsed = JSON.parse(snapshotHash);
    const row = Array.isArray(parsed) ? parsed[0] : parsed;
    return getTeacherCourseConfirmationArrangementFingerprint(row);
  } catch (_) {
    return String(snapshotHash);
  }
}

/**
 * 修复：仅因共同授课名单等展示字段变化而被打成 pending 的误失效。
 * 最近事件为 arrangement-changed 失效，且本人安排指纹仍一致时，恢复此前确认态。
 */
function repairSpuriousTeacherCourseConfirmationInvalidation(pkg, sectionId, st) {
  if (!pkg || !st || st.status !== 'pending' || !st.snapshotHash) return false;
  if (!isTeacherCourseConfirmationSectionSnapshotCurrent(pkg, sectionId)) return false;
  const hist = Array.isArray(pkg.history) ? pkg.history : [];
  const sid = String(sectionId);
  const touches = (h) => {
    const ids = h?.sectionIds;
    if (!ids || !ids.length) return true;
    return ids.map(String).includes(sid);
  };
  let lastIdx = -1;
  for (let i = hist.length - 1; i >= 0; i--) {
    if (touches(hist[i])) {
      lastIdx = i;
      break;
    }
  }
  if (lastIdx < 0) return false;
  const last = hist[lastIdx];
  if (last.type !== 'invalidated' || last.reason !== 'arrangement-changed') return false;
  for (let j = lastIdx - 1; j >= 0; j--) {
    const prev = hist[j];
    if (!touches(prev)) continue;
    if (prev.type === 'confirmed') {
      const isProxy = prev.confirmedBy === 'admin-proxy';
      st.status = isProxy ? 'admin-proxy' : 'confirmed';
      st.confirmedBy = prev.confirmedBy || (isProxy ? 'admin-proxy' : 'teacher');
      st.proxyBy = prev.proxyBy || null;
      st.confirmedAt = prev.at || new Date().toISOString();
      st.feedback = '';
      const live = buildTeacherCourseConfirmationRows(pkg.teacherId, pkg.termCode)
        .find(r => r.sectionId === sectionId);
      if (live) st.snapshotHash = computeTeacherCourseConfirmationSnapshotHash([live]);
      return true;
    }
    if (prev.type === 'issued' || prev.type === 'reissued' || prev.type === 'disagreed') {
      return false;
    }
  }
  return false;
}

function getTeacherCourseConfirmationSectionStatus(staffId, termCode, sectionId, pkg) {
  if (isOfferingTbcTeacher(staffId)) return 'confirmed';
  const p = pkg || getTeacherCourseConfirmationPackage(staffId, termCode);
  if (!p || !sectionId) return 'draft';
  const st = getTeacherCourseConfirmationSectionState(p, sectionId);
  const status = st.status || 'draft';
  if ((status === 'confirmed' || status === 'admin-proxy') && !isTeacherCourseConfirmationSectionSnapshotCurrent(p, sectionId)) {
    return 'pending';
  }
  return status;
}

function recomputeTeacherCourseConfirmationPackageStatus(pkg) {
  if (!pkg) return;
  migrateTeacherCourseConfirmationPackageSectionStates(pkg);
  const states = Object.values(ensureTeacherCourseConfirmationSectionStates(pkg)).map(s => s.status || 'draft');
  if (!states.length) {
    pkg.status = 'draft';
    pkg.confirmedBy = null;
    pkg.confirmedAt = null;
    pkg.proxyBy = null;
    return;
  }
  if (states.some(s => s === 'pending')) {
    pkg.status = 'pending';
    return;
  }
  if (states.some(s => s === 'disagreed')) {
    pkg.status = 'disagreed';
    const hit = Object.values(pkg.sectionStates).find(s => s.status === 'disagreed');
    pkg.feedback = hit?.feedback || pkg.feedback || '';
    return;
  }
  if (states.every(s => s === 'confirmed' || s === 'admin-proxy')) {
    pkg.status = 'confirmed';
    const first = Object.values(pkg.sectionStates)[0];
    pkg.confirmedBy = first?.confirmedBy || null;
    pkg.confirmedAt = first?.confirmedAt || null;
    pkg.proxyBy = first?.proxyBy || null;
    return;
  }
  if (states.some(s => s === 'confirmed' || s === 'admin-proxy')) {
    pkg.status = 'confirmed';
    return;
  }
  pkg.status = 'draft';
}

function countTeacherConfirmationLectureLabGroups(staffId, sec) {
  let lecture = 0;
  let lab = 0;
  (sec?.groupAssignments || []).forEach(row => {
    if (!getGroupAssignTeachers(row).some(t => String(t?.staffId || '') === String(staffId))) return;
    const ht = String(getGroupAssignHourTypeDisplayLabel(sec, row.hourType) || row.hourType || '').toLowerCase();
    const isLecture = ht.includes('lecture') || ht.includes('理论') || ht === 'l';
    if (isLecture) lecture += 1;
    else lab += 1;
  });
  return { lectureGroups: lecture || (lab ? 0 : 1), labGroups: lab };
}

function computeTeacherWeeklyHoursOnSection(staffId, sec) {
  if (!staffId || !sec) return 0;
  let sum = 0;
  (sec.groupAssignments || []).forEach(row => {
    if (!getGroupAssignTeachers(row).some(t => String(t?.staffId || '') === String(staffId))) return;
    const weekly = Number(row.weeklyHours) || 0;
    if (weekly <= 0) return;
    if (row.simultaneousGroups) sum += weekly;
    else sum += weekly * Math.max(1, getGroupAssignRowGroupIds(row).length);
  });
  return sum;
}

function countTeacherConfirmationResponsibleGroups(staffId, sec) {
  // return (Number(lectureGroups) || 0) + (Number(labGroups) || 0); // 原 lecture/lab 加总，改对齐 Teaching Load Groups
  return countTeacherOfferingSectionNoOfGroups(staffId, sec);
}

/** 教师在本课实际授课周次（去重） */
function collectTeacherTeachingWeeksOnSection(staffId, sec) {
  if (!staffId || !sec) return [];
  const weekSet = new Set();
  const maxWeeks = typeof getSectionTermTeachingWeeks === 'function'
    ? getSectionTermTeachingWeeks(sec)
    : MAJOR_OFFERING_MAX_WEEKS;
  let any = false;
  (sec.groupAssignments || []).forEach(row => {
    if (!getGroupAssignTeachers(row).some(t => String(t?.staffId || '') === String(staffId))) return;
    any = true;
    const wr = typeof clampGroupAssignWeekRangeToSection === 'function'
      ? (clampGroupAssignWeekRangeToSection(sec, row.weekRange) || row.weekRange)
      : row.weekRange;
    const weeks = parseWeekRangeToWeeks(wr, maxWeeks);
    if (weeks.length) {
      weeks.forEach(w => weekSet.add(w));
      return;
    }
    const sectionWeeks = typeof getSectionSelectedWeeks === 'function'
      ? getSectionSelectedWeeks(sec)
      : parseWeekRangeToWeeks(sec.weekRange || sec.weeks, maxWeeks);
    (sectionWeeks || []).forEach(w => weekSet.add(w));
  });
  if (!any) {
    const sectionWeeks = typeof getSectionSelectedWeeks === 'function'
      ? getSectionSelectedWeeks(sec)
      : parseWeekRangeToWeeks(sec.weekRange || sec.weeks, maxWeeks);
    (sectionWeeks || []).forEach(w => weekSet.add(w));
  }
  return [...weekSet].sort((a, b) => a - b);
}

function resolveTeacherConfirmationTeachingWeeks(staffId, sec) {
  const fromAssign = collectTeacherTeachingWeeksOnSection(staffId, sec).length;
  if (fromAssign > 0) return fromAssign;
  // 安排行周次未能解析时，回退课程教学周数（开课时间设置按学期类型写入）
  const hasTeacher = (sec?.groupAssignments || []).some(row =>
    getGroupAssignTeachers(row).some(t => String(t?.staffId || '') === String(staffId || ''))
  );
  if (!hasTeacher) return 0;
  const termWeeks = Number(sec?.teachingWeeks) || 0;
  return termWeeks > 0 ? termWeeks : 0;
}

function resolveTeacherConfirmationWeekRange(sec) {
  if (!sec) return '—';
  if (typeof getSectionWeekRangeDisplay === 'function') {
    const range = getSectionWeekRangeDisplay(sec);
    if (range) return range;
  }
  const weeks = typeof getSectionSelectedWeeks === 'function'
    ? getSectionSelectedWeeks(sec)
    : parseWeekRangeToWeeks(sec.weekRange || sec.weeks, getSectionTermTeachingWeeks(sec));
  if (weeks?.length) {
    return typeof formatWeeksSegmentDisplay === 'function'
      ? formatWeeksSegmentDisplay(weeks)
      : `${weeks[0]}-${weeks[weeks.length - 1]}`;
  }
  return String(sec.weekRange || sec.weeks || '').trim() || '—';
}

/** 确认函周学时：本课总学时 / 授课周数，四舍五入 */
function computeTeacherConfirmationWeeklyHours(staffId, sec, teachingWeeks) {
  const weeks = teachingWeeks != null
    ? Number(teachingWeeks) || 0
    : resolveTeacherConfirmationTeachingWeeks(staffId, sec);
  if (!weeks) return '—';
  const totalHours = typeof sumTeacherOfferingTeachingLoadHoursOnSection === 'function'
    ? sumTeacherOfferingTeachingLoadHoursOnSection(staffId, sec)
    : computeTeacherWeeklyHoursOnSection(staffId, sec) * weeks;
  if (!(totalHours > 0)) return 0;
  return Math.round(totalHours / weeks);
}

function teacherHasSimultaneousGroupsOnSection(staffId, sec) {
  return (sec?.groupAssignments || []).some(row => {
    if (!getGroupAssignTeachers(row).some(t => t?.staffId === staffId)) return false;
    if (row.simultaneousGroups) return true;
    return getGroupAssignRowGroupIds(row).length > 1;
  });
}

/**
 * No. of Combined Groups：该教师在本课同时授课的「合并组」个数。
 * 取互不包含的最大合并组集合数；若某周带 1–4 组、另一周仅带 1–2 组，只计 1 个大组。
 * 无合并组（仅单独小组）返回 0，展示为 —。
 */
function countTeacherConfirmationCombinedGroups(staffId, sec) {
  if (!staffId || !sec) return 0;
  const staffKey = String(staffId || '').trim();
  const sets = [];
  (sec.groupAssignments || []).forEach(row => {
    if (!getGroupAssignTeachers(row).some(t => String(t?.staffId || '').trim() === staffKey)) return;
    let ids = getGroupAssignRowGroupIds(row).map(id => String(id)).filter(Boolean);
    if (!ids.length && row.deliveryScope === 'section') {
      ids = (sec.groups || []).map(g => String(g.id)).filter(Boolean);
    }
    const isCombined = !!row.simultaneousGroups || ids.length > 1;
    if (!isCombined || ids.length < 2) return;
    sets.push(new Set(ids));
  });
  if (!sets.length) return 0;
  const isSubset = (a, b) => {
    if (a.size > b.size) return false;
    for (const v of a) if (!b.has(v)) return false;
    return true;
  };
  const maximal = sets.filter((s, i) =>
    !sets.some((other, j) => j !== i && other.size > s.size && isSubset(s, other))
  );
  const seen = new Set();
  let count = 0;
  maximal.forEach(s => {
    const key = [...s].sort().join('\0');
    if (seen.has(key)) return;
    seen.add(key);
    count += 1;
  });
  return count;
}

function formatTeacherCourseConfirmationCombinedGroupsCell(count) {
  const n = Number(count) || 0;
  return n > 0 ? escapeHtml(String(n)) : '—';
}

/**
 * 共同授课学时展示：仅「共同授课组内相同任课教师」显示 Combined with {对端课号}。
 * 教师同一性与共同授课设置一致：工号相同，或清单姓名相同（忽略 Dr./Prof. 前缀）。
 * 同课其他教师仍显示正常学时。
 */
function normalizeSharedTeachingTeacherNameKey(name) {
  return String(name || '')
    .trim()
    .toLowerCase()
    .replace(/^(dr\.?|prof\.?|professor|mr\.?|ms\.?|mrs\.?)\s+/i, '')
    .replace(/\s+/g, ' ');
}

function collectSharedTeachingSectionTeacherKeys(sec) {
  const ids = new Set();
  const names = new Set();
  const push = (staffId, name) => {
    const id = String(staffId || '').trim();
    if (id) ids.add(id);
    const nk = normalizeSharedTeachingTeacherNameKey(name);
    if (nk) names.add(nk);
  };
  if (typeof collectSectionAssignTeachers === 'function') {
    collectSectionAssignTeachers(sec).forEach(t => push(t?.staffId, t?.name));
  }
  if (typeof collectMajorOfferingSectionAssignedTeachers === 'function') {
    collectMajorOfferingSectionAssignedTeachers(sec).forEach(t => push(t?.staffId, t?.name));
  }
  // 与共同授课设置同源：开课清单教师姓名
  if (typeof getOfferingManifestTeachersForSection === 'function'
    && typeof parseOfferingManifestTeacherNames === 'function') {
    parseOfferingManifestTeacherNames(getOfferingManifestTeachersForSection(sec))
      .forEach(n => push('', n));
  }
  return { ids, names };
}

function teacherBelongsToSharedTeachingSection(sec, staffId, teacherName) {
  const keys = collectSharedTeachingSectionTeacherKeys(sec);
  const staffKey = String(staffId || '').trim();
  if (staffKey && keys.ids.has(staffKey)) return true;
  const nameKey = normalizeSharedTeachingTeacherNameKey(teacherName);
  return !!(nameKey && keys.names.has(nameKey));
}

function resolveTeacherConfirmationHoursCombinedWithCode(staffId, termCode, sec) {
  if (!sec) return '';
  const staffKey = String(staffId || '').trim();
  if (!staffKey) return '';
  if (!(sec.sharedTeachingCode || '').trim()) return '';

  // 先取对端课号（与原先可展示 Combined with 的数据源一致）
  const peerCodes = typeof getSectionSharedTeachingPeerCourseCodes === 'function'
    ? getSectionSharedTeachingPeerCourseCodes(sec)
    : [];
  if (!peerCodes.length) return '';

  const selfTeachers = typeof collectSectionAssignTeachers === 'function'
    ? collectSectionAssignTeachers(sec)
    : [];
  const selfHit = selfTeachers.find(t => String(t?.staffId || '').trim() === staffKey);
  const teacherName = String(
    selfHit?.name
    || (typeof resolveOfferingTeacherDisplayName === 'function'
      ? resolveOfferingTeacherDisplayName(staffKey)
      : '')
    || ''
  ).trim();
  if (!teacherBelongsToSharedTeachingSection(sec, staffKey, teacherName)) return '';

  const mark = (sec.sharedTeachingCode || '').trim();
  const selfCode = String(sec.code || '').trim().toUpperCase();
  const term = String(
    sec.termCode
    || COURSE_OFFERING_PLAN_STORE?.termCode
    || termCode
    || (typeof resolveSectionOfferingTermCode === 'function' ? resolveSectionOfferingTermCode(sec) : '')
    || ''
  ).trim();
  const peerCodeSet = new Set(peerCodes.map(c => String(c).trim().toUpperCase()).filter(Boolean));
  const matchedCodes = [];
  const seen = new Set();
  const consider = (s) => {
    if (!s || s.id === sec.id) return;
    if ((s.sharedTeachingCode || '').trim() !== mark) return;
    if (term && String(s.termCode || '').trim() && String(s.termCode || '').trim() !== term) return;
    const code = String(s.code || '').trim();
    if (!code || code.toUpperCase() === selfCode) return;
    if (!peerCodeSet.has(code.toUpperCase())) return;
    if (!teacherBelongsToSharedTeachingSection(s, staffKey, teacherName)) return;
    const key = code.toUpperCase();
    if (seen.has(key)) return;
    seen.add(key);
    matchedCodes.push(code);
  };
  const scan = (sections) => (sections || []).forEach(consider);
  scan(COURSE_OFFERING_PLAN_STORE?.sections);
  if (typeof COURSE_OFFERING_PLAN_BY_TERM !== 'undefined') {
    Object.values(COURSE_OFFERING_PLAN_BY_TERM || {}).forEach(st => {
      if (st && st !== COURSE_OFFERING_PLAN_STORE) scan(st.sections);
    });
  }
  if (term && typeof getOfferingSectionsForTerm === 'function') {
    scan(getOfferingSectionsForTerm(term));
  }

  if (!matchedCodes.length) return '';
  matchedCodes.sort((a, b) => a.localeCompare(b, 'en'));
  return matchedCodes.length === 1 ? matchedCodes[0] : matchedCodes.join(' / ');
}

function formatTeacherCourseConfirmationHoursCell(row, field) {
  const withCode = String(row?.hoursCombinedWithCode || '').trim();
  if (withCode) {
    return `<span class="tcc-hours-combined-with">`
      + `<span class="tcc-hours-combined-with-word">Combined</span>`
      + `<span class="tcc-hours-combined-with-word">with</span>`
      + `<span class="tcc-hours-combined-with-code">${escapeHtml(withCode)}</span>`
      + `</span>`;
  }
  const val = field === 'weekly' ? row?.weeklyHours : row?.totalTeachingHours;
  return escapeHtml(String(val ?? '—'));
}

function getTeacherCombinedGroupsFieldTipText() {
  return [
    '所带小组中「同时多组合并授课」的合并组数量',
    '· 不同周次的合并组若存在包含关系，只计最大合并组',
    '· 例：某周带 1–4 组、另周仅带 1–2 组 → 计 1',
    '· 无合并组（仅单独小组）显示 —'
  ].join('\n');
}

function resolveTeacherConfirmationCombinedClass(staffId, sec) {
  if ((sec?.sharedTeachingCode || '').trim()) return 'Y';
  if (teacherHasSimultaneousGroupsOnSection(staffId, sec)) return 'Y';
  return 'N';
}

/** 同学期同 course code 下授课教师，排除本人与 Course Coordinator */
function collectCoTeachingStaffForCourseCode(teacherId, termCode, courseCode, coordinatorStaffId = '') {
  const id = String(teacherId || '').trim();
  const code = String(courseCode || '').trim();
  const coordId = String(coordinatorStaffId || '').trim();
  if (!id || !code) return [];
  const out = [];
  const seen = new Set();
  getOfferingSectionsForTerm(termCode)
    .filter(sec => sec?.offeringType === 'major' && sec.submitStatus === 'submitted')
    .filter(sec => String(sec.code || '').trim() === code)
    .forEach(sec => {
      collectSectionAssignTeachers(sec).forEach(t => {
        const sid = String(t?.staffId || '').trim();
        if (!sid || sid === id) return;
        if (coordId && sid === coordId) return;
        if (seen.has(sid)) return;
        seen.add(sid);
        const name = t.name || sid;
        out.push({
          staffId: sid,
          name,
          email: resolveOfferingTeacherEmail(sid, name)
        });
      });
    });
  return out;
}

function resolveOfferingTeacherEmail(staffId, name = '') {
  const id = String(staffId || '').trim();
  if (isOfferingTbcTeacher(id)) return '—';
  const pick = typeof buildMockTeacherPickerPool === 'function'
    ? buildMockTeacherPickerPool().find(t => t.staffId === id)
    : null;
  if (pick?.email) return pick.email;
  const local = id.replace(/[^a-zA-Z0-9]/g, '').toLowerCase()
    || String(name || 'teacher').replace(/[^a-zA-Z0-9]/g, '').toLowerCase()
    || 'teacher';
  return `${local}@xmu.edu.my`;
}

function mapHourTypeToTeachingMethodLabel(hourType, sec) {
  const raw = String(
    (typeof getGroupAssignHourTypeDisplayLabel === 'function'
      ? getGroupAssignHourTypeDisplayLabel(sec, hourType)
      : hourType) || hourType || ''
  ).trim();
  if (!raw) return '';
  const lower = raw.toLowerCase();
  if (raw === GROUP_ASSIGN_MERGED_HOUR_TYPE || lower.includes('总学时')) return 'Lecture';
  const parts = raw.split(/[&、,/]+/).map(s => s.trim()).filter(Boolean);
  if (parts.length > 1) {
    const mapped = [...new Set(parts.map(p => mapHourTypeToTeachingMethodLabel(p, sec)).filter(Boolean))];
    return mapped.join(' & ') || raw;
  }
  if (lower.includes('lecture') || raw.includes('理论')) return 'Lecture';
  if (lower.includes('tutorial') || lower.includes('tutoring') || raw.includes('辅导')) return 'Tutorial';
  if (lower.includes('practical') || lower.includes('practice') || lower.includes('lab') || raw.includes('实践')) {
    return 'Practical';
  }
  if (lower.includes('other') || raw.includes('其他')) return 'Others';
  return raw;
}

function resolveTeacherConfirmationTeachingMethod(staffId, sec) {
  const methods = [];
  const seen = new Set();
  (sec?.groupAssignments || []).forEach(row => {
    if (!getGroupAssignTeachers(row).some(t => String(t?.staffId || '') === String(staffId))) return;
    const label = mapHourTypeToTeachingMethodLabel(row.hourType, sec);
    if (!label || seen.has(label)) return;
    seen.add(label);
    methods.push(label);
  });
  return methods.length ? methods.join(' & ') : '—';
}

function formatTccStackedCell(lines) {
  const list = (Array.isArray(lines) ? lines : [lines])
    .map(v => String(v == null ? '' : v).trim())
    .filter(v => v && v !== '—');
  if (!list.length) return '—';
  if (list.length === 1) return escapeHtml(list[0]);
  return `<div class="tcc-stacked-lines">${list.map(line =>
    `<div class="tcc-stacked-line" title="${escapeHtml(line)}">${escapeHtml(line)}</div>`
  ).join('')}</div>`;
}

function buildTeacherCourseConfirmationRows(teacherId, termCode) {
  const id = String(teacherId || '').trim();
  const term = String(termCode || '').trim();
  if (!id || !term) return [];
  // TBC 占位教师不进入授课确认清单（默认已确认）
  if (isOfferingTbcTeacher(id)) return [];
  return getOfferingSectionsForTerm(term)
    .filter(sec => sec?.offeringType === 'major' && sec.submitStatus === 'submitted')
    .filter(sec => collectSectionAssignTeachers(sec).some(t => t.staffId === id))
    .map(sec => {
      const groupCount = countTeacherConfirmationResponsibleGroups(id, sec);
      const teachingWeeks = resolveTeacherConfirmationTeachingWeeks(id, sec);
      const weeklyHours = computeTeacherConfirmationWeeklyHours(id, sec, teachingWeeks);
      const totalTeachingHours = typeof sumTeacherOfferingTeachingLoadHoursOnSection === 'function'
        ? sumTeacherOfferingTeachingLoadHoursOnSection(id, sec)
        : (Number(weeklyHours) > 0 && Number(teachingWeeks) > 0
          ? Number(weeklyHours) * Number(teachingWeeks)
          : 0);
      const coord = getSectionCoordinator(sec);
      const coordId = String(coord?.staffId || '').trim();
      const coordName = coord?.name || '—';
      const coTeaching = collectCoTeachingStaffForCourseCode(id, term, sec.code, coordId);
      const hoursCombinedWithCode = resolveTeacherConfirmationHoursCombinedWithCode(id, term, sec);
      return {
        sectionId: sec.id,
        code: sec.code || '—',
        name: sec.name || '—',
        classification: getOfferingSectionCategoryDisplay(sec),
        credits: sec.credits ?? '—',
        teachingWeeks: teachingWeeks > 0 ? teachingWeeks : '—',
        // weekRange：兼容旧字段，展示授课周数
        weekRange: teachingWeeks > 0 ? teachingWeeks : '—',
        teachingMethod: resolveTeacherConfirmationTeachingMethod(id, sec),
        combinedClass: resolveTeacherConfirmationCombinedClass(id, sec),
        groupCount,
        combinedGroupsCount: countTeacherConfirmationCombinedGroups(id, sec),
        totalStudentNo: getSectionPlannedStudentCount(sec),
        // totalStudentNo: getSectionCapacityLimit(sec), // 原人数上限，改计划人数（不含预留）
        weeklyHours,
        totalTeachingHours: totalTeachingHours > 0 ? Math.round(totalTeachingHours * 100) / 100 : '—',
        hoursCombinedWithCode,
        coordinatorName: coordName,
        coordinatorEmail: coordId || coordName !== '—'
          ? resolveOfferingTeacherEmail(coordId, coordName)
          : '—',
        coTeachingStaff: coTeaching.length ? coTeaching.map(t => t.name).join('、') : '—',
        coTeachingStaffEmails: coTeaching.length ? coTeaching.map(t => t.email).join('、') : '—',
        coTeachingStaffList: coTeaching
      };
    })
    .sort((a, b) => String(a.code).localeCompare(String(b.code), 'zh'));
}

function computeTeacherCourseConfirmationSnapshotHash(rows) {
  return JSON.stringify(rows || []);
}

function syncTeacherCourseConfirmationPackageRows(teacherId, termCode) {
  const pkg = ensureTeacherCourseConfirmationPackage(teacherId, termCode);
  if (!pkg) return null;
  migrateTeacherCourseConfirmationPackageSectionStates(pkg);
  const rows = buildTeacherCourseConfirmationRows(teacherId, termCode);
  pkg.teacherName = resolveOfferingTeacherDisplayName(teacherId, pkg.teacherName);
  pkg.rows = rows;
  const states = ensureTeacherCourseConfirmationSectionStates(pkg);
  if (!rows.length) {
    pkg.sectionStates = {};
    recomputeTeacherCourseConfirmationPackageStatus(pkg);
    pkg.snapshotHash = '';
    return pkg;
  }
  const liveIds = new Set(rows.map(r => r.sectionId).filter(Boolean));
  Object.keys(states).forEach(sid => {
    if (!liveIds.has(sid)) {
      delete states[sid];
      return;
    }
    const st = states[sid];
    if (!st) return;
    if ((st.status === 'confirmed' || st.status === 'admin-proxy')
      && !isTeacherCourseConfirmationSectionSnapshotCurrent(pkg, sid)) {
      st.status = 'pending';
      st.confirmedBy = null;
      st.confirmedAt = null;
      st.proxyBy = null;
      pushTeacherCourseConfirmationHistory(pkg, {
        type: 'invalidated',
        reason: 'arrangement-changed',
        operator: '系统',
        sectionIds: [sid]
      });
    } else if (st.status === 'pending') {
      repairSpuriousTeacherCourseConfirmationInvalidation(pkg, sid, st);
    }
  });
  recomputeTeacherCourseConfirmationPackageStatus(pkg);
  pkg.snapshotHash = computeTeacherCourseConfirmationSnapshotHash(rows);
  return pkg;
}

function isTeacherCourseConfirmationSnapshotCurrent(pkg) {
  if (!pkg) return false;
  migrateTeacherCourseConfirmationPackageSectionStates(pkg);
  const states = ensureTeacherCourseConfirmationSectionStates(pkg);
  const pendingIds = Object.keys(states).filter(id => states[id]?.status === 'pending');
  if (pendingIds.length) {
    return pendingIds.every(id => isTeacherCourseConfirmationSectionSnapshotCurrent(pkg, id));
  }
  const rows = buildTeacherCourseConfirmationRows(pkg.teacherId, pkg.termCode);
  return computeTeacherCourseConfirmationSnapshotHash(rows) === computeTeacherCourseConfirmationSnapshotHash(pkg.rows);
}

function pushTeacherCourseConfirmationHistory(pkg, entry) {
  if (!pkg) return;
  if (!Array.isArray(pkg.history)) pkg.history = [];
  pkg.history.push({ at: new Date().toISOString(), ...entry });
}

function normalizeTeacherCourseConfirmationSectionIds(sectionIds, rows) {
  if (sectionIds == null) return null;
  const idSet = new Set((Array.isArray(sectionIds) ? sectionIds : [sectionIds]).map(String).filter(Boolean));
  if (!idSet.size) return [];
  return (rows || []).filter(r => idSet.has(String(r.sectionId)));
}

/** 发送授课确认：同步发邮件提示（二次确认弹窗 hint） */
const TEACHER_COURSE_CONFIRMATION_ISSUE_EMAIL_HINT = '系统将同步向对应教师发送确认邮件。';

/** 发送授课确认二次确认文案（message 不含邮件句；邮件见 TEACHER_COURSE_CONFIRMATION_ISSUE_EMAIL_HINT） */
function buildTeacherCourseConfirmationIssueConfirmMessage({
  count = 1,
  reissueCount = 0,
  scope = 'one'
} = {}) {
  if (scope === 'section-batch') {
    return reissueCount
      ? `确定向本课程 ${count} 位教师发送授课确认？其中 ${reissueCount} 位将重新下发并清除该课程当前确认状态。`
      : `确定向本课程 ${count} 位教师发送授课确认？`;
  }
  if (scope === 'admin-batch') {
    return reissueCount
      ? `确定发送 ${count} 条课程的授课确认？其中 ${reissueCount} 条将重新下发并清除该课程当前确认状态。`
      : `确定发送 ${count} 条课程的授课确认？`;
  }
  if (reissueCount) {
    return '确定重新下发该课程的确认？将清除该课程当前确认状态。';
  }
  return '确定发送该课程的授课确认？';
}

function openTeacherCourseConfirmationIssueConfirm({
  count = 1,
  reissueCount = 0,
  scope = 'one',
  onConfirm
} = {}) {
  const message = buildTeacherCourseConfirmationIssueConfirmMessage({ count, reissueCount, scope });
  openDeleteConfirm({
    title: reissueCount ? '二次确认：重新发送授课确认' : '二次确认：发送授课确认',
    message: escapeHtml(message),
    emailHint: TEACHER_COURSE_CONFIRMATION_ISSUE_EMAIL_HINT,
    confirmLabel: '确定发送',
    onConfirm: typeof onConfirm === 'function' ? onConfirm : null
  });
}

function issueTeacherCourseConfirmation(teacherId, termCode, { reissue = false, quiet = false, sectionIds = null } = {}) {
  if (isOfferingTbcTeacher(teacherId)) {
    if (!quiet) alert('TBC 为占位教师，无需下发授课确认。');
    return false;
  }
  const pkg = syncTeacherCourseConfirmationPackageRows(teacherId, termCode);
  if (!pkg?.rows?.length) {
    if (!quiet) alert('该教师本学期暂无专业开课授课安排，无法下发确认。');
    return false;
  }
  const rows = buildTeacherCourseConfirmationRows(teacherId, termCode);
  pkg.rows = rows;
  const targets = sectionIds == null
    ? rows
    : normalizeTeacherCourseConfirmationSectionIds(sectionIds, rows);
  if (!targets.length) {
    if (!quiet) alert('未找到可下发的课程。');
    return false;
  }
  const states = ensureTeacherCourseConfirmationSectionStates(pkg);
  targets.forEach(row => {
    states[row.sectionId] = {
      status: 'pending',
      confirmedBy: null,
      confirmedAt: null,
      proxyBy: null,
      feedback: '',
      snapshotHash: computeTeacherCourseConfirmationSnapshotHash([row])
    };
  });
  recomputeTeacherCourseConfirmationPackageStatus(pkg);
  pkg.snapshotHash = computeTeacherCourseConfirmationSnapshotHash(rows);
  pushTeacherCourseConfirmationHistory(pkg, {
    type: reissue ? 'reissued' : 'issued',
    by: 'admin',
    operator: '教务管理员',
    sectionIds: targets.map(r => r.sectionId),
    courseCodes: targets.map(r => r.code)
  });
  return true;
}

function confirmTeacherCourseConfirmation(teacherId, termCode, {
  by = 'teacher',
  proxyBy = '',
  quiet = false,
  sectionIds = null
} = {}) {
  const pkg = getTeacherCourseConfirmationPackage(teacherId, termCode)
    || syncTeacherCourseConfirmationPackageRows(teacherId, termCode);
  if (!pkg) {
    if (!quiet) alert('当前无可确认的授课安排任务。');
    return false;
  }
  migrateTeacherCourseConfirmationPackageSectionStates(pkg);
  const states = ensureTeacherCourseConfirmationSectionStates(pkg);
  const candidateIds = sectionIds == null
    ? Object.keys(states).filter(id => states[id]?.status === 'pending')
    : (Array.isArray(sectionIds) ? sectionIds : [sectionIds]).map(String).filter(Boolean);
  const targets = candidateIds.filter(id => states[id]?.status === 'pending');
  if (!targets.length) {
    if (!quiet) alert('当前无可确认的授课安排任务。');
    return false;
  }
  for (const sid of targets) {
    if (!isTeacherCourseConfirmationSectionSnapshotCurrent(pkg, sid)) {
      if (!quiet) alert('授课安排已变更，请教务重新下发确认后再操作。');
      return false;
    }
  }
  const now = new Date().toISOString();
  const confirmedBy = by === 'admin-proxy' ? 'admin-proxy' : 'teacher';
  const liveRows = buildTeacherCourseConfirmationRows(teacherId, termCode);
  targets.forEach(sid => {
    const row = (pkg.rows || []).find(r => r.sectionId === sid)
      || liveRows.find(r => r.sectionId === sid);
    states[sid] = {
      status: confirmedBy === 'admin-proxy' ? 'admin-proxy' : 'confirmed',
      confirmedBy,
      confirmedAt: now,
      proxyBy: by === 'admin-proxy' ? (proxyBy || '教务管理员') : null,
      feedback: '',
      snapshotHash: row
        ? computeTeacherCourseConfirmationSnapshotHash([row])
        : (states[sid]?.snapshotHash || '')
    };
  });
  recomputeTeacherCourseConfirmationPackageStatus(pkg);
  pushTeacherCourseConfirmationHistory(pkg, {
    type: 'confirmed',
    confirmedBy,
    proxyBy: by === 'admin-proxy' ? (proxyBy || '教务管理员') : null,
    operator: by === 'admin-proxy'
      ? (proxyBy || '教务管理员')
      : (pkg.teacherName || resolveOfferingTeacherDisplayName(teacherId) || '教师'),
    sectionIds: targets,
    courseCodes: targets.map(sid => {
      const row = (pkg.rows || []).find(r => r.sectionId === sid)
        || liveRows.find(r => r.sectionId === sid);
      return row?.code || sid;
    })
  });
  return true;
}

function disagreeTeacherCourseConfirmation(teacherId, termCode, feedback, { sectionIds = null } = {}) {
  const text = String(feedback || '').trim();
  if (!text) {
    alert('请填写不同意原因或诉求。');
    return false;
  }
  const pkg = getTeacherCourseConfirmationPackage(teacherId, termCode);
  if (!pkg) {
    alert('当前无可操作的授课确认任务。');
    return false;
  }
  migrateTeacherCourseConfirmationPackageSectionStates(pkg);
  const states = ensureTeacherCourseConfirmationSectionStates(pkg);
  const candidateIds = sectionIds == null
    ? Object.keys(states).filter(id => states[id]?.status === 'pending')
    : (Array.isArray(sectionIds) ? sectionIds : [sectionIds]).map(String).filter(Boolean);
  const targets = candidateIds.filter(id => states[id]?.status === 'pending');
  if (!targets.length) {
    alert('当前无可操作的授课确认任务。');
    return false;
  }
  targets.forEach(sid => {
    const prev = states[sid] || {};
    states[sid] = {
      status: 'disagreed',
      confirmedBy: null,
      confirmedAt: null,
      proxyBy: null,
      feedback: text,
      snapshotHash: prev.snapshotHash || ''
    };
  });
  recomputeTeacherCourseConfirmationPackageStatus(pkg);
  pushTeacherCourseConfirmationHistory(pkg, {
    type: 'disagreed',
    feedback: text,
    operator: pkg.teacherName || resolveOfferingTeacherDisplayName(teacherId) || '教师',
    sectionIds: targets,
    courseCodes: targets.map(sid => {
      const row = (pkg.rows || []).find(r => r.sectionId === sid);
      return row?.code || sid;
    })
  });
  return true;
}

function encodeTeacherCourseConfirmationRowKey(staffId, sectionId) {
  return `${String(staffId || '').trim()}||${String(sectionId || '').trim()}`;
}

function parseTeacherCourseConfirmationRowKey(value) {
  const raw = String(value || '');
  const sep = raw.indexOf('||');
  if (sep < 0) return { staffId: raw.trim(), sectionId: '' };
  return {
    staffId: raw.slice(0, sep).trim(),
    sectionId: raw.slice(sep + 2).trim()
  };
}

function getTeacherCourseConfirmationLetterSelectedSectionIds() {
  return [...document.querySelectorAll('.tcc-letter-row-check:checked')]
    .map(el => String(el.value || '').trim())
    .filter(Boolean);
}

function getSectionAssignedTeacherIds(sec) {
  // TBC 非真实教师：不参与授课确认进度与生效确认校验
  return collectSectionAssignTeachers(sec)
    .map(t => t.staffId)
    .filter(id => id && !isOfferingTbcTeacher(id));
}

function getSectionTeacherConfirmationProgress(sec) {
  const termCode = resolveSectionOfferingTermCode(sec);
  const teacherIds = getSectionAssignedTeacherIds(sec);
  const sectionId = sec?.id || sec?.sectionId || '';
  if (!teacherIds.length) {
    return { total: 0, confirmed: 0, pending: 0, disagreed: 0, proxyCount: 0, complete: true, teachers: [] };
  }
  let confirmed = 0;
  let pending = 0;
  let disagreed = 0;
  let proxyCount = 0;
  const teachers = teacherIds.map(id => {
    syncTeacherCourseConfirmationPackageRows(id, termCode);
    const pkg = getTeacherCourseConfirmationPackage(id, termCode);
    const name = resolveOfferingTeacherDisplayName(id);
    const state = sectionId
      ? getTeacherCourseConfirmationSectionStatus(id, termCode, sectionId, pkg)
      : getSectionTeacherConfirmationProgressForTeacher(id, termCode, pkg).status;
    const st = sectionId ? getTeacherCourseConfirmationSectionState(pkg, sectionId) : null;
    if (state === 'confirmed' || state === 'admin-proxy') {
      confirmed += 1;
      if (state === 'admin-proxy') proxyCount += 1;
    } else if (state === 'disagreed') {
      disagreed += 1;
    } else {
      pending += 1;
    }
    return { staffId: id, name, state, feedback: st?.feedback || pkg?.feedback || '' };
  });
  const complete = confirmed === teacherIds.length;
  return { total: teacherIds.length, confirmed, pending, disagreed, proxyCount, complete, teachers };
}

function isSectionTeacherConfirmationComplete(sec) {
  return getSectionTeacherConfirmationProgress(sec).complete;
}

function validateMajorOfferingTaskTeacherConfirmation(sec) {
  const progress = getSectionTeacherConfirmationProgress(sec);
  if (!progress.total) return { ok: true };
  if (progress.complete) return { ok: true };
  const lines = progress.teachers
    .filter(t => t.state !== 'confirmed' && t.state !== 'admin-proxy')
    .map(t => {
      if (t.state === 'disagreed') return `${t.name}：已不同意（${t.feedback || '有诉求'}）`;
      if (t.state === 'pending') return `${t.name}：待确认`;
      return `${t.name}：尚未下发确认`;
    });
  return {
    ok: false,
    message: `授课教师尚未全部确认（${progress.confirmed}/${progress.total}）：\n${lines.map(l => `· ${l}`).join('\n')}`
  };
}

function invalidateTeacherCourseConfirmationsForSection(sec) {
  if (!sec) return;
  const termCode = resolveSectionOfferingTermCode(sec);
  getSectionAssignedTeacherIds(sec).forEach(id => syncTeacherCourseConfirmationPackageRows(id, termCode));
}

/** 演示/联调：为某教学班下发并管理端代确认全部授课教师（静默） */
function seedSectionTeacherCourseConfirmationsComplete(sec) {
  if (!sec?.id) return false;
  const termCode = resolveSectionOfferingTermCode(sec);
  const teacherIds = getSectionAssignedTeacherIds(sec);
  if (!teacherIds.length) return true;
  teacherIds.forEach(id => {
    syncTeacherCourseConfirmationPackageRows(id, termCode);
    issueTeacherCourseConfirmation(id, termCode, {
      quiet: true,
      sectionIds: [sec.id]
    });
    confirmTeacherCourseConfirmation(id, termCode, {
      by: 'admin-proxy',
      proxyBy: '教务管理员',
      quiet: true,
      sectionIds: [sec.id]
    });
  });
  return isSectionTeacherConfirmationComplete(sec);
}

// ── 授课教师替换（已生效开课 · 整行替换） ──
const OFFERING_TEACHER_REPLACE_LOG_KEY = 'pyfa-offering-teacher-replace-log-v1';
const OFFERING_TEACHER_REPLACE_DEMO_VERSION = 'v2';
const OFFERING_TEACHER_REPLACE_TYPE_LABELS = { major: '专业开课', ge: '通识选修' };

let offeringTeacherReplaceFocusSectionId = '';
let offeringTeacherReplacePickerCtx = null; // { sectionId, assignRowId }
let offeringTeacherReplacePendingTeachers = null;
let offeringTeacherReplaceBatchCtx = null; // { sectionId, fromStaffId, toTeacher }
let offeringTeacherReplaceLogStore = null;

function loadOfferingTeacherReplaceLogStore() {
  if (Array.isArray(offeringTeacherReplaceLogStore)) return offeringTeacherReplaceLogStore;
  try {
    const raw = localStorage.getItem(OFFERING_TEACHER_REPLACE_LOG_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    offeringTeacherReplaceLogStore = Array.isArray(parsed) ? parsed : [];
  } catch (_) {
    offeringTeacherReplaceLogStore = [];
  }
  return offeringTeacherReplaceLogStore;
}

function persistOfferingTeacherReplaceLogStore() {
  try {
    localStorage.setItem(OFFERING_TEACHER_REPLACE_LOG_KEY, JSON.stringify(loadOfferingTeacherReplaceLogStore()));
  } catch (err) {
    console.warn('persistOfferingTeacherReplaceLogStore failed', err);
  }
}

function listOfferingTeacherReplaceLogs() {
  return loadOfferingTeacherReplaceLogStore().slice().sort((a, b) =>
    String(b.operatedAt || '').localeCompare(String(a.operatedAt || ''))
  );
}

function appendOfferingTeacherReplaceLog(entry) {
  const store = loadOfferingTeacherReplaceLogStore();
  store.unshift({
    id: `otr-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
    operatedAt: new Date().toISOString(),
    operator: '教务',
    ...entry
  });
  if (store.length > 200) store.length = 200;
  persistOfferingTeacherReplaceLogStore();
}

function isOfferingSectionEligibleForTeacherReplace(sec) {
  if (!sec) return false;
  if (sec.offeringType === 'other') return false;
  if (typeof isTeacherTeachingLoadDemoSection === 'function' && isTeacherTeachingLoadDemoSection(sec)) {
    return false;
  }
  // 与 style2「已生效」一致：任务安排已生效
  return typeof isMajorOfferingTaskArrangementSubmitted === 'function'
    && isMajorOfferingTaskArrangementSubmitted(sec);
}

function getEffectiveOfferingSectionsForTeacherReplace(termCode) {
  const term = normalizeOfferingTermCode(
    termCode
      || document.getElementById('otr-filter-term')?.value
      || getDefaultOfferingTermCode()
      || ''
  );
  const sections = typeof getOfferingSectionsForTerm === 'function'
    ? getOfferingSectionsForTerm(term)
    : [];
  return sections
    .filter(isOfferingSectionEligibleForTeacherReplace)
    .filter(sec => sec.offeringType === 'major' || sec.offeringType === 'ge')
    .slice()
    .sort((a, b) =>
      String(a.code || '').localeCompare(String(b.code || ''), 'zh-CN', { numeric: true })
      || String(a.id || '').localeCompare(String(b.id || ''))
    );
}

function findOfferingSectionByIdForTeacherReplace(sectionId) {
  const id = String(sectionId || '');
  if (!id) return null;
  if (COURSE_OFFERING_PLAN_STORE?.sections) {
    const hit = COURSE_OFFERING_PLAN_STORE.sections.find(s => s.id === id);
    if (hit) return hit;
  }
  for (const store of Object.values(COURSE_OFFERING_PLAN_BY_TERM || {})) {
    const hit = (store?.sections || []).find(s => s.id === id);
    if (hit) return hit;
  }
  return null;
}

function getOfferingTeacherReplaceSectionUnit(sec) {
  if (!sec) return '';
  if (sec.offeringType === 'ge' && typeof resolveGeOfferingSectionOfferingUnit === 'function') {
    return resolveGeOfferingSectionOfferingUnit(sec) || '';
  }
  if (typeof resolveMajorOfferingSectionOfferingUnit === 'function') {
    return resolveMajorOfferingSectionOfferingUnit(sec) || '';
  }
  return sec.offeringUnitAbbr || '';
}

function getOfferingTeacherReplaceAssignRows(sec) {
  if (!sec) return [];
  if (typeof sanitizeSectionGroupAssignments === 'function') sanitizeSectionGroupAssignments(sec);
  return (sec.groupAssignments || []).slice();
}

function mapOfferingTeacherReplaceAssignRowView(sec, row, idx) {
  const teachers = typeof getGroupAssignTeachers === 'function' ? getGroupAssignTeachers(row) : [];
  return {
    row,
    idx,
    assignRowId: row.id || `idx-${idx}`,
    groupLabel: typeof formatGroupAssignGroupsSummaryCell === 'function'
      ? formatGroupAssignGroupsSummaryCell(row, sec)
      : '—',
    groupLabelText: typeof getGroupAssignRowGroupLabels === 'function'
      ? (getGroupAssignRowGroupLabels(row, sec).join('、') || '—')
      : '—',
    hourTypeLabel: typeof getGroupAssignHourTypeDisplayLabel === 'function'
      ? (getGroupAssignHourTypeDisplayLabel(sec, row.hourType) || '—')
      : (row.hourType || '—'),
    weekRange: typeof clampGroupAssignWeekRangeToSection === 'function'
      ? (clampGroupAssignWeekRangeToSection(sec, row.weekRange) || row.weekRange || '—')
      : (row.weekRange || '—'),
    weeklyHours: typeof formatGroupAssignWeeklyHoursDisplay === 'function'
      ? formatGroupAssignWeeklyHoursDisplay(row)
      : (row.weeklyHours ?? '—'),
    totalHours: typeof formatGroupAssignRowTotalHoursDisplay === 'function'
      ? formatGroupAssignRowTotalHoursDisplay(row, sec)
      : (row.totalHours ?? '—'),
    teachers,
    teacherNames: teachers.map(t => t.name).filter(Boolean).join('、') || '—',
    simultaneous: !!row.simultaneousGroups
  };
}

function rebuildOfferingTeacherReplaceUnitFilter(sections) {
  const sel = document.getElementById('otr-filter-unit');
  if (!sel) return;
  const cur = sel.value || '';
  const units = [...new Set((sections || []).map(getOfferingTeacherReplaceSectionUnit).filter(Boolean))].sort();
  sel.innerHTML = '<option value="">全部开课单位</option>' +
    units.map(u => `<option value="${escapeHtml(u)}">${escapeHtml(u)}</option>`).join('');
  if (cur && units.includes(cur)) sel.value = cur;
}

function getFilteredOfferingTeacherReplaceSections() {
  const term = normalizeOfferingTermCode(
    document.getElementById('otr-filter-term')?.value || getDefaultOfferingTermCode() || ''
  );
  const unit = document.getElementById('otr-filter-unit')?.value || '';
  const codeQ = (document.getElementById('otr-filter-code')?.value || '').trim().toLowerCase();
  return getEffectiveOfferingSectionsForTeacherReplace(term).filter(sec => {
    if (unit && getOfferingTeacherReplaceSectionUnit(sec) !== unit) return false;
    if (codeQ && !(sec.code || '').toLowerCase().includes(codeQ)) return false;
    return true;
  });
}

function formatOfferingTeacherReplaceSectionTeachersSummary(sec) {
  const byId = new Map();
  getOfferingTeacherReplaceAssignRows(sec).forEach(row => {
    (typeof getGroupAssignTeachers === 'function' ? getGroupAssignTeachers(row) : []).forEach(t => {
      const staffId = String(t?.staffId || '').trim();
      const name = String(t?.name || staffId || '').trim();
      if (!name) return;
      const key = staffId || name;
      if (!byId.has(key)) byId.set(key, { staffId, name });
    });
  });
  const teachers = [...byId.values()];
  if (!teachers.length) return '—';
  return `<span class="otr-teacher-summary">${teachers.map(t => {
    if (!t.staffId) {
      return `<span class="otr-teacher-summary-line">${escapeHtml(t.name)}</span>`;
    }
    return `<button type="button" class="offering-group-status-teacher-link otr-teacher-summary-line"
      title="查看课时详情"
      onclick="event.stopPropagation();openOfferingTeacherTermAssignModal('${escapeHtml(t.staffId)}')">${escapeHtml(t.name)}</button>`;
  }).join('')}</span>`;
}

function onOfferingTeacherReplaceTermChange() {
  const term = normalizeOfferingTermCode(document.getElementById('otr-filter-term')?.value || '');
  if (term && typeof syncCourseOfferingPlanStoreFromTerm === 'function') {
    syncCourseOfferingPlanStoreFromTerm(term);
  }
  offeringTeacherReplaceFocusSectionId = '';
  rebuildOfferingTeacherReplaceUnitFilter(getEffectiveOfferingSectionsForTeacherReplace(term));
  renderOfferingTeacherReplacePage();
}

function queryOfferingTeacherReplacePage() {
  resetListPage('offeringTeacherReplace');
  renderOfferingTeacherReplacePage();
}

function resetOfferingTeacherReplaceFilters() {
  rebuildOfferingTermFilterSelect('otr-filter-term', { preserveValue: false });
  const codeEl = document.getElementById('otr-filter-code');
  if (codeEl) codeEl.value = '';
  const unitEl = document.getElementById('otr-filter-unit');
  if (unitEl) unitEl.value = '';
  offeringTeacherReplaceFocusSectionId = '';
  onOfferingTeacherReplaceTermChange();
}

function clearOfferingTeacherReplaceDetail() {
  offeringTeacherReplaceFocusSectionId = '';
  renderOfferingTeacherReplaceCourseList();
}

function toggleOfferingTeacherReplaceExpand(sectionId, event) {
  event?.stopPropagation?.();
  event?.preventDefault?.();
  const id = String(sectionId || '');
  if (!id) return;
  offeringTeacherReplaceFocusSectionId = offeringTeacherReplaceFocusSectionId === id ? '' : id;
  renderOfferingTeacherReplaceCourseList();
}

function selectOfferingTeacherReplaceSection(sectionId) {
  toggleOfferingTeacherReplaceExpand(sectionId);
}

function renderOfferingTeacherReplaceAssignPanel(sec) {
  if (!sec || !isOfferingSectionEligibleForTeacherReplace(sec)) {
    return `<div class="offering-grouping-global-assign-empty"><span class="text-muted">暂无开课安排明细</span></div>`;
  }
  const rows = getOfferingTeacherReplaceAssignRows(sec).map((row, idx) =>
    mapOfferingTeacherReplaceAssignRowView(sec, row, idx)
  );
  const body = rows.length
    ? rows.map(view => `<tr>
        <td class="col-index col-center">${view.idx + 1}</td>
        <td class="col-groups">${view.groupLabel}</td>
        <td class="col-center col-hour-type">${escapeHtml(view.hourTypeLabel)}</td>
        <td class="col-center col-week"><code>${escapeHtml(view.weekRange)}</code></td>
        <td class="col-center col-weekly">${escapeHtml(String(view.weeklyHours))}</td>
        <td class="col-center col-plan-total">${escapeHtml(String(view.totalHours))}</td>
        <td class="col-teacher">${typeof formatGroupAssignTeachersSummaryCell === 'function'
          ? formatGroupAssignTeachersSummaryCell(view.row)
          : escapeHtml(view.teacherNames)}</td>
        <td class="col-center col-simul">${view.simultaneous ? '是' : '否'}</td>
        <td class="col-center col-classroom-attr">${escapeHtml(formatAssignClassroomAttributeDisplay(view.row.classroomAttribute))}</td>
        <td class="col-center col-classroom-pref">${formatAssignClassroomPreferenceCellHtml(view.row.classroomPreferences, view.row.classroomAttribute)}</td>
        <td class="actions col-center col-sticky-actions">
          <a href="#" onclick="openOfferingTeacherReplacePicker('${escapeHtml(sec.id)}','${escapeHtml(view.assignRowId)}');return false">替换教师</a>
        </td>
      </tr>`).join('')
    : '<tr><td colspan="11" class="text-muted" style="text-align:center;padding:20px">暂无开课安排明细</td></tr>';
  return `<div class="offering-grouping-global-assign-panel otr-assign-panel">
    <div class="offering-grouping-global-assign-head">
      <strong>开课安排明细</strong>
      <span class="form-hint">整行替换：不改起止周、学时类型与学时</span>
      <div class="otr-assign-head-actions">
        <button type="button" class="btn btn-primary btn-sm" onclick="openOfferingTeacherReplaceBatchModal('${escapeHtml(sec.id)}')">一键替换</button>
        <button type="button" class="btn btn-outline btn-sm" onclick="clearOfferingTeacherReplaceDetail()">收起</button>
      </div>
    </div>
    <div class="offering-grouping-global-assign-table-wrap">
      <table class="data-table compact offering-grouping-global-assign-table otr-assign-table">
        <thead>
          <tr>
            <th class="col-center col-index">序号</th>
            <th class="col-groups">课程班/小组</th>
            <th class="col-center col-hour-type">学时类型</th>
            <th class="col-center col-week">起止周</th>
            <th class="col-center col-weekly">周学时</th>
            <th class="col-center col-plan-total">总学时</th>
            <th class="col-teacher">教师</th>
            <th class="col-center col-simul">同时授课</th>
            <th class="col-center col-classroom-attr">场地类型</th>
            <th class="col-center col-classroom-pref">教室偏好</th>
            <th class="col-center col-sticky-actions">操作</th>
          </tr>
        </thead>
        <tbody>${body}</tbody>
      </table>
    </div>
  </div>`;
}

function renderOfferingTeacherReplaceCourseList() {
  const tbody = document.getElementById('otr-course-body');
  if (!tbody) return;
  const list = getFilteredOfferingTeacherReplaceSections();
  const paged = paginateListItems(list, 'offeringTeacherReplace');
  const colCount = 10;
  tbody.innerHTML = paged.items.length
    ? paged.items.map((sec) => {
      const termCode = resolveSectionOfferingTermCode(sec);
      const typeLabel = OFFERING_TEACHER_REPLACE_TYPE_LABELS[sec.offeringType] || sec.offeringType || '—';
      const expanded = sec.id === offeringTeacherReplaceFocusSectionId;
      const isGe = sec.offeringType === 'ge';
      const progCell = isGe
        ? '-'
        : formatEllipsisTipCell(
          getSectionMergedProgrammeDisplay(sec),
          getSectionMergedProgrammeDisplayFull(sec)
        );
      const intakeCell = isGe
        ? '-'
        : formatEllipsisTipCell(
          getSectionMergedIntakeDisplay(sec),
          getSectionMergedIntakeDisplayFull(sec)
        );
      const mainRow = `<tr class="otr-course-main-row${expanded ? ' is-expanded is-selected' : ''}">
        <td class="col-center">${escapeHtml(formatCourseTermDisplay(termCode) || termCode || '—')}</td>
        <td class="col-center">${escapeHtml(typeLabel)}</td>
        <td class="col-center col-code"><strong>${escapeHtml(sec.code || '—')}</strong></td>
        <td>${escapeHtml(sec.name || '—')}</td>
        <td class="col-center col-prog">${progCell}</td>
        <td class="col-center col-intake">${intakeCell}</td>
        <td class="col-center col-enrollment-type">${renderMajorOfferingEnrollmentTypeDisplay(sec)}</td>
        <td class="col-center"><code>${escapeHtml(getOfferingTeacherReplaceSectionUnit(sec) || '—')}</code></td>
        <td class="col-teachers">${formatOfferingTeacherReplaceSectionTeachersSummary(sec)}</td>
        <td class="actions col-sticky-actions">
          <a href="#" onclick="toggleOfferingTeacherReplaceExpand('${escapeHtml(sec.id)}', event);return false">详情</a>
          <span class="mot-style2-action-sep" aria-hidden="true">·</span>
          <a href="#" onclick="event.preventDefault();openTeacherCourseConfirmationSectionManageModal('${escapeHtml(sec.id)}');return false">授课确认</a>
        </td>
      </tr>`;
      if (!expanded) return mainRow;
      return `${mainRow}
      <tr class="offering-grouping-global-detail-row otr-detail-row">
        <td colspan="${colCount}">${renderOfferingTeacherReplaceAssignPanel(sec)}</td>
      </tr>`;
    }).join('')
    : `<tr><td colspan="${colCount}" class="text-muted" style="text-align:center;padding:24px">暂无已生效开课可替换；请先在「开课安排」完成任务安排生效</td></tr>`;
  renderListPagination('otr-course-pagination', 'offeringTeacherReplace', paged.total);
  bindCellFloatTips(tbody, '.cell-ellipsis-tip[data-tip]');
}

function renderOfferingTeacherReplaceDetail() {
  // 明细已并入课程行下展开子表；保留空函数以免旧调用报错
}

function renderOfferingTeacherReplaceLog() {
  const tbody = document.getElementById('otr-log-body');
  if (!tbody) return;
  const logs = listOfferingTeacherReplaceLogs().slice(0, 30);
  tbody.innerHTML = logs.length
    ? logs.map((log, idx) => {
      const when = log.operatedAt ? new Date(log.operatedAt).toLocaleString('zh-CN', { hour12: false }) : '—';
      const rowLabel = [log.groupLabel, log.hourType, log.weekRange].filter(Boolean).join(' · ') || '—';
      return `<tr>
        <td class="col-index">${idx + 1}</td>
        <td class="col-center">${escapeHtml(when)}</td>
        <td class="col-center">${escapeHtml(formatCourseTermDisplay(log.termCode) || log.termCode || '—')}</td>
        <td><strong>${escapeHtml(log.code || '—')}</strong></td>
        <td>${escapeHtml(rowLabel)}</td>
        <td>${escapeHtml((log.fromTeachers || []).join('、') || '—')}</td>
        <td>${escapeHtml((log.toTeachers || []).join('、') || '—')}</td>
      </tr>`;
    }).join('')
    : '<tr><td colspan="7" class="text-muted" style="text-align:center;padding:16px">暂无替换记录</td></tr>';
}

function setOfferingTeacherReplaceTab(tab) {
  const key = tab === 'log' ? 'log' : 'replace';
  const page = document.getElementById('page-course-offering-teacher-replace');
  if (!page) return;
  page.querySelectorAll('[data-otr-tab]').forEach(btn => {
    const on = btn.getAttribute('data-otr-tab') === key;
    btn.classList.toggle('active', on);
    btn.setAttribute('aria-selected', on ? 'true' : 'false');
  });
  page.querySelectorAll('[data-otr-panel]').forEach(panel => {
    panel.classList.toggle('active', panel.getAttribute('data-otr-panel') === key);
  });
  if (key === 'log') renderOfferingTeacherReplaceLog();
}

function renderOfferingTeacherReplacePage() {
  ensureTeacherReplaceDemoEffectiveSections();
  rebuildOfferingTermFilterSelect('otr-filter-term');
  const term = normalizeOfferingTermCode(
    document.getElementById('otr-filter-term')?.value || getDefaultOfferingTermCode() || ''
  );
  if (term && typeof syncCourseOfferingPlanStoreFromTerm === 'function') {
    syncCourseOfferingPlanStoreFromTerm(term);
  }
  rebuildOfferingTeacherReplaceUnitFilter(getEffectiveOfferingSectionsForTeacherReplace(term));
  renderOfferingTeacherReplaceCourseList();
  renderOfferingTeacherReplaceLog();
}

function openOfferingTeacherReplacePicker(sectionId, assignRowId) {
  const sec = findOfferingSectionByIdForTeacherReplace(sectionId);
  if (!sec || !isOfferingSectionEligibleForTeacherReplace(sec)) {
    alert('该开课任务未生效，无法在此替换教师。');
    return;
  }
  const row = getOfferingTeacherReplaceAssignRows(sec).find(r => r.id === assignRowId);
  if (!row) {
    alert('未找到对应安排行。');
    return;
  }
  offeringTeacherReplacePickerCtx = { sectionId: sec.id, assignRowId };
  offeringTeacherReplacePendingTeachers = null;
  offeringGroupingSectionId = sec.id;
  teacherPickerContext = 'teacherReplace';
  majorOfferingTeacherPickerSelected.clear();
  const titleEl = document.getElementById('teacher-picker-title');
  if (titleEl) {
    const unit = getOfferingTeacherReplaceSectionUnit(sec);
    const supportUnits = typeof getMajorOfferingSectionSupportUnits === 'function'
      ? getMajorOfferingSectionSupportUnits(sec)
      : [];
    if (unit && supportUnits.length) {
      titleEl.textContent = `替换授课教师（整行 · 开课单位：${unit}；Support：${supportUnits.join('、')}）`;
    } else if (unit) {
      titleEl.textContent = `替换授课教师（整行 · 开课单位：${unit}）`;
    } else {
      titleEl.textContent = '替换授课教师（整行）';
    }
  }
  resetListPage('majorOfferingTeacherPicker');
  ['teacher-picker-filter-staff-id', 'teacher-picker-filter-name'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  ['teacher-picker-filter-type', 'teacher-picker-filter-gender'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  ensureMajorOfferingTeacherPickerDeptFilter();
  if (typeof syncGroupAssignTeacherPickerOfferingUnitFilter === 'function') {
    syncGroupAssignTeacherPickerOfferingUnitFilter();
  }
  if (typeof syncTeacherPickerSimultaneousVisibility === 'function') {
    syncTeacherPickerSimultaneousVisibility();
  }
  if (typeof syncTeacherPickerAssignContext === 'function') syncTeacherPickerAssignContext();
  // 预勾选当前行教师
  const pool = buildMockTeacherPickerPool();
  getGroupAssignTeachers(row).forEach(t => {
    const pick = pool.find(p => p.staffId === t.staffId);
    if (pick?.key) majorOfferingTeacherPickerSelected.add(pick.key);
  });
  renderMajorOfferingTeacherPickerModal();
  openModal('modal-major-teacher-picker');
}

function prepareOfferingTeacherReplaceFromPicker() {
  const ctx = offeringTeacherReplacePickerCtx;
  if (!ctx?.sectionId || !ctx?.assignRowId) return false;
  const keys = [...majorOfferingTeacherPickerSelected];
  if (!keys.length) {
    alert('请至少勾选一名教师。');
    return false;
  }
  const sec = findOfferingSectionByIdForTeacherReplace(ctx.sectionId);
  if (!sec) return false;
  const allowedUnits = typeof getGroupAssignTeacherPickerAllowedUnits === 'function'
    ? getGroupAssignTeacherPickerAllowedUnits()
    : [];
  const poolMap = new Map(buildMockTeacherPickerPool().map(t => [t.key, t]));
  const nextTeachers = [];
  const seen = new Set();
  keys.forEach(key => {
    const pick = poolMap.get(key);
    if (!pick || seen.has(pick.staffId)) return;
    if (!isOfferingTbcTeacher(pick) && allowedUnits.length && !allowedUnits.includes(pick.departmentCode)) return;
    nextTeachers.push(enrichGroupAssignFormTeacher({
      staffId: pick.staffId,
      name: pick.name,
      teacherType: pick.teacherType,
      departmentCode: pick.departmentCode
    }, sec));
    seen.add(pick.staffId);
  });
  if (!nextTeachers.length) {
    alert('所选教师不在开课单位 / Support 范围内，请重新选择。');
    return false;
  }
  offeringTeacherReplacePendingTeachers = nextTeachers;
  closeModal('modal-major-teacher-picker');
  majorOfferingTeacherPickerSelected.clear();
  teacherPickerContext = null;
  const row = getOfferingTeacherReplaceAssignRows(sec).find(r => r.id === ctx.assignRowId);
  const fromNames = getGroupAssignTeachers(row).map(t => formatOfferingTeacherNameForDisplay(t)).filter(Boolean).join('、') || '—';
  const toNames = nextTeachers.map(t => formatOfferingTeacherNameForDisplay(t)).filter(Boolean).join('、') || '—';
  const week = row
    ? (clampGroupAssignWeekRangeToSection(sec, row.weekRange) || row.weekRange || '—')
    : '—';
  openDeleteConfirm({
    title: '确认整行替换教师',
    message: `将把该安排行教师由 <strong>${escapeHtml(fromNames)}</strong> 替换为 <strong>${escapeHtml(toNames)}</strong>。`,
    hint: `整行起止周（${week}）内教师一并替换，不可按周拆分；学时类型、周学时、总学时、同时授课等其它字段保持不变。生效状态保持「已生效」；授课确认按替换后教师状态更新，需重新下发/确认。`,
    hintWarn: true,
    emailHint: '系统将向被替换教师发送邮件，通知其原有安排的调整或取消。',
    confirmLabel: '确认替换',
    onConfirm: () => applyOfferingTeacherReplacePending()
  });
  return true;
}

function applyOfferingTeacherReplacePending() {
  const ctx = offeringTeacherReplacePickerCtx;
  const nextTeachers = offeringTeacherReplacePendingTeachers;
  offeringTeacherReplacePendingTeachers = null;
  offeringTeacherReplacePickerCtx = null;
  if (!ctx || !nextTeachers?.length) return;
  const sec = findOfferingSectionByIdForTeacherReplace(ctx.sectionId);
  if (!sec || !isOfferingSectionEligibleForTeacherReplace(sec)) {
    alert('目标开课任务不可用或已失效。');
    return;
  }
  const row = getOfferingTeacherReplaceAssignRows(sec).find(r => r.id === ctx.assignRowId);
  if (!row) {
    alert('未找到对应安排行。');
    return;
  }
  const fromTeachers = getGroupAssignTeachers(row).map(t => ({ ...t }));
  const fromNames = fromTeachers.map(t => t.name).filter(Boolean);
  const toNames = nextTeachers.map(t => t.name).filter(Boolean);
  const view = mapOfferingTeacherReplaceAssignRowView(sec, row, 0);
  // 整行仅替换 teachers；其它字段不动
  row.teachers = nextTeachers.map(t => ({ ...t }));
  row.teacher = toNames.join('、');
  row.staffId = nextTeachers.map(t => t.staffId).filter(Boolean).join('、');
  row.role = nextTeachers.map(t => t.role).filter(Boolean).join('、');
  appendOfferingTeacherReplaceLog({
    termCode: resolveSectionOfferingTermCode(sec),
    sectionId: sec.id,
    assignmentRowId: row.id,
    code: sec.code,
    courseName: sec.name,
    groupLabel: view.groupLabelText,
    hourType: view.hourTypeLabel,
    weekRange: view.weekRange,
    fromTeachers: fromNames,
    toTeachers: toNames
  });
  // 仅同步被替换进出的教师确认态；同课其他教师不因共同授课名单变化而失效
  const termCode = resolveSectionOfferingTermCode(sec);
  const touchedIds = new Set([
    ...fromTeachers.map(t => t.staffId),
    ...nextTeachers.map(t => t.staffId)
  ].filter(Boolean));
  touchedIds.forEach(id => syncTeacherCourseConfirmationPackageRows(id, termCode));
  offeringTeacherReplaceFocusSectionId = sec.id;
  renderOfferingTeacherReplacePage();
  if (typeof renderCourseMajorOfferingTaskStyle2Page === 'function') {
    renderCourseMajorOfferingTaskStyle2Page();
  }
  if (typeof renderCourseMajorOfferingTaskPage === 'function') {
    renderCourseMajorOfferingTaskPage();
  }
  alert('已整行替换教师。生效状态保持「已生效」；请按新教师重新下发/确认授课。');
}

function listOfferingTeacherReplaceSectionTeachers(sec) {
  const map = new Map();
  getOfferingTeacherReplaceAssignRows(sec).forEach(row => {
    getGroupAssignTeachers(row).forEach(t => {
      const id = String(t?.staffId || '').trim();
      if (!id || map.has(id)) return;
      map.set(id, {
        staffId: id,
        name: formatOfferingTeacherNameForDisplay(t) || t.name || id
      });
    });
  });
  return [...map.values()].sort((a, b) =>
    String(a.name).localeCompare(String(b.name), 'zh')
    || String(a.staffId).localeCompare(String(b.staffId))
  );
}

function countOfferingTeacherReplaceRowsWithTeacher(sec, staffId) {
  const id = String(staffId || '').trim();
  if (!id) return 0;
  return getOfferingTeacherReplaceAssignRows(sec)
    .filter(row => getGroupAssignTeachers(row).some(t => String(t?.staffId || '') === id))
    .length;
}

function syncOfferingTeacherReplaceRowTeacherFields(row, teachers) {
  const list = (teachers || []).map(t => ({ ...t }));
  row.teachers = list;
  row.teacher = list.map(t => formatOfferingTeacherNameForDisplay(t) || t.name || '').filter(Boolean).join('、');
  row.staffId = list.map(t => t.staffId).filter(Boolean).join('、');
  row.role = list.map(t => t.role).filter(Boolean).join('、');
}

function openOfferingTeacherReplaceBatchModal(sectionId) {
  const sec = findOfferingSectionByIdForTeacherReplace(sectionId);
  if (!sec || !isOfferingSectionEligibleForTeacherReplace(sec)) {
    alert('该开课任务未生效，无法在此替换教师。');
    return;
  }
  const teachers = listOfferingTeacherReplaceSectionTeachers(sec);
  if (!teachers.length) {
    alert('本课程暂无已安排教师，无法一键替换。');
    return;
  }
  offeringTeacherReplaceBatchCtx = {
    sectionId: sec.id,
    fromStaffId: teachers[0].staffId,
    toTeacher: null
  };
  offeringGroupingSectionId = sec.id;
  const titleEl = document.getElementById('otr-batch-replace-title');
  if (titleEl) titleEl.textContent = `一键替换教师 · ${sec.code || ''}`.trim();
  const metaEl = document.getElementById('otr-batch-replace-meta');
  if (metaEl) {
    const term = formatCourseTermDisplay(resolveSectionOfferingTermCode(sec)) || '—';
    metaEl.innerHTML = `
      <span class="otr-batch-replace-meta-item"><span class="otr-batch-replace-meta-label">课程号</span><strong>${escapeHtml(sec.code || '—')}</strong></span>
      <span class="otr-batch-replace-meta-item"><span class="otr-batch-replace-meta-label">课程名称</span><span>${escapeHtml(sec.name || '—')}</span></span>
      <span class="otr-batch-replace-meta-item"><span class="otr-batch-replace-meta-label">学期</span><span>${escapeHtml(term)}</span></span>`;
  }
  const fromSel = document.getElementById('otr-batch-from-teacher');
  if (fromSel) {
    fromSel.innerHTML = teachers.map(t =>
      `<option value="${escapeHtml(t.staffId)}">${escapeHtml(t.name)}${isOfferingTbcTeacher(t.staffId) ? '' : `（${escapeHtml(t.staffId)}）`}</option>`
    ).join('');
    fromSel.value = offeringTeacherReplaceBatchCtx.fromStaffId;
  }
  refreshOfferingTeacherReplaceBatchModalDisplay();
  openModal('modal-otr-batch-replace');
}

function closeOfferingTeacherReplaceBatchModal() {
  closeModal('modal-otr-batch-replace');
  offeringTeacherReplaceBatchCtx = null;
}

function onOfferingTeacherReplaceBatchFromChange() {
  if (!offeringTeacherReplaceBatchCtx) return;
  offeringTeacherReplaceBatchCtx.fromStaffId = String(
    document.getElementById('otr-batch-from-teacher')?.value || ''
  ).trim();
  refreshOfferingTeacherReplaceBatchModalDisplay();
}

function refreshOfferingTeacherReplaceBatchModalDisplay() {
  const ctx = offeringTeacherReplaceBatchCtx;
  const toEl = document.getElementById('otr-batch-to-teacher-display');
  const impactEl = document.getElementById('otr-batch-replace-impact');
  if (!ctx) return;
  const sec = findOfferingSectionByIdForTeacherReplace(ctx.sectionId);
  const fromId = String(ctx.fromStaffId || '').trim();
  const to = ctx.toTeacher;
  if (toEl) {
    if (to?.staffId) {
      const label = formatOfferingTeacherNameForDisplay(to);
      toEl.textContent = isOfferingTbcTeacher(to)
        ? label
        : `${label}（${to.staffId}）`;
      toEl.classList.remove('is-empty');
    } else {
      toEl.textContent = '尚未选择';
      toEl.classList.add('is-empty');
    }
  }
  if (!impactEl || !sec) return;
  const rowCount = countOfferingTeacherReplaceRowsWithTeacher(sec, fromId);
  if (!fromId) {
    impactEl.textContent = '请先选择原教师。';
    return;
  }
  if (!to?.staffId) {
    impactEl.textContent = `原教师出现在 ${rowCount} 条安排中；请选择新教师。`;
    return;
  }
  if (String(to.staffId) === fromId) {
    impactEl.textContent = '新教师与原教师相同，请重新选择。';
    return;
  }
  impactEl.textContent = `确认后将替换 ${rowCount} 条安排中的该教师；同行其他教师保留。`;
}

function openOfferingTeacherReplaceBatchToPicker() {
  const ctx = offeringTeacherReplaceBatchCtx;
  if (!ctx?.sectionId) return;
  const sec = findOfferingSectionByIdForTeacherReplace(ctx.sectionId);
  if (!sec || !isOfferingSectionEligibleForTeacherReplace(sec)) {
    alert('该开课任务未生效，无法在此替换教师。');
    return;
  }
  offeringGroupingSectionId = sec.id;
  teacherPickerContext = 'teacherReplaceBatch';
  majorOfferingTeacherPickerSelected.clear();
  const titleEl = document.getElementById('teacher-picker-title');
  if (titleEl) {
    const unit = getOfferingTeacherReplaceSectionUnit(sec);
    const supportUnits = typeof getMajorOfferingSectionSupportUnits === 'function'
      ? getMajorOfferingSectionSupportUnits(sec)
      : [];
    if (unit && supportUnits.length) {
      titleEl.textContent = `选择新教师（一键替换 · 开课单位：${unit}；Support：${supportUnits.join('、')}）`;
    } else if (unit) {
      titleEl.textContent = `选择新教师（一键替换 · 开课单位：${unit}）`;
    } else {
      titleEl.textContent = '选择新教师（一键替换）';
    }
  }
  resetListPage('majorOfferingTeacherPicker');
  ['teacher-picker-filter-staff-id', 'teacher-picker-filter-name'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  ['teacher-picker-filter-type', 'teacher-picker-filter-gender'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });
  ensureMajorOfferingTeacherPickerDeptFilter();
  if (typeof syncGroupAssignTeacherPickerOfferingUnitFilter === 'function') {
    syncGroupAssignTeacherPickerOfferingUnitFilter();
  }
  if (typeof syncTeacherPickerSimultaneousVisibility === 'function') {
    syncTeacherPickerSimultaneousVisibility();
  }
  if (typeof syncTeacherPickerAssignContext === 'function') syncTeacherPickerAssignContext();
  // 预勾选已选新教师（便于改选）
  if (ctx.toTeacher?.staffId) {
    const pool = buildMockTeacherPickerPool();
    const pick = pool.find(p => p.staffId === ctx.toTeacher.staffId);
    if (pick?.key) majorOfferingTeacherPickerSelected.add(pick.key);
  }
  renderMajorOfferingTeacherPickerModal();
  openModal('modal-major-teacher-picker');
}

function prepareOfferingTeacherReplaceBatchToFromPicker() {
  const ctx = offeringTeacherReplaceBatchCtx;
  if (!ctx?.sectionId) return false;
  const keys = [...majorOfferingTeacherPickerSelected];
  if (!keys.length) {
    alert('请勾选一名新教师。');
    return false;
  }
  if (keys.length > 1) {
    alert('一键替换仅支持选择一名新教师。');
    return false;
  }
  const sec = findOfferingSectionByIdForTeacherReplace(ctx.sectionId);
  if (!sec) return false;
  const allowedUnits = typeof getGroupAssignTeacherPickerAllowedUnits === 'function'
    ? getGroupAssignTeacherPickerAllowedUnits()
    : [];
  const poolMap = new Map(buildMockTeacherPickerPool().map(t => [t.key, t]));
  const pick = poolMap.get(keys[0]);
  if (!pick) {
    alert('未找到所选教师。');
    return false;
  }
  if (!isOfferingTbcTeacher(pick) && allowedUnits.length && !allowedUnits.includes(pick.departmentCode)) {
    alert('所选教师不在开课单位 / Support 范围内，请重新选择。');
    return false;
  }
  ctx.toTeacher = enrichGroupAssignFormTeacher({
    staffId: pick.staffId,
    name: pick.name,
    teacherType: pick.teacherType,
    departmentCode: pick.departmentCode
  }, sec);
  closeModal('modal-major-teacher-picker');
  majorOfferingTeacherPickerSelected.clear();
  teacherPickerContext = null;
  refreshOfferingTeacherReplaceBatchModalDisplay();
  return true;
}

function confirmOfferingTeacherReplaceBatch() {
  const ctx = offeringTeacherReplaceBatchCtx;
  if (!ctx?.sectionId) return;
  const sec = findOfferingSectionByIdForTeacherReplace(ctx.sectionId);
  if (!sec || !isOfferingSectionEligibleForTeacherReplace(sec)) {
    alert('目标开课任务不可用或已失效。');
    return;
  }
  const fromId = String(
    document.getElementById('otr-batch-from-teacher')?.value || ctx.fromStaffId || ''
  ).trim();
  ctx.fromStaffId = fromId;
  const to = ctx.toTeacher;
  if (!fromId) {
    alert('请选择原教师。');
    return;
  }
  if (!to?.staffId) {
    alert('请选择新教师。');
    return;
  }
  if (String(to.staffId) === fromId) {
    alert('新教师与原教师相同，请重新选择。');
    return;
  }
  const rowCount = countOfferingTeacherReplaceRowsWithTeacher(sec, fromId);
  if (!rowCount) {
    alert('原教师在本课程安排中未出现。');
    return;
  }
  const fromName = listOfferingTeacherReplaceSectionTeachers(sec)
    .find(t => t.staffId === fromId)?.name
    || formatOfferingTeacherNameForDisplay(fromId)
    || fromId;
  const toName = formatOfferingTeacherNameForDisplay(to);
  openDeleteConfirm({
    title: '确认一键替换教师',
    message: `将把本课程安排中的 <strong>${escapeHtml(fromName)}</strong> 全部替换为 <strong>${escapeHtml(toName)}</strong>（共 ${rowCount} 条安排）。`,
    hint: '仅替换教师身份；学时类型、起止周、周学时、总学时、同时授课、场地类型与教室偏好等保持不变。生效状态保持「已生效」；授课确认按替换后教师状态更新，需重新下发/确认。',
    hintWarn: true,
    emailHint: '系统将向被替换教师发送邮件，通知其原有安排的调整或取消。',
    confirmLabel: '确认替换',
    onConfirm: () => applyOfferingTeacherReplaceBatch()
  });
}

function applyOfferingTeacherReplaceBatch() {
  const ctx = offeringTeacherReplaceBatchCtx;
  if (!ctx?.sectionId || !ctx?.toTeacher?.staffId) return;
  const sec = findOfferingSectionByIdForTeacherReplace(ctx.sectionId);
  if (!sec || !isOfferingSectionEligibleForTeacherReplace(sec)) {
    alert('目标开课任务不可用或已失效。');
    return;
  }
  const fromId = String(ctx.fromStaffId || '').trim();
  const toTeacher = enrichGroupAssignFormTeacher({ ...ctx.toTeacher }, sec);
  if (!fromId || !toTeacher?.staffId) return;
  const touchedRows = [];
  getOfferingTeacherReplaceAssignRows(sec).forEach((row, idx) => {
    const teachers = getGroupAssignTeachers(row);
    if (!teachers.some(t => String(t?.staffId || '') === fromId)) return;
    const fromTeachers = teachers.map(t => ({ ...t }));
    const next = [];
    const seen = new Set();
    teachers.forEach(t => {
      const id = String(t?.staffId || '').trim();
      const nextT = id === fromId ? { ...toTeacher } : { ...t };
      const nextId = String(nextT.staffId || '').trim();
      if (!nextId || seen.has(nextId)) return;
      seen.add(nextId);
      next.push(nextT);
    });
    if (!next.length) return;
    syncOfferingTeacherReplaceRowTeacherFields(row, next);
    const view = mapOfferingTeacherReplaceAssignRowView(sec, row, idx);
    appendOfferingTeacherReplaceLog({
      termCode: resolveSectionOfferingTermCode(sec),
      sectionId: sec.id,
      assignmentRowId: row.id,
      code: sec.code,
      courseName: sec.name,
      groupLabel: view.groupLabelText,
      hourType: view.hourTypeLabel,
      weekRange: view.weekRange,
      fromTeachers: fromTeachers.map(t => formatOfferingTeacherNameForDisplay(t)).filter(Boolean),
      toTeachers: next.map(t => formatOfferingTeacherNameForDisplay(t)).filter(Boolean),
      batchReplace: true
    });
    touchedRows.push(row.id);
  });
  if (!touchedRows.length) {
    alert('未找到可替换的安排行。');
    return;
  }
  const termCode = resolveSectionOfferingTermCode(sec);
  const touchedIds = new Set([fromId, toTeacher.staffId].filter(Boolean));
  touchedIds.forEach(id => syncTeacherCourseConfirmationPackageRows(id, termCode));
  if (typeof refreshSectionCoordinatorAfterAssignmentChange === 'function') {
    refreshSectionCoordinatorAfterAssignmentChange(sec);
  }
  offeringTeacherReplaceFocusSectionId = sec.id;
  closeOfferingTeacherReplaceBatchModal();
  renderOfferingTeacherReplacePage();
  if (typeof renderCourseMajorOfferingTaskStyle2Page === 'function') {
    renderCourseMajorOfferingTaskStyle2Page();
  }
  if (typeof renderCourseMajorOfferingTaskPage === 'function') {
    renderCourseMajorOfferingTaskPage();
  }
  alert(`已一键替换 ${touchedRows.length} 条安排中的教师。生效状态保持「已生效」；请按新教师重新下发/确认授课。`);
}

/** 演示：仅当学期内尚无任何已生效开课时，才把 MPU3113 / OCE101 标为已生效，便于替换页空库联调 */
function ensureTeacherReplaceDemoEffectiveSections() {
  if (!ensureCourseOfferingPlan()) return;
  // 清掉误用展示值（如 2026/04）建出的空学期 store，避免污染
  Object.keys(COURSE_OFFERING_PLAN_BY_TERM || {}).forEach(key => {
    if ((COURSE_TIME_SETTINGS || []).some(r => r.termCode === key)) return;
    if (resolveOfferingTermCodeFromDisplay(key)) delete COURSE_OFFERING_PLAN_BY_TERM[key];
  });
  Object.values(COURSE_OFFERING_PLAN_BY_TERM || {}).forEach(store => {
    if (!store) return;
    const prev = COURSE_OFFERING_PLAN_STORE;
    COURSE_OFFERING_PLAN_STORE = store;
    const hasUserEffective = (store.sections || []).some(sec =>
      (sec.offeringType === 'major' || sec.offeringType === 'ge')
      && isOfferingSectionEligibleForTeacherReplace(sec)
    );
    const targets = (store.sections || []).filter(sec =>
      sec.offeringType === 'major'
      && (sec.catalogId === 'mpu3113' || sec.catalogId === 'oce101')
      && (sec.groupAssignments || []).length >= 1
    );
    const alreadySeeded = store._teacherReplaceDemoVersion === OFFERING_TEACHER_REPLACE_DEMO_VERSION;
    if (alreadySeeded || hasUserEffective) {
      // 已有用户生效课：不再强行改展示课；允许「已生效 + 授课未齐套确认」（替换教师后常态）
      if (hasUserEffective) store._teacherReplaceDemoVersion = OFFERING_TEACHER_REPLACE_DEMO_VERSION;
      COURSE_OFFERING_PLAN_STORE = prev;
      return;
    }
    let touched = 0;
    targets.slice(0, 2).forEach(sec => {
      if (sec.submitStatus !== 'submitted') {
        markMajorOfferingPlanUserSubmitted(sec);
      }
      const arrangeOk = typeof validateMajorOfferingTaskArrangementSubmit !== 'function'
        || validateMajorOfferingTaskArrangementSubmit(sec).ok;
      if (!arrangeOk) return;
      // 须先授课教师确认齐套，才允许标为已生效
      if (!isSectionTeacherConfirmationComplete(sec)) {
        seedSectionTeacherCourseConfirmationsComplete(sec);
      }
      if (!isSectionTeacherConfirmationComplete(sec)) return;
      if (!isMajorOfferingTaskArrangementSubmitted(sec)) {
        markMajorOfferingTaskArrangementSubmitted(sec);
      }
      touched += 1;
    });
    if (touched) store._teacherReplaceDemoVersion = OFFERING_TEACHER_REPLACE_DEMO_VERSION;
    COURSE_OFFERING_PLAN_STORE = prev;
  });
}

/** 管理端列表状态：未发送 / 待确认 / 退回 / 已确认 / 管理端确认 */
function renderTeacherCourseConfirmationStatusPill(state) {
  if (state === 'admin-proxy') {
    return '<span class="offering-status-pill is-on is-proxy-confirm">管理端确认</span>';
  }
  if (state === 'confirmed') {
    return '<span class="offering-status-pill is-on">已确认</span>';
  }
  if (state === 'disagreed') {
    return '<span class="offering-status-pill is-warn">退回</span>';
  }
  if (state === 'pending') return '<span class="offering-status-pill is-warn">待确认</span>';
  return '<span class="offering-status-pill is-off">未发送</span>';
}

/** Teaching Load 弹窗：未发送 / 待确认 / 已确认 / 管理端确认 / 退回 */
function renderTeacherCourseConfirmationTeachingLoadStatusPill(state) {
  if (state === 'admin-proxy') {
    return '<span class="offering-status-pill is-on is-proxy-confirm">管理端确认</span>';
  }
  if (state === 'confirmed') return '<span class="offering-status-pill is-on">已确认</span>';
  if (state === 'disagreed') return '<span class="offering-status-pill is-warn">退回</span>';
  if (state === 'pending') return '<span class="offering-status-pill is-warn">待确认</span>';
  return '<span class="offering-status-pill is-off">未发送</span>';
}

/** 确认信表格行状态：待确认 / 已确认 / 管理端确认 / 退回 */
function renderTeacherCourseConfirmationLetterRowStatus(state, feedback = '') {
  if (state === 'admin-proxy') {
    return '<span class="offering-status-pill is-on is-proxy-confirm">管理端确认</span>';
  }
  if (state === 'confirmed') return '<span class="offering-status-pill is-on">已确认</span>';
  if (state === 'disagreed') return '<span class="offering-status-pill is-warn">退回</span>';
  if (state === 'pending') return '<span class="offering-status-pill is-warn">待确认</span>';
  return '<span class="text-muted">—</span>';
}

function renderSectionTeacherConfirmationProgressCell(sec) {
  try {
    const p = getSectionTeacherConfirmationProgress(sec);
    if (!p.total) return '<span class="text-muted">—</span>';
    if (p.complete) {
      return '<span class="tcc-progress-pill is-complete">已确认</span>';
    }
    if (p.confirmed > 0) {
      return '<span class="tcc-progress-pill is-partial">部分确认</span>';
    }
    return '<span class="tcc-progress-pill is-none">未确认</span>';
  } catch (err) {
    console.warn('renderSectionTeacherConfirmationProgressCell failed', err);
    return '<span class="text-muted">—</span>';
  }
}

function getSectionTeacherConfirmationProgressForTeacher(staffId, termCode, pkg) {
  const p = pkg || getTeacherCourseConfirmationPackage(staffId, termCode);
  if (!p) return { status: 'draft' };
  migrateTeacherCourseConfirmationPackageSectionStates(p);
  const rows = p.rows?.length ? p.rows : buildTeacherCourseConfirmationRows(staffId, termCode);
  if (!rows.length) return { status: 'draft' };
  const statuses = rows.map(r => getTeacherCourseConfirmationSectionStatus(staffId, termCode, r.sectionId, p));
  if (statuses.some(s => s === 'pending')) return { status: 'pending' };
  if (statuses.some(s => s === 'disagreed')) return { status: 'disagreed' };
  if (statuses.length && statuses.every(s => s === 'confirmed' || s === 'admin-proxy')) {
    return { status: statuses.every(s => s === 'admin-proxy') ? 'admin-proxy' : 'confirmed' };
  }
  if (statuses.some(s => s === 'confirmed' || s === 'admin-proxy')) return { status: 'confirmed' };
  return { status: 'draft' };
}

function listTeacherCourseConfirmationAdminRows(termCode, collegeCode = resolveTeacherCourseConfirmationAdminCollege()) {
  const term = String(termCode || '').trim();
  const college = isTeacherCourseConfirmationAdminCollegeAll(collegeCode)
    ? ''
    : String(collegeCode || '').trim();
  if (!term) return [];
  const map = new Map();
  getOfferingSectionsForTerm(term)
    .filter(sec => sec?.offeringType === 'major' && sec.submitStatus === 'submitted')
    .forEach(sec => {
      collectSectionAssignTeachers(sec).forEach(t => {
        if (!t?.staffId || map.has(t.staffId)) return;
        if (isOfferingTbcTeacher(t)) return;
        const dept = t.departmentCode || getTeacherDepartmentCode(t.staffId);
        if (college && dept !== college) return;
        syncTeacherCourseConfirmationPackageRows(t.staffId, term);
        const pkg = getTeacherCourseConfirmationPackage(t.staffId, term);
        const progress = getSectionTeacherConfirmationProgressForTeacher(t.staffId, term, pkg);
        const rows = pkg?.rows?.length ? pkg.rows : buildTeacherCourseConfirmationRows(t.staffId, term);
        const groupCount = rows.reduce((sum, r) => {
          if (r.groupCount != null) return sum + (Number(r.groupCount) || 0);
          return sum + (Number(r.lectureGroups) || 0) + (Number(r.labGroups) || 0);
        }, 0);
        map.set(t.staffId, {
          staffId: t.staffId,
          name: t.name || resolveOfferingTeacherDisplayName(t.staffId),
          departmentCode: dept || '—',
          pkg,
          courseCount: rows.length,
          groupCount,
          teachingLoad: sumTeacherOfferingTeachingLoadHours(t.staffId, term),
          status: progress.status,
          confirmedBy: pkg?.confirmedBy || null,
          feedback: pkg?.feedback || ''
        });
      });
    });
  return [...map.values()].sort((a, b) => String(a.name).localeCompare(String(b.name), 'zh'));
}

/** 管理端列表：教师 + 课程 一行（与详情确认信表同维度） */
function listTeacherCourseConfirmationAdminCourseRows(termCode, collegeCode = resolveTeacherCourseConfirmationAdminCollege()) {
  const teachers = listTeacherCourseConfirmationAdminRows(termCode, collegeCode);
  const out = [];
  teachers.forEach(t => {
    const courseRows = t.pkg?.rows?.length
      ? t.pkg.rows
      : buildTeacherCourseConfirmationRows(t.staffId, termCode);
    courseRows.forEach(course => {
      const groupCount = course.groupCount != null
        ? course.groupCount
        : (Number(course.lectureGroups) || 0) + (Number(course.labGroups) || 0);
      const sectionStatus = getTeacherCourseConfirmationSectionStatus(
        t.staffId,
        termCode,
        course.sectionId,
        t.pkg
      );
      const sectionState = getTeacherCourseConfirmationSectionState(t.pkg, course.sectionId);
      out.push({
        staffId: t.staffId,
        teacherName: t.name,
        departmentCode: t.departmentCode,
        status: sectionStatus,
        confirmedBy: sectionState.confirmedBy || null,
        feedback: sectionState.feedback || '',
        sectionId: course.sectionId,
        code: course.code,
        courseName: course.name,
        classification: course.classification,
        credits: course.credits,
        teachingWeeks: course.teachingWeeks ?? course.weekRange,
        weekRange: course.teachingWeeks ?? course.weekRange,
        teachingMethod: course.teachingMethod || '—',
        combinedClass: course.combinedClass || 'N',
        groupCount,
        combinedGroupsCount: course.combinedGroupsCount ?? 0,
        totalStudentNo: course.totalStudentNo,
        weeklyHours: course.weeklyHours,
        totalTeachingHours: course.totalTeachingHours,
        hoursCombinedWithCode: course.hoursCombinedWithCode || '',
        coordinatorName: course.coordinatorName,
        coordinatorEmail: course.coordinatorEmail || '—',
        coTeachingStaff: course.coTeachingStaff,
        coTeachingStaffEmails: course.coTeachingStaffEmails || '—',
        coTeachingStaffList: course.coTeachingStaffList || []
      });
    });
  });
  return out;
}

function defaultTeacherCourseConfirmationAdminCompare(a, b) {
  return String(a?.teacherName || '').localeCompare(String(b?.teacherName || ''), 'zh')
    || String(a?.code || '').localeCompare(String(b?.code || ''), 'zh')
    || String(a?.sectionId || '').localeCompare(String(b?.sectionId || ''));
}

