/** @type {'term'|'academic-year'|'week'} 按学期 / 按学年 / 按周次 */
let teacherTeachingLoadDimension = 'term';
/** 按学年汇总时是否计入当前开课学期（默认否） */
let teacherTeachingLoadIncludeCurrentTermInYear = false;
/** @type {string[]|null} null 表示尚未初始化，首次进入按当前开课学期默认单选 */
let teacherTeachingLoadSelectedTerms = null;
/** @type {number[]|null} 学年起始年，如 2024 表示 2024学年 = 2024/09 + 2025/02 + 2025/04 */
let teacherTeachingLoadSelectedYears = null;
/** 课程类型多选：含 `__all__` 表示全部；否则为 GE / ME / 实习 / Thesis */
let teacherTeachingLoadSelectedCourseTypes = ['__all__'];
/** 学期维度：已展开开课安排详情的教师工号 */
const teacherTeachingLoadExpandedStaffIds = new Set();
/** 超限标红阈值：按维度各自独立；null/空 = 不标红 */
const teacherTeachingLoadHighlightThresholds = {
  week: null,
  term: null,
  'academic-year': null
};
/** Teaching Load 表排序：默认按 Name 首字母升序 */
listSortStates.teacherTeachingLoad = { key: 'name', dir: 'asc' };

const TEACHER_TEACHING_LOAD_COURSE_TYPE_OPTIONS = [
  { value: '__all__', label: '全部' },
  { value: 'GE', label: 'GE' },
  { value: 'ME', label: 'ME' },
  { value: '实习', label: '实习' },
  { value: 'Thesis', label: 'Thesis' }
];

function formatTeacherTeachingLoadTermLabel(termCode) {
  const code = String(termCode || '');
  const short = code.length >= 4 ? code.slice(-4) : code;
  return `${short} semester`;
}

function formatTeacherTeachingLoadAcademicYearLabel(year) {
  const y = Number(year);
  if (!Number.isFinite(y)) return '—';
  return `${y}学年`;
}

function formatTeacherTeachingLoadHours(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return '—';
  return Number.isInteger(n) ? String(n) : n.toFixed(1);
}

function getTeacherTeachingLoadHighlightThreshold(dimension = teacherTeachingLoadDimension) {
  const key = dimension === 'academic-year'
    ? 'academic-year'
    : (dimension === 'week' ? 'week' : 'term');
  const raw = teacherTeachingLoadHighlightThresholds[key];
  if (raw === '' || raw == null) return null;
  const n = Number(raw);
  return Number.isFinite(n) ? n : null;
}

function isTeacherTeachingLoadHoursOverThreshold(hours, dimension = teacherTeachingLoadDimension) {
  const threshold = getTeacherTeachingLoadHighlightThreshold(dimension);
  if (threshold == null) return false;
  const n = Number(hours);
  return Number.isFinite(n) && n > threshold;
}

function formatTeacherTeachingLoadHoursValueHtml(hours, dimension = teacherTeachingLoadDimension) {
  const over = isTeacherTeachingLoadHoursOverThreshold(hours, dimension);
  return `<span class="teacher-load-hours-value${over ? ' is-over-threshold' : ''}">${escapeHtml(formatTeacherTeachingLoadHours(hours))}</span>`;
}

function formatTeacherTeachingLoadThresholdValueText(dimension = teacherTeachingLoadDimension) {
  const threshold = getTeacherTeachingLoadHighlightThreshold(dimension);
  if (threshold == null) return '当前未设阈值';
  return `当前阈值设置为：${threshold}`;
}

function getTeacherTeachingLoadThresholdDimensionKey(dimension = teacherTeachingLoadDimension) {
  if (dimension === 'academic-year') return 'academic-year';
  if (dimension === 'week') return 'week';
  return 'term';
}

function getTeacherTeachingLoadThresholdDimensionLabel(dimension = teacherTeachingLoadDimension) {
  if (dimension === 'academic-year') return '按学年';
  if (dimension === 'week') return '按周次';
  return '按学期';
}

function parseTeacherTeachingLoadThresholdInputValue(raw) {
  const text = String(raw ?? '').trim();
  if (text === '') return { ok: true, value: null };
  const n = Number(text);
  if (!Number.isFinite(n)) return { ok: false, value: null };
  return { ok: true, value: n };
}

function openTeacherTeachingLoadThresholdModal() {
  const key = getTeacherTeachingLoadThresholdDimensionKey();
  const dimLabel = getTeacherTeachingLoadThresholdDimensionLabel();
  const titleEl = document.getElementById('ttl-threshold-modal-title');
  const hintEl = document.getElementById('ttl-threshold-modal-hint');
  const labelEl = document.getElementById('ttl-threshold-value-label');
  const inputEl = document.getElementById('ttl-threshold-value');
  const current = getTeacherTeachingLoadHighlightThreshold(key);
  if (titleEl) titleEl.textContent = `设置超限阈值 · ${dimLabel}`;
  if (hintEl) {
    hintEl.textContent = `仅作用于当前「${dimLabel}」列表：超过阈值的学时标红加粗；留空表示不标红。合计与人均不受影响。`;
  }
  if (labelEl) labelEl.textContent = `${dimLabel}阈值`;
  if (inputEl) inputEl.value = current == null ? '' : String(current);
  openModal('modal-teacher-teaching-load-threshold');
  inputEl?.focus();
}

function confirmTeacherTeachingLoadThresholdModal() {
  const key = getTeacherTeachingLoadThresholdDimensionKey();
  const parsed = parseTeacherTeachingLoadThresholdInputValue(
    document.getElementById('ttl-threshold-value')?.value
  );
  if (!parsed.ok) {
    alert('请填写有效的数字阈值，或留空表示不标红。');
    document.getElementById('ttl-threshold-value')?.focus();
    return;
  }
  teacherTeachingLoadHighlightThresholds[key] = parsed.value;
  closeModal('modal-teacher-teaching-load-threshold');
  renderCourseTeacherTeachingLoadPage();
}

function getTeacherTeachingLoadAvailableTerms() {
  const fromSettings = (typeof COURSE_TIME_SETTINGS !== 'undefined' ? COURSE_TIME_SETTINGS : [])
    .map(r => r?.termCode)
    .filter(Boolean);
  const fromDemo = TEACHER_TEACHING_LOAD_DEMO.terms || [];
  return [...new Set([...fromSettings, ...fromDemo])].sort();
}

/**
 * 学年定义：9 月为第一学期、次年 2 月第二学期、次年 4 月第三学期。
 * 例：2024学年 = 202409 + 202502 + 202504
 */
function getAcademicYearStartFromTermCode(termCode) {
  const code = String(termCode || '');
  if (code.length < 6) return null;
  const year = Number(code.slice(0, 4));
  const month = Number(code.slice(4, 6));
  if (!Number.isFinite(year) || !Number.isFinite(month)) return null;
  if (month === 9) return year;
  if (month === 2 || month === 4) return year - 1;
  return null;
}

function getTermCodesForAcademicYear(year) {
  const y = Number(year);
  if (!Number.isFinite(y)) return [];
  return [`${y}09`, `${y + 1}02`, `${y + 1}04`];
}

/** 某学年在当前学期库中实际存在的学期（允许仅有 9 月等部分学期） */
function getAvailableTermCodesForAcademicYear(year) {
  const available = new Set(getTeacherTeachingLoadAvailableTerms());
  return getTermCodesForAcademicYear(year).filter(code => available.has(code));
}

function getTeacherTeachingLoadAvailableAcademicYears() {
  const terms = getTeacherTeachingLoadAvailableTerms();
  const years = new Set();
  terms.forEach(term => {
    const y = getAcademicYearStartFromTermCode(term);
    if (y != null) years.add(y);
  });
  // 连续补齐首尾学年，避免中间缺档；含仅有 9 月学期的学年（如 2026）
  const sorted = [...years].sort((a, b) => a - b);
  if (sorted.length < 2) return sorted;
  const filled = [];
  for (let y = sorted[0]; y <= sorted[sorted.length - 1]; y += 1) filled.push(y);
  return filled;
}

function getDefaultTeacherTeachingLoadTerms() {
  const available = getTeacherTeachingLoadAvailableTerms();
  const def = getDefaultOfferingTermCode();
  if (def && available.includes(def)) return [def];
  return available.length ? [available[available.length - 1]] : [];
}

function getDefaultTeacherTeachingLoadYears() {
  const available = getTeacherTeachingLoadAvailableAcademicYears();
  const defTerm = getDefaultOfferingTermCode();
  const fromDef = defTerm ? getAcademicYearStartFromTermCode(defTerm) : null;
  if (fromDef != null && available.includes(fromDef)) return [fromDef];
  return available.length ? [available[available.length - 1]] : [];
}

function ensureTeacherTeachingLoadSelectedTerms() {
  const available = getTeacherTeachingLoadAvailableTerms();
  if (!teacherTeachingLoadSelectedTerms) {
    teacherTeachingLoadSelectedTerms = getDefaultTeacherTeachingLoadTerms();
  } else {
    teacherTeachingLoadSelectedTerms = teacherTeachingLoadSelectedTerms.filter(t => available.includes(t));
    if (!teacherTeachingLoadSelectedTerms.length) {
      teacherTeachingLoadSelectedTerms = getDefaultTeacherTeachingLoadTerms();
    }
  }
  const max = teacherTeachingLoadDimension === 'week'
    ? TEACHER_TEACHING_LOAD_MAX_WEEK_TERMS
    : TEACHER_TEACHING_LOAD_MAX_TERMS;
  return teacherTeachingLoadSelectedTerms.slice(0, max);
}

function ensureTeacherTeachingLoadSelectedYears() {
  const available = getTeacherTeachingLoadAvailableAcademicYears();
  if (!teacherTeachingLoadSelectedYears) {
    teacherTeachingLoadSelectedYears = getDefaultTeacherTeachingLoadYears();
  } else {
    teacherTeachingLoadSelectedYears = teacherTeachingLoadSelectedYears
      .map(Number)
      .filter(y => available.includes(y));
    if (!teacherTeachingLoadSelectedYears.length) {
      teacherTeachingLoadSelectedYears = getDefaultTeacherTeachingLoadYears();
    }
  }
  return teacherTeachingLoadSelectedYears.slice(0, TEACHER_TEACHING_LOAD_MAX_YEARS);
}

function getTeacherTeachingLoadTermIndices(selectedTerms) {
  const all = TEACHER_TEACHING_LOAD_DEMO.terms;
  return selectedTerms.map(term => all.indexOf(term)).filter(idx => idx >= 0);
}

function getTeacherTeachingLoadScopeTermCodes() {
  if (teacherTeachingLoadDimension === 'academic-year') {
    return [...new Set(
      ensureTeacherTeachingLoadSelectedYears().flatMap(year => getAcademicYearTermsForTeachingLoad(year))
    )];
  }
  // term / week 均按所选开课学期汇总教师范围
  return ensureTeacherTeachingLoadSelectedTerms().slice();
}

/** 按周次表头列：每学期展开为 W1..Wn（学期已在上层分组表头，周列仅显示 W#） */
function getTeacherTeachingLoadWeekColumns(terms = ensureTeacherTeachingLoadSelectedTerms()) {
  const list = (terms || []).filter(Boolean);
  return list.flatMap(term => {
    const n = Math.max(1, Number(getOfferingTermTeachingWeeks(term)) || 14);
    return Array.from({ length: n }, (_, i) => {
      const week = i + 1;
      return {
        termCode: term,
        week,
        key: `week:${term}:${week}`,
        label: `W${week}`,
        // label: list.length > 1 ? `${String(term).slice(-4)} W${week}` : `W${week}`, // 原多学期时带学期短码，改由上层学期分组表头区分
        title: `${formatCourseTermDisplay(term)} · 第${week}周`
      };
    });
  });
}

/** 某安排行在单周计入该教师的 Teaching Load（周学时份额） */
function getGroupAssignRowTeacherShareWeeklyHours(row, sec) {
  if (!row || !sec) return 0;
  if (typeof isGroupAssignRowScopeUnset === 'function' && isGroupAssignRowScopeUnset(row)) return 0;
  const teachers = getGroupAssignTeachers(row).filter(t => t?.staffId);
  const n = teachers.length || 1;
  let weekly = Number(row.weeklyHours);
  if (!Number.isFinite(weekly) || weekly < 0) {
    const weeks = parseWeekRangeToWeeks(row.weekRange, getSectionTermTeachingWeeks(sec));
    if (!weeks.length) return 0;
    weekly = (Number(getGroupAssignRowRecordedHours(row, sec)) || 0) / weeks.length;
  }
  const groupIds = getGroupAssignRowGroupIds(row);
  const groupFactor = (!row.simultaneousGroups && groupIds.length > 1) ? groupIds.length : 1;
  return (weekly * groupFactor) / n;
}

function sumTeacherOfferingTeachingLoadHoursForWeek(staffId, termCode, weekNum, typeFilter = null) {
  if (!staffId || !termCode || !weekNum) return 0;
  const week = Number(weekNum);
  if (!Number.isFinite(week) || week < 1) return 0;
  let sum = 0;
  getTeacherTeachingLoadSectionsForTerm(termCode).forEach(sec => {
    if (!sectionMatchesTeacherTeachingLoadCourseTypeFilter(sec, typeFilter)) return;
    (sec.groupAssignments || []).forEach(row => {
      if (typeof isGroupAssignRowScopeUnset === 'function' && isGroupAssignRowScopeUnset(row)) return;
      if (!getGroupAssignTeachers(row).some(t => String(t?.staffId || '') === String(staffId))) return;
      const weeks = parseWeekRangeToWeeks(row.weekRange, getSectionTermTeachingWeeks(sec));
      if (!weeks.includes(week)) return;
      sum += getGroupAssignRowTeacherShareWeeklyHours(row, sec);
    });
  });
  return sum;
}

function getTeacherTeachingLoadHoursForWeek(row, termCode, weekNum) {
  if (!row?.staffId || !termCode) return 0;
  return sumTeacherOfferingTeachingLoadHoursForWeek(
    row.staffId,
    termCode,
    weekNum,
    getTeacherTeachingLoadActiveCourseTypeFilter()
  );
}

/** 从开课安排汇总教师 Teaching Load（与 Course/Groups 同源） */
function buildLiveTeacherTeachingLoadRows(termCodes) {
  const terms = [...new Set((termCodes || []).filter(Boolean))];
  const map = new Map();
  terms.forEach(term => {
    if (typeof getOfferingSectionsForTerm !== 'function') return;
    getOfferingSectionsForTerm(term).forEach(sec => {
      const teachers = typeof collectSectionAssignTeachers === 'function'
        ? collectSectionAssignTeachers(sec)
        : [];
      teachers.forEach(t => {
        const staffId = String(t?.staffId || '').trim();
        if (!staffId) return;
        if (map.has(staffId)) return;
        const pool = typeof buildMockTeacherPickerPool === 'function'
          ? buildMockTeacherPickerPool().find(p => p.staffId === staffId)
          : null;
        const departmentCode = String(
          t.departmentCode || pool?.departmentCode || ''
        ).trim();
        map.set(staffId, {
          staffId,
          name: t.name || pool?.name || staffId,
          teacherType: t.teacherType || pool?.teacherType || '',
          departmentCode,
          hoursByTerm: {}
        });
      });
    });
  });
  map.forEach(row => {
    terms.forEach(term => {
      row.hoursByTerm[term] = typeof sumTeacherOfferingTeachingLoadHours === 'function'
        ? sumTeacherOfferingTeachingLoadHours(row.staffId, term)
        : 0;
    });
  });
  return [...map.values()].sort((a, b) =>
    String(a.name).localeCompare(String(b.name), 'zh')
    || String(a.staffId).localeCompare(String(b.staffId))
  );
}

function ensureTeacherTeachingLoadUnitFilter(root = getTeacherTeachingLoadRoot()) {
  const sel = ttlEl('unit-filter', root);
  if (!sel) return;
  const cur = sel.value || '';
  const scopeTerms = getTeacherTeachingLoadScopeTermCodes();
  const depts = buildLiveTeacherTeachingLoadRows(scopeTerms)
    .map(row => row.departmentCode)
    .filter(Boolean);
  const unitCodes = typeof mergeOfferingUnitCodes === 'function'
    ? mergeOfferingUnitCodes(depts)
    : [...new Set([...(depts || []), ...(OFFERING_UNIT_CODES || [])])].sort();
  sel.innerHTML = '<option value="">全部所属部门</option>' + unitCodes.map(c =>
    `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`
  ).join('');
  if (cur && unitCodes.includes(cur)) sel.value = cur;
}

function ensureTeacherTeachingLoadTypeFilter(root = getTeacherTeachingLoadRoot()) {
  const sel = ttlEl('type-filter', root);
  if (!sel) return;
  const cur = sel.value || '';
  const codes = (typeof TEACHER_TYPE_CODES !== 'undefined' ? TEACHER_TYPE_CODES : []).slice();
  sel.innerHTML = '<option value="">全部教师类型</option>' + codes.map(c =>
    `<option value="${escapeHtml(c)}">${escapeHtml(c)}</option>`
  ).join('');
  if (cur && codes.includes(cur)) sel.value = cur;
}

function formatTeacherTeachingLoadDepartmentCell(row) {
  return escapeHtml(String(row?.departmentCode || '').trim() || '—');
}

function ensureTeacherTeachingLoadSelectedCourseTypes() {
  const valid = new Set(TEACHER_TEACHING_LOAD_COURSE_TYPE_OPTIONS.map(o => o.value));
  let selected = (teacherTeachingLoadSelectedCourseTypes || [])
    .map(String)
    .filter(v => valid.has(v));
  if (!selected.length || selected.includes('__all__')) {
    teacherTeachingLoadSelectedCourseTypes = ['__all__'];
  } else {
    teacherTeachingLoadSelectedCourseTypes = selected;
  }
  return teacherTeachingLoadSelectedCourseTypes.slice();
}

/** @returns {Set<string>|null} null = 不限类型 */
function getTeacherTeachingLoadActiveCourseTypeFilter() {
  const selected = ensureTeacherTeachingLoadSelectedCourseTypes();
  if (!selected.length || selected.includes('__all__')) return null;
  return new Set(selected);
}

/** 将课程归入 Teaching Load 筛选桶：GE / ME / 实习 / Thesis；其他返回空串 */
function getTeacherTeachingLoadCourseTypeKey(sec) {
  if (!sec) return '';
  if (sec.offeringType === 'ge') return 'GE';
  const cls = String(
    (typeof getOfferingSectionCategoryDisplay === 'function'
      ? getOfferingSectionCategoryDisplay(sec)
      : (sec.category || ''))
    || ''
  );
  const name = String(sec.name || '');
  const blob = `${cls} ${name} ${sec.code || ''}`.toLowerCase();
  if (/general\s*elective|\bge\b|通识|校选/.test(blob) || /General Elective/i.test(cls)) return 'GE';
  if (/major\s*elective|\bme\b|专业选修/.test(blob) || /Major Elective/i.test(cls)) return 'ME';
  if (/industrial\s*training|practicum|clinical|internship|实习|实训/.test(blob)) return '实习';
  if (/thesis|dissertation|毕业论文|毕业设计|capstone/.test(blob)) return 'Thesis';
  return '';
}

function sectionMatchesTeacherTeachingLoadCourseTypeFilter(sec, typeFilter = getTeacherTeachingLoadActiveCourseTypeFilter()) {
  if (!typeFilter) return true;
  const key = getTeacherTeachingLoadCourseTypeKey(sec);
  return !!(key && typeFilter.has(key));
}

function getTeacherTeachingLoadHoursForTerm(row, termCode) {
  if (!termCode || !row?.staffId) return 0;
  if (typeof sumTeacherOfferingTeachingLoadHours === 'function') {
    return sumTeacherOfferingTeachingLoadHours(
      row.staffId,
      termCode,
      getTeacherTeachingLoadActiveCourseTypeFilter()
    );
  }
  const typeFilter = getTeacherTeachingLoadActiveCourseTypeFilter();
  if (!typeFilter && row?.hoursByTerm && Object.prototype.hasOwnProperty.call(row.hoursByTerm, termCode)) {
    return Number(row.hoursByTerm[termCode]) || 0;
  }
  const all = TEACHER_TEACHING_LOAD_DEMO.terms;
  const idx = all.indexOf(termCode);
  if (idx < 0) return 0;
  return Number(row?.hours?.[idx]) || 0;
}

function sumTeacherTeachingLoadHoursForTerms(row, termCodes) {
  return (termCodes || []).reduce((sum, term) => sum + getTeacherTeachingLoadHoursForTerm(row, term), 0);
}

/** 学时统计挂载根：分组页 Tab 优先，否则独立页 */
function getTeacherTeachingLoadRoot() {
  const groupingPage = document.getElementById('page-offering-grouping');
  if (groupingPage?.classList.contains('active') && offeringGroupingSidebarView === 'teacher-load') {
    return document.getElementById('offering-grouping-teacher-load');
  }
  return document.getElementById('page-course-teacher-teaching-load');
}

const TEACHER_TEACHING_LOAD_DEMO_VERSION = 'v5';

/** Teaching Load 演示课：覆盖全部 / GE / ME / 实习 / Thesis */
const TEACHER_TEACHING_LOAD_DEMO_COURSE_SPECS = [
  { code: 'OCE101', name: 'Introduction to Marine Science', credits: 3, hours: 42, unit: 'CAMS', classification: 'Major Core', offeringType: 'major' },
  { code: 'ART201', name: 'Introduction to Art History', credits: 3, hours: 42, unit: 'SASS', classification: 'General Elective', offeringType: 'ge' },
  { code: 'BUS201', name: 'International Business', credits: 3, hours: 42, unit: 'SEM', classification: 'General Elective', offeringType: 'ge' },
  { code: 'FIN301', name: 'Investment Analysis', credits: 4, hours: 56, unit: 'SEM', classification: 'Major Elective', offeringType: 'major' },
  { code: 'FIN401', name: 'Derivative Markets', credits: 4, hours: 56, unit: 'SEM', classification: 'Major Elective', offeringType: 'major' },
  { code: 'INT401', name: 'Industrial Training', credits: 6, hours: 84, unit: 'SEM', classification: 'Industrial Training', offeringType: 'major' },
  { code: 'CME440', name: 'Final Year Thesis', credits: 3, hours: 42, unit: 'SECE', classification: 'Thesis', offeringType: 'major' }
];

/** 历史学期 + 当前开课学期均注入，便于课程类型筛选有数可看 */
function getTeacherTeachingLoadDemoTermCodes() {
  const available = getTeacherTeachingLoadAvailableTerms();
  const current = getTeacherTeachingLoadCurrentTermCode()
    || (typeof getDefaultOfferingTermCode === 'function' ? getDefaultOfferingTermCode() : '')
    || '202604';
  const set = new Set([...(available || []), current].filter(Boolean));
  return [...set].sort();
}

/**
 * 为 Teaching Load 注入各课程类型演示开课（GE/ME/实习/Thesis + Major Core）。
 * 仅写入带 _ttlCourseTypeDemo 标记的 section，不覆盖用户真实安排。
 * 不标记任务安排生效 / 授课确认，避免污染 Course List「生效状态」。
 */
function seedTeacherTeachingLoadHistoricalOfferingDemo() {
  if (typeof ensureCourseOfferingPlan === 'function') ensureCourseOfferingPlan();
  const pool = typeof buildMockTeacherPickerPool === 'function'
    ? buildMockTeacherPickerPool().slice(0, 8)
    : [];
  if (!pool.length) return;
  const prevStore = COURSE_OFFERING_PLAN_STORE;
  getTeacherTeachingLoadDemoTermCodes().forEach((termCode, termIdx) => {
    const store = syncCourseOfferingPlanStoreFromTerm(termCode);
    if (!store) return;
    if (store._ttlCourseTypeDemoVersion === TEACHER_TEACHING_LOAD_DEMO_VERSION) return;
    store.sections = (store.sections || []).filter(s => !s._ttlCourseTypeDemo && !s._ttlHistoricalDemo);
    store.lines = (store.lines || []).filter(l => !l._ttlCourseTypeDemo && !l._ttlHistoricalDemo);
    const isShort = String(termCode).endsWith('02');
    const weekRange = isShort ? '1-5' : '1-14';
    const weekCount = isShort ? 5 : 14;
    TEACHER_TEACHING_LOAD_DEMO_COURSE_SPECS.forEach((spec, si) => {
      // 短学期少开几门，避免过满
      if (isShort && si % 2 === 1) return;
      const codeKey = String(spec.code || '').trim().toUpperCase();
      // 同学期已有真实开课同课号时不再注入演示课（避免与展示课 OCE101 等双计）
      if (codeKey && (store.sections || []).some(s =>
        !s._ttlCourseTypeDemo && !s._ttlHistoricalDemo
        && String(s.code || '').trim().toUpperCase() === codeKey
      )) return;
      const teacherA = pool[(termIdx + si) % pool.length];
      const teacherB = pool[(termIdx + si + 3) % pool.length];
      const secId = `ttl-demo-${termCode}-${spec.code}`;
      const g1 = { id: `${secId}-g1`, name: 'Group1', capacityLimit: 45 };
      const g2 = { id: `${secId}-g2`, name: 'Group2', capacityLimit: 45 };
      const weeklyHours = Math.max(1, Math.round((Number(spec.hours) || 42) / weekCount));
      const rowHours = weeklyHours * weekCount;
      const makeTeacher = (t) => ({
        staffId: t.staffId,
        name: t.name,
        teacherType: t.teacherType,
        departmentCode: t.departmentCode,
        role: '主讲'
      });
      const makeAssign = (id, group, teacher) => ({
        id,
        deliveryScope: 'group',
        groupId: group.id,
        groupIds: [group.id],
        groupName: group.name,
        hourType: spec.classification === 'Industrial Training' ? '其他学时'
          : (spec.classification === 'Thesis' ? '其他学时' : '理论学时'),
        mergeHours: true,
        weekRange,
        weeklyHours,
        hours: rowHours,
        simultaneousGroups: false,
        teachers: [makeTeacher(teacher)],
        staffId: teacher.staffId,
        teacher: teacher.name,
        role: '主讲'
      });
      const catalogId = (Array.isArray(COURSE_CATALOG)
        ? COURSE_CATALOG.find(c => String(c.code || '').toUpperCase() === String(spec.code).toUpperCase())?.id
        : '') || '';
      const groups = (spec.classification === 'Industrial Training' || spec.classification === 'Thesis')
        ? [g1]
        : [g1, g2];
      const assigns = groups.length === 1
        ? [makeAssign(`${secId}-ga1`, g1, teacherA)]
        : [
          makeAssign(`${secId}-ga1`, g1, teacherA),
          makeAssign(`${secId}-ga2`, g2, teacherB)
        ];
      const sec = {
        id: secId,
        code: spec.code,
        name: spec.name,
        credits: spec.credits,
        hours: rowHours,
        theoryHours: spec.classification === 'Industrial Training' || spec.classification === 'Thesis' ? 0 : rowHours,
        practiceHours: 0,
        otherHours: spec.classification === 'Industrial Training' || spec.classification === 'Thesis' ? rowHours : 0,
        weekRange,
        weeks: weekRange,
        teachingWeeks: weekCount,
        offeringType: spec.offeringType || 'major',
        category: spec.classification,
        catalogId,
        // 仅供学时统计；不进入任务安排「已生效」态
        submitStatus: 'draft',
        schedulingVisible: false,
        teachingConfirmStatus: 'pending',
        offeringUnitAbbr: spec.unit || teacherA.departmentCode || 'CAMS',
        groups,
        groupAssignments: assigns,
        plannedGroupCount: groups.length,
        _ttlCourseTypeDemo: true,
        _ttlHistoricalDemo: true
      };
      if (spec.offeringType === 'ge' && typeof ensureGeOfferingSectionFields === 'function') {
        ensureGeOfferingSectionFields(sec);
      } else if (typeof ensureSectionOfferingFields === 'function') {
        ensureSectionOfferingFields(sec);
      }
      // 目录/ensure 可能冲掉演示分类与学时，写回筛选所需字段
      sec.category = spec.classification;
      sec.offeringType = spec.offeringType || 'major';
      sec.submitStatus = 'draft';
      sec.schedulingVisible = false;
      sec.teachingConfirmStatus = 'pending';
      delete sec.taskArrangementSubmittedAt;
      delete sec.planSubmittedByUser;
      sec.groupAssignments = assigns;
      sec.groups = groups;
      sec._ttlCourseTypeDemo = true;
      sec._ttlHistoricalDemo = true;
      store.sections.push(sec);
    });
    store._ttlCourseTypeDemoVersion = TEACHER_TEACHING_LOAD_DEMO_VERSION;
    store._ttlHistoricalDemoVersion = TEACHER_TEACHING_LOAD_DEMO_VERSION;
    if (!store.generatedAt) store.generatedAt = new Date().toISOString();
  });
  COURSE_OFFERING_PLAN_STORE = prevStore;
}

function isTeacherTeachingLoadDemoSection(sec) {
  return !!(sec && (sec._ttlCourseTypeDemo || sec._ttlHistoricalDemo));
}

function ttlEl(name, root = getTeacherTeachingLoadRoot()) {
  if (!root || !name) return null;
  return root.querySelector(`[data-ttl="${name}"]`);
}

function getTeacherTeachingLoadCurrentTermCode() {
  const groupingPage = document.getElementById('page-offering-grouping');
  if (groupingPage?.classList.contains('active') && typeof getOfferingGroupingSection === 'function') {
    const sec = getOfferingGroupingSection();
    const fromSec = typeof resolveSectionOfferingTermCode === 'function'
      ? resolveSectionOfferingTermCode(sec)
      : '';
    if (fromSec) return fromSec;
  }
  if (typeof getDefaultOfferingTermCode === 'function') {
    return getDefaultOfferingTermCode() || '';
  }
  return '';
}

/** 学年汇总用学期；默认不含当前开课学期，可由开关计入 */
function getAcademicYearTermsForTeachingLoad(year) {
  const terms = getAvailableTermCodesForAcademicYear(year);
  if (teacherTeachingLoadIncludeCurrentTermInYear) return terms.slice();
  const current = getTeacherTeachingLoadCurrentTermCode();
  return terms.filter(code => code && code !== current);
}

function resolveTeacherTeachingLoadTeacherType(row) {
  const fromRow = String(row?.teacherType || '').trim();
  if (fromRow) return fromRow;
  const pick = typeof buildMockTeacherPickerPool === 'function'
    ? buildMockTeacherPickerPool().find(t => t.staffId === row?.staffId)
    : null;
  return String(pick?.teacherType || '').trim() || '—';
}

function summarizeTeacherTeachingLoadCourseGroupsAcrossTerms(staffId, termCodes) {
  const courses = [];
  let groups = 0;
  (termCodes || []).forEach(term => {
    const rows = getTeacherOfferingTermSectionDetailRows(
      staffId,
      term,
      getTeacherTeachingLoadActiveCourseTypeFilter()
    );
    rows.forEach(r => {
      courses.push(r);
      groups += Number(r.groupCount) || 0;
    });
  });
  return { courses: courses.length, groups, courseRows: courses };
}

function formatTeacherTeachingLoadHoursCell(hours, courseRowsOrSummary) {
  if (courseRowsOrSummary && typeof courseRowsOrSummary.courses === 'number') {
    const { courses, groups } = courseRowsOrSummary;
    const courseLabel = courses <= 1 ? 'Course' : 'Courses';
    const groupLabel = groups <= 1 ? 'Group' : 'Groups';
    return `<span class="teacher-load-hours-cell">`
      + formatTeacherTeachingLoadHoursValueHtml(hours)
      + `<span class="offering-teacher-term-load-summary">(${courses} ${courseLabel}, ${groups} ${groupLabel})</span>`
      + `</span>`;
  }
  return formatTeacherTeachingLoadHoursWithCourseGroupSummary(hours, courseRowsOrSummary || []);
}

function formatTeacherTeachingLoadNameCell(row) {
  const staffId = String(row?.staffId || '').trim();
  const name = String(row?.name || staffId || '—').trim() || '—';
  if (!staffId) return escapeHtml(name);
  return `<button type="button" class="offering-group-status-teacher-link teacher-load-name-link"
    title="查看课时详情"
    onclick="openOfferingTeacherTermAssignModal('${escapeHtml(staffId)}')">${escapeHtml(name)}</button>`;
}

function toggleTeacherTeachingLoadRowExpand(staffId) {
  const id = String(staffId || '').trim();
  if (!id) return;
  if (teacherTeachingLoadExpandedStaffIds.has(id)) teacherTeachingLoadExpandedStaffIds.delete(id);
  else teacherTeachingLoadExpandedStaffIds.add(id);
  renderCourseTeacherTeachingLoadPage();
}

function renderTeacherTeachingLoadExpandDetail(staffId, termCodes) {
  const codes = [...new Set(
    (Array.isArray(termCodes) ? termCodes : [termCodes])
      .map(c => String(c || '').trim())
      .filter(Boolean)
  )];
  const typeFilter = getTeacherTeachingLoadActiveCourseTypeFilter();
  const courseRows = codes
    .flatMap(termCode => getTeacherOfferingTermSectionDetailRows(staffId, termCode, typeFilter))
    .sort((a, b) =>
      String(a.termCode || '').localeCompare(String(b.termCode || ''))
      || String(a.code).localeCompare(String(b.code), 'zh')
      || String(a.name).localeCompare(String(b.name), 'zh')
    );
  const termDisplay = codes.length
    ? codes.map(c => formatCourseTermDisplay(c)).join('、')
    : '本学期';
  if (!courseRows.length) {
    return `<div class="teacher-load-expand-detail">
      <div class="teacher-load-expand-head"><strong>开课安排详情</strong><span class="text-muted">${escapeHtml(termDisplay)} · 只读</span></div>
      <p class="text-muted teacher-load-expand-empty">所选学期尚未安排该教师的开课课时。</p>
    </div>`;
  }
  const body = courseRows.map(row => {
    const rowTerm = row.termCode || codes[0] || '';
    const confirmStatus = getTeacherCourseConfirmationSectionStatus(staffId, rowTerm, row.sectionId);
    return `<tr>
      <td class="col-center col-term">${escapeHtml(rowTerm ? formatCourseTermDisplay(rowTerm) : '—')}</td>
      <td class="col-center">${escapeHtml(row.code)}</td>
      <td>${escapeHtml(row.name)}</td>
      <td class="col-center">${escapeHtml(row.classification || '—')}</td>
      <td class="col-center col-groups">${formatTeacherOfferingNoOfGroupsCell(row)}</td>
      <td class="col-center">${escapeHtml(formatTeacherTeachingLoadHours(row.hours))}</td>
      <td class="col-center">${renderTeacherCourseConfirmationTeachingLoadStatusPill(confirmStatus)}</td>
    </tr>`;
  }).join('');
  return `<div class="teacher-load-expand-detail">
    <div class="teacher-load-expand-head">
      <strong>开课安排详情</strong>
      <span class="text-muted">${escapeHtml(termDisplay)} · 只读</span>
    </div>
    <div class="table-scroll teacher-load-expand-scroll">
      <table class="data-table compact teacher-load-expand-table">
        <thead>
          <tr>
            <th class="col-center col-term">开课学期</th>
            <th class="col-center">Course Code</th>
            <th>Course Name</th>
            <th class="col-center">课程类型</th>
            <th class="col-center">No. of Groups</th>
            <th class="col-center">Teaching Load</th>
            <th class="col-center">授课确认状态</th>
          </tr>
        </thead>
        <tbody>${body}</tbody>
      </table>
    </div>
  </div>`;
}

function syncTeacherTeachingLoadDimensionChrome(root = getTeacherTeachingLoadRoot()) {
  if (!root) return;
  const isYear = teacherTeachingLoadDimension === 'academic-year';
  const isWeek = teacherTeachingLoadDimension === 'week';
  root.querySelectorAll('[data-ttl="dimension-tab"]').forEach(btn => {
    const active = btn.dataset.dimension === teacherTeachingLoadDimension;
    btn.classList.toggle('is-active', active);
    btn.setAttribute('aria-selected', active ? 'true' : 'false');
  });
  const termLabel = ttlEl('term-label', root);
  if (termLabel) termLabel.textContent = isYear ? '学年' : '开课学期';
  const hint = ttlEl('hint', root);
  if (hint) {
    if (isYear) {
      hint.textContent = teacherTeachingLoadIncludeCurrentTermInYear
        ? '单位：学时（hour）；可多选学年（最多 4 个）；学年含 9/次年2/次年4，汇总已计入当前开课学期；仅有部分学期时按已有数据汇总；底部为合计与人均均值'
        : '单位：学时（hour）；可多选学年（最多 4 个）；学年含 9/次年2/次年4，汇总默认不含当前开课学期；仅有部分学期时按已有数据汇总；底部为合计与人均均值';
    } else if (isWeek) {
      hint.textContent = '单位：学时（hour）；按周次展开周学时；最多同时查看 2 个学期；单元格为该周计入该教师的周学时份额；底部为合计与人均均值';
    } else {
      hint.textContent = '单位：学时（hour）；默认展示当前开课学期，最多可选 6 个学期；「详情」可展开所选学期的开课安排（只读）；底部为学期合计与人均均值';
    }
  }
  const includeWrap = ttlEl('include-current-term-wrap', root);
  if (includeWrap) includeWrap.hidden = !isYear;
  const includeInput = ttlEl('include-current-term', root);
  if (includeInput) includeInput.checked = !!teacherTeachingLoadIncludeCurrentTermInYear;
  const thresholdBtn = ttlEl('threshold-btn', root);
  const thresholdValueEl = ttlEl('threshold-value', root);
  const threshold = getTeacherTeachingLoadHighlightThreshold();
  if (thresholdBtn) {
    thresholdBtn.textContent = '超限阈值';
    thresholdBtn.title = threshold == null
      ? '设置各维度超限标红阈值（当前维度未设置）'
      : `当前维度阈值 ${threshold}；点击修改`;
  }
  if (thresholdValueEl) {
    thresholdValueEl.textContent = formatTeacherTeachingLoadThresholdValueText();
    thresholdValueEl.classList.toggle('is-empty', threshold == null);
  }
}

function onTeacherTeachingLoadIncludeCurrentTermChange(input) {
  teacherTeachingLoadIncludeCurrentTermInYear = !!input?.checked;
  renderCourseTeacherTeachingLoadPage();
}

function setTeacherTeachingLoadDimension(dimension) {
  const next = dimension === 'academic-year'
    ? 'academic-year'
    : (dimension === 'week' ? 'week' : 'term');
  if (teacherTeachingLoadDimension === next) {
    renderCourseTeacherTeachingLoadPage();
    return;
  }
  teacherTeachingLoadDimension = next;
  if (next === 'week') {
    // 从多学期切过来时裁到最多 2 个
    const terms = ensureTeacherTeachingLoadSelectedTerms();
    teacherTeachingLoadSelectedTerms = terms.slice(0, TEACHER_TEACHING_LOAD_MAX_WEEK_TERMS);
  }
  closeTeacherTeachingLoadTermDropdown();
  closeTeacherTeachingLoadCourseTypeDropdown();
  renderCourseTeacherTeachingLoadPage();
}

function ensureTeacherTeachingLoadTermMultiselect(root = getTeacherTeachingLoadRoot()) {
  const options = ttlEl('term-options', root);
  if (!options) return;
  if (teacherTeachingLoadDimension === 'academic-year') {
    const selected = new Set(ensureTeacherTeachingLoadSelectedYears().map(String));
    options.innerHTML = getTeacherTeachingLoadAvailableAcademicYears().map(year => {
      return `<label class="clo-multiselect-option">
        <input type="checkbox" class="teacher-load-term-check" value="${escapeHtml(String(year))}" ${selected.has(String(year)) ? 'checked' : ''} onchange="onTeacherTeachingLoadTermToggle(this)">
        <span>${escapeHtml(formatTeacherTeachingLoadAcademicYearLabel(year))}</span>
      </label>`;
    }).join('');
  } else {
    const selected = new Set(ensureTeacherTeachingLoadSelectedTerms());
    options.innerHTML = getTeacherTeachingLoadAvailableTerms().map(term =>
      `<label class="clo-multiselect-option">
        <input type="checkbox" class="teacher-load-term-check" value="${escapeHtml(term)}" ${selected.has(term) ? 'checked' : ''} onchange="onTeacherTeachingLoadTermToggle(this)">
        <span>${escapeHtml(formatCourseTermDisplay(term))}</span>
      </label>`
    ).join('');
  }
  updateTeacherTeachingLoadTermDisplay(root);
}

function getTeacherTeachingLoadTermChecks(root = getTeacherTeachingLoadRoot()) {
  const options = ttlEl('term-options', root);
  if (!options) return [];
  return [...options.querySelectorAll('.teacher-load-term-check')];
}

function updateTeacherTeachingLoadTermDisplay(root = getTeacherTeachingLoadRoot()) {
  const display = ttlEl('term-display', root);
  if (!display) return;
  if (teacherTeachingLoadDimension === 'academic-year') {
    const selected = ensureTeacherTeachingLoadSelectedYears();
    if (selected.length) {
      display.textContent = selected.map(formatTeacherTeachingLoadAcademicYearLabel).join('、');
      display.classList.remove('placeholder');
    } else {
      display.textContent = '请选择';
      display.classList.add('placeholder');
    }
    return;
  }
  const selected = ensureTeacherTeachingLoadSelectedTerms();
  if (selected.length) {
    display.textContent = selected.map(formatCourseTermDisplay).join('、');
    display.classList.remove('placeholder');
  } else {
    display.textContent = '请选择';
    display.classList.add('placeholder');
  }
}

function onTeacherTeachingLoadTermToggle(checkbox) {
  if (!checkbox) return;
  const root = checkbox.closest('[data-ttl-root]') || getTeacherTeachingLoadRoot();
  const checked = getTeacherTeachingLoadTermChecks(root).filter(el => el.checked).map(el => el.value);
  const isYear = teacherTeachingLoadDimension === 'academic-year';
  const isWeek = teacherTeachingLoadDimension === 'week';
  const maxCount = isYear
    ? TEACHER_TEACHING_LOAD_MAX_YEARS
    : (isWeek ? TEACHER_TEACHING_LOAD_MAX_WEEK_TERMS : TEACHER_TEACHING_LOAD_MAX_TERMS);
  const unitLabel = isYear ? '个学年' : '个学期';
  if (checkbox.checked && checked.length > maxCount) {
    checkbox.checked = false;
    alert(isWeek
      ? `按周次最多同时查看 ${maxCount} 个学期`
      : `最多同时展示 ${maxCount}${unitLabel}`);
    return;
  }
  if (!checked.length) {
    checkbox.checked = true;
    alert(isYear ? '请至少选择 1 个学年' : '请至少选择 1 个开课学期');
    return;
  }
  if (isYear) {
    teacherTeachingLoadSelectedYears = getTeacherTeachingLoadTermChecks(root)
      .filter(el => el.checked)
      .map(el => Number(el.value))
      .filter(Number.isFinite);
  } else {
    teacherTeachingLoadSelectedTerms = getTeacherTeachingLoadTermChecks(root)
      .filter(el => el.checked)
      .map(el => el.value);
  }
  updateTeacherTeachingLoadTermDisplay(root);
  // 勾选后只刷新表格，避免重绘筛选项把下拉关掉
  const dd = ttlEl('term-dropdown', root);
  const keepOpen = dd && !dd.hidden;
  renderCourseTeacherTeachingLoadPage({ preserveTermDropdown: keepOpen });
}

function toggleTeacherTeachingLoadTermDropdown(event) {
  event.preventDefault();
  event.stopPropagation();
  const root = event.currentTarget?.closest?.('[data-ttl-root]') || getTeacherTeachingLoadRoot();
  const dd = ttlEl('term-dropdown', root);
  if (!dd) return;
  const willOpen = dd.hidden;
  closeTeacherTeachingLoadTermDropdown();
  closeTeacherTeachingLoadCourseTypeDropdown();
  if (willOpen) {
    ensureTeacherTeachingLoadTermMultiselect(root);
    dd.hidden = false;
  }
}

function closeTeacherTeachingLoadTermDropdown() {
  document.querySelectorAll('[data-ttl="term-dropdown"]').forEach(dd => {
    dd.hidden = true;
  });
}

function ensureTeacherTeachingLoadCourseTypeMultiselect(root = getTeacherTeachingLoadRoot()) {
  const options = ttlEl('course-type-options', root);
  if (!options) return;
  const selected = new Set(ensureTeacherTeachingLoadSelectedCourseTypes());
  options.innerHTML = TEACHER_TEACHING_LOAD_COURSE_TYPE_OPTIONS.map(opt =>
    `<label class="clo-multiselect-option">
      <input type="checkbox" class="teacher-load-course-type-check" value="${escapeHtml(opt.value)}" ${selected.has(opt.value) ? 'checked' : ''} onchange="onTeacherTeachingLoadCourseTypeToggle(this)">
      <span>${escapeHtml(opt.label)}</span>
    </label>`
  ).join('');
  updateTeacherTeachingLoadCourseTypeDisplay(root);
}

function updateTeacherTeachingLoadCourseTypeDisplay(root = getTeacherTeachingLoadRoot()) {
  const display = ttlEl('course-type-display', root);
  if (!display) return;
  const selected = ensureTeacherTeachingLoadSelectedCourseTypes();
  if (!selected.length || selected.includes('__all__')) {
    display.textContent = '全部';
    display.classList.remove('placeholder');
    return;
  }
  const labelMap = Object.fromEntries(TEACHER_TEACHING_LOAD_COURSE_TYPE_OPTIONS.map(o => [o.value, o.label]));
  display.textContent = selected.map(v => labelMap[v] || v).join('、');
  display.classList.remove('placeholder');
}

function onTeacherTeachingLoadCourseTypeToggle(checkbox) {
  if (!checkbox) return;
  const root = checkbox.closest('[data-ttl-root]') || getTeacherTeachingLoadRoot();
  const checks = [...(ttlEl('course-type-options', root)?.querySelectorAll('.teacher-load-course-type-check') || [])];
  const value = checkbox.value;
  if (value === '__all__') {
    if (checkbox.checked) {
      checks.forEach(el => { el.checked = el.value === '__all__'; });
    } else {
      checkbox.checked = true;
    }
  } else if (checkbox.checked) {
    const allCheck = checks.find(el => el.value === '__all__');
    if (allCheck) allCheck.checked = false;
  } else {
    const anySpecific = checks.some(el => el.value !== '__all__' && el.checked);
    if (!anySpecific) {
      const allCheck = checks.find(el => el.value === '__all__');
      if (allCheck) allCheck.checked = true;
    }
  }
  const next = checks.filter(el => el.checked).map(el => el.value);
  teacherTeachingLoadSelectedCourseTypes = next.includes('__all__') || !next.length
    ? ['__all__']
    : next.filter(v => v !== '__all__');
  updateTeacherTeachingLoadCourseTypeDisplay(root);
  const dd = ttlEl('course-type-dropdown', root);
  const keepOpen = dd && !dd.hidden;
  renderCourseTeacherTeachingLoadPage({
    preserveTermDropdown: !!(ttlEl('term-dropdown', root) && !ttlEl('term-dropdown', root).hidden),
    preserveCourseTypeDropdown: keepOpen
  });
}

function toggleTeacherTeachingLoadCourseTypeDropdown(event) {
  event.preventDefault();
  event.stopPropagation();
  const root = event.currentTarget?.closest?.('[data-ttl-root]') || getTeacherTeachingLoadRoot();
  const dd = ttlEl('course-type-dropdown', root);
  if (!dd) return;
  const willOpen = dd.hidden;
  closeTeacherTeachingLoadCourseTypeDropdown();
  closeTeacherTeachingLoadTermDropdown();
  if (willOpen) {
    ensureTeacherTeachingLoadCourseTypeMultiselect(root);
    dd.hidden = false;
  }
}

function closeTeacherTeachingLoadCourseTypeDropdown() {
  document.querySelectorAll('[data-ttl="course-type-dropdown"]').forEach(dd => {
    dd.hidden = true;
  });
}

function getFilteredTeacherTeachingLoadRows(root = getTeacherTeachingLoadRoot()) {
  const staffIdQ = (ttlEl('staff-id-filter', root)?.value || '').trim().toLowerCase();
  const nameQ = (ttlEl('name-filter', root)?.value || '').trim().toLowerCase();
  const unitQ = (ttlEl('unit-filter', root)?.value || '').trim();
  const typeQ = (ttlEl('type-filter', root)?.value || '').trim();
  const scopeTerms = getTeacherTeachingLoadScopeTermCodes();
  return buildLiveTeacherTeachingLoadRows(scopeTerms).filter(row => {
    if (staffIdQ && !String(row.staffId || '').toLowerCase().includes(staffIdQ)) return false;
    if (nameQ && !String(row.name || '').toLowerCase().includes(nameQ)) return false;
    if (unitQ && String(row.departmentCode || '').trim() !== unitQ) return false;
    if (typeQ && resolveTeacherTeachingLoadTeacherType(row) !== typeQ) return false;
    const hasLoad = scopeTerms.some(term => getTeacherTeachingLoadHoursForTerm(row, term) > 0)
      || scopeTerms.some(term => getTeacherOfferingTermSectionDetailRows(
        row.staffId,
        term,
        getTeacherTeachingLoadActiveCourseTypeFilter()
      ).length > 0);
    return hasLoad;
  });
}

function defaultTeacherTeachingLoadCompare(a, b) {
  const byName = String(a?.name || '').localeCompare(String(b?.name || ''), 'en', {
    sensitivity: 'base',
    numeric: true
  });
  if (byName) return byName;
  return String(a?.staffId || '').localeCompare(String(b?.staffId || ''));
}

/** @param {Array<string|number>} periodKeys 学期 code 或学年起始年 */
function buildTeacherTeachingLoadSortColumns(periodKeys, isYear) {
  const cols = {
    name: { get: row => String(row?.name || '') },
    dept: { get: row => String(row?.departmentCode || '').trim() },
    teacherType: { get: row => resolveTeacherTeachingLoadTeacherType(row) }
  };
  (periodKeys || []).forEach(key => {
    if (isYear) {
      cols[`year:${key}`] = {
        get: row => sumTeacherTeachingLoadHoursForTerms(row, getAcademicYearTermsForTeachingLoad(key)),
        type: 'number'
      };
    } else {
      cols[`term:${key}`] = {
        get: row => getTeacherTeachingLoadHoursForTerm(row, key),
        type: 'number'
      };
    }
  });
  return cols;
}

function buildTeacherTeachingLoadWeekSortColumns(weekCols) {
  const cols = {
    name: { get: row => String(row?.name || '') },
    dept: { get: row => String(row?.departmentCode || '').trim() },
    teacherType: { get: row => resolveTeacherTeachingLoadTeacherType(row) }
  };
  (weekCols || []).forEach(col => {
    cols[col.key] = {
      get: row => getTeacherTeachingLoadHoursForWeek(row, col.termCode, col.week),
      type: 'number'
    };
  });
  return cols;
}

function queryTeacherTeachingLoadPage() {
  closeTeacherTeachingLoadTermDropdown();
  closeTeacherTeachingLoadCourseTypeDropdown();
  renderCourseTeacherTeachingLoadPage();
}

function resetTeacherTeachingLoadFilters() {
  const root = getTeacherTeachingLoadRoot();
  const staffIdInput = ttlEl('staff-id-filter', root);
  const nameInput = ttlEl('name-filter', root);
  const unitSel = ttlEl('unit-filter', root);
  const typeSel = ttlEl('type-filter', root);
  if (staffIdInput) staffIdInput.value = '';
  if (nameInput) nameInput.value = '';
  if (unitSel) unitSel.value = '';
  if (typeSel) typeSel.value = '';
  teacherTeachingLoadSelectedTerms = getDefaultTeacherTeachingLoadTerms();
  teacherTeachingLoadSelectedYears = getDefaultTeacherTeachingLoadYears();
  teacherTeachingLoadSelectedCourseTypes = ['__all__'];
  ensureTeacherTeachingLoadTermMultiselect(root);
  ensureTeacherTeachingLoadCourseTypeMultiselect(root);
  ensureTeacherTeachingLoadUnitFilter(root);
  ensureTeacherTeachingLoadTypeFilter(root);
  closeTeacherTeachingLoadTermDropdown();
  closeTeacherTeachingLoadCourseTypeDropdown();
  renderCourseTeacherTeachingLoadPage();
}

function renderCourseTeacherTeachingLoadPage(opts = {}) {
  seedTeacherTeachingLoadHistoricalOfferingDemo();
  const root = getTeacherTeachingLoadRoot();
  const head = ttlEl('head', root);
  const body = ttlEl('body', root);
  const foot = ttlEl('foot', root);
  if (!head || !body || !foot) return;
  syncTeacherTeachingLoadDimensionChrome(root);
  const dd = ttlEl('term-dropdown', root);
  const typeDd = ttlEl('course-type-dropdown', root);
  const keepOpen = !!(opts.preserveTermDropdown && dd && !dd.hidden);
  const keepTypeOpen = !!(opts.preserveCourseTypeDropdown && typeDd && !typeDd.hidden);
  ensureTeacherTeachingLoadTermMultiselect(root);
  ensureTeacherTeachingLoadCourseTypeMultiselect(root);
  ensureTeacherTeachingLoadUnitFilter(root);
  ensureTeacherTeachingLoadTypeFilter(root);
  if (keepOpen && dd) dd.hidden = false;
  if (keepTypeOpen && typeDd) typeDd.hidden = false;
  const filteredRows = getFilteredTeacherTeachingLoadRows(root);
  const isYear = teacherTeachingLoadDimension === 'academic-year';
  const isWeek = teacherTeachingLoadDimension === 'week';
  const currentTermCode = getTeacherTeachingLoadCurrentTermCode();
  const listKey = 'teacherTeachingLoad';

  if (isYear) {
    const years = ensureTeacherTeachingLoadSelectedYears();
    const colCount = years.length;
    const fixedCols = 3; // Name + 所属部门 + 教师类型（序号先隐藏）
    // const fixedCols = 4; // 序号 + Name + 所属部门 + 教师类型
    syncTeacherTeachingLoadColgroup(root, { showExpand: false, metricCount: colCount });
    const rows = sortListWithState(
      filteredRows,
      listKey,
      buildTeacherTeachingLoadSortColumns(years, true),
      defaultTeacherTeachingLoadCompare
    );
    head.innerHTML = `
      <tr>
        ${formatTeacherTeachingLoadTitleHtml('Teaching Load (hour) · 按学年', fixedCols + colCount)}
      </tr>
      <tr>
        ${'' /* <th class="col-index col-center">序号</th> */}
        ${renderListSortTh(listKey, 'Name', 'name', { extraClass: 'col-name' })}
        ${renderListSortTh(listKey, '所属部门', 'dept', { center: true, extraClass: 'col-dept' })}
        ${renderListSortTh(listKey, '教师类型', 'teacherType', { center: true, extraClass: 'col-teacher-type' })}
        ${years.map(year => {
          const terms = getAcademicYearTermsForTeachingLoad(year);
          const tip = terms.length
            ? `${terms.map(formatCourseTermDisplay).join('、')}${teacherTeachingLoadIncludeCurrentTermInYear ? '' : '（不含当前学期）'}`
            : (currentTermCode && !teacherTeachingLoadIncludeCurrentTermInYear
              ? `当前学期 ${formatCourseTermDisplay(currentTermCode)} 已排除，暂无其他学期`
              : '暂无学期');
          return renderListSortTh(
            listKey,
            formatTeacherTeachingLoadAcademicYearLabel(year),
            `year:${year}`,
            { center: true, extraClass: 'col-term', title: tip }
          );
        }).join('')}
      </tr>`;
    bindCellFloatTips(root, '.offering-teacher-term-group-rule-btn[data-tip]', { alwaysShow: true });
    if (!rows.length) {
      body.innerHTML = `<tr><td colspan="${fixedCols + colCount}" class="text-muted" style="text-align:center;padding:24px">暂无教师学时数据</td></tr>`;
      foot.innerHTML = '';
      return;
    }
    const yearMeta = years.map(year => {
      const terms = getAcademicYearTermsForTeachingLoad(year);
      return {
        terms,
        values: rows.map(row => sumTeacherTeachingLoadHoursForTerms(row, terms)),
        summaries: rows.map(row => summarizeTeacherTeachingLoadCourseGroupsAcrossTerms(row.staffId, terms))
      };
    });
    body.innerHTML = rows.map((row, idx) => {
      const teacherType = resolveTeacherTeachingLoadTeacherType(row);
      return `<tr>
        ${'' /* <td class="col-index col-center">${idx + 1}</td> */}
        <td class="col-name">${formatTeacherTeachingLoadNameCell(row)}</td>
        <td class="col-dept col-center">${formatTeacherTeachingLoadDepartmentCell(row)}</td>
        <td class="col-teacher-type col-center">${escapeHtml(teacherType)}</td>
        ${yearMeta.map(meta => `<td class="col-term col-center">${formatTeacherTeachingLoadHoursCell(meta.values[idx], meta.summaries[idx])}</td>`).join('')}
      </tr>`;
    }).join('');
    const totals = yearMeta.map(meta => meta.values.reduce((sum, v) => sum + v, 0));
    const averages = totals.map(total => (rows.length ? total / rows.length : 0));
    foot.innerHTML = `
      <tr class="is-total">
        <td class="col-name col-center" colspan="3">Grand Total</td>
        ${totals.map(v => `<td class="col-term col-center">${escapeHtml(formatTeacherTeachingLoadHours(v))}</td>`).join('')}
      </tr>
      <tr class="is-average">
        <td class="col-name col-center" colspan="3">AVERAGE</td>
        ${averages.map(v => `<td class="col-term col-center">${escapeHtml(Number(v).toFixed(1))}</td>`).join('')}
      </tr>`;
    return;
  }

  if (isWeek) {
    const terms = ensureTeacherTeachingLoadSelectedTerms();
    const weekCols = getTeacherTeachingLoadWeekColumns(terms);
    const colCount = weekCols.length;
    const fixedCols = 3;
    const termGroups = terms.map(term => ({
      term,
      count: Math.max(1, Number(getOfferingTermTeachingWeeks(term)) || 14)
    }));
    const spacerCount = Math.max(0, termGroups.length - 1);
    const displayColCount = colCount + spacerCount;
    syncTeacherTeachingLoadColgroup(root, {
      showExpand: false,
      compactMetric: true,
      weekTermGroups: termGroups.map(g => g.count)
    });
    const rows = sortListWithState(
      filteredRows,
      listKey,
      buildTeacherTeachingLoadWeekSortColumns(weekCols),
      defaultTeacherTeachingLoadCompare
    );
    const termSpacerTh = '<th class="col-term-spacer" rowspan="2" aria-hidden="true"></th>';
    const termSpacerTd = '<td class="col-term-spacer" aria-hidden="true"></td>';
    head.innerHTML = `
      <tr>
        ${formatTeacherTeachingLoadTitleHtml('Teaching Load (hour) · 按周次', fixedCols + displayColCount, { showGroupRuleTip: false })}
      </tr>
      <tr>
        ${renderListSortTh(listKey, 'Name', 'name', { extraClass: 'col-name', rowspan: 2 })}
        ${renderListSortTh(listKey, '所属部门', 'dept', { center: true, extraClass: 'col-dept', rowspan: 2 })}
        ${renderListSortTh(listKey, '教师类型', 'teacherType', { center: true, extraClass: 'col-teacher-type', rowspan: 2 })}
        ${termGroups.map((g, gi) =>
          `${gi > 0 ? termSpacerTh : ''}<th class="col-center col-term-group" colspan="${g.count}" title="${escapeHtml(formatCourseTermDisplay(g.term))}">${escapeHtml(formatTeacherTeachingLoadTermLabel(g.term))}</th>`
        ).join('')}
      </tr>
      <tr>
        ${weekCols.map((col, ci) => renderListSortTh(
          listKey,
          col.label,
          col.key,
          { center: true, extraClass: 'col-term col-week-load', title: col.title }
        )).join('')}
      </tr>`;
    // 周次行不插空列：学期交界空列已在上一行用 rowspan=2 占位
    if (!rows.length) {
      body.innerHTML = `<tr><td colspan="${fixedCols + Math.max(1, displayColCount)}" class="text-muted" style="text-align:center;padding:24px">暂无教师学时数据</td></tr>`;
      foot.innerHTML = '';
      return;
    }
    const weekValues = weekCols.map(col =>
      rows.map(row => getTeacherTeachingLoadHoursForWeek(row, col.termCode, col.week))
    );
    const joinWeekMetricCells = (renderCell) => weekCols.map((col, ci) => {
      const spacer = ci > 0 && weekCols[ci - 1].termCode !== col.termCode ? termSpacerTd : '';
      return spacer + renderCell(ci);
    }).join('');
    body.innerHTML = rows.map((row, idx) => {
      const teacherType = resolveTeacherTeachingLoadTeacherType(row);
      return `<tr>
        <td class="col-name">${formatTeacherTeachingLoadNameCell(row)}</td>
        <td class="col-dept col-center">${formatTeacherTeachingLoadDepartmentCell(row)}</td>
        <td class="col-teacher-type col-center">${escapeHtml(teacherType)}</td>
        ${joinWeekMetricCells(ci =>
          `<td class="col-term col-week-load col-center">${formatTeacherTeachingLoadHoursValueHtml(weekValues[ci][idx])}</td>`
        )}
      </tr>`;
    }).join('');
    const totals = weekValues.map(vals => vals.reduce((sum, v) => sum + v, 0));
    const averages = totals.map(total => (rows.length ? total / rows.length : 0));
    foot.innerHTML = `
      <tr class="is-total">
        <td class="col-name col-center" colspan="3">Grand Total</td>
        ${joinWeekMetricCells(ci =>
          `<td class="col-term col-week-load col-center">${escapeHtml(formatTeacherTeachingLoadHours(totals[ci]))}</td>`
        )}
      </tr>
      <tr class="is-average">
        <td class="col-name col-center" colspan="3">AVERAGE</td>
        ${joinWeekMetricCells(ci =>
          `<td class="col-term col-week-load col-center">${escapeHtml(Number(averages[ci]).toFixed(1))}</td>`
        )}
      </tr>`;
    return;
  }

  const terms = ensureTeacherTeachingLoadSelectedTerms();
  const termColCount = terms.length;
  const fixedCols = 4; // 详情 + Name + 所属部门 + 教师类型
  syncTeacherTeachingLoadColgroup(root, { showExpand: true, metricCount: termColCount });
  const rows = sortListWithState(
    filteredRows,
    listKey,
    buildTeacherTeachingLoadSortColumns(terms, false),
    defaultTeacherTeachingLoadCompare
  );
  head.innerHTML = `
    <tr>
      ${formatTeacherTeachingLoadTitleHtml('Teaching Load (hour) · 按学期', fixedCols + termColCount)}
    </tr>
    <tr>
      <th class="col-expand col-center">详情</th>
      ${renderListSortTh(listKey, 'Name', 'name', { extraClass: 'col-name' })}
      ${renderListSortTh(listKey, '所属部门', 'dept', { center: true, extraClass: 'col-dept' })}
      ${renderListSortTh(listKey, '教师类型', 'teacherType', { center: true, extraClass: 'col-teacher-type' })}
      ${terms.map(term => renderListSortTh(
        listKey,
        formatTeacherTeachingLoadTermLabel(term),
        `term:${term}`,
        { center: true, extraClass: 'col-term' }
      )).join('')}
    </tr>`;
  bindCellFloatTips(root, '.offering-teacher-term-group-rule-btn[data-tip]', { alwaysShow: true });
  if (!rows.length) {
    body.innerHTML = `<tr><td colspan="${fixedCols + termColCount}" class="text-muted" style="text-align:center;padding:24px">暂无教师学时数据</td></tr>`;
    foot.innerHTML = '';
    return;
  }
  const colSpan = fixedCols + termColCount;
  body.innerHTML = rows.map(row => {
    const staffId = String(row.staffId || '');
    const expanded = teacherTeachingLoadExpandedStaffIds.has(staffId);
    const teacherType = resolveTeacherTeachingLoadTeacherType(row);
    const expandBtn = `<button type="button" class="teacher-load-expand-btn${expanded ? ' is-expanded' : ''}"
      aria-expanded="${expanded ? 'true' : 'false'}"
      aria-label="${expanded ? '收起开课安排详情' : '展开开课安排详情'}"
      onclick="toggleTeacherTeachingLoadRowExpand('${escapeHtml(staffId)}')">${expanded ? '−' : '+'}</button>`;
    const mainRow = `<tr class="teacher-load-main-row${expanded ? ' is-expanded' : ''}">
      <td class="col-expand col-center">${expandBtn}</td>
      <td class="col-name">${formatTeacherTeachingLoadNameCell(row)}</td>
      <td class="col-dept col-center">${formatTeacherTeachingLoadDepartmentCell(row)}</td>
      <td class="col-teacher-type col-center">${escapeHtml(teacherType)}</td>
      ${terms.map(term => {
        const hours = getTeacherTeachingLoadHoursForTerm(row, term);
        const courseRows = getTeacherOfferingTermSectionDetailRows(
          staffId,
          term,
          getTeacherTeachingLoadActiveCourseTypeFilter()
        );
        return `<td class="col-term col-center">${formatTeacherTeachingLoadHoursCell(hours, courseRows)}</td>`;
      }).join('')}
    </tr>`;
    const detailRow = expanded
      ? `<tr class="teacher-load-detail-row">
          <td colspan="${colSpan}">${renderTeacherTeachingLoadExpandDetail(staffId, terms)}</td>
        </tr>`
      : '';
    return mainRow + detailRow;
  }).join('');
  // renderTeacherTeachingLoadExpandDetail(staffId, currentTermCode); // 原仅展开当前开课学期，改跟筛选所选学期
  const totals = terms.map(term =>
    rows.reduce((sum, row) => sum + getTeacherTeachingLoadHoursForTerm(row, term), 0)
  );
  const averages = totals.map(total => (rows.length ? total / rows.length : 0));
  foot.innerHTML = `
    <tr class="is-total">
      <td class="col-expand col-center"></td>
      <td class="col-name col-center" colspan="3">Grand Total</td>
      ${totals.map(v => `<td class="col-term col-center">${escapeHtml(formatTeacherTeachingLoadHours(v))}</td>`).join('')}
    </tr>
    <tr class="is-average">
      <td class="col-expand col-center"></td>
      <td class="col-name col-center" colspan="3">AVERAGE</td>
      ${averages.map(v => `<td class="col-term col-center">${escapeHtml(Number(v).toFixed(1))}</td>`).join('')}
    </tr>`;
}

/** Teaching Load 导出：按当前筛选与维度导出 CSV（学时 + 课程/组数摘要） */
function formatTeacherTeachingLoadHoursExportText(hours, courseRowsOrSummary) {
  const hoursText = formatTeacherTeachingLoadHours(hours);
  let courses = 0;
  let groups = 0;
  if (courseRowsOrSummary && typeof courseRowsOrSummary.courses === 'number') {
    courses = courseRowsOrSummary.courses;
    groups = courseRowsOrSummary.groups || 0;
  } else if (typeof summarizeTeacherOfferingTermCourseGroupCounts === 'function') {
    const summary = summarizeTeacherOfferingTermCourseGroupCounts(courseRowsOrSummary || []);
    courses = summary.courses || 0;
    groups = summary.groups || 0;
  }
  const courseLabel = courses <= 1 ? 'Course' : 'Courses';
  const groupLabel = groups <= 1 ? 'Group' : 'Groups';
  return `${hoursText} (${courses} ${courseLabel}, ${groups} ${groupLabel})`;
}

function downloadTeacherTeachingLoadCsv(headers, rows, fileStem) {
  const csv = [headers, ...rows]
    .map(cols => cols.map(c => `"${String(c ?? '').replace(/"/g, '""')}"`).join(','))
    .join('\n');
  const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `${fileStem || 'Teaching_Load'}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
}

function exportTeacherTeachingLoad() {
  const root = getTeacherTeachingLoadRoot();
  const filteredRows = getFilteredTeacherTeachingLoadRows(root);
  if (!filteredRows.length) {
    alert('暂无符合条件的数据可导出');
    return;
  }
  const isYear = teacherTeachingLoadDimension === 'academic-year';
  const isWeek = teacherTeachingLoadDimension === 'week';
  const listKey = 'teacherTeachingLoad';
  const stamp = new Date().toISOString().slice(0, 10);

  if (isYear) {
    const years = ensureTeacherTeachingLoadSelectedYears();
    const rows = sortListWithState(
      filteredRows,
      listKey,
      buildTeacherTeachingLoadSortColumns(years, true),
      defaultTeacherTeachingLoadCompare
    );
    const headers = ['Name', '所属部门', '教师类型', ...years.map(formatTeacherTeachingLoadAcademicYearLabel)];
    const yearMeta = years.map(year => {
      const terms = getAcademicYearTermsForTeachingLoad(year);
      return {
        values: rows.map(row => sumTeacherTeachingLoadHoursForTerms(row, terms)),
        summaries: rows.map(row => summarizeTeacherTeachingLoadCourseGroupsAcrossTerms(row.staffId, terms))
      };
    });
    const data = rows.map((row, idx) => [
      String(row?.name || row?.staffId || '').trim() || '—',
      String(row?.departmentCode || '').trim() || '—',
      resolveTeacherTeachingLoadTeacherType(row),
      ...yearMeta.map(meta => formatTeacherTeachingLoadHoursExportText(meta.values[idx], meta.summaries[idx]))
    ]);
    const totals = yearMeta.map(meta => meta.values.reduce((sum, v) => sum + v, 0));
    const averages = totals.map(total => (rows.length ? total / rows.length : 0));
    data.push(['Grand Total', '', '', ...totals.map(formatTeacherTeachingLoadHours)]);
    data.push(['AVERAGE', '', '', ...averages.map(v => Number(v).toFixed(1))]);
    downloadTeacherTeachingLoadCsv(headers, data, `Teaching_Load_按学年_${stamp}`);
    return;
  }

  if (isWeek) {
    const terms = ensureTeacherTeachingLoadSelectedTerms();
    const weekCols = getTeacherTeachingLoadWeekColumns(terms);
    const rows = sortListWithState(
      filteredRows,
      listKey,
      buildTeacherTeachingLoadWeekSortColumns(weekCols),
      defaultTeacherTeachingLoadCompare
    );
    const headers = ['Name', '所属部门', '教师类型', ...weekCols.map(col => col.title || col.label)];
    const data = rows.map(row => [
      String(row?.name || row?.staffId || '').trim() || '—',
      String(row?.departmentCode || '').trim() || '—',
      resolveTeacherTeachingLoadTeacherType(row),
      ...weekCols.map(col => formatTeacherTeachingLoadHours(
        getTeacherTeachingLoadHoursForWeek(row, col.termCode, col.week)
      ))
    ]);
    const totals = weekCols.map(col =>
      rows.reduce((sum, row) => sum + getTeacherTeachingLoadHoursForWeek(row, col.termCode, col.week), 0)
    );
    const averages = totals.map(total => (rows.length ? total / rows.length : 0));
    data.push(['Grand Total', '', '', ...totals.map(formatTeacherTeachingLoadHours)]);
    data.push(['AVERAGE', '', '', ...averages.map(v => Number(v).toFixed(1))]);
    downloadTeacherTeachingLoadCsv(headers, data, `Teaching_Load_按周次_${stamp}`);
    return;
  }

  const terms = ensureTeacherTeachingLoadSelectedTerms();
  const rows = sortListWithState(
    filteredRows,
    listKey,
    buildTeacherTeachingLoadSortColumns(terms, false),
    defaultTeacherTeachingLoadCompare
  );
  const headers = ['Name', '所属部门', '教师类型', ...terms.map(formatTeacherTeachingLoadTermLabel)];
  const data = rows.map(row => {
    const staffId = String(row.staffId || '');
    return [
      String(row?.name || staffId || '').trim() || '—',
      String(row?.departmentCode || '').trim() || '—',
      resolveTeacherTeachingLoadTeacherType(row),
      ...terms.map(term => {
        const hours = getTeacherTeachingLoadHoursForTerm(row, term);
        const courseRows = getTeacherOfferingTermSectionDetailRows(
          staffId,
          term,
          getTeacherTeachingLoadActiveCourseTypeFilter()
        );
        return formatTeacherTeachingLoadHoursExportText(hours, courseRows);
      })
    ];
  });
  const totals = terms.map(term =>
    rows.reduce((sum, row) => sum + getTeacherTeachingLoadHoursForTerm(row, term), 0)
  );
  const averages = totals.map(total => (rows.length ? total / rows.length : 0));
  data.push(['Grand Total', '', '', ...totals.map(formatTeacherTeachingLoadHours)]);
  data.push(['AVERAGE', '', '', ...averages.map(v => Number(v).toFixed(1))]);
  downloadTeacherTeachingLoadCsv(headers, data, `Teaching_Load_按学期_${stamp}`);
}

// ── 通识选修 · 需求 / 配额（方案 A） ──
/**
 * 专业代码 → 文/商/理（挂在专业；学院本身无文商理类别）
 * Arts: CHS/ENG/ADT/COS/JRN · Business: ACC/ECM/FIN/HMT/IBU
 * Science: CAMS/SCDS/SECE/SEEAI/SMP/STCM 下各专业
 */
const PROGRAMME_GE_STREAM_MAP = {
  CHS: 'arts', ENG: 'arts',
  ADT: 'arts', COS: 'arts', JRN: 'arts',
  ACC: 'business', ECM: 'business', FIN: 'business', HMT: 'business', IBU: 'business',
  MBT: 'science', MEC: 'science',
  CST: 'science', CYS: 'science', DMT: 'science', DSC: 'science', SWE: 'science',
  CME: 'science', EGE: 'science',
  AIT: 'science', EEE: 'science', ERA: 'science',
  MAT: 'science', PHY: 'science',
  TCM: 'science'
};

const GE_OFFERING_CROSS_RULE_NOTE =
  '文科学生可选商科、理科 GE；商科学生可选文科、理科 GE；理科学生可选文科、商科 GE（不可同大类）。';

const GE_OFFERING_DEMAND_BY_TERM = {};
const GE_OFFERING_QUOTA_BY_TERM = {};
/** 演示需求按学期分化后的版本；变更后自动重建未手改缓存 */
const GE_OFFERING_DEMAND_MOCK_VERSION = 3;
/** 演示配额默认值按学期分化；仅重建仍带 mockVersion 的缓存，不覆盖用户已保存计划 */
const GE_OFFERING_QUOTA_MOCK_VERSION = 3;

function getProgrammeGeStream(programmeCodeOrKey) {
  if (!programmeCodeOrKey) return 'science';
  const raw = String(programmeCodeOrKey);
  const code = (PROGRAMMES[raw]?.code || raw).toUpperCase();
  return PROGRAMME_GE_STREAM_MAP[code] || 'science';
}

/** 从学期代码解析年份/月份，用于演示数据按学期分化 */
function parseGeOfferingTermParts(termCode) {
  const digits = String(termCode || '').replace(/\D/g, '');
  const n = parseInt(digits, 10) || 0;
  const year = digits.length >= 6 ? parseInt(digits.slice(0, 4), 10) : Math.floor(n / 100);
  const month = digits.length >= 6 ? parseInt(digits.slice(4, 6), 10) : (n % 100);
  return {
    seed: n || 0,
    year: year || 2025,
    month: month || 9,
    isShort: month === 2
  };
}

/** 按开课学期类型给出不同入学批次，保证同学年 02/04/09 列表也不相同 */
function resolveGeOfferingMockIntakes(parts) {
  const y = parts.year;
  const m = parts.month;
  if (m === 9) {
    return {
      a: `${y - 1}/09`,
      b: `${y}/02`,
      c: `${y - 1}/02`,
      d: `${y - 2}/09`,
      elder: `${y - 2}/02`
    };
  }
  if (m === 4) {
    return {
      a: `${y - 1}/09`,
      b: `${y - 1}/02`,
      c: `${y - 2}/09`,
      d: `${y}/02`,
      elder: `${y - 2}/02`
    };
  }
  // 2 月短学期：人数少、批次偏旧
  return {
    a: `${y - 1}/09`,
    b: `${y - 2}/09`,
    c: `${y - 1}/02`,
    d: `${y - 2}/02`,
    elder: `${y - 3}/09`
  };
}

function scaleGeOfferingMockStudents(base, termParts, salt) {
  const { seed, year, month, isShort } = termParts;
  const baseScale = isShort ? 0.58 : (month === 4 ? 0.88 : 1.18);
  const yearDelta = (year - 2025) * 0.08;
  const jitter = (((seed + (salt || 0) * 17) % 21) - 10) / 100;
  const scale = Math.max(0.45, Math.min(1.55, baseScale + yearDelta + jitter));
  const wobble = ((seed + (salt || 0) * 13) % 23) - 11;
  return Math.max(12, Math.round(base * scale) + wobble);
}

function buildGeOfferingDemandMock(termCode) {
  const parts = parseGeOfferingTermParts(termCode);
  const { a: intakeA, b: intakeB, c: intakeC, d: intakeD, elder: intakeElder } = resolveGeOfferingMockIntakes(parts);
  const S = (base, salt) => scaleGeOfferingMockStudents(base, parts, salt);
  const isSep = parts.month === 9;
  const isApr = parts.month === 4;

  // batches: { programmeCode, intake, students } — 人数、批次、学院组合均随 termCode 变化
  const bySchool = [
    {
      schoolCode: 'SASS',
      batches: [
        { programmeCode: 'ENG', intake: intakeA, students: S(70, 1) },
        { programmeCode: 'CHS', intake: intakeB, students: S(50, 2) },
        ...(isSep ? [{ programmeCode: 'ENG', intake: intakeC, students: S(35, 23) }] : [])
      ]
    },
    {
      schoolCode: 'SOC',
      batches: [
        { programmeCode: 'JRN', intake: intakeA, students: S(55, 3) },
        { programmeCode: 'ADT', intake: intakeB, students: S(50, 4) },
        ...(parts.isShort ? [] : [{ programmeCode: 'COS', intake: intakeC, students: S(55, 5) }])
      ]
    },
    {
      schoolCode: 'SEM',
      batches: [
        { programmeCode: 'ACC', intake: intakeA, students: S(80, 6) },
        { programmeCode: 'FIN', intake: isApr ? intakeC : intakeA, students: S(75, 7) },
        { programmeCode: 'IBU', intake: intakeB, students: S(65, 8) },
        ...(parts.isShort ? [] : [{ programmeCode: 'ECM', intake: intakeD, students: S(60, 9) }])
      ]
    },
    {
      schoolCode: 'SEEAI',
      batches: [
        { programmeCode: 'AIT', intake: intakeA, students: S(80, 10) },
        { programmeCode: 'EEE', intake: intakeB, students: S(60, 11) },
        ...(isSep || isApr ? [{ programmeCode: 'ERA', intake: intakeC, students: S(60, 12) }] : [])
      ]
    },
    {
      schoolCode: 'SCDS',
      batches: [
        { programmeCode: 'CST', intake: intakeA, students: S(90, 13) },
        { programmeCode: 'SWE', intake: intakeB, students: S(75, 14) },
        ...(parts.isShort ? [] : [{ programmeCode: 'DSC', intake: intakeC, students: S(75, 15) }])
      ]
    },
    {
      schoolCode: 'SMP',
      batches: [
        { programmeCode: 'MAT', intake: intakeA, students: S(50, 16) },
        ...(isSep ? [{ programmeCode: 'PHY', intake: intakeB, students: S(40, 17) }] : [])
      ]
    },
    {
      schoolCode: 'SECE',
      batches: [
        { programmeCode: 'CME', intake: intakeA, students: S(60, 18) },
        { programmeCode: 'EGE', intake: isApr ? intakeD : intakeB, students: S(50, 19) }
      ]
    },
    ...(parts.isShort ? [] : [{
      schoolCode: 'CAMS',
      batches: [
        { programmeCode: 'MBT', intake: intakeA, students: S(40, 20) },
        { programmeCode: 'MEC', intake: intakeB, students: S(30, 21) }
      ]
    }]),
    {
      schoolCode: 'STCM',
      batches: [
        { programmeCode: 'TCM', intake: intakeElder, students: S(isSep ? 55 : 40, 22) }
      ]
    }
  ].map(row => {
    const students = row.batches.reduce((n, b) => n + (b.students || 0), 0);
    return {
      schoolCode: row.schoolCode,
      students,
      batches: row.batches.map(b => `${b.programmeCode} ${b.intake}`),
      batchDetails: row.batches.map(b => ({
        ...b,
        stream: getProgrammeGeStream(b.programmeCode)
      }))
    };
  });
  const byStream = { arts: 0, business: 0, science: 0 };
  bySchool.forEach(row => {
    (row.batchDetails || []).forEach(b => {
      byStream[b.stream] = (byStream[b.stream] || 0) + (b.students || 0);
    });
  });
  const totalStudents = bySchool.reduce((sum, row) => sum + row.students, 0);
  return {
    termCode,
    totalStudents,
    bySchool,
    byStream,
    crossRuleNote: GE_OFFERING_CROSS_RULE_NOTE,
    isMock: true,
    mockVersion: GE_OFFERING_DEMAND_MOCK_VERSION
  };
}

function ensureGeOfferingDemand(termCode) {
  if (!termCode) return null;
  const cached = GE_OFFERING_DEMAND_BY_TERM[termCode];
  // 旧 mock 按学院挂 stream / 未按学期分化 → 重建
  if (!cached
    || !Array.isArray(cached.bySchool?.[0]?.batchDetails)
    || cached.mockVersion !== GE_OFFERING_DEMAND_MOCK_VERSION) {
    GE_OFFERING_DEMAND_BY_TERM[termCode] = buildGeOfferingDemandMock(termCode);
  }
  return GE_OFFERING_DEMAND_BY_TERM[termCode];
}

function refreshGeOfferingDemandPage() {
  const termCode = getGeOfferingQuotaTermCode();
  const termDisplay = getGeOfferingQuotaTermDisplay() || (termCode ? formatCourseTermDisplay(termCode) : '');
  if (!termCode) {
    alert('请先选择开课学期。');
    return;
  }
  openDeleteConfirm({
    title: '刷新开课计划',
    message: `确定要刷新 <strong>${escapeHtml(termDisplay)}</strong> 学期的开课计划情况吗？`,
    hint: '将重新汇总该学期预计需修 GE 人数与学院需求（演示数据）。',
    confirmLabel: '确认刷新',
    onConfirm: () => {
      delete GE_OFFERING_DEMAND_BY_TERM[termCode];
      ensureGeOfferingDemand(termCode);
      renderGeOfferingQuotaPage();
    }
  });
}

function getGeOfferingSectionPlannedGroupCount(sec) {
  if (!sec) return 0;
  const fromGroups = Array.isArray(sec.groups) ? sec.groups.length : 0;
  const planned = Number(sec.plannedGroupCount);
  const n = Math.max(fromGroups, Number.isFinite(planned) && planned > 0 ? planned : 0);
  return n > 0 ? n : 1;
}

function getGeOfferingActualGroupsBySchool(termCode) {
  if (!termCode) return {};
  const prev = COURSE_OFFERING_PLAN_STORE;
  syncCourseOfferingPlanStoreFromTerm(termCode);
  const map = {};
  (COURSE_OFFERING_PLAN_STORE?.sections || [])
    .filter(s => s.offeringType === 'ge')
    .forEach(sec => {
      ensureGeOfferingSectionFields(sec);
      const unit = resolveGeOfferingSectionOfferingUnit(sec);
      if (!unit) return;
      map[unit] = (map[unit] || 0) + getGeOfferingSectionPlannedGroupCount(sec);
    });
  if (prev?.termCode && prev.termCode !== termCode) {
    syncCourseOfferingPlanStoreFromTerm(prev.termCode);
  } else if (prev) {
    COURSE_OFFERING_PLAN_STORE = prev;
  }
  return map;
}

function buildDefaultGeOfferingQuota(termCode) {
  const parts = parseGeOfferingTermParts(termCode);
  const actual = getGeOfferingActualGroupsBySchool(termCode);
  const termBase = parts.isShort ? 1 : (parts.month === 4 ? 2 : 3);
  // 开课单位 = 9 学院 + MPU（与 OFFERING_UNIT_CODES 一致）；保底随学期分化
  const colleges = (OFFERING_UNIT_CODES || SCHOOL_CODES || []).map((schoolCode, idx) => {
    const wobble = (parts.seed + idx * 11) % 3; // 0..2
    let minGroups = Math.max(1, termBase + wobble - 1);
    // 演示：SEEAI 保底比当前已开多 1 组，便于演示「差 1 组不可提交」
    if (schoolCode === 'SEEAI') {
      minGroups = Math.max(minGroups, (actual.SEEAI || 0) + 1);
    } else if (schoolCode === 'SEM') {
      minGroups = Math.max(minGroups, parts.isShort ? 2 : 4);
    } else if (schoolCode === 'MPU') {
      minGroups = parts.isShort ? 1 : (parts.month === 9 ? 3 : 2);
    } else if (schoolCode === 'SCDS') {
      minGroups = parts.month === 9 ? Math.max(minGroups, 4) : minGroups;
    }
    return { schoolCode, minGroups };
  });
  return { termCode, colleges, mockVersion: GE_OFFERING_QUOTA_MOCK_VERSION };
}

function ensureGeOfferingQuota(termCode) {
  if (!termCode) return null;
  const cached = GE_OFFERING_QUOTA_BY_TERM[termCode];
  // 仅重建仍带 mockVersion 的演示默认；用户保存（无 mockVersion）不覆盖
  if (!cached || (cached.mockVersion != null && cached.mockVersion !== GE_OFFERING_QUOTA_MOCK_VERSION)) {
    GE_OFFERING_QUOTA_BY_TERM[termCode] = buildDefaultGeOfferingQuota(termCode);
  } else {
    // 兼容旧缓存：去掉学院 stream / 统筹参数字段；补齐 MPU 等开课单位
    const q = GE_OFFERING_QUOTA_BY_TERM[termCode];
    delete q.refGroupSize;
    delete q.categoryTotals;
    if (Array.isArray(q.colleges)) {
      const byCode = new Map();
      q.colleges.forEach(c => {
        if (!c?.schoolCode) return;
        byCode.set(c.schoolCode, {
          schoolCode: c.schoolCode,
          minGroups: Number(c.minGroups) || 0
        });
      });
      (OFFERING_UNIT_CODES || []).forEach(code => {
        if (!byCode.has(code)) {
          byCode.set(code, { schoolCode: code, minGroups: 2 });
        }
      });
      const order = OFFERING_UNIT_CODES || [];
      q.colleges = [...byCode.values()].sort((a, b) => {
        const ia = order.indexOf(a.schoolCode);
        const ib = order.indexOf(b.schoolCode);
        return (ia < 0 ? 999 : ia) - (ib < 0 ? 999 : ib);
      });
    }
  }
  return GE_OFFERING_QUOTA_BY_TERM[termCode];
}

function getGeOfferingQuotaCollege(termCode, schoolCode) {
  const quota = ensureGeOfferingQuota(termCode);
  return quota?.colleges?.find(c => c.schoolCode === schoolCode) || null;
}

function getGeOfferingQuotaProgressRows(termCode) {
  const quota = ensureGeOfferingQuota(termCode);
  if (!quota) return [];
  const actual = getGeOfferingActualGroupsBySchool(termCode);
  return (quota.colleges || []).map(c => {
    const actualGroups = actual[c.schoolCode] || 0;
    const minGroups = Number(c.minGroups) || 0;
    return {
      schoolCode: c.schoolCode,
      minGroups,
      actualGroups,
      met: actualGroups >= minGroups,
      shortfall: Math.max(0, minGroups - actualGroups)
    };
  });
}

function collectGeOfferingQuotaShortfallsForSections(secs, termCode) {
  const units = [...new Set(
    (secs || []).map(sec => resolveGeOfferingSectionOfferingUnit(ensureGeOfferingSectionFields(sec))).filter(Boolean)
  )];
  if (!units.length) return [];
  const rows = getGeOfferingQuotaProgressRows(termCode);
  return rows.filter(r => units.includes(r.schoolCode) && !r.met);
}

