function populateGeOfferingEditDrawer(line, sec) {
  ensureGeOfferingSectionFields(sec);
  // ensureGeOfferingVenueTypeMultiselect(); // 原场地类型选择，字段已从抽屉移除
  // closeGeOfferingVenueTypeDropdown();
  const set = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.value = val ?? '';
  };
  set('ge-edit-course-code', line.code || sec.code);
  set('ge-edit-course-name', line.name || sec.name);
  set('ge-edit-credits', line.credits ?? sec.credits);
  set('ge-edit-total-hours', line.totalHours ?? sec.totalHours);
  set('ge-edit-offering-unit', line.offeringUnitAbbr || sec.offeringUnitAbbr
    || resolveSchoolElectiveOfferingUnitAbbr({ code: line.code, offeringUnitAbbr: line.offeringUnitAbbr }));
  // set('ge-edit-planned-group-count', ...); // 拟开组数已从抽屉移除，仍由 section.plannedGroupCount 内部维护
  set('ge-edit-student-total', sec.estimatedStudents ?? sec.studentCount ?? 0);
  set('ge-edit-reserved-spots', sec.reservedSpots ?? DEFAULT_MAJOR_OFFERING_RESERVED_SPOTS);
  updateGeOfferingEditCapacityLimitDisplay();
  set('ge-edit-support-history', formatMajorOfferingSupportHistoryDisplay(sec));
  set('ge-edit-enrollment-type', '开放选课');
  // setGeOfferingVenueTypeSelected(sec.venueTypes || []); // 原场地类型选择，字段已从抽屉移除
  // set('ge-edit-classroom-arrangement', formatClassroomArrangementSummary(sec.classroomAssignments)); // 原教室安排，字段已从抽屉移除
  set('ge-edit-is-scheduled', sec.isScheduled || 'yes');
  set('ge-edit-is-venue-scheduled', sec.isVenueScheduled || 'yes');
  set('ge-edit-is-attendance', sec.isAttendance || 'yes');
  set('ge-edit-is-grade-entry', sec.isGradeEntry || 'yes');
  set('ge-edit-is-exam-scheduled', sec.isExamScheduled || 'yes');
  set('ge-edit-remark', line.remark || '');
  set('ge-edit-theory-hours', sec.theoryHours);
  set('ge-edit-tutorial-hours', sec.tutorialHours);
  set('ge-edit-practice-hours', sec.practiceHours);
  set('ge-edit-other-hours', sec.otherHours);
}

function openGeOfferingEditDrawer(lineId) {
  const line = getGeOfferingLineById(lineId);
  if (!line) return;
  const sec = getGeOfferingSectionForLine(line);
  if (!sec) {
    alert('未找到关联教学班，无法修改。');
    return;
  }
  geOfferingEditLineId = lineId;
  populateGeOfferingEditDrawer(line, sec);
  syncGeOfferingEditDrawerReadOnly(isMajorOfferingTaskArrangementSubmitted(sec));
  // syncGeOfferingEditDrawerReadOnly(false); // 原始终可改；合页后已提交安排则只读查看
  document.getElementById('drawer-ge-offering-edit-backdrop')?.classList.add('open');
  document.getElementById('drawer-ge-offering-edit')?.classList.add('open');
}

function closeGeOfferingEditDrawer() {
  document.getElementById('drawer-ge-offering-edit-backdrop')?.classList.remove('open');
  document.getElementById('drawer-ge-offering-edit')?.classList.remove('open');
  closeGeOfferingVenueTypeDropdown();
  syncGeOfferingEditDrawerReadOnly(false);
  geOfferingEditLineId = null;
}

function confirmGeOfferingEditDrawer() {
  const line = getGeOfferingLineById(geOfferingEditLineId);
  if (!line) return;
  const sec = getGeOfferingSectionForLine(line);
  if (!sec) return;
  const plannedRaw = document.getElementById('ge-edit-student-total')?.value;
  if (plannedRaw === '' || plannedRaw == null) {
    alert('请填写计划总人数。');
    return;
  }
  const plannedTotal = Number(plannedRaw);
  if (!Number.isFinite(plannedTotal) || plannedTotal < 0) {
    alert('请填写有效的计划总人数（非负整数）。');
    return;
  }
  const reservedRaw = document.getElementById('ge-edit-reserved-spots')?.value;
  if (reservedRaw === '' || reservedRaw == null) {
    alert('请填写预留名额。');
    return;
  }
  const reservedSpots = Number(reservedRaw);
  if (!Number.isFinite(reservedSpots) || reservedSpots < 0) {
    alert('请填写有效的预留名额（非负整数）。');
    return;
  }
  // 拟开组数已从抽屉移除，保留既有 plannedGroupCount（ensure 兜底 ≥1）
  ensureGeOfferingSectionFields(sec);
  sec.estimatedStudents = Math.max(0, Math.round(plannedTotal));
  sec.studentCount = sec.estimatedStudents;
  sec.reservedSpots = Math.max(0, Math.round(reservedSpots));
  sec.supportHistory = normalizeMajorOfferingSupportHistory(
    document.getElementById('ge-edit-support-history')?.value
  );
  sec.enrollmentType = 'open';
  // sec.venueTypes = getGeOfferingVenueTypeSelected(); // 原场地类型选择，字段已从抽屉移除
  sec.isScheduled = document.getElementById('ge-edit-is-scheduled')?.value || 'yes';
  sec.isVenueScheduled = document.getElementById('ge-edit-is-venue-scheduled')?.value || 'yes';
  sec.isAttendance = document.getElementById('ge-edit-is-attendance')?.value || 'yes';
  sec.isGradeEntry = document.getElementById('ge-edit-is-grade-entry')?.value || 'yes';
  sec.isExamScheduled = document.getElementById('ge-edit-is-exam-scheduled')?.value || 'yes';
  line.remark = document.getElementById('ge-edit-remark')?.value.trim() || '';
  closeGeOfferingEditDrawer();
  renderGeOfferingPlanPage();
  // renderCourseGeOfferingTaskPage(); // 已由 renderGeOfferingPlanPage 一并刷新下段
}

function openGeOfferingIntakeModal(catalogId) {
  if (!ensureCourseOfferingPlan()) {
    alert('请先维护通识选修开课。');
    return;
  }
  const lines = COURSE_OFFERING_PLAN_STORE.lines.filter(l => l.offeringType === 'ge' && l.catalogId === catalogId);
  if (!lines.length) return;
  const sample = lines[0];
  const title = document.getElementById('course-offering-intake-title');
  const summary = document.getElementById('course-offering-intake-summary');
  const tbody = document.getElementById('course-offering-intake-body');
  if (title) title.textContent = `${sample.code} · 上课批次`;
  if (summary) {
    summary.textContent = `${sample.name} · 开课学期 ${COURSE_OFFERING_PLAN_STORE.termDisplay} · 共 ${lines.length} 个上课批次开设本课程`;
  }
  if (tbody) {
    tbody.innerHTML = lines.map((line, idx) => `<tr>
      <td class="col-index">${idx + 1}</td>
      <td>—</td>
      <td class="col-center"><code>${formatIntakeDisplay(line.intake)}</code></td>
      <td><code>—</code></td>
      <td class="col-center">—</td>
      <td class="col-center">${line.credits ?? '—'}</td>
    </tr>`).join('');
  }
  openModal('modal-course-offering-intake');
}

function ensureSectionOfferingFields(sec) {
  if (!sec) return sec;
  const line = COURSE_OFFERING_PLAN_STORE?.lines.find(l => l.id === sec.lineIds?.[0]);
  const meta = getCatalogOfferingMeta(sec.catalogId);
  if (sec.totalHours == null) {
    Object.assign(sec, meta);
    // 不要沿用目录遗留 weekRange/teachingWeeks（常见 1-12），改由学期默认 1-N
    sec.weekRange = '';
    sec.weeks = '';
    sec.selectedWeeks = [];
  }
  if (!sec.className && line) sec.className = defaultClassNameForLine(line, sec.sectionNo);
  if (!sec.programmeKey && line) sec.programmeKey = line.programmeKey;
  if (!sec.grade && line) {
    const p = parseIntake(line.intake);
    sec.grade = p ? String(p.year) : '';
  }
  if (sec.estimatedStudents == null) sec.estimatedStudents = sec.studentCount || 30;
  if (sec.reservedSpots == null || sec.reservedSpots === '') {
    sec.reservedSpots = DEFAULT_MAJOR_OFFERING_RESERVED_SPOTS;
  }
  if (sec.isGrouped == null) sec.isGrouped = (sec.groups?.length || 0) > 0;
  if (!sec.groups) sec.groups = [];
  if (!sec.groupAssignments) sec.groupAssignments = [];
  // syncSectionGroupsFromProgrammeBatches(sec); // 原计划阶段按专业批次自动生成分组；改由任务安排环节操作
  sanitizeSectionGroupAssignments(sec);
  // seedDemoOfferingGroupAssignments(sec); // 原每次 ensure 都自动造演示学时；新开课任务应保持未安排，演示数据仅在 seedMajorOfferingDemoTasks 中注入
  if (!sec.submitStatus) {
    sec.submitStatus = 'draft'; // 兼容旧 status=offered 也不再自动抬成已提交
    // sec.submitStatus = sec.status === 'offered' ? 'submitted' : 'draft';
  }
  if (!sec.teachingConfirmStatus) sec.teachingConfirmStatus = 'pending';
  if (sec.schedulingVisible == null) {
    sec.schedulingVisible = sec.submitStatus === 'submitted';
  }
  if (sec.rosterScheduleStatus == null) sec.rosterScheduleStatus = 'draft';
  if (sec.sharedTeachingCode == null) sec.sharedTeachingCode = '';
  // if (!sec.status) sec.status = 'offered';
  // if (!sec.weekRange) sec.weekRange = sec.weeks || meta.weekRange; // 原取课程目录默认，改按开课学期教学周数默认 1-N
  ensureSectionWeekRangeFromTerm(sec);
  // 同课程号学分/学时/开课单位对齐目录，避免不同专业批次出现不同学分总学时或开课单位
  if (!sec.offeringType || sec.offeringType === 'major') {
    applyCanonicalMajorOfferingCourseMetrics(
      sec,
      getCanonicalMajorOfferingCourseMetrics(sec.catalogId, sec.code)
    );
    const unit = getCanonicalMajorOfferingUnitAbbr(sec.catalogId, sec.code);
    if (unit) sec.offeringUnitAbbr = unit;
  }
  syncOfferingSectionHoursConsistency(sec);
  ensureOfferingSectionOwner(sec);
  return sec;
}

function syncSectionGroupsFromProgrammeBatches(sec, { force = false } = {}) {
  if (!sec?.lineIds?.length) return;
  const metas = getSectionLineMetas(sec);
  if (!metas.length) return;
  if (!force && sec.groups?.length) {
    const groupLineIds = new Set(sec.groups.map(g => g.lineId).filter(Boolean));
    if (!groupLineIds.size) return; // 自动/手动/合并分组无 lineId 时不覆盖
    const metaLineIds = new Set(metas.map(m => m.lineId));
    // if (groupLineIds.size === metaLineIds.size && [...groupLineIds].every(id => metaLineIds.has(id))) return; // 原仅完全匹配时跳过，合并后小组数变少仍会误覆盖重建
    if (sec.groups.some(g => !g.lineId)) return; // 含合并/自动分组等无 lineId 小组时不覆盖
    if (groupLineIds.size !== metaLineIds.size) return; // 合并/删除后小组数与专业批次不一致时不覆盖
    if (groupLineIds.size === metaLineIds.size && [...groupLineIds].every(id => metaLineIds.has(id))) return;
  }
  sec.groups = metas.map((meta, idx) => ({
    id: `grp-${offeringGroupSeq++}`,
    name: buildDefaultOfferingGroupName(idx + 1),
    // name: meta.batchLabel, // 原默认专业批次名，改 Group1/Group2...
    batchLabel: meta.batchLabel,
    lineId: meta.lineId,
    remark: '',
    capacityLimit: getLineEstimatedStudents(meta.lineId)
      || Math.round((sec.estimatedStudents || 0) / metas.length)
      || 0,
    studentCount: 0
  }));
  // studentCount: getLineEstimatedStudents(meta.lineId) ... // 原 studentCount 兼作上限，改 capacityLimit
  sec.isGrouped = sec.groups.length > 0;
}

function shouldSeedDemoOfferingGroupAssignments(sec, idx = 0) {
  // 演示学时仅由 showcase / prepare*DemoSection 等显式注入；
  // 进入分组页或 init 回填时不得给真实任务自动安排教师（否则会出现「没安排却冒出肖云」）。
  return false;
  // if (sec?.submitStatus !== 'submitted') return false;
  // if (!sec?.groups?.length) return false;
  // return true;
  // if (!sec?.groups?.length) return false;
  // // 多专业批次合班示例、以及前 2 条初始演示任务保留预置学时
  // if ((sec.lineIds?.length || 0) > 1) return true;
  // return idx < 2;
  // if (sec?.teachingConfirmStatus !== 'confirmed') return false; // 原按授课确认，改已提交即可演示任务安排
}

function seedDemoOfferingGroupAssignments(sec) {
  if (!sec || sec.groupAssignments?.length) return;
  const groups = sec.groups || [];
  if (!groups.length) return;
  const pool = buildMockTeacherPickerPool();
  ensureSectionWeekRangeFromTerm(sec);
  seedDemoSectionClassroomInfo(sec);
  const sectionWeekRange = getSectionWeekRangeDisplay(sec);
  const sectionWeeks = getSectionSelectedWeeks(sec);
  const secKey = sec.id || sec.catalogId || '';
  const variant = (secKey.charCodeAt(secKey.length - 1) || 0) % 3;

  function teacherAt(idx, opts = {}) {
    const t = pool[idx % pool.length];
    const teacher = {
      staffId: t.staffId,
      name: t.name,
      teacherType: t.teacherType,
      departmentCode: t.departmentCode,
      isCoordinator: !!opts.isCoordinator
    };
    teacher.role = resolveTeacherTeachingRoleForSection(sec, teacher);
    // role: resolveTeacherTeachingRoleFromType(t.teacherType) // 原仅按教师类型
    return teacher;
  }
  // function teacherAt(idx, role = '主讲') { ... } // 原手动指定授课角色，改由教师类型自动带出

  function buildTeachersPayload(teachers) {
    return {
      teachers,
      staffId: teachers.map(t => t.staffId).filter(Boolean).join('、'),
      teacher: teachers.map(t => t.name).filter(Boolean).join('、'),
      role: teachers.map(t => t.role).filter(Boolean).join('、')
    };
  }

  function makeAssignment({ deliveryScope, groupIds = [], hourType, weekRange: rowWeekRange, teachers, mergeHours = true, weeklyHours: weeklyHoursOverride }) {
    const primaryGroup = groupIds.length ? groups.find(g => g.id === groupIds[0]) : null;
    const weekRangeVal = clampGroupAssignWeekRangeToSection(sec, rowWeekRange || sectionWeekRange);
    // const weekRangeVal = rowWeekRange || defaultWeekRange; // 原未校验课程起止周
    const planWeekly = getGroupAssignPlanWeeklyHours(sec);
    const weeklyHours = weeklyHoursOverride ?? planWeekly ?? null;
    // const weeklyHours = planWeekly || null; // 原不可指定周学时，演示各组已录入学时无法区分
    const rowHours = weeklyHours && weekRangeVal
      ? calcGroupAssignRowHours(weeklyHours, weekRangeVal, sec)
      : null;
    const classroomInfo = resolveSectionClassroomInfoForAssignHourType(sec, hourType);
    return {
      id: `ga-${offeringGroupAssignSeq++}`,
      deliveryScope,
      groupId: groupIds[0] || '',
      groupIds: [...groupIds],
      groupName: deliveryScope === 'section' ? '全体小组' : (primaryGroup?.name || ''),
      studentCount: deliveryScope === 'section'
        ? (sec.estimatedStudents ?? 0)
        : (primaryGroup?.capacityLimit ?? primaryGroup?.studentCount ?? 0),
      // : (primaryGroup?.studentCount ?? 0), // 原取实际人数，改取人数上限
      adminClass: '',
      programmeBatch: deliveryScope === 'section'
        ? getSectionMergedBatchLabelDisplayFull(sec)
        : (primaryGroup?.batchLabel || ''),
      hourType,
      mergeHours,
      weekRange: weekRangeVal,
      weeklyHours,
      hours: rowHours,
      classroomAttribute: classroomInfo.attribute || 'normal',
      classroomPreferences: [...(classroomInfo.referenceClassrooms || [])],
      ...buildTeachersPayload(teachers)
    };
  }

  const assignments = [];
  const emptyTeachers = [];
  if (isOfferingSectionHourTypeArrangeable(sec, '理论学时')) {
    // assignments.push(makeAssignment({
    //   deliveryScope: 'section',
    //   hourType: '理论学时',
    //   weekRange: sectionWeekRange,
    //   teachers: variant === 0 ? [teacherAt(0)] : [teacherAt(0, { isCoordinator: true }), teacherAt(1)]
    // })); // 原全体合班一条理论安排，各组已录入学时无法分别体现
    if (groups[0]) {
      const theoryWeeks1 = sectionWeeks.slice(0, Math.min(10, sectionWeeks.length));
      assignments.push(makeAssignment({
        deliveryScope: 'group',
        groupIds: [groups[0].id],
        hourType: '理论学时',
        weekRange: formatGroupAssignWeekRangeFromSectionWeeks(sec, theoryWeeks1),
        weeklyHours: 3,
        teachers: emptyTeachers
        // teachers: variant === 0 ? [teacherAt(0)] : [teacherAt(0, { isCoordinator: true }), teacherAt(1)]
      }));
    }
    if (groups.length > 1) {
      const theoryWeeks2 = sectionWeeks.slice(0, Math.min(13, sectionWeeks.length));
      assignments.push(makeAssignment({
        deliveryScope: 'group',
        groupIds: [groups[1].id],
        hourType: '理论学时',
        weekRange: formatGroupAssignWeekRangeFromSectionWeeks(sec, theoryWeeks2),
        weeklyHours: 2,
        teachers: emptyTeachers
        // teachers: [teacherAt(1)]
      }));
    }
  }

  if (groups[0] && isOfferingSectionHourTypeArrangeable(sec, '实践学时')) {
    const practiceWeeks = sectionWeeks.length > 2
      ? sectionWeeks.slice(-Math.min(2, sectionWeeks.length))
      : sectionWeeks;
    assignments.push(makeAssignment({
      deliveryScope: 'group',
      groupIds: [groups[0].id],
      hourType: '实践学时',
      weekRange: formatGroupAssignWeekRangeFromSectionWeeks(sec, practiceWeeks),
      // weekRange: variant === 1 ? '9-16' : '10-16', // 原硬编码超出短学期起止周
      teachers: emptyTeachers
      // teachers: variant === 2 ? [teacherAt(2, { isCoordinator: true }), teacherAt(3)] : [teacherAt(2)]
    }));
  }

  if (groups.length > 1 && isOfferingSectionHourTypeArrangeable(sec, '辅导学时')) {
    const tutorialWeeks = sectionWeeks.slice(0, Math.min(4, sectionWeeks.length));
    assignments.push(makeAssignment({
      deliveryScope: 'group',
      groupIds: [groups[1].id],
      hourType: '辅导学时',
      weekRange: formatGroupAssignWeekRangeFromSectionWeeks(sec, tutorialWeeks),
      // weekRange: '1-8', // 原硬编码，改须在课程起止周范围内
      teachers: emptyTeachers
      // teachers: [teacherAt(4)]
    }));
  }

  if (groups.length > 1 && variant !== 0 && isOfferingSectionHourTypeArrangeable(sec, '实践学时')) {
    const practiceWeeks2 = sectionWeeks.length > 1
      ? sectionWeeks.slice(-Math.min(2, sectionWeeks.length))
      : sectionWeeks;
    assignments.push(makeAssignment({
      deliveryScope: 'group',
      groupIds: [groups[1].id],
      hourType: '实践学时',
      weekRange: formatGroupAssignWeekRangeFromSectionWeeks(sec, practiceWeeks2),
      // weekRange: '11-16', // 原硬编码超出短学期起止周
      teachers: emptyTeachers
      // teachers: [teacherAt(5)]
    }));
  }

  const otherGroup = groups[2] || groups[0];
  if (otherGroup && isOfferingSectionHourTypeArrangeable(sec, '其他学时')) {
    const otherWeeks = sectionWeeks.length > 1
      ? sectionWeeks.slice(-Math.min(2, sectionWeeks.length))
      : sectionWeeks;
    assignments.push(makeAssignment({
      deliveryScope: 'group',
      groupIds: [otherGroup.id],
      hourType: '其他学时',
      weekRange: formatGroupAssignWeekRangeFromSectionWeeks(sec, otherWeeks),
      // weekRange: '13-16', // 原硬编码超出短学期起止周
      teachers: emptyTeachers
      // teachers: variant === 1 ? [teacherAt(6, { isCoordinator: true }), teacherAt(7)] : [teacherAt(6)]
    }));
  }

  // if (groups.length > 2 && variant === 1) { ... 原仅部分合班且 variant=1 时造其他学时
  sec.groupAssignments = assignments;
  syncSectionCoordinatorsFromAssignments(sec);
}

function getMajorOfferingSections() {
  if (!ensureCourseOfferingPlan()) return [];
  return COURSE_OFFERING_PLAN_STORE.sections
    .filter(isMajorOfferingCatalogSection)
    // .filter(s => s.offeringType === 'major') // 原仅按 offeringType，改排除通识选修课目录
    .map(ensureSectionOfferingFields)
    .sort((a, b) => a.code.localeCompare(b.code) || a.sectionNo - b.sectionNo);
}

function sectionMatchesMajorOfferingLine(sec, line) {
  if (!sec || !line) return false;
  if (sec.offeringType && sec.offeringType !== 'major') return false;
  if (line.offeringType && line.offeringType !== 'major') return false;
  const lineCode = normalizeOfferingCourseCode(line.code);
  const secCode = normalizeOfferingCourseCode(sec.code);
  // 同课号即可视为可挂接（合班场景）；避免 OCE101 / OCE101* 或 catalogId 不一致被误剥离
  if (lineCode && secCode) return lineCode === secCode;
  if (line.catalogId && sec.catalogId && line.catalogId !== sec.catalogId) return false;
  return true;
  // const lineCode = String(line.code || '').toUpperCase();
  // const secCode = String(sec.code || '').toUpperCase();
  // if (lineCode && secCode && lineCode !== secCode) return false;
  // if (line.catalogId && sec.catalogId && line.catalogId !== sec.catalogId) return false;
}

function resolveMajorOfferingSectionForLine(line, store = COURSE_OFFERING_PLAN_STORE) {
  if (!line || !store?.sections) return null;
  // 清掉错误挂在其它课程教学班上的 lineId（手动合班同课号批次不得拆）
  store.sections.forEach(sec => {
    if (!(sec.lineIds || []).includes(line.id)) return;
    if (sectionMatchesMajorOfferingLine(sec, line)) return;
    if (sec._manualMerged
      && normalizeOfferingCourseCode(sec.code)
      && normalizeOfferingCourseCode(sec.code) === normalizeOfferingCourseCode(line.code)) {
      return;
    }
    sec.lineIds = (sec.lineIds || []).filter(id => id !== line.id);
  });

  const byLineId = store.sections.find(s =>
    (s.lineIds || []).includes(line.id) && sectionMatchesMajorOfferingLine(s, line)
  );
  if (byLineId) {
    if (line.sectionId !== byLineId.id) line.sectionId = byLineId.id;
    return byLineId;
  }

  const pointed = line.sectionId
    ? store.sections.find(s => s.id === line.sectionId)
    : null;
  if (pointed && sectionMatchesMajorOfferingLine(pointed, line)) {
    if (!(pointed.lineIds || []).includes(line.id)) {
      pointed.lineIds = [...(pointed.lineIds || []), line.id];
    }
    return pointed;
  }
  if (pointed && !sectionMatchesMajorOfferingLine(pointed, line)) {
    line.sectionId = null;
  }
  return null;
}

function getMajorOfferingPlanRows() {
  if (!ensureCourseOfferingPlan()) return [];
  repairMajorOfferingLineSectionLinks(COURSE_OFFERING_PLAN_STORE);
  // 纠偏：通识占位行若误标为 major，改回 ge，避免混入专业开课列表
  (COURSE_OFFERING_PLAN_STORE.lines || []).forEach(line => {
    if (!line) return;
    if (line.offeringType === 'ge') return;
    if (line.programmeKey === '__ge__' || line.intake === '__ge-unset__' || line.source === 'school-elective') {
      line.offeringType = 'ge';
      const sec = (COURSE_OFFERING_PLAN_STORE.sections || []).find(s => s.id === line.sectionId);
      if (sec && sec.offeringType !== 'ge') sec.offeringType = 'ge';
    }
  });
  const majorLineById = new Map((COURSE_OFFERING_PLAN_STORE.lines || [])
    .filter(isMajorOfferingCatalogLine)
    .map(line => [line.id, line]));
  return (COURSE_OFFERING_PLAN_STORE.sections || [])
    .filter(sec => {
      if (!sec || sec.offeringType === 'ge' || sec.offeringType === 'other') return false;
      if (sec.offeringType && sec.offeringType !== 'major') return false;
      if (sec.programmeKey === '__ge__') return false;
      return (sec.lineIds || []).some(id => majorLineById.has(id));
    })
    .map(sec => {
      const lines = (sec.lineIds || []).map(id => majorLineById.get(id)).filter(Boolean);
      return {
        line: lines[0] || null,
        lines,
        sec: ensureSectionOfferingFields(sec)
      };
    })
    .sort((a, b) =>
      (a.sec.code || '').localeCompare(b.sec.code || '')
      || getSectionMergedProgrammeDisplayFull(a.sec).localeCompare(getSectionMergedProgrammeDisplayFull(b.sec))
      || getSectionMergedIntakeDisplayFull(a.sec).localeCompare(getSectionMergedIntakeDisplayFull(b.sec))
      || (a.sec.id || '').localeCompare(b.sec.id || '')
    );
}

function getMajorOfferingPlanRowLines(row) {
  if (Array.isArray(row?.lines) && row.lines.length) return row.lines;
  return row?.line ? [row.line] : [];
}

function getMajorOfferingLineSchoolDisplay(line) {
  return getProgrammeSchoolCode(line?.programmeKey) || '—';
}

function getMajorOfferingLineProgrammeDisplay(line) {
  return getProgrammeCode(line?.programmeKey) || '—';
}

function getMajorOfferingLineIntakeDisplay(line) {
  return formatIntakeDisplay(line?.intake) || '—';
}

/** 开课学年学期代码（与上课批次同码制：202409） */
function getMajorOfferingOfferingTermCode(sec = null) {
  const fromSec = normalizeIntakeCode(sec?.termCode || '');
  if (fromSec) return fromSec;
  const fromStore = normalizeIntakeCode(COURSE_OFFERING_PLAN_STORE?.termCode || '');
  if (fromStore) return fromStore;
  const display = document.getElementById('course-major-filter-term')?.value
    || COURSE_OFFERING_PLAN_STORE?.termDisplay
    || getDefaultOfferingTermDisplay()
    || '';
  return normalizeIntakeCode(resolveOfferingTermCodeFromDisplay(display) || getDefaultOfferingTermCode() || '');
}

/** 上课批次 = 开课学年学期 → 新生批次（学生尚未入学） */
function isMajorOfferingNewStudentIntake(intake, termCode = null) {
  const a = normalizeIntakeCode(intake);
  const b = normalizeIntakeCode(termCode || getMajorOfferingOfferingTermCode());
  return !!(a && b && a === b);
}

/** 计划列表「存在新生」：挂接的专业批次中至少有一个新生批次 */
function sectionHasMajorOfferingNewStudentIntake(sec) {
  if (!sec) return false;
  const termCode = getMajorOfferingOfferingTermCode(sec);
  const metas = typeof getSectionLineMetas === 'function' ? getSectionLineMetas(sec) : [];
  if (metas.length) {
    return metas.some(m => isMajorOfferingNewStudentIntake(m.line?.intake, termCode));
  }
  return isMajorOfferingNewStudentIntake(sec.intake, termCode);
}

function isMajorOfferingPlanRowHasNewIntake(row) {
  if (row?.sec) return sectionHasMajorOfferingNewStudentIntake(row.sec);
  return isMajorOfferingNewStudentIntake(row?.line?.intake, getMajorOfferingOfferingTermCode(row?.sec));
}

/** 计划行是否「全部为新生批次」（名单/计划人数等业务口径） */
function isMajorOfferingPlanRowNewIntake(row) {
  if (row?.sec) return isMajorOfferingSectionNewStudentIntake(row.sec);
  return isMajorOfferingNewStudentIntake(row?.line?.intake, getMajorOfferingOfferingTermCode(row?.sec));
}

/** 教学班全部批次均为新生（计划人数/名单等业务口径，非列表「存在新生」） */
function isMajorOfferingSectionNewStudentIntake(sec) {
  if (!sec) return false;
  const termCode = getMajorOfferingOfferingTermCode(sec);
  const metas = typeof getSectionLineMetas === 'function' ? getSectionLineMetas(sec) : [];
  if (metas.length) {
    return metas.every(m => isMajorOfferingNewStudentIntake(m.line?.intake, termCode));
  }
  return isMajorOfferingNewStudentIntake(sec.intake, termCode);
}

/** 专业批次招生计划人数（原型 mock：稳定可复现） */
function getProgrammeIntakeAdmissionPlanCount(programmeKey, intake) {
  const keyIntake = normalizeIntakeCode(intake);
  if (!programmeKey || !keyIntake) return 0;
  const ep = typeof findExecPlanByProgrammeIntake === 'function'
    ? findExecPlanByProgrammeIntake(programmeKey, keyIntake)
    : null;
  if (ep && Number.isFinite(Number(ep.admissionPlanCount))) {
    return Math.max(0, Math.round(Number(ep.admissionPlanCount)));
  }
  const seed = `${programmeKey}|${keyIntake}`;
  let h = 0;
  for (let i = 0; i < seed.length; i += 1) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
  return 80 + (h % 41); // 80–120
}

function getMajorOfferingLineAdmissionPlanCount(line) {
  return getProgrammeIntakeAdmissionPlanCount(line?.programmeKey, line?.intake);
}

function getMajorOfferingSectionAdmissionPlanCount(sec) {
  if (!sec) return 0;
  const metas = typeof getSectionLineMetas === 'function' ? getSectionLineMetas(sec) : [];
  if (metas.length) {
    return metas.reduce(
      (sum, m) => sum + getMajorOfferingLineAdmissionPlanCount(m.line),
      0
    );
  }
  return getProgrammeIntakeAdmissionPlanCount(sec.programmeKey, sec.intake);
}

function syncMajorOfferingNewIntakeSectionPlannedCount(sec) {
  if (!sec || !isMajorOfferingSectionNewStudentIntake(sec)) return;
  if (isMajorOfferingOpenEnrollment(sec)) return;
  const n = getMajorOfferingSectionAdmissionPlanCount(sec);
  sec.estimatedStudents = n;
  sec.studentCount = n;
  majorOfferingStudentRosterStore[sec.id] = [];
}

function migrateSyncMajorOfferingNewIntakePlannedCounts() {
  Object.values(COURSE_OFFERING_PLAN_BY_TERM || {}).forEach(store => {
    if (!store?.sections?.length) return;
    const prev = COURSE_OFFERING_PLAN_STORE;
    COURSE_OFFERING_PLAN_STORE = store;
    store.sections.forEach(sec => {
      if (sec.offeringType && sec.offeringType !== 'major') return;
      syncMajorOfferingNewIntakeSectionPlannedCount(sec);
    });
    COURSE_OFFERING_PLAN_STORE = prev;
  });
}

function renderMajorOfferingNewIntakeDisplay(isNew) {
  return isNew
    ? '<span class="offering-status-pill is-on">是</span>'
    : '<span class="offering-status-pill is-off">否</span>';
}

function getMajorOfferingPlanRowStudentCount(row) {
  return getMajorOfferingPlanRowPresetCount(row);
}

function getMajorOfferingPlanRowPresetCount(row) {
  if (!row?.sec) return 0;
  // 新生批次尚无在校名单，预置人数为 0
  if (isMajorOfferingPlanRowNewIntake(row)) return 0;
  return getMajorOfferingSectionPresetStudentCount(row.sec);
}

function getMajorOfferingSectionPresetStudentCount(sec) {
  if (!sec) return 0;
  if (isMajorOfferingOpenEnrollment(sec)) return 0;
  if (isMajorOfferingSectionNewStudentIntake(sec)) return 0;
  return buildEligiblePresetStudentPool(sec).length;
}

function estimateMajorOfferingPresetRosterCount(sec) {
  const metas = getSectionLineMetas(sec);
  const batches = metas.length ? metas : [{
    line: { programmeKey: sec?.programmeKey, intake: '202409' }
  }];
  return Math.max(batches.length * 8, 12);
}

function clearMajorOfferingPresetRoster(sectionId) {
  if (!sectionId) return;
  const roster = majorOfferingStudentRosterStore[sectionId];
  if (!Array.isArray(roster) || !roster.length) {
    majorOfferingStudentRosterStore[sectionId] = [];
    return;
  }
  // 仅清预置来源，保留选课应用/手动添加（选修仍可在开课名单维护）
  majorOfferingStudentRosterStore[sectionId] = roster.filter(stu => !isPresetMajorOfferingRosterStudent(stu));
  // majorOfferingStudentRosterStore[sectionId] = []; // 原整表清空，会误删选课应用/手动名单
}

function onMajorOfferingEditEnrollmentTypeChange() {
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === majorOfferingEditSectionId);
  if (!sec) return;
  syncMajorOfferingEditStudentTotalField(sec);
  updateMajorOfferingEditCapacityLimitDisplay();
}

function syncMajorOfferingEditStudentTotalField(sec) {
  const el = document.getElementById('mos-edit-student-total');
  const hintEl = document.getElementById('mos-edit-student-total-hint');
  if (!el || !sec) return;
  const locked = isMajorOfferingEditDrawerNonClassroomLocked(sec);
  const enrollmentType = document.getElementById('mos-edit-enrollment-type')?.value || sec.enrollmentType || 'closed';
  const open = enrollmentType === 'open';
  if (open) {
    el.type = 'number';
    el.min = '0';
    el.step = '1';
    el.readOnly = false;
    el.disabled = locked;
    el.classList.toggle('readonly', locked);
    el.removeAttribute('tabindex');
    el.value = sec.estimatedStudents ?? sec.studentCount ?? 0;
    if (hintEl) hintEl.textContent = '开放选课：请手动设置计划总人数';
  } else if (isMajorOfferingSectionNewStudentIntake(sec)) {
    el.type = 'text';
    el.removeAttribute('min');
    el.removeAttribute('step');
    el.readOnly = true;
    el.disabled = false;
    el.classList.add('readonly');
    el.setAttribute('tabindex', '-1');
    syncMajorOfferingNewIntakeSectionPlannedCount(sec);
    el.value = getMajorOfferingSectionAdmissionPlanCount(sec);
    if (hintEl) hintEl.textContent = '新生：读取该专业批次招生计划人数，不可修改；批次尚无在校名单';
  } else {
    el.type = 'text';
    el.removeAttribute('min');
    el.removeAttribute('step');
    el.readOnly = true;
    el.disabled = false;
    el.classList.add('readonly');
    el.setAttribute('tabindex', '-1');
    el.value = isMajorOfferingOpenEnrollment(sec)
      ? estimateMajorOfferingPresetRosterCount(sec)
      : getSectionPlannedStudentCount(sec);
    if (hintEl) hintEl.textContent = '老生：读取批次中可修该课程的学生人数，不可修改';
  }
}

function getSectionIncludedClasses(sec) {
  // return sec.lineIds.map(id => { // 原行政班简称（如 25金融A），XMUM 无行政班概念
  //   const line = COURSE_OFFERING_PLAN_STORE.lines.find(l => l.id === id);
  //   if (!line) return '';
  //   return defaultClassNameForLine(line, 1);
  // }).filter(Boolean);
  return getSectionLineMetas(sec).map(m => m.batchLabel).filter(Boolean);
}

function syncSectionEstimatedStudentsFromRoster(sectionId) {
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === sectionId);
  if (!sec) return;
  if (isMajorOfferingSectionNewStudentIntake(sec)) syncMajorOfferingNewIntakeSectionPlannedCount(sec);
  // 名单管理只维护当前名单与分配结果，不反写计划人数/课程人数上限。
}

function formatMajorOfferingGroupName(courseName, batchLabel) {
  return `${courseName || '—'}（${batchLabel || '—'}）`;
}

function formatMajorOfferingSectionGroupsSummary(sec) {
  if (!sec?.groups?.length) return '尚未分组';
  return sec.groups.map(g => formatMajorOfferingGroupName(sec.name, g.name)).join('、');
}

function getMajorOfferingSectionGroupCount(sec) {
  return sec?.groups?.length || 0;
}

function getMajorOfferingSectionTeacherCount(sec) {
  return collectMajorOfferingSectionTaskArrangementTeachers(sec).length;
}

function areSectionHourTypesAllZero(sec) {
  const theory = Number(sec?.theoryHours) || 0;
  const tutorial = Number(sec?.tutorialHours) || 0;
  const practice = Number(sec?.practiceHours) || 0;
  const other = Number(sec?.otherHours) || 0;
  return theory + tutorial + practice + other === 0;
}

function applySectionScheduleDefaultsByHours(sec) {
  if (!sec) return;
  if (areSectionHourTypesAllZero(sec)) {
    if (!sec.isVenueScheduled) sec.isVenueScheduled = 'no';
    if (!sec.isAttendance) sec.isAttendance = 'no';
  } else {
    if (!sec.isVenueScheduled) sec.isVenueScheduled = 'yes';
    if (!sec.isAttendance) sec.isAttendance = 'yes';
  }
  // if (!sec.isVenueScheduled) sec.isVenueScheduled = 'yes'; // 原不区分学时，改学时全为 0 时默认不排场地
  // if (!sec.isAttendance) sec.isAttendance = 'yes'; // 原不区分学时，改学时全为 0 时默认不考勤
}

function formatMajorOfferingSectionGroupCountDisplay(sec) {
  if (!sec?.isGrouped || !sec?.groups?.length) return '—';
  return String(getMajorOfferingSectionGroupCount(sec));
}

function getMajorOfferingRosterScheduleStatusKey(sec) {
  if (!sec) return 'draft';
  if (sec.submitStatus === 'reverted' || sec.rosterScheduleStatus === 'reverted') return 'reverted';
  if (sec.rosterScheduleStatus === 'submitted') return 'submitted';
  return 'draft';
}

function renderMajorOfferingRosterScheduleStatus(sec) {
  if (isMajorOfferingOpenEnrollment(sec)) {
    return '<span class="offering-status-pill is-off" title="名单由选课应用根据选课结果生成">选课应用</span>';
  }
  const key = getMajorOfferingRosterScheduleStatusKey(sec);
  if (key === 'submitted') {
    return '<span class="offering-status-pill is-on">提交排课</span>';
  }
  if (key === 'reverted') {
    return '<span class="offering-status-pill is-warn">回退</span>';
  }
  return '<span class="offering-status-pill is-off">草稿</span>';
}

function getProgrammeBatchGroupName(courseName, programmeKey, intake) {
  const batchLabel = formatProgrammeIntakeCode(programmeKey, intake);
  return formatMajorOfferingGroupName(courseName, batchLabel);
  // return `${courseName || '—'}(${batchLabel})`; // 原半角括号格式
  // return `${formatProgrammeIntakeCode(programmeKey, intake)} 小组`; // 原格式：专业批次+小组
}

function resolveStudentBatchGroupName(meta, sec) {
  const courseName = sec?.name || '—';
  if (meta?.batchLabel) return formatMajorOfferingGroupName(courseName, meta.batchLabel);
  // if (meta?.batchLabel) return `${courseName}(${meta.batchLabel})`;
  const line = meta?.line;
  if (line?.programmeKey && line?.intake) return getProgrammeBatchGroupName(courseName, line.programmeKey, line.intake);
  return getProgrammeBatchGroupName(courseName, sec?.programmeKey, line?.intake || '202409');
}

function getStudentGroupNames(stu) {
  if (Array.isArray(stu.groupNames) && stu.groupNames.length) {
    return stu.groupNames.filter(Boolean);
  }
  return stu.groupName ? [stu.groupName] : [];
}

function setStudentGroupNames(stu, names) {
  const list = [...new Set((names || []).map(n => String(n).trim()).filter(Boolean))];
  stu.groupNames = list;
  stu.groupName = list.join('、');
}

function getMajorOfferingSectionGroupNames(sectionId) {
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === sectionId);
  if (sec?.groups?.length) return sec.groups.map(g => g.name).filter(Boolean);
  const roster = getMajorOfferingStudentRoster(sectionId);
  return [...new Set(roster.flatMap(stu => getStudentGroupNames(stu)))].sort();
}

function formatStudentCourseGroupLabel(courseName, groupLabel) {
  const label = String(groupLabel || '').trim();
  if (!label) return '—';
  const course = courseName || '—';
  const fullPrefix = `${course}（`;
  if (label.startsWith(fullPrefix) && label.endsWith('）')) return label;
  return formatMajorOfferingGroupName(course, label);
}

function getCourseLevelRosterGroupName(sec) {
  return sec?.name || '课程班';
}

function formatStudentGroupNamesDisplay(stu, sec) {
  const names = getStudentGroupNames(stu);
  if (!names.length) return '未分配';
  const courseName = sec?.name || '—';
  return names.map(n => formatStudentCourseGroupLabel(courseName, n)).join('、');
  // return names.length ? names.join('、') : '—'; // 原直接展示存储的小组名，改为课程名称（小组名称）
  // if (!names.length) return '—'; // 原空组展示破折号，改「未分配」
}

/** 学生名单抽屉「小组」列：无小组时仅课程班，显示为 — */
function formatMajorOfferingStudentRosterGroupCell(stu, sec) {
  if (!(sec?.groups || []).length) return '—';
  return formatStudentGroupNamesDisplay(stu, sec);
}

function isSameStudentCourseGroupName(sec, a, b) {
  const left = String(a || '').trim();
  const right = String(b || '').trim();
  if (!left || !right) return false;
  return left === right
    || formatStudentCourseGroupLabel(sec?.name, left) === formatStudentCourseGroupLabel(sec?.name, right);
}

function refreshMajorOfferingStudentRosterGroups(sectionId) {
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === sectionId);
  const roster = majorOfferingStudentRosterStore[sectionId];
  if (!sec || !roster?.length) return;
  const groups = sec.groups || [];
  if (!groups.length) {
    // 无小组：预置生默认都在课程班，无需再点「一键分配」
    const courseLevel = getCourseLevelRosterGroupName(sec);
    roster.forEach(stu => {
      const names = getStudentGroupNames(stu);
      if (names.length === 1 && isSameStudentCourseGroupName(sec, names[0], courseLevel)) return;
      setStudentGroupNames(stu, [courseLevel]);
    });
    return;
    // 原未走「预置名单分配」前清空课程班占位，名单显示「未分配」，须再点一键分配
    // if (!sec._courseLevelPresetRosterAllocated && !hasPresetRosterAppliedChangeLog(sectionId)) {
    //   roster.forEach(stu => { ... setStudentGroupNames(stu, []); });
    // }
  }
  // 有小组时：仅保留已落到真实小组的分配；其余视为未分配（不再按专业批次自动塞组）
  const validNames = groups.map(g => g.name).filter(Boolean);
  roster.forEach(stu => {
    const names = getStudentGroupNames(stu);
    if (!names.length) return;
    const matched = names.filter(n =>
      validNames.some(vn => isSameStudentCourseGroupName(sec, n, vn))
    );
    if (matched.length !== names.length) setStudentGroupNames(stu, matched);
  });
  // const metas = getSectionLineMetas(sec);
  // roster.forEach(stu => {
  //   if (!(sec.groups || []).length) {
  //     if (!getStudentGroupNames(stu).length) setStudentGroupNames(stu, [getCourseLevelRosterGroupName(sec)]);
  //     return;
  //   }
  //   const meta = metas.find(m =>
  //     m.programmeCode === stu.programmeCode && m.line?.intake === stu.intake
  //   ) || metas.find(m => m.programmeCode === stu.programmeCode) || metas[0];
  //   const defaultGroup = resolveStudentBatchGroupName(meta, sec);
  //   if (!getStudentGroupNames(stu).length) setStudentGroupNames(stu, [defaultGroup]);
  // }); // 原有小组时也按批次自动分配，导致未走「预置名单分配」也显示课程班/批次名
}

const MAJOR_OFFERING_ROSTER_SOURCE_PRESET = '预置名单';
const MAJOR_OFFERING_ROSTER_SOURCE_MANUAL = '手动添加';
const MAJOR_OFFERING_ROSTER_SOURCE_SELECTION = '选课应用';

const OFFERING_ROSTER_CHANGE_TYPE_ADD = '添加';
const OFFERING_ROSTER_CHANGE_TYPE_REMOVE = '移除';
const OFFERING_ROSTER_CHANGE_METHOD_PRESET = '预置名单管理';
const OFFERING_ROSTER_CHANGE_METHOD_MANUAL = '手动管理';
const OFFERING_ROSTER_CHANGE_METHOD_REGISTRY = '学籍异动';

function formatMajorOfferingStudentRosterSource(source) {
  if (source === MAJOR_OFFERING_ROSTER_SOURCE_MANUAL || source === '人工添加' || source === '人工新增') {
    return MAJOR_OFFERING_ROSTER_SOURCE_MANUAL;
  }
  if (source === MAJOR_OFFERING_ROSTER_SOURCE_SELECTION || source === '选课结果') {
    return MAJOR_OFFERING_ROSTER_SOURCE_SELECTION;
  }
  if (source === MAJOR_OFFERING_ROSTER_SOURCE_PRESET || source === '自动生成' || source === '执行计划' || source === 'exec') {
    return MAJOR_OFFERING_ROSTER_SOURCE_PRESET;
  }
  return source || MAJOR_OFFERING_ROSTER_SOURCE_PRESET;
  // if (source === '人工添加' || source === '人工新增') return '人工添加'; // 原展示「人工添加」，改统一为「手动添加」
  // return '自动生成'; // 原展示「自动生成」，改统一为「预置名单」
  // if (source === '执行计划' || source === 'exec') return '自动生成';
}

function isManualMajorOfferingRosterStudent(stu) {
  return formatMajorOfferingStudentRosterSource(stu?.source) === MAJOR_OFFERING_ROSTER_SOURCE_MANUAL;
}

function isPresetMajorOfferingRosterStudent(stu) {
  return formatMajorOfferingStudentRosterSource(stu?.source) === MAJOR_OFFERING_ROSTER_SOURCE_PRESET;
}

function isSelectionAppOfferingRosterStudent(stu) {
  return formatMajorOfferingStudentRosterSource(stu?.source) === MAJOR_OFFERING_ROSTER_SOURCE_SELECTION;
}

function isMajorOfferingSectionElective(sec) {
  return getCatalogOfferingMeta(sec?.catalogId)?.courseNature === '选修';
}

function isPresetStudentEligibleForSection(preset, sec) {
  if (!isEligibleMajorOfferingRosterStudent(preset)) return false;
  const metas = getSectionLineMetas(sec);
  const inScope = metas.some(meta =>
    meta.programmeCode === preset.programmeCode && (meta.line?.intake || '') === (preset.intake || '')
  );
  if (!inScope) return false;
  if (!isMajorOfferingSectionElective(sec)) return true;
  const slot = Number.parseInt(String(preset.studentNo || '').slice(-2), 10);
  return Number.isFinite(slot) ? slot % 10 !== 0 : true;
}

function buildEligiblePresetStudentPool(sec) {
  const metas = getSectionLineMetas(sec);
  const batches = metas.length ? metas : [{
    line: { programmeKey: sec.programmeKey, intake: '202409' },
    lineId: '',
    schoolCode: getProgrammeSchoolCode(sec.programmeKey),
    programmeCode: getProgrammeCode(sec.programmeKey),
    batchLabel: formatProgrammeIntakeCode(sec.programmeKey, '202409')
  }];
  const demoCounts = sec?._oneClickDemoBatchCounts && typeof sec._oneClickDemoBatchCounts === 'object'
    ? sec._oneClickDemoBatchCounts
    : null;
  const demoTotal = demoCounts
    ? batches.reduce((sum, meta) => sum + (Number(demoCounts[meta.programmeCode]) || 0), 0)
    : 0;
  const lineTotal = batches.reduce((sum, meta) => sum + (getLineEstimatedStudents(meta.lineId) || 0), 0);
  const totalCount = Math.max(sec.estimatedStudents || 0, lineTotal, demoTotal, batches.length * 8, 12);
  const perBatch = Math.max(1, Math.floor(totalCount / batches.length));
  const pool = [];
  batches.forEach((meta, batchIdx) => {
    const line = meta.line || { programmeKey: sec.programmeKey, intake: '202409' };
    const demoCount = demoCounts ? Number(demoCounts[meta.programmeCode]) : NaN;
    const batchCount = Number.isFinite(demoCount) && demoCount >= 0
      ? Math.floor(demoCount)
      : (batchIdx === batches.length - 1 ? totalCount - pool.length : perBatch);
    for (let j = 0; j < batchCount; j++) {
      const candidate = {
        studentNo: formatStudentNo(meta.programmeCode, line.intake || '202409', j + 1),
        name: getMockStudentEnglishName(pool.length),
        schoolCode: meta.schoolCode,
        programmeCode: meta.programmeCode,
        intake: line.intake || '202409',
        nationality: getMockStudentNationality(pool.length),
        gender: getMockStudentGender(pool.length),
        registryStatus: 'active',
        registryCategory: 'normal',
        presetLineId: meta.lineId || '',
        presetBatchLabel: meta.batchLabel || '',
        programmeKey: line.programmeKey || sec.programmeKey
      };
      if (isPresetStudentEligibleForSection(candidate, sec)) pool.push(candidate);
    }
  });
  return pool;
}

function resolvePresetStudentCandidateGroups(preset, sec, groups) {
  if (!groups?.length) return [];
  let matched = groups.filter(g => g.lineId && preset.presetLineId && g.lineId === preset.presetLineId);
  if (!matched.length && preset.presetBatchLabel) {
    matched = groups.filter(g => g.batchLabel === preset.presetBatchLabel);
  }
  if (!matched.length && preset.programmeCode) {
    const batchMeta = getSectionLineMetas(sec).find(m =>
      m.programmeCode === preset.programmeCode && (m.line?.intake || '') === (preset.intake || '')
    );
    if (batchMeta?.batchLabel) matched = groups.filter(g => g.batchLabel === batchMeta.batchLabel);
  }
  if (!matched.length && groups.length === 1) matched = groups;
  return matched.length ? matched : groups;
}

function pickPresetStudentTargetGroup(preset, sec, groups, groupCounts) {
  const candidates = resolvePresetStudentCandidateGroups(preset, sec, groups);
  const withRoom = candidates
    .map(g => ({
      group: g,
      remaining: (Number(g.capacityLimit) || Infinity) - (groupCounts.get(g.id) || 0)
    }))
    .filter(x => x.remaining > 0)
    .sort((a, b) => b.remaining - a.remaining || String(a.group.name).localeCompare(String(b.group.name), 'zh-CN'));
  return withRoom[0]?.group || null;
}

function countPresetStudentsInGroups(sec, roster, groupCounts) {
  sec.groups.forEach(g => groupCounts.set(g.id, 0));
  roster.forEach(stu => {
    if (!isPresetMajorOfferingRosterStudent(stu)) return;
    sec.groups.forEach(g => {
      if (studentMatchesOfferingGroup(stu, g, sec)) {
        groupCounts.set(g.id, (groupCounts.get(g.id) || 0) + 1);
      }
    });
  });
}

function resolvePresetRosterStudentGroupingStatus(existing, sec) {
  if (!existing) return 'ungrouped';
  if (!(sec?.groups || []).length) return getStudentGroupNames(existing).length ? 'grouped' : 'ungrouped';
  if ((sec?.groups || []).some(g => studentMatchesOfferingGroup(existing, g, sec))) return 'grouped';
  return 'ungrouped';
}

function formatPresetRosterGroupingStatusLabel(groupingStatus) {
  return groupingStatus === 'grouped' ? '已分配' : '未分配';
}

function buildPresetRosterGroupingPreviewRows(sec) {
  const sectionId = sec.id;
  const roster = [...getMajorOfferingStudentRoster(sectionId)];
  const existingByNo = new Map(roster.map(s => [s.studentNo, s]));
  const rows = [];
  buildEligiblePresetStudentPool(sec).forEach(preset => {
    const existing = existingByNo.get(preset.studentNo);
    if (existing && isManualMajorOfferingRosterStudent(existing)) return;
    const groupingStatus = resolvePresetRosterStudentGroupingStatus(existing, sec);
    if (groupingStatus === 'grouped') return;
    rows.push({
      key: preset.studentNo,
      preset,
      status: 'assignable',
      groupingStatus,
      groupingStatusLabel: formatPresetRosterGroupingStatusLabel(groupingStatus)
    });
  });
  return rows;
  // return buildEligiblePresetStudentPool(sec).map(preset => { ... targetGroup ... }); // 原含已分组与推荐课程组列
}

function applyPresetRosterGroupingCore(sectionId, { studentNos = null, groupByStudentNo = null } = {}) {
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === sectionId);
  if (!sec) return { ok: false, message: '未找到当前课程。' };
  const hasGroups = !!(sec.groups || []).length;
  const presetPool = buildEligiblePresetStudentPool(sec);
  if (!presetPool.length) return { ok: false, message: '未找到符合上课条件的预置名单学生。' };

  const roster = [...getMajorOfferingStudentRoster(sectionId)];
  const existingByNo = new Map(roster.map(s => [s.studentNo, s]));
  const groupCounts = new Map();
  if (hasGroups) countPresetStudentsInGroups(sec, roster, groupCounts);

  let assigned = 0;
  let skippedManual = 0;
  let skippedFull = 0;
  const changeLogEntries = [];

  if (hasGroups && studentNos && groupByStudentNo?.size) {
    const addsByGroupId = buildPresetRosterGroupAddCounts(sec, presetPool, studentNos, groupByStudentNo, existingByNo);
    for (const [gid, addCount] of addsByGroupId) {
      const group = sec.groups.find(g => g.id === gid);
      const validation = validateOfferingGroupCanAcceptStudents(sec, group, addCount, { sectionId });
      if (!validation.ok) return { ok: false, message: validation.message };
    }
  }

  presetPool.forEach(preset => {
    if (studentNos && !studentNos.has(preset.studentNo)) return;
    const existing = existingByNo.get(preset.studentNo);
    if (existing && isManualMajorOfferingRosterStudent(existing)) {
      skippedManual += 1;
      return;
    }
    const explicitGroupId = groupByStudentNo?.get(preset.studentNo);
    const group = hasGroups
      ? (explicitGroupId
        ? sec.groups.find(g => g.id === explicitGroupId)
        : pickPresetStudentTargetGroup(preset, sec, sec.groups, groupCounts))
      : null;
    // const group = pickPresetStudentTargetGroup(preset, sec, sec.groups, groupCounts); // 原仅按规则自动匹配分组
    if (hasGroups && !group) {
      skippedFull += 1;
      return;
    }
    if (hasGroups) {
      const cap = getOfferingGroupCapacityLimitValue(group);
      const cur = groupCounts.get(group.id) || 0;
      if (Number.isFinite(cap) && cur >= cap) {
        skippedFull += 1;
        return;
      }
    }
    // const cap = Number(group.capacityLimit); ... // 原超限静默跳过，改提交前校验并阻止添加
    const groupShortName = hasGroups ? group.name : getCourseLevelRosterGroupName(sec);
    if (existing) {
      setStudentGroupNames(existing, [groupShortName]);
      existing.source = MAJOR_OFFERING_ROSTER_SOURCE_PRESET;
      ensureStudentNationalityFields(existing, roster.indexOf(existing));
      ensureStudentGenderFields(existing, roster.indexOf(existing));
      ensureStudentRegistryFields(existing, roster.indexOf(existing));
    } else {
      const stu = {
        id: `mos-${majorOfferingStudentRosterSeq++}`,
        studentNo: preset.studentNo,
        name: preset.name,
        schoolCode: preset.schoolCode,
        programmeCode: preset.programmeCode,
        intake: preset.intake,
        nationality: preset.nationality,
        gender: preset.gender,
        registryStatus: preset.registryStatus,
        registryCategory: preset.registryCategory,
        groupNames: [groupShortName],
        groupName: groupShortName,
        source: MAJOR_OFFERING_ROSTER_SOURCE_PRESET
      };
      roster.push(stu);
      existingByNo.set(preset.studentNo, stu);
    }
    if (hasGroups) groupCounts.set(group.id, (groupCounts.get(group.id) || 0) + 1);
    assigned += 1;
    changeLogEntries.push({
      studentNo: preset.studentNo,
      studentName: preset.name,
      groupName: groupShortName,
      changeType: OFFERING_ROSTER_CHANGE_TYPE_ADD,
      changeMethod: OFFERING_ROSTER_CHANGE_METHOD_PRESET,
      source: MAJOR_OFFERING_ROSTER_SOURCE_PRESET
    });
  });

  majorOfferingStudentRosterStore[sectionId] = roster;
  if (assigned > 0) {
    sec._presetRosterGroupingApplied = true;
    if (!hasGroups) sec._courseLevelPresetRosterAllocated = true;
  }
  appendOfferingRosterChangeLogEntries(sectionId, changeLogEntries);
  syncSectionEstimatedStudentsFromRoster(sectionId);
  syncOfferingGroupStudentCounts(sec);
  persistMajorOfferingStudentRosterStore();

  const parts = [`已为 ${assigned} 名预置名单学生分配课程组。`];
  if (skippedManual) parts.push(`跳过 ${skippedManual} 名手动添加学生。`);
  if (skippedFull) {
    return { ok: false, message: `${skippedFull} 名学生因分组人数已满未能分配，请调整勾选人数或分组上限后重试。` };
  }
  return { ok: true, assigned, skippedManual, skippedFull, message: parts.join('') };
  // function applyPresetRosterGroupingCore(sectionId) { ... } // 原一次性全量分配，改支持按勾选学号分配
}

// ── 一键分配（无特殊分组导入 / 自定义规则拆组） ──
const ONE_CLICK_ASSIGN_DIMENSIONS = [
  { key: 'nationalityType', label: '国籍类型' },
  { key: 'programme', label: '专业' },
  { key: 'intake', label: '入学批次' },
  { key: 'gender', label: '性别' }
];
const ONE_CLICK_ASSIGN_MODE_OPTIONS = [
  { value: 'proportional', label: '等比例' },
  { value: 'sequential', label: '按顺序' },
  { value: 'unique', label: '唯一值' }
];
const ONE_CLICK_ASSIGN_DIM_CATEGORY_ORDER = {
  nationalityType: ['Local', 'Chinese', 'International'],
  gender: ['Female', 'Male']
};

function shouldShowOfferingGroupingOneClickAssign(sec = getOfferingGroupingSection()) {
  if (!shouldShowOfferingGroupingPresetRosterGrouping(sec)) return false;
  // 无小组时学生默认在课程班，无需再走一键分配；有小组（含唯一组）才展示
  return (sec?.groups || []).length > 0;
}

/** 一键分配前：课程名单人数不得超过各小组人数上限合计 */
function getOneClickAssignGroupCapacityShortfall(sec = getOfferingGroupingSection()) {
  const groups = sec?.groups || [];
  if (!groups.length || !sec?.id) return null;
  const totalCap = getOfferingGroupCapacityAllocated(sec);
  const rosterCount = (getMajorOfferingStudentRoster(sec.id) || []).length;
  if (!rosterCount) return null;
  if (!Number.isFinite(totalCap) || totalCap <= 0) {
    return {
      rosterCount,
      totalCap: 0,
      shortfall: rosterCount,
      courseLimit: getSectionCapacityLimit(sec)
    };
  }
  if (rosterCount <= totalCap) return null;
  return {
    rosterCount,
    totalCap,
    shortfall: rosterCount - totalCap,
    courseLimit: getSectionCapacityLimit(sec)
  };
}

function assertOneClickAssignGroupCapacityCoversRoster(sec = getOfferingGroupingSection()) {
  const gap = getOneClickAssignGroupCapacityShortfall(sec);
  if (!gap) return true;
  const parts = gap.totalCap > 0
    ? [
      `当前课程名单共 ${gap.rosterCount} 人，各小组人数上限合计仅 ${gap.totalCap} 人，还差 ${gap.shortfall} 人。`,
      '请先在左侧小组旁点「✎」调高人数上限后再试一键分配。'
    ]
    : [
      '各小组尚未设置有效的人数上限。',
      '请先在左侧小组旁点「✎」填写人数上限后再试一键分配。'
    ];
  const courseLimit = gap.courseLimit;
  if (Number.isFinite(courseLimit) && courseLimit > 0
    && gap.totalCap >= courseLimit && gap.rosterCount > courseLimit) {
    parts.push(`注意：课程人数上限为 ${courseLimit}，名单人数已超过课程名额，无法仅靠调高小组上限覆盖全部名单。`);
  }
  alert(parts.join('\n'));
  return false;
}

function isOneClickAssignNoSpecialGroupingScenario(sec = getOfferingGroupingSection()) {
  return (sec?.groups || []).length < 2;
}

function getOneClickStudentDimensionValue(stu, dimKey) {
  if (dimKey === 'nationalityType') return getStudentType(stu) || 'International';
  if (dimKey === 'programme') return stu?.programmeCode || '';
  if (dimKey === 'intake') return String(stu?.intake || '');
  if (dimKey === 'gender') return getStudentGender(stu) || '';
  return '';
}

function sortOneClickDimensionCategories(dimKey, categories) {
  const order = ONE_CLICK_ASSIGN_DIM_CATEGORY_ORDER[dimKey];
  return [...categories].sort((a, b) => {
    if (order) {
      const ia = order.indexOf(a);
      const ib = order.indexOf(b);
      const sa = ia < 0 ? 999 : ia;
      const sb = ib < 0 ? 999 : ib;
      if (sa !== sb) return sa - sb;
    }
    return String(a).localeCompare(String(b), 'en');
  });
}

function oneClickSeededShuffle(list, seedText) {
  const arr = [...list];
  let h = 2166136261;
  const seed = String(seedText || 'one-click');
  for (let i = 0; i < seed.length; i += 1) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  for (let i = arr.length - 1; i > 0; i -= 1) {
    h ^= h << 13;
    h ^= h >>> 17;
    h ^= h << 5;
    const j = Math.abs(h) % (i + 1);
    const tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }
  return arr;
}

function orderOneClickAssignableStudents(students, sortByStudentId, seedText) {
  if (sortByStudentId) {
    return [...students].sort((a, b) => String(a.studentNo || '').localeCompare(String(b.studentNo || ''), 'en'));
  }
  return oneClickSeededShuffle(students, seedText);
}

function buildOneClickAssignableStudentPool(sec) {
  if (!sec) return { pool: [], skippedManual: 0 };
  const sectionId = sec.id;
  const roster = getMajorOfferingStudentRoster(sectionId);
  const existingByNo = new Map(roster.map(s => [s.studentNo, s]));
  let skippedManual = 0;
  const pool = [];
  buildEligiblePresetStudentPool(sec).forEach((preset, idx) => {
    const existing = existingByNo.get(preset.studentNo);
    if (existing && isManualMajorOfferingRosterStudent(existing)) {
      skippedManual += 1;
      return;
    }
    const base = existing
      ? { ...existing }
      : {
        studentNo: preset.studentNo,
        name: preset.name,
        schoolCode: preset.schoolCode,
        programmeCode: preset.programmeCode,
        intake: preset.intake,
        nationality: preset.nationality,
        gender: preset.gender,
        registryStatus: preset.registryStatus || 'active',
        registryCategory: preset.registryCategory || 'normal',
        programmeKey: preset.programmeKey
      };
    ensureStudentNationalityFields(base, idx);
    ensureStudentGenderFields(base, idx);
    pool.push(base);
  });
  return { pool, skippedManual };
}

function computeOneClickProportionalTargets(total, caps) {
  const n = caps.length;
  if (total <= 0 || !n) return caps.map(() => 0);
  const capacitySum = caps.reduce((sum, c) => sum + Math.max(0, c), 0);
  const want = Math.min(total, capacitySum);
  let targets = caps.map(() => Math.round(total / n));
  targets = targets.map((t, i) => Math.min(Math.max(0, t), Math.max(0, caps[i])));
  let sum = targets.reduce((a, b) => a + b, 0);
  while (sum < want) {
    let best = -1;
    let bestRoom = 0;
    for (let i = 0; i < n; i += 1) {
      const room = caps[i] - targets[i];
      if (room > bestRoom) {
        bestRoom = room;
        best = i;
      }
    }
    if (best < 0 || bestRoom <= 0) break;
    targets[best] += 1;
    sum += 1;
  }
  while (sum > want) {
    let best = -1;
    let bestVal = -1;
    for (let i = 0; i < n; i += 1) {
      if (targets[i] > bestVal) {
        bestVal = targets[i];
        best = i;
      }
    }
    if (best < 0 || bestVal <= 0) break;
    targets[best] -= 1;
    sum -= 1;
  }
  return targets;
}

function distributeOneClickPoolToGroups(pool, dims, groupIndices, caps) {
  const assigned = [];
  const leftover = [];
  if (!pool?.length) return { assigned, leftover };
  if (!groupIndices?.length) {
    leftover.push(...pool);
    return { assigned, leftover };
  }

  const placeInto = (stu, localIdx) => {
    const gi = groupIndices[localIdx];
    if (caps[localIdx] <= 0) return false;
    assigned.push({ student: stu, groupIndex: gi });
    caps[localIdx] -= 1;
    return true;
  };

  const fillAny = (subset) => {
    for (const stu of subset) {
      let placed = false;
      for (let i = 0; i < groupIndices.length; i += 1) {
        if (placeInto(stu, i)) {
          placed = true;
          break;
        }
      }
      if (!placed) leftover.push(stu);
    }
  };

  if (!dims?.length) {
    fillAny(pool);
    return { assigned, leftover };
  }

  const [dim, ...rest] = dims;
  const byCat = new Map();
  pool.forEach(stu => {
    const key = getOneClickStudentDimensionValue(stu, dim.key) || '—';
    if (!byCat.has(key)) byCat.set(key, []);
    byCat.get(key).push(stu);
  });
  const cats = sortOneClickDimensionCategories(dim.key, [...byCat.keys()]);

  if (dim.mode === 'proportional') {
    cats.forEach(cat => {
      const list = byCat.get(cat) || [];
      const targets = computeOneClickProportionalTargets(list.length, caps);
      const tempCaps = [...targets];
      const sub = distributeOneClickPoolToGroups(list, rest, groupIndices, tempCaps);
      assigned.push(...sub.assigned);
      leftover.push(...sub.leftover);
      sub.assigned.forEach(item => {
        const localIdx = groupIndices.indexOf(item.groupIndex);
        if (localIdx >= 0) caps[localIdx] = Math.max(0, caps[localIdx] - 1);
      });
    });
    return { assigned, leftover };
  }

  if (dim.mode === 'sequential') {
    const capsWork = [...caps];
    const needByLocal = groupIndices.map(() => Object.create(null));
    let localIdx = 0;
    cats.forEach(cat => {
      let left = (byCat.get(cat) || []).length;
      while (left > 0 && localIdx < groupIndices.length) {
        while (localIdx < groupIndices.length && capsWork[localIdx] <= 0) localIdx += 1;
        if (localIdx >= groupIndices.length) break;
        const take = Math.min(left, capsWork[localIdx]);
        needByLocal[localIdx][cat] = (needByLocal[localIdx][cat] || 0) + take;
        capsWork[localIdx] -= take;
        left -= take;
        if (capsWork[localIdx] <= 0) localIdx += 1;
      }
    });
    cats.forEach(cat => {
      const list = byCat.get(cat) || [];
      const catCaps = needByLocal.map(need => need[cat] || 0);
      const want = catCaps.reduce((a, b) => a + b, 0);
      const slice = list.slice(0, want);
      const restStudents = list.slice(want);
      const sub = distributeOneClickPoolToGroups(slice, rest, groupIndices, catCaps);
      assigned.push(...sub.assigned);
      leftover.push(...sub.leftover, ...restStudents);
      sub.assigned.forEach(item => {
        const idx = groupIndices.indexOf(item.groupIndex);
        if (idx >= 0) caps[idx] = Math.max(0, caps[idx] - 1);
      });
    });
    return { assigned, leftover };
  }

  // unique：尽量一组一类，溢出进后续组
  {
    const capsWork = [...caps];
    const needByLocal = groupIndices.map(() => Object.create(null));
    let localIdx = 0;
    cats.forEach(cat => {
      let left = (byCat.get(cat) || []).length;
      while (left > 0 && localIdx < groupIndices.length) {
        while (localIdx < groupIndices.length && capsWork[localIdx] <= 0) localIdx += 1;
        if (localIdx >= groupIndices.length) break;
        const take = Math.min(left, capsWork[localIdx]);
        needByLocal[localIdx][cat] = (needByLocal[localIdx][cat] || 0) + take;
        capsWork[localIdx] -= take;
        left -= take;
        if (capsWork[localIdx] <= 0) localIdx += 1;
      }
    });
    cats.forEach(cat => {
      const list = byCat.get(cat) || [];
      const catCaps = needByLocal.map(need => need[cat] || 0);
      const want = catCaps.reduce((a, b) => a + b, 0);
      const slice = list.slice(0, want);
      const restStudents = list.slice(want);
      const sub = distributeOneClickPoolToGroups(slice, rest, groupIndices, catCaps);
      assigned.push(...sub.assigned);
      leftover.push(...sub.leftover, ...restStudents);
      sub.assigned.forEach(item => {
        const idx = groupIndices.indexOf(item.groupIndex);
        if (idx >= 0) caps[idx] = Math.max(0, caps[idx] - 1);
      });
    });
    return { assigned, leftover };
  }
}

function buildOneClickGroupRemainingCaps(sec, sectionId) {
  const roster = getMajorOfferingStudentRoster(sectionId);
  return (sec.groups || []).map(g => {
    const cap = getOfferingGroupCapacityLimitValue(g);
    const occupied = roster.filter(stu =>
      isManualMajorOfferingRosterStudent(stu) && studentMatchesOfferingGroup(stu, g, sec)
    ).length;
    if (!Number.isFinite(cap)) return Number.MAX_SAFE_INTEGER;
    return Math.max(0, cap - occupied);
  });
}

function applyOneClickRuleAssignCore(sectionId, ruleConfig) {
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === sectionId);
  if (!sec) return { ok: false, message: '未找到开课任务。' };
  const groups = sec.groups || [];
  if (groups.length < 2) return { ok: false, message: '当前课程不存在平行分组，请使用无特殊分组导入。' };
  const dims = (ruleConfig?.dimensions || [])
    .filter(d => d && d.key && d.mode)
    .sort((a, b) => (Number(a.priority) || 99) - (Number(b.priority) || 99));
  if (!dims.length) return { ok: false, message: '请至少选择一个分配维度。' };

  const { pool, skippedManual } = buildOneClickAssignableStudentPool(sec);
  if (!pool.length) {
    return {
      ok: false,
      message: skippedManual
        ? `无可分配学生（已跳过 ${skippedManual} 名手动添加学生）。`
        : '未找到符合上课条件的可分配学生。'
    };
  }

  const sortByStudentId = !!ruleConfig.sortByStudentId;
  const ordered = orderOneClickAssignableStudents(pool, sortByStudentId, `${sectionId}:${dims.map(d => d.key).join(',')}`);
  const caps = buildOneClickGroupRemainingCaps(sec, sectionId);
  const groupIndices = groups.map((_, i) => i);
  const { assigned, leftover } = distributeOneClickPoolToGroups(
    ordered,
    dims.map(d => ({ key: d.key, mode: d.mode })),
    groupIndices,
    [...caps]
  );

  const roster = [...getMajorOfferingStudentRoster(sectionId)];
  const existingByNo = new Map(roster.map(s => [s.studentNo, s]));
  const changeLogEntries = [];
  let assignedCount = 0;

  assigned.forEach(({ student, groupIndex }) => {
    const group = groups[groupIndex];
    if (!group) return;
    const groupShortName = group.name;
    const existing = existingByNo.get(student.studentNo);
    if (existing && isManualMajorOfferingRosterStudent(existing)) return;
    if (existing) {
      setStudentGroupNames(existing, [groupShortName]);
      existing.source = MAJOR_OFFERING_ROSTER_SOURCE_PRESET;
      ensureStudentNationalityFields(existing, roster.indexOf(existing));
      ensureStudentGenderFields(existing, roster.indexOf(existing));
      ensureStudentRegistryFields(existing, roster.indexOf(existing));
    } else {
      const stu = {
        id: `mos-${majorOfferingStudentRosterSeq++}`,
        studentNo: student.studentNo,
        name: student.name,
        schoolCode: student.schoolCode,
        programmeCode: student.programmeCode,
        intake: student.intake,
        nationality: student.nationality,
        gender: student.gender,
        registryStatus: student.registryStatus || 'active',
        registryCategory: student.registryCategory || 'normal',
        groupNames: [groupShortName],
        groupName: groupShortName,
        source: MAJOR_OFFERING_ROSTER_SOURCE_PRESET
      };
      roster.push(stu);
      existingByNo.set(stu.studentNo, stu);
    }
    assignedCount += 1;
    changeLogEntries.push({
      studentNo: student.studentNo,
      studentName: student.name,
      groupName: groupShortName,
      changeType: OFFERING_ROSTER_CHANGE_TYPE_ADD,
      changeMethod: OFFERING_ROSTER_CHANGE_METHOD_PRESET,
      source: MAJOR_OFFERING_ROSTER_SOURCE_PRESET
    });
  });

  majorOfferingStudentRosterStore[sectionId] = roster;
  if (assignedCount > 0) sec._presetRosterGroupingApplied = true;
  appendOfferingRosterChangeLogEntries(sectionId, changeLogEntries);
  syncSectionEstimatedStudentsFromRoster(sectionId);
  syncOfferingGroupStudentCounts(sec);
  persistMajorOfferingStudentRosterStore();

  const parts = [`已按规则为 ${assignedCount} 名学生分配小组。`];
  if (skippedManual) parts.push(`跳过 ${skippedManual} 名手动添加学生。`);
  if (leftover.length) {
    parts.push(`${leftover.length} 名学生因小组人数上限不足未能入组。请在左侧小组旁点「✎」调高上限后重试。`);
  }
  return {
    ok: true,
    assigned: assignedCount,
    skippedManual,
    leftover: leftover.length,
    message: parts.join('')
  };
}

function applyOneClickNoSpecialAssignCore(sectionId) {
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === sectionId);
  if (!sec) return { ok: false, message: '未找到开课任务。' };
  const { pool, skippedManual } = buildOneClickAssignableStudentPool(sec);
  if (!pool.length) {
    return {
      ok: false,
      message: skippedManual
        ? `无可导入学生（已跳过 ${skippedManual} 名手动添加学生）。`
        : '未找到符合专业与入学批次的可导入学生。'
    };
  }
  const studentNos = new Set(pool.map(s => s.studentNo));
  const result = applyPresetRosterGroupingCore(sectionId, { studentNos });
  if (!result.ok) return result;
  const parts = [`已导入 ${result.assigned || 0} 名学生到课程班。`];
  const skipped = (result.skippedManual || 0) || skippedManual;
  if (skipped) parts.push(`跳过 ${skipped} 名手动添加学生。`);
  return {
    ok: true,
    assigned: result.assigned || 0,
    skippedManual: skipped,
    message: parts.join('')
  };
}

function refreshOneClickAssignResultUi() {
  renderOfferingGroupingPanel();
  syncOfferingGroupingStudentActionButtons();
}

function startOfferingGroupingOneClickAssign() {
  if (!shouldShowOfferingGroupingOneClickAssign()) return;
  if (!assertOfferingGroupingStudentEditable('一键分配')) return;
  const sec = getOfferingGroupingSection();
  if (!sec) return;
  if (!assertOneClickAssignGroupCapacityCoversRoster(sec)) return;
  if (isOneClickAssignNoSpecialGroupingScenario(sec)) {
    openOneClickNoSpecialAssignConfirm(sec);
    return;
  }
  openOneClickAssignRulesModal();
}

function openOneClickNoSpecialAssignConfirm(sec) {
  const { pool, skippedManual } = buildOneClickAssignableStudentPool(sec);
  const groupHint = (sec.groups || []).length === 1
    ? `唯一分组「${formatMajorOfferingGroupName(sec.name, sec.groups[0].name)}」`
    : '课程班';
  const groupedCount = getMajorOfferingStudentRoster(sec.id)
    .filter(stu => getStudentGroupNames(stu).length > 0).length;
  openDeleteConfirm({
    title: '一键分配',
    message: `将按专业与入学批次匹配，把 <strong>${pool.length}</strong> 名学生导入到${escapeHtml(groupHint)}。`,
    hint: [
      '与「预置名单分配」并存：本操作为整班快捷导入，不会打开批次勾选抽屉。',
      skippedManual ? `另有 ${skippedManual} 名手动添加学生将跳过。` : '',
      groupedCount ? `当前已有 ${groupedCount} 名学生在课程班/组中；可点「重置」撤回到未分配。` : ''
    ].filter(Boolean).join('\n'),
    confirmLabel: '确认导入',
    resetLabel: '重置',
    resetDisabled: groupedCount === 0,
    onReset: () => {
      const result = resetOneClickNoSpecialAssignGroups(sec);
      if (result.message) alert(result.message);
    },
    onConfirm: () => {
      const result = applyOneClickNoSpecialAssignCore(sec.id);
      refreshOneClickAssignResultUi();
      alert(result.message || (result.ok ? '导入完成。' : '导入失败。'));
    }
  });
}

/** 一键分配（无特殊分组）：撤销已入组，回到未放入课程班/组 */
function resetOneClickNoSpecialAssignGroups(sec) {
  if (!sec) return { ok: false, message: '未找到开课任务。' };
  if (!assertOfferingGroupingStudentEditable('重置')) {
    return { ok: false, message: '' };
  }
  const sectionId = sec.id;
  const roster = getMajorOfferingStudentRoster(sectionId);
  const grouped = roster.filter(stu => getStudentGroupNames(stu).length > 0);
  if (!grouped.length) {
    return { ok: false, message: '当前没有已放入课程班/组的学生。' };
  }
  grouped.forEach(stu => setStudentGroupNames(stu, []));
  delete sec._presetRosterGroupingApplied;
  delete sec._courseLevelPresetRosterAllocated;
  syncSectionEstimatedStudentsFromRoster(sectionId);
  syncOfferingGroupStudentCounts(sec);
  refreshOneClickAssignResultUi();
  return {
    ok: true,
    count: grouped.length,
    message: `已将 ${grouped.length} 名学生撤回到未放入课程班/组的状态。`
  };
}

function renderOneClickAssignRulesDimensionRows(ruleConfig = null) {
  const box = document.getElementById('oca-rule-dims');
  if (!box) return;
  const dims = Array.isArray(ruleConfig?.dimensions)
    ? [...ruleConfig.dimensions]
      .filter(d => d && d.key)
      .sort((a, b) => (Number(a.priority) || 99) - (Number(b.priority) || 99) || String(a.key).localeCompare(String(b.key)))
    : [];
  const selectedKeys = dims.map(d => d.key).filter(key =>
    ONE_CLICK_ASSIGN_DIMENSIONS.some(dim => dim.key === key)
  );
  const modeByKey = Object.fromEntries(dims.map(d => [d.key, d.mode || 'proportional']));
  const checkedCount = selectedKeys.length;
  const priorityMax = Math.max(1, checkedCount);
  const head = `<div class="oca-rule-row oca-rule-head" aria-hidden="true">
    <span></span>
    <span>维度</span>
    <span>分配模式</span>
    <span>优先级</span>
  </div>`;
  const rows = ONE_CLICK_ASSIGN_DIMENSIONS.map(dim => {
    const checked = selectedKeys.includes(dim.key);
    const priorityIdx = selectedKeys.indexOf(dim.key);
    const priorityValue = priorityIdx >= 0 ? String(priorityIdx + 1) : '';
    const selectedMode = modeByKey[dim.key] || 'proportional';
    const modeOptions = ONE_CLICK_ASSIGN_MODE_OPTIONS.map(opt =>
      `<option value="${opt.value}" ${opt.value === selectedMode ? 'selected' : ''}>${opt.label}</option>`
    ).join('');
    return `<div class="oca-rule-row ${checked ? '' : 'is-off'}" data-dim-key="${escapeHtml(dim.key)}">
      <input type="checkbox" class="oca-dim-check" value="${escapeHtml(dim.key)}" ${checked ? 'checked' : ''} onchange="onOneClickAssignDimensionToggle(this)">
      <label>${escapeHtml(dim.label)}</label>
      <select class="input input-sm oca-dim-mode" ${checked ? '' : 'disabled'}>${modeOptions}</select>
      <input class="input input-sm oca-dim-priority" type="number" min="1" max="${priorityMax}" step="1" value="${priorityValue}" ${checked ? '' : 'disabled'} placeholder="" title="优先级（1～已勾选数）" onchange="onOneClickAssignPriorityChange(this)">
    </div>`;
  }).join('');
  box.innerHTML = head + rows;
}

function getOneClickAssignLastRules(sec = getOfferingGroupingSection()) {
  const raw = sec?._oneClickAssignLastRules;
  if (!raw || typeof raw !== 'object') return null;
  const dimensions = (Array.isArray(raw.dimensions) ? raw.dimensions : [])
    .filter(d => d && ONE_CLICK_ASSIGN_DIMENSIONS.some(dim => dim.key === d.key))
    .map((d, idx) => ({
      key: d.key,
      mode: ONE_CLICK_ASSIGN_MODE_OPTIONS.some(opt => opt.value === d.mode) ? d.mode : 'proportional',
      priority: Number.isFinite(Number(d.priority)) ? Number(d.priority) : (idx + 1)
    }))
    .sort((a, b) => a.priority - b.priority || a.key.localeCompare(b.key))
    .map((d, idx) => ({ ...d, priority: idx + 1 }));
  if (!dimensions.length) return null;
  return {
    dimensions,
    sortByStudentId: raw.sortByStudentId !== false
  };
}

function saveOneClickAssignLastRules(sec, config) {
  if (!sec || !config?.dimensions?.length) return;
  sec._oneClickAssignLastRules = {
    dimensions: config.dimensions.map((d, idx) => ({
      key: d.key,
      mode: d.mode || 'proportional',
      priority: Number(d.priority) || (idx + 1)
    })),
    sortByStudentId: !!config.sortByStudentId
  };
}

function updateOneClickAssignRulesPoolHint(sec = getOfferingGroupingSection()) {
  const hint = document.getElementById('oca-rule-pool-hint');
  if (!hint || !sec) return;
  const { pool, skippedManual } = buildOneClickAssignableStudentPool(sec);
  const roster = getMajorOfferingStudentRoster(sec.id);
  const groupedCount = roster.filter(stu => getStudentGroupNames(stu).length > 0).length;
  const groupCaps = (sec.groups || []).map(g =>
    `${formatMajorOfferingGroupName(sec.name, g.name)}≤${getOfferingGroupCapacityLimitValue(g) === Infinity ? '∞' : getOfferingGroupCapacityLimitValue(g)}`
  ).join('、');
  hint.textContent = `可分配 ${pool.length} 人；已入组 ${groupedCount} 人；平行组 ${sec.groups.length} 个（${groupCaps}）`
    + (skippedManual ? `；跳过手动添加 ${skippedManual} 人` : '')
    + '。';
}

function applyOneClickAssignRulesConfigToForm(config = null) {
  const last = config || null;
  renderOneClickAssignRulesDimensionRows(last);
  const sortSel = document.getElementById('oca-sort-by-student-id');
  if (sortSel) sortSel.value = last && last.sortByStudentId === false ? 'N' : 'Y';
}

function resetOneClickAssignStudentGroupsFromRulesModal() {
  const sec = getOfferingGroupingSection();
  if (!sec) return;
  if (!assertOfferingGroupingStudentEditable('重置分组')) return;
  const sectionId = sec.id;
  const roster = getMajorOfferingStudentRoster(sectionId);
  const grouped = roster.filter(stu => getStudentGroupNames(stu).length > 0);
  const hasGrouped = grouped.length > 0;
  const hasRules = !!getOneClickAssignLastRules(sec) || getOneClickAssignCheckedDimRows().length > 0;
  if (!hasGrouped && !hasRules) {
    alert('当前没有已分入组的学生，也没有可清空的分配规则。');
    return;
  }
  openDeleteConfirm({
    title: '重置分组',
    message: hasGrouped
      ? `确定将 <strong>${grouped.length}</strong> 名学生全部撤销分组，并清空分配规则吗？`
      : '确定清空当前分配规则吗？',
    hint: '将清除学生与课程组的关联（不删除平行分组），并清空维度勾选、分配模式、优先级与按学号顺序设置。',
    confirmLabel: '重置分组',
    onConfirm: () => {
      if (hasGrouped) {
        grouped.forEach(stu => setStudentGroupNames(stu, []));
        syncSectionEstimatedStudentsFromRoster(sectionId);
        syncOfferingGroupStudentCounts(sec);
        refreshOneClickAssignResultUi();
      }
      delete sec._oneClickAssignLastRules;
      applyOneClickAssignRulesConfigToForm(null);
      updateOneClickAssignRulesPoolHint(sec);
      alert(hasGrouped
        ? `已撤销 ${grouped.length} 名学生的分组，并清空分配规则。`
        : '已清空分配规则。');
    }
  });
}

function getOneClickAssignCheckedDimRows() {
  return [...document.querySelectorAll('#oca-rule-dims .oca-rule-row:not(.oca-rule-head)')]
    .filter(row => row.querySelector('.oca-dim-check')?.checked);
}

function getOneClickAssignDimPriority(row) {
  const raw = String(row.querySelector('.oca-dim-priority')?.value || '').trim();
  const v = Number(raw);
  return Number.isFinite(v) ? v : Infinity;
}

/** 已勾选维度优先级重排为连续 1…N；可指定某行目标位次（夹紧到 1…N） */
function syncOneClickAssignPriorityInputs(changedRow = null, requestedRaw = null) {
  const allRows = [...document.querySelectorAll('#oca-rule-dims .oca-rule-row:not(.oca-rule-head)')];
  const checkedRows = allRows.filter(row => row.querySelector('.oca-dim-check')?.checked);
  const n = checkedRows.length;
  const priorityMax = Math.max(1, n);

  allRows.forEach(row => {
    const checked = !!row.querySelector('.oca-dim-check')?.checked;
    const modeEl = row.querySelector('.oca-dim-mode');
    const priEl = row.querySelector('.oca-dim-priority');
    row.classList.toggle('is-off', !checked);
    if (modeEl) modeEl.disabled = !checked;
    if (!priEl) return;
    priEl.disabled = !checked;
    priEl.min = '1';
    priEl.max = String(priorityMax);
    if (!checked) priEl.value = '';
  });

  if (!n) return;

  let ordered;
  if (changedRow && checkedRows.includes(changedRow)) {
    let target = Math.round(Number(requestedRaw));
    if (!Number.isFinite(target)) target = n;
    target = Math.max(1, Math.min(n, target));
    const others = checkedRows
      .filter(row => row !== changedRow)
      .sort((a, b) => getOneClickAssignDimPriority(a) - getOneClickAssignDimPriority(b)
        || String(a.dataset.dimKey || '').localeCompare(String(b.dataset.dimKey || '')));
    ordered = [...others];
    ordered.splice(target - 1, 0, changedRow);
  } else {
    ordered = [...checkedRows].sort((a, b) => getOneClickAssignDimPriority(a) - getOneClickAssignDimPriority(b)
      || String(a.dataset.dimKey || '').localeCompare(String(b.dataset.dimKey || '')));
  }

  ordered.forEach((row, idx) => {
    const priEl = row.querySelector('.oca-dim-priority');
    if (priEl) priEl.value = String(idx + 1);
  });
}

function onOneClickAssignDimensionToggle(checkEl) {
  const row = checkEl?.closest?.('.oca-rule-row');
  if (!row) return;
  if (checkEl.checked) {
    // 新勾选追加到末位，再统一重排为 1…N
    syncOneClickAssignPriorityInputs(row, getOneClickAssignCheckedDimRows().length);
    return;
  }
  syncOneClickAssignPriorityInputs();
}

function onOneClickAssignPriorityChange(priEl) {
  if (!priEl || priEl.disabled) return;
  const row = priEl.closest('.oca-rule-row');
  if (!row) return;
  syncOneClickAssignPriorityInputs(row, priEl.value);
}

function readOneClickAssignRulesConfigFromForm() {
  syncOneClickAssignPriorityInputs();
  const dimensions = [];
  let missingPriority = false;
  let invalidPriority = false;
  const seen = new Set();
  const checkedRows = getOneClickAssignCheckedDimRows();
  const n = checkedRows.length;
  checkedRows.forEach(row => {
    const check = row.querySelector('.oca-dim-check');
    const key = check?.value;
    if (!key) return;
    const mode = row.querySelector('.oca-dim-mode')?.value || 'proportional';
    const raw = String(row.querySelector('.oca-dim-priority')?.value || '').trim();
    const priority = Number(raw);
    if (!raw || !Number.isFinite(priority)) {
      missingPriority = true;
      return;
    }
    if (priority < 1 || priority > n || !Number.isInteger(priority) || seen.has(priority)) {
      invalidPriority = true;
    }
    seen.add(priority);
    dimensions.push({ key, mode, priority });
  });
  dimensions.sort((a, b) => a.priority - b.priority || a.key.localeCompare(b.key));
  const sortByStudentId = document.getElementById('oca-sort-by-student-id')?.value !== 'N';
  return { dimensions, sortByStudentId, missingPriority, invalidPriority };
}

function getOneClickAssignRulesTipText() {
  return [
    '分配规则说明',
    '· 勾选分配维度，并设置分配模式与优先级',
    '· 优先级仅为 1～已勾选数的连续正整数，数字越小越优先',
    '· 修改任一优先级后，其余已勾选维度自动重排为连续序号',
    '· 未勾选维度优先级禁用，不参与排序',
    '· 至少选择一个维度后方可开始分配',
    '· 成功分配后再次打开将回填上次规则',
    '· 「重置分组」撤销全部学生入组，并清空本次分配规则',
    '· 分配跳过「手动添加」学生，并遵守各组人数上限'
  ].join('\n');
}

function openOneClickAssignRulesModal() {
  const sec = getOfferingGroupingSection();
  if (!sec) return;
  applyOneClickAssignRulesConfigToForm(getOneClickAssignLastRules(sec));
  updateOneClickAssignRulesPoolHint(sec);
  openModal('modal-one-click-assign-rules');
  const rulesModal = document.getElementById('modal-one-click-assign-rules');
  if (rulesModal) {
    const tipBtn = rulesModal.querySelector('.oca-rules-help-btn');
    if (tipBtn) {
      tipBtn.dataset.tip = getOneClickAssignRulesTipText();
      tipBtn.dataset.tipBound = '';
    }
    bindCellFloatTips(rulesModal, '.oca-rules-help-btn[data-tip]', { alwaysShow: true });
  }
}

function closeOneClickAssignRulesModal() {
  closeModal('modal-one-click-assign-rules');
}

function confirmOneClickAssignRulesModal() {
  const sec = getOfferingGroupingSection();
  if (!sec) return;
  if (!assertOfferingGroupingStudentEditable('一键分配')) return;
  if (!assertOneClickAssignGroupCapacityCoversRoster(sec)) return;
  const config = readOneClickAssignRulesConfigFromForm();
  if (!config.dimensions.length) {
    alert(config.missingPriority ? '请为已勾选维度填写优先级。' : '请至少勾选一个分配维度。');
    return;
  }
  if (config.missingPriority) {
    alert('请为已勾选维度填写优先级。');
    return;
  }
  if (config.invalidPriority) {
    alert('优先级须为 1 到已勾选数的连续正整数，请调整后再分配。');
    return;
  }
  const result = applyOneClickRuleAssignCore(sec.id, config);
  if (result.ok) saveOneClickAssignLastRules(sec, config);
  closeOneClickAssignRulesModal();
  refreshOneClickAssignResultUi();
  alert(result.message || (result.ok ? '分配完成。' : '分配失败。'));
}

