/** Support 学院不可选本课开课单位（通识 / 专业共用） */
function resolveSupportApplyHomeOfferingUnit(sec) {
  if (!sec) return '';
  if (sec.offeringType === 'ge') {
    ensureGeOfferingSectionFields(sec);
    // 与通识列表「开课单位」列同一套来源，避免 section 旧值漏滤
    const line = (COURSE_OFFERING_PLAN_STORE?.lines || []).find(
      l => l.offeringType === 'ge' && (l.sectionId === sec.id || (sec.lineIds || []).includes(l.id))
    );
    const fromLine = line?.offeringUnitAbbr
      || resolveSchoolElectiveOfferingUnitAbbr(findSchoolElectiveCourseForGeLine(line) || {
        code: sec.code || line?.code,
        offeringUnitAbbr: line?.offeringUnitAbbr
      });
    const unit = (fromLine && fromLine !== '—')
      ? fromLine
      : (resolveGeOfferingSectionOfferingUnit(sec) || '');
    if (unit && unit !== '—') {
      if (sec.offeringUnitAbbr !== unit) sec.offeringUnitAbbr = unit;
      return unit;
    }
    return '';
  }
  const unit = resolveMajorOfferingSectionOfferingUnit(sec) || sec.offeringUnitAbbr || '';
  return (unit && unit !== '—') ? unit : '';
}

function formatSupportApplyUnitLabel(code) {
  return `${code} · ${SCHOOL_NAME_MAP[code] || code}`;
}

function ensureMajorOfferingSupportApplyDocListener() {
  if (majorOfferingSupportApplyDocListenerBound) return;
  majorOfferingSupportApplyDocListenerBound = true;
  document.addEventListener('click', ev => {
    const wrap = document.getElementById('support-apply-multiselect');
    if (!wrap || wrap.contains(ev.target)) return;
    closeMajorOfferingSupportApplyDropdown();
  });
}

function closeMajorOfferingSupportApplyDropdown() {
  const dd = document.getElementById('support-apply-dropdown');
  if (dd) dd.hidden = true;
}

function toggleMajorOfferingSupportApplyDropdown(event) {
  event?.stopPropagation?.();
  const dd = document.getElementById('support-apply-dropdown');
  if (!dd) return;
  const willOpen = dd.hidden;
  closeMajorOfferingSupportApplyDropdown();
  if (willOpen) {
    ensureMajorOfferingSupportApplyDocListener();
    dd.hidden = false;
  }
}

function updateMajorOfferingSupportApplyDisplay() {
  const display = document.getElementById('support-apply-display');
  const current = document.getElementById('support-apply-current');
  const codes = [...majorOfferingSupportApplySelectedCodes];
  if (display) {
    if (codes.length) {
      display.textContent = codes.join('、');
      display.classList.remove('placeholder');
    } else {
      display.textContent = '请选择 Support 学院';
      display.classList.add('placeholder');
    }
  }
  if (!current) return;
  if (!codes.length) {
    current.classList.add('is-empty');
    current.textContent = '暂无';
    return;
  }
  current.classList.remove('is-empty');
  current.innerHTML = codes.map(code => {
    const label = formatSupportApplyUnitLabel(code);
    return `<span class="support-apply-chip" title="${escapeHtml(label)}">
      <code>${escapeHtml(code)}</code>
      <span>${escapeHtml(SCHOOL_NAME_MAP[code] || code)}</span>
      <button type="button" class="support-apply-chip-remove" aria-label="移除 ${escapeHtml(code)}"
        onclick="removeMajorOfferingSupportApplyUnit('${escapeHtml(code)}')">×</button>
    </span>`;
  }).join('');
}

function onMajorOfferingSupportApplyToggle(checkbox) {
  const val = checkbox?.value;
  if (!val) return;
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === majorOfferingSupportApplySectionId);
  const homeUnit = resolveSupportApplyHomeOfferingUnit(sec);
  if (checkbox.checked) {
    if (homeUnit && val === homeUnit) {
      checkbox.checked = false;
      return;
    }
    if (!majorOfferingSupportApplySelectedCodes.includes(val)) {
      majorOfferingSupportApplySelectedCodes.push(val);
    }
  } else {
    majorOfferingSupportApplySelectedCodes = majorOfferingSupportApplySelectedCodes.filter(code => code !== val);
  }
  updateMajorOfferingSupportApplyDisplay();
}

function removeMajorOfferingSupportApplyUnit(code) {
  if (!code) return;
  majorOfferingSupportApplySelectedCodes = majorOfferingSupportApplySelectedCodes.filter(c => c !== code);
  const check = document.querySelector(`.support-apply-unit-check[value="${CSS.escape(code)}"]`);
  if (check) check.checked = false;
  updateMajorOfferingSupportApplyDisplay();
}

function openMajorOfferingSupportApplyModal(sectionId) {
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === sectionId);
  if (!sec) return;
  majorOfferingSupportApplySectionId = sectionId;
  majorOfferingSupportApplySelectedCodes = [...getMajorOfferingSectionSupportUnits(sec)];
  renderMajorOfferingSupportApplyModal();
  openModal('modal-major-offering-support-apply');
}

function renderMajorOfferingSupportApplyModal() {
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === majorOfferingSupportApplySectionId);
  if (!sec) return;
  const offeringUnit = resolveSupportApplyHomeOfferingUnit(sec);
  const taskEl = document.getElementById('support-apply-task');
  const unitEl = document.getElementById('support-apply-offering-unit');
  if (taskEl) taskEl.value = sec.code || '';
  // if (taskEl) taskEl.value = `${sec.code || ''} ${sec.name || ''}`.trim(); // 原课号+课程名
  if (unitEl) unitEl.value = offeringUnit || '—';
  // if (unitEl) unitEl.value = offeringUnit ? formatSupportApplyUnitLabel(offeringUnit) : '—'; // 原代码+学院全称
  const options = document.getElementById('support-apply-options');
  const empty = document.getElementById('support-apply-empty');
  if (!options) return;
  const allUnits = [...(typeof OFFERING_UNIT_CODES !== 'undefined' ? OFFERING_UNIT_CODES : SCHOOL_CODES)].sort();
  // 不可选本课开课单位（通识 / 专业开课 Support 管理共用）
  const home = String(offeringUnit || '').trim();
  const units = home
    ? allUnits.filter(c => c !== home)
    : allUnits;
  majorOfferingSupportApplySelectedCodes = majorOfferingSupportApplySelectedCodes.filter(code => units.includes(code));
  if (!units.length) {
    if (empty) empty.hidden = false;
    options.innerHTML = '';
  } else {
    if (empty) empty.hidden = true;
    options.innerHTML = units.map(code => {
      const checked = majorOfferingSupportApplySelectedCodes.includes(code) ? ' checked' : '';
      const label = formatSupportApplyUnitLabel(code);
      return `<label class="clo-multiselect-option">
        <input type="checkbox" class="support-apply-unit-check" value="${escapeHtml(code)}"${checked}
          onchange="onMajorOfferingSupportApplyToggle(this)">
        <span><code>${escapeHtml(code)}</code> ${escapeHtml(SCHOOL_NAME_MAP[code] || code)}</span>
      </label>`;
    }).join('');
  }
  closeMajorOfferingSupportApplyDropdown();
  updateMajorOfferingSupportApplyDisplay();
  // const wrap = document.getElementById('support-apply-units'); // 原平铺勾选
  // const infoEl = document.getElementById('support-apply-info');
}

function closeMajorOfferingSupportApplyModal() {
  closeMajorOfferingSupportApplyDropdown();
  closeModal('modal-major-offering-support-apply');
  majorOfferingSupportApplySectionId = null;
  majorOfferingSupportApplySelectedCodes = [];
}

function confirmMajorOfferingSupportApply() {
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === majorOfferingSupportApplySectionId);
  if (!sec) return;
  const homeUnit = resolveSupportApplyHomeOfferingUnit(sec);
  const selected = majorOfferingSupportApplySelectedCodes.filter(code => code && code !== homeUnit);
  // const selected = [...document.querySelectorAll('.support-apply-unit-check:checked')].map(el => el.value);
  sec.supportUnits = selected;
  // Support历史由「特殊课程设置」维护，不随本次申请改写
  closeMajorOfferingSupportApplyModal();
  renderCourseMajorOfferingTaskPage();
  renderCourseOfferingMajorPage();
  if (document.getElementById('page-course-major-offering-task-style2')?.classList.contains('active')) {
    renderCourseMajorOfferingTaskStyle2Page();
  }
  if (sec.offeringType === 'ge') renderGeOfferingPlanPage();
  if (selected.length) {
    alert(`已保存 Support 学院：${selected.join('、')}。\n该开课任务已共享给对应 Support 学院，Support 学院管理员可查看并在「安排教师」时安排本学院教师。`);
  } else {
    alert('已清空该开课任务的 Support 学院。');
  }
}

function isMajorOfferingPlanEditLocked(sec) {
  if (!sec) return false;
  return sec.submitStatus === 'submitted';
}

function isMajorOfferingSectionStructureLocked(sec) {
  if (!sec) return false;
  return isMajorOfferingTaskArrangementSubmitted(sec);
  // return sec.submitStatus === 'submitted' || sec.teachingConfirmStatus === 'confirmed'; // 原提交后即锁定，改由授课确认后锁定（任务安排阶段可合分班/分组）
}

function getMajorOfferingPlanEditLockMessage(sec) {
  if (!isMajorOfferingPlanEditLocked(sec)) return '';
  return '当前计划已提交，不支持修改，仅可查看。';
}

function getMajorOfferingStructureLockMessage(sec) {
  if (!isMajorOfferingSectionStructureLocked(sec)) return '';
  return '已提交生效，不支持修改，仅可查看。';
  // return '当前已完成授课确认，不支持修改，仅可查看。'; // 原授课确认锁定提示，改任务安排提交
  // const parts = [];
  // if (sec.submitStatus === 'submitted') parts.push('已提交');
  // if (sec.teachingConfirmStatus === 'confirmed') parts.push('已授课确认');
  // return `当前状态（${parts.join('、')}）不支持修改，仅可查看。`; // 原合并提示
}

/** 编辑抽屉完全锁定（任务安排已提交生效）：不可改、不可保存 */
function isMajorOfferingEditDrawerFullyLocked(sec) {
  return isMajorOfferingSectionStructureLocked(sec);
}

/**
 * 计划已提交、任务安排尚未生效：仅教室信息可改。
 * 开课计划「编辑」与开课安排「开课前期设置」共用此规则。
 */
function isMajorOfferingEditDrawerClassroomOnly(sec) {
  if (!sec || isMajorOfferingEditDrawerFullyLocked(sec)) return false;
  return sec.submitStatus === 'submitted';
}

/** 非教室字段是否只读 */
function isMajorOfferingEditDrawerNonClassroomLocked(sec) {
  return isMajorOfferingEditDrawerFullyLocked(sec) || isMajorOfferingEditDrawerClassroomOnly(sec);
}

/** @deprecated 语义改为完全锁定；教室仅可改请用 isMajorOfferingEditDrawerClassroomOnly */
function isMajorOfferingEditDrawerLocked(sec) {
  return isMajorOfferingEditDrawerFullyLocked(sec);
}

function getMajorOfferingEditDrawerLockMessage(sec) {
  if (!isMajorOfferingEditDrawerFullyLocked(sec)) return '';
  return getMajorOfferingStructureLockMessage(sec) || '已提交生效，不支持修改，仅可查看。';
}

function getMajorOfferingEditDrawerClassroomOnlyMessage(sec) {
  if (!isMajorOfferingEditDrawerClassroomOnly(sec)) return '';
  return '计划已提交生效，仅可修改教室信息。';
}

function assertMajorOfferingEditDrawerEditable(sec, actionLabel = '操作') {
  if (!isMajorOfferingEditDrawerFullyLocked(sec)) return true;
  alert(getMajorOfferingEditDrawerLockMessage(sec) || `当前状态不支持${actionLabel}。`);
  return false;
}

function assertMajorOfferingEditDrawerNonClassroomEditable(sec, actionLabel = '操作') {
  if (isMajorOfferingEditDrawerFullyLocked(sec)) {
    alert(getMajorOfferingEditDrawerLockMessage(sec) || `当前状态不支持${actionLabel}。`);
    return false;
  }
  if (isMajorOfferingEditDrawerClassroomOnly(sec)) {
    alert(getMajorOfferingEditDrawerClassroomOnlyMessage(sec) || `计划已提交，仅可修改教室信息，不支持${actionLabel}。`);
    return false;
  }
  return true;
}

function syncMajorOfferingReadonlyHint(host, sec, bannerId, {
  insertAfter = null,
  isLocked = isMajorOfferingSectionStructureLocked,
  getMessage = getMajorOfferingStructureLockMessage
} = {}) {
  if (!host) return;
  let banner = document.getElementById(bannerId);
  const locked = isLocked(sec);
  if (!locked) {
    if (banner) banner.hidden = true;
    return;
  }
  if (!banner) {
    banner = document.createElement('div');
    banner.id = bannerId;
    banner.className = 'offering-readonly-hint';
    const anchor = insertAfter ? host.querySelector(insertAfter) : null;
    if (anchor) anchor.insertAdjacentElement('afterend', banner);
    else host.insertBefore(banner, host.firstChild);
  }
  banner.textContent = getMessage(sec);
  banner.hidden = false;
}

function assertMajorOfferingPlanEditEditable(sec, actionLabel = '操作') {
  if (!isMajorOfferingPlanEditLocked(sec)) return true;
  alert(getMajorOfferingPlanEditLockMessage(sec) || `当前状态不支持${actionLabel}。`);
  return false;
}

function setContainerButtonsDisabled(container, disabled) {
  if (!container) return;
  container.querySelectorAll('button').forEach(btn => { btn.disabled = disabled; });
}

function renderMajorOfferingStructureActions(sec) {
  const parts = [];
  // `<a href="#" onclick="openMajorOfferingEditDrawer('${sec.id}');return false">修改</a>` // 改由「课程信息」列「编辑」
  if (isMajorOfferingPlanEditLocked(sec)) {
    parts.push(renderDisabledAction('合班', getMajorMergeSplitSelectableMessage('plan')));
  } else {
    parts.push(`<a href="#" onclick="openMajorMergeSplitModal('${sec.id}', { context: 'plan' });return false">合班</a>`);
  }
  if (sec?.submitStatus === 'reverted' && (sec.taskRevertRemark || '').trim()) {
    parts.push(`<a href="#" onclick="openMajorOfferingTaskRevertRemarkView('${sec.id}');return false">回退说明</a>`);
  }
  return parts.join(' · ');
}

