function buildMajorOfferingTaskSubmitConfirm(pendingSections) {
  const failures = [];
  const overHourTitles = [];
  const underHourTitles = [];
  let allOk = true;
  pendingSections.forEach(sec => {
    ensureSectionOfferingFields(sec);
    const result = validateMajorOfferingTaskArrangementSubmit(sec);
    const teacherConfirm = validateMajorOfferingTaskTeacherConfirmation(sec);
    const title = [sec.code, sec.name].filter(Boolean).join(' ') || '当前任务';
    if (!result.ok) {
      allOk = false;
      const detail = (result.message || '')
        .replace(/^提交失败，请先完善以下内容：\n?/, '')
        .replace(/^以下分组学时尚未安排完成：\n*/, '')
        .trim();
      failures.push(detail ? `${title}：\n${detail}` : title);
      return;
    }
    if (!teacherConfirm.ok) {
      allOk = false;
      failures.push(`${title}：\n${teacherConfirm.message}`);
      return;
    }
    if (result.overHourWarning) {
      overHourTitles.push(title);
    }
    if (result.underHourWarning) {
      underHourTitles.push(title);
    }
  });
  const openEnrollmentCount = pendingSections.filter(isMajorOfferingOpenEnrollment).length;
  const closedCount = pendingSections.length - openEnrollmentCount;
  let baseHint = '生效后将锁定合分班、分组与教师安排；须全部授课教师已在系统内完成确认（含管理端代确认）。';
  if (closedCount) {
    baseHint += '必修课程可在「开课名单」按小组维护学生名单。';
    // baseHint += '不开放选课的课程，教务处可在「专业开课学生名单管理」按小组维护学生名单。'; // 原文案
  }
  if (openEnrollmentCount) {
    baseHint += closedCount
      ? `其中 ${openEnrollmentCount} 门为选修，默认名单由选课应用生成，仍可在「开课名单」维护。`
      : '所选均为选修课程，默认名单由选课应用生成，仍可在「开课名单」维护。';
    // baseHint += ... '学生名单不由本模块维护...' // 原不可维护口径，改选修也可在开课名单维护
  }
  if (!allOk) {
    return {
      allOk: false,
      hint: [
        '以下开课任务尚未满足生效条件（未安排教师、教师安排信息不完整、授课教师未全部确认，或有小组时分组人数上限未覆盖计划人数等），暂无法生效：',
        '',
        ...failures.map(text => `· ${text}`),
        '',
        '请完善分组/师资安排并完成授课教师确认后再生效。'
      ].join('\n'),
      hasOverHour: false
    };
  }
  let hint = baseHint;
  const warnBlocks = [];
  if (underHourTitles.length) {
    warnBlocks.push([
      '以下任务的学时尚未排满，确认后仍可提交：',
      '',
      ...underHourTitles.map(title => `· ${title}`)
    ].join('\n'));
  }
  if (overHourTitles.length) {
    warnBlocks.push([
      '以下任务的学时安排已超过计划学时，确认后仍可提交：',
      '',
      ...overHourTitles.map(title => `· ${title}`)
    ].join('\n'));
  }
  if (warnBlocks.length) hint = [baseHint, '', ...warnBlocks].join('\n\n');
  return {
    allOk: true,
    hint,
    hasOverHour: overHourTitles.length > 0,
    hasUnderHour: underHourTitles.length > 0
  };
}

function submitSelectedMajorOfferingTaskArrangements(selectedIds = null) {
  if (!ensureCourseOfferingPlan()) return;
  const ids = selectedIds ? [...selectedIds] : [...courseMajorTaskSelectedSectionIds];
  if (!ids.length) {
    alert('请先勾选需要提交的开课任务。');
    return;
  }
  const secs = ids
    .map(id => COURSE_OFFERING_PLAN_STORE.sections.find(s => s.id === id))
    .filter(s => s && s.offeringType === 'major');
  const pending = secs.filter(s => s.teachingConfirmStatus !== 'confirmed');
  if (!pending.length) {
    alert('所选开课任务均已提交。');
    return;
  }
  const { allOk, hint, hasOverHour, hasUnderHour } = buildMajorOfferingTaskSubmitConfirm(pending);
  // const validation = validateMajorOfferingTaskArrangementsSubmit(pending);
  // if (!validation.ok) {
  //   alert(validation.message);
  //   return;
  // } // 原 alert 阻断，改二次弹窗内警示且禁用确认
  openDeleteConfirm({
    title: '确认生效',
    message: `确定对选中的 <strong>${pending.length}</strong> 条开课任务安排执行生效吗？`,
    hint,
    hintWarn: !allOk || !!hasOverHour || !!hasUnderHour,
    confirmLabel: '生效',
    confirmDisabled: !allOk,
    onConfirm: allOk
      ? () => {
          pending.forEach(sec => {
            markMajorOfferingTaskArrangementSubmitted(sec);
          });
          courseMajorTaskSelectedSectionIds.clear();
          finalizeOfferingGroupingAfterTaskSubmit(pending);
          renderCourseMajorOfferingTaskPage();
          renderCourseMajorOfferingTaskStyle2Page();
          renderCourseMajorOfferingRosterPage();
          updateMajorOfferingTaskSelection();
          updateMajorOfferingTaskStyle2Selection();
          const openCount = pending.filter(isMajorOfferingOpenEnrollment).length;
          const rosterNote = openCount === pending.length
            ? '选修课程默认名单由选课应用生成，仍可前往「开课名单」维护。'
            : openCount
              ? `其中 ${openCount} 门选修课程默认名单由选课应用生成；全部课程均可前往「开课名单」维护。`
              : '请前往「开课名单」为各小组维护学生名单。';
          // alert(... '开放选课...将由选课应用生成' ...); // 原选修不可维护口径，改仍可在开课名单维护
          // alert(`已提交 ${pending.length} 条任务安排。请前往「专业开课学生名单管理」为各小组维护学生名单。`); // 原未区分开放选课
          alert(`已提交 ${pending.length} 条任务安排。${rosterNote}`);
        }
      : null
  });
}

