function defaultCourseMajorOfferingRosterCompare(a, b) {
  return (a.sec?.code || '').localeCompare(b.sec?.code || '')
    || (a.rowKey || '').localeCompare(b.rowKey || '');
  // || (a.group?.name || '').localeCompare(b.group?.name || '') // 原按小组排序，改按开课任务
}

