function getMajorOfferingRosterStudentCount(sec) {
  if (!sec?.id) return 0;
  return (getMajorOfferingStudentRoster(sec.id) || []).length;
}

/** 已分配人数 / 名单人数（人数列）；另带课程名额上限供超限状态判断 */
function getMajorOfferingRosterAssignCounts(sec) {
  if (!sec?.id) return { assigned: 0, total: 0, capacity: 0 };
  const roster = getMajorOfferingStudentRoster(sec.id) || [];
  const total = roster.length;
  const assigned = roster.filter(stu => getStudentGroupNames(stu).length > 0).length;
  const capacity = Math.max(0, Number(getSectionCapacityLimit(sec)) || 0);
  return { assigned, total, capacity };
}

/** missing=未分配 / warn=部分完成或超出名额上限 / ok=名单已全部分配且未超限 */
function getMajorOfferingRosterAssignStatusKey(sec) {
  const { assigned, total, capacity } = getMajorOfferingRosterAssignCounts(sec);
  if (total <= 0 || assigned <= 0) return 'missing';
  if (capacity > 0 && assigned > capacity) return 'warn';
  if (assigned >= total) return 'ok';
  return 'warn';
}

function getMajorOfferingRosterAssignStatusSortValue(sec) {
  const key = getMajorOfferingRosterAssignStatusKey(sec);
  if (key === 'ok') return 2;
  if (key === 'warn') return 1;
  return 0;
}

function formatMajorOfferingRosterAssignStatusMeta(statusKey, sec) {
  if (statusKey === 'ok') {
    return { key: 'ok', symbol: '✓', title: '全部分配' };
  }
  if (statusKey === 'warn') {
    const { assigned, capacity } = getMajorOfferingRosterAssignCounts(sec);
    const over = capacity > 0 && assigned > capacity;
    return {
      key: 'warn',
      symbol: '✓',
      title: over ? `超出名额上限（已分配 ${assigned} / 上限 ${capacity}）` : '部分完成'
    };
  }
  return { key: 'missing', symbol: '!', title: '未完成' };
}

function renderMajorOfferingRosterAssignStatusCell(sec) {
  const statusMeta = formatMajorOfferingRosterAssignStatusMeta(getMajorOfferingRosterAssignStatusKey(sec), sec);
  const statusAttrs = statusMeta.key === 'ok'
    ? `class="offering-grouping-course-status is-${statusMeta.key}" title="${escapeHtml(statusMeta.title)}" aria-label="${escapeHtml(statusMeta.title)}"`
    : `class="offering-grouping-course-status is-${statusMeta.key} cell-ellipsis-tip" data-tip="${escapeHtml(statusMeta.title)}" data-tip-tone="${statusMeta.key}" aria-label="${escapeHtml(statusMeta.title)}" tabindex="0"`;
  return `<span ${statusAttrs}>${statusMeta.symbol}</span>`;
}

function formatMajorOfferingRosterAssignProgressDisplay(sec) {
  const { assigned, total } = getMajorOfferingRosterAssignCounts(sec);
  return `${assigned}/${total}`;
}

function getMajorOfferingRosterRevertableSelection() {
  if (!ensureCourseOfferingPlan() || !courseMajorRosterSelectedSectionIds.size) return [];
  return [...courseMajorRosterSelectedSectionIds]
    .map(id => COURSE_OFFERING_PLAN_STORE.sections.find(s => s.id === id))
    .filter(s => s && s.offeringType === 'major' && isMajorOfferingTaskArrangementSubmitted(s));
}

function updateMajorOfferingRosterSelection() {
  courseMajorRosterSelectedSectionIds = new Set(
    [...document.querySelectorAll('.course-major-roster-row-check:checked')].map(el => el.value)
  );
  const hasSelection = courseMajorRosterSelectedSectionIds.size > 0;
  const btnRosterRevert = document.getElementById('btn-major-roster-revert');
  if (btnRosterRevert) {
    btnRosterRevert.disabled = !getMajorOfferingRosterRevertableSelection().length;
  }
  const checkAll = document.getElementById('course-major-roster-check-all');
  const selectable = document.querySelectorAll('.course-major-roster-row-check');
  if (checkAll && selectable.length) {
    const checkedOnPage = [...selectable].filter(el => el.checked).length;
    checkAll.checked = checkedOnPage === selectable.length;
    checkAll.indeterminate = checkedOnPage > 0 && checkedOnPage < selectable.length;
  } else if (checkAll) {
    checkAll.checked = false;
    checkAll.indeterminate = false;
  }
}

function toggleMajorOfferingRosterCheckAll(checked) {
  document.querySelectorAll('.course-major-roster-row-check').forEach(el => { el.checked = checked; });
  updateMajorOfferingRosterSelection();
}

