function openOfferingGroupingModal(sectionId, options = {}) {
  // 切换课程时丢弃未保存的安排草稿，避免带到另一门课看起来像「多出一条」
  if (offeringGroupingSectionId !== sectionId) {
    offeringGroupStatusAssignDraft = null;
    offeringGroupStatusTeacherPickerForDraft = false;
  }
  offeringGroupingSectionId = sectionId;
  const activePageId = document.querySelector('.page.active')?.id?.replace(/^page-/, '') || '';
  offeringGroupingReturnPage = options.returnPage
    || (activePageId && activePageId !== 'offering-grouping' ? activePageId : 'course-major-offering-task-style2');
  // 样式1入口已隐藏，返回统一落到「开课安排」
  if (offeringGroupingReturnPage === 'course-major-offering-task') {
    offeringGroupingReturnPage = 'course-major-offering-task-style2';
  }
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === sectionId);
  if (sec) ensureSectionOfferingFields(sec);
  const requestedTab = options.tab || 'group-status';
  const studentRosterMode = isOfferingGroupingStudentRosterMode(sec);
  const studentViewOnlyContext = isOfferingGroupingManifestViewContext();
  // const studentViewOnlyContext = isOfferingGroupingManifestViewContext() || isOfferingGroupingGeRosterViewContext(); // 原 GE 名单只读，改名单管理可编辑
  if (studentRosterMode && (!options.tab || options.tab === 'teacher' || options.tab === 'group-status')) {
    offeringGroupingActiveTab = 'student';
  } else if (requestedTab === 'student' && !studentRosterMode && !studentViewOnlyContext) {
    offeringGroupingActiveTab = 'group-status';
  // } else if (requestedTab === 'student' && !studentRosterMode) { // 原会将 manifest/ge 名单查看强制切回教师 Tab
  } else {
    offeringGroupingActiveTab = normalizeOfferingGroupingTab(requestedTab);
  }
  // if (requestedTab === 'student' && offeringGroupingReturnPage !== 'course-major-offering-roster') {
  //   offeringGroupingActiveTab = 'teacher';
  // } else {
  //   offeringGroupingActiveTab = normalizeOfferingGroupingTab(requestedTab);
  // } // 原仅名单管理入口可进学生 Tab，改任务安排已提交后从「分组」亦维护名单
  // offeringGroupingActiveTab = options.tab || 'teacher'; // 原不区分入口，分组页也展示学生名单 Tab
  offeringGroupingSelectedGroupId = options.groupId || null;
  offeringGroupingStudentSelected.clear();
  if (sec?.groups?.length && !offeringGroupingSelectedGroupId && !studentRosterMode) {
    offeringGroupingSelectedGroupId = sec.groups[0].id;
  }
  // offeringGroupingActiveTab = 'teacher'; // 原固定教师 Tab
  // offeringGroupingSelectedGroupId = null; // 原固定清空
  // const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === sectionId); // 原在 Tab 判定之后加载
  offeringGroupingReadOnly = isMajorOfferingSectionStructureLocked(sec);
  offeringGroupingLastSavedAt = null;
  offeringGroupingAutosaveStampReady = false;
  if (!options.keepSidebarView) {
    // 外部入口默认 Course；显式 sidebarView / 全局表跳转可指定
    offeringGroupingSidebarView = normalizeOfferingGroupingSidebarView(options.sidebarView);
  }
  if (sec) {
    // syncSectionGroupsFromProgrammeBatches(sec); // 原进入分组页自动按批次建组，改由任务安排环节手动/自动分组
    // if (shouldSeedDemoOfferingGroupAssignments(sec) && !(sec.groupAssignments?.length)) {
    //   seedDemoOfferingGroupAssignments(sec);
    // } // 原进入分组页对已提交空安排自动灌演示教师；改仅显式 demo 种子注入
    // 清掉历史会话里已自动灌入的演示教师（本页加载只跑一次，之后用户自选保留）
    stripAutoSeededAssignTeachersFromPlanStores();
    getMajorOfferingStudentRoster(sectionId);
  }
  updateOfferingGroupingPageTitle(sec);
  syncOfferingGroupingBreadcrumb();
  syncOfferingGroupingHeaderActions();
  goPage('offering-grouping');
  renderOfferingGroupingPanel();
  offeringGroupingAutosaveStampReady = true;
  syncOfferingGroupingLastSavedHint();
  refreshOfferingGroupingLeaveSnapshot();
  // renderOfferingGroupingPanel(); goPage('offering-grouping'); // 原先渲染后跳转，渲染异常时点击无反应
  // openModal('modal-offering-grouping'); // 原全屏弹窗，改独立页 page-offering-grouping
}

/** 任务安排「安排教师」：优先新窗口打开分组工作台；弹窗被拦截时回退为当前页跳转 */
function openOfferingGroupingInNewWindow(sectionId, options = {}) {
  const id = String(sectionId || '');
  if (!id) return false;
  const tab = normalizeOfferingGroupingTab(options.tab || 'group-status');
  const returnPage = options.returnPage
    || document.querySelector('.page.active')?.id?.replace(/^page-/, '')
    || 'course-major-offering-task-style2';
  const resolvedReturnPage = returnPage === 'course-major-offering-task'
    ? 'course-major-offering-task-style2'
    : returnPage;
  try {
    const snapshot = JSON.stringify({
      sectionId: id,
      tab,
      returnPage: resolvedReturnPage,
      groupId: options.groupId || null,
      activeTerm: COURSE_OFFERING_PLAN_STORE?.termCode || '',
      planByTerm: cloneJson(COURSE_OFFERING_PLAN_BY_TERM),
      rosterStore: cloneJson(majorOfferingStudentRosterStore)
    });
    sessionStorage.setItem(`${OFFERING_GROUPING_POPUP_STORAGE_KEY}:${id}`, snapshot);
    sessionStorage.setItem(OFFERING_GROUPING_POPUP_STORAGE_KEY, snapshot);
  } catch (err) {
    console.warn('openOfferingGroupingInNewWindow: failed to snapshot plan store', err);
  }
  const hash = new URLSearchParams({
    ogPopup: '1',
    sectionId: id,
    tab,
    returnPage: resolvedReturnPage
  }).toString();
  const url = `${location.pathname}${location.search}#${hash}`;
  // 先开空白窗再跳转，避免个别环境把同 URL 导航到当前页；原列表页始终不动
  let win = null;
  try {
    win = window.open('about:blank', `pyfa-og-${id}`);
  } catch (_) {
    win = null;
  }
  if (!win || win === window) {
    // Cursor Simple Browser / 内嵌预览等常拦截 window.open：回退同页进入分组工作台
    openOfferingGroupingModal(id, { ...options, tab, returnPage: resolvedReturnPage });
    return false;
  }
  try {
    win.location.href = url;
    win.focus();
  } catch (err) {
    console.warn('openOfferingGroupingInNewWindow: failed to navigate popup', err);
    try { win.close(); } catch (_) { /* ignore */ }
    openOfferingGroupingModal(id, { ...options, tab, returnPage: resolvedReturnPage });
    return false;
  }
  return true;
}

function parseOfferingGroupingPopupHash() {
  const raw = String(location.hash || '').replace(/^#/, '');
  if (!raw) return null;
  const params = new URLSearchParams(raw);
  if (params.get('ogPopup') !== '1') return null;
  const sectionId = params.get('sectionId') || '';
  if (!sectionId) return null;
  return {
    sectionId,
    tab: params.get('tab') || 'group-status',
    returnPage: params.get('returnPage') || 'course-major-offering-task-style2'
  };
}

function applyOfferingGroupingPopupStoreSnapshot(payload) {
  if (!payload?.planByTerm || typeof payload.planByTerm !== 'object') return false;
  COURSE_OFFERING_PLAN_BY_TERM = payload.planByTerm;
  const term = payload.activeTerm || Object.keys(COURSE_OFFERING_PLAN_BY_TERM)[0] || '';
  if (term) syncCourseOfferingPlanStoreFromTerm(term);
  if (payload.rosterStore) applyMajorOfferingStudentRosterStoreSnapshot(payload.rosterStore, { replace: true });
  return !!COURSE_OFFERING_PLAN_STORE?.sections?.some(s => s.id === payload.sectionId);
}

function refreshMajorOfferingTaskPagesAfterPopupSync() {
  const taskActive = document.getElementById('page-course-major-offering-task')?.classList.contains('active');
  const style2Active = document.getElementById('page-course-major-offering-task-style2')?.classList.contains('active');
  const rosterActive = document.getElementById('page-course-major-offering-roster')?.classList.contains('active');
  if (taskActive) renderCourseMajorOfferingTaskPage();
  if (style2Active) renderCourseMajorOfferingTaskStyle2Page();
  if (rosterActive) renderCourseMajorOfferingRosterPage();
}

function syncOfferingGroupingPopupBackToOpener({ includeRoster = true } = {}) {
  if (!offeringGroupingOpenedAsPopup) return false;
  const payload = {
    type: OFFERING_GROUPING_POPUP_MESSAGE,
    activeTerm: COURSE_OFFERING_PLAN_STORE?.termCode || '',
    planByTerm: cloneJson(COURSE_OFFERING_PLAN_BY_TERM),
    sectionId: offeringGroupingSectionId
  };
  if (includeRoster) {
    payload.rosterStore = cloneJson(majorOfferingStudentRosterStore);
    persistMajorOfferingStudentRosterStore();
  }
  try {
    if (window.opener && !window.opener.closed) {
      window.opener.postMessage(payload, location.origin);
      return true;
    }
  } catch (err) {
    console.warn('syncOfferingGroupingPopupBackToOpener failed', err);
  }
  return false;
}

function tryBootstrapOfferingGroupingPopup() {
  const fromHash = parseOfferingGroupingPopupHash();
  if (!fromHash?.sectionId) return false;
  // 只在新窗口上下文启动，避免原标签页因 hash 被误切换
  const isPopupCtx = Boolean(window.opener && !window.opener.closed)
    || String(window.name || '').startsWith('pyfa-og-');
  if (!isPopupCtx) {
    try { history.replaceState(null, '', `${location.pathname}${location.search}`); } catch (_) { /* ignore */ }
    return false;
  }
  const sectionId = fromHash.sectionId;
  let payload = null;
  try {
    const scoped = sessionStorage.getItem(`${OFFERING_GROUPING_POPUP_STORAGE_KEY}:${sectionId}`);
    const raw = scoped || sessionStorage.getItem(OFFERING_GROUPING_POPUP_STORAGE_KEY);
    if (raw) payload = JSON.parse(raw);
  } catch (_) { /* ignore */ }
  const tab = payload?.tab || fromHash.tab || 'group-status';
  const returnPage = payload?.returnPage || fromHash.returnPage || 'course-major-offering-task-style2';
  const groupId = payload?.groupId || null;
  if (payload?.sectionId === sectionId) applyOfferingGroupingPopupStoreSnapshot({ ...payload, sectionId });
  else ensureCourseOfferingPlan();
  const sec = COURSE_OFFERING_PLAN_STORE?.sections?.find(s => s.id === sectionId);
  if (!sec) {
    alert(`未找到开课任务 ${sectionId}，无法在新窗口打开安排教师。`);
    return false;
  }
  offeringGroupingOpenedAsPopup = true;
  document.querySelector('.app')?.classList.remove('portal-mode');
  setActiveModule('course');
  openOfferingGroupingModal(sectionId, { returnPage, tab, groupId });
  try { history.replaceState(null, '', `${location.pathname}${location.search}`); } catch (_) { /* ignore */ }
  return true;
}

window.addEventListener('message', (event) => {
  if (event.origin !== location.origin) return;
  const data = event.data;
  if (!data || data.type !== OFFERING_GROUPING_POPUP_MESSAGE) return;
  if (!data.planByTerm || typeof data.planByTerm !== 'object') return;
  COURSE_OFFERING_PLAN_BY_TERM = data.planByTerm;
  if (data.activeTerm) syncCourseOfferingPlanStoreFromTerm(data.activeTerm);
  if (data.rosterStore) {
    applyMajorOfferingStudentRosterStoreSnapshot(data.rosterStore, { replace: true });
    persistMajorOfferingStudentRosterStore();
  }
  refreshMajorOfferingTaskPagesAfterPopupSync();
});

function buildOfferingGroupingLeaveSnapshot(sectionId) {
  const sec = COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === sectionId);
  if (!sec) return null;
  const roster = getMajorOfferingStudentRoster(sectionId) || [];
  return cloneJson({
    roster: roster.map(stu => ({
      id: stu.id,
      studentNo: stu.studentNo,
      groupNames: [...(stu.groupNames || [])],
      source: stu.source || ''
    })),
    groups: (sec.groups || []).map(g => ({
      id: g.id,
      name: g.name,
      remark: g.remark || '',
      capacityLimit: g.capacityLimit,
      batchLabel: g.batchLabel || ''
    })),
    groupAssignments: (sec.groupAssignments || []).map(a => ({
      id: a.id,
      deliveryScope: a.deliveryScope,
      groupId: a.groupId,
      groupIds: [...(a.groupIds || [])],
      hourType: a.hourType,
      weekRange: a.weekRange,
      weeklyHours: a.weeklyHours,
      hours: a.hours,
      staffId: a.staffId,
      teacher: a.teacher
    }))
  });
}

function refreshOfferingGroupingLeaveSnapshot() {
  if (!offeringGroupingSectionId) {
    offeringGroupingLeaveSnapshot = null;
    return;
  }
  offeringGroupingLeaveSnapshot = buildOfferingGroupingLeaveSnapshot(offeringGroupingSectionId);
}

function isOfferingGroupingPageDirty() {
  if (!offeringGroupingSectionId || !offeringGroupingLeaveSnapshot) return false;
  const current = buildOfferingGroupingLeaveSnapshot(offeringGroupingSectionId);
  return JSON.stringify(current) !== JSON.stringify(offeringGroupingLeaveSnapshot);
}

function shouldConfirmOfferingGroupingLeave() {
  // 分组/教师安排已自动保存，返回不再二次确认；名单模式仍有未保存修改时才确认。
  return isOfferingGroupingStudentRosterMode() && isOfferingGroupingPageDirty();
  // return true; // 原普通返回统一二次确认
}

function performCloseOfferingGroupingPage(options = {}) {
  let target = offeringGroupingReturnPage || 'course-major-offering-task-style2';
  // 样式1入口已隐藏，返回统一落到侧栏「开课安排」
  if (target === 'course-major-offering-task') target = 'course-major-offering-task-style2';
  offeringGroupingLeaveSnapshot = null;
  if (offeringGroupingOpenedAsPopup) {
    syncOfferingGroupingPopupBackToOpener({
      includeRoster: options.syncRoster !== false
    });
    try {
      if (offeringGroupingSectionId) {
        sessionStorage.removeItem(`${OFFERING_GROUPING_POPUP_STORAGE_KEY}:${offeringGroupingSectionId}`);
      }
      sessionStorage.removeItem(OFFERING_GROUPING_POPUP_STORAGE_KEY);
    } catch (_) { /* ignore */ }
    offeringGroupingOpenedAsPopup = false;
    offeringGroupingSectionId = null;
    window.close();
    // 若浏览器不允许脚本关窗，回落到原返回页
    if (!window.closed) goPage(target);
    return;
  }
  if (options.syncRoster !== false) persistMajorOfferingStudentRosterStore();
  goPage(target);
  if (target === 'course-major-offering-task') renderCourseMajorOfferingTaskPage();
  else if (target === 'course-major-offering-task-style2') renderCourseMajorOfferingTaskStyle2Page();
  else if (target === 'course-offering-ge' || target === 'course-ge-offering-task') renderGeOfferingPlanPage();
  // else if (target === 'course-ge-offering-task') renderCourseGeOfferingTaskPage(); // 已并入合页
  else if (target === 'course-ge-offering-roster') renderCourseGeOfferingRosterPage();
  else if (target === 'course-major-offering-roster') renderCourseMajorOfferingRosterPage();
  else if (target === 'course-special-offering-task') renderCourseSpecialOfferingTaskPage();
  else if (target === 'course-special-offering-roster') renderCourseSpecialOfferingRosterPage();
  else if (target === 'course-offering-major') renderCourseOfferingMajorPage();
  else if (target === 'course-offering-other') renderOtherOfferingPlanPage();
  else if (target === 'course-offering-manifest') renderCourseOfferingManifestPage();
  else if (target === 'course-offering-teacher-replace') renderOfferingTeacherReplacePage();
}

function closeOfferingGroupingPage(options = {}) {
  const force = options === true || options?.force;
  if (!force && shouldConfirmOfferingGroupingLeave()) {
    openDeleteConfirm({
      title: '返回确认',
      message: '当前学生名单有未保存修改，直接返回不会保存，确认返回吗？',
      hint: '如需保留名单修改，请先点击「保存名单」。',
      confirmLabel: '不保存并返回',
      confirmDanger: true,
      onConfirm: () => performCloseOfferingGroupingPage({ syncRoster: false })
    });
    return;
  }
  // if (!force && shouldConfirmOfferingGroupingLeave()) { ... 分组已自动保存仍二次确认 ... } // 原统一确认，改直接返回
  performCloseOfferingGroupingPage();
}

/** 该课程班/小组在指定学时类型上是否已有带教师的安排 */
function canonicalizeGroupAssignHourTypeKey(sec, hourType) {
  if (!hourType) return '';
  if (hourType === GROUP_ASSIGN_MERGED_HOUR_TYPE) return hourType;
  if (isGroupAssignPartialMergedHourType(hourType)) {
    const sources = getSectionGroupAssignPartialMergeSourcesForHourType(sec, hourType);
    if (sources.length) return buildGroupAssignPartialMergeHourType(sources);
  }
  return hourType;
}

function groupAssignRowMatchesHourType(sec, row, hourType) {
  if (!row?.hourType || !hourType) return false;
  if (row.hourType === hourType) return true;
  return canonicalizeGroupAssignHourTypeKey(sec, row.hourType)
    === canonicalizeGroupAssignHourTypeKey(sec, hourType);
}

function groupHasHourTypeAssignment(sec, groupId, hourType) {
  return (sec?.groupAssignments || []).some(row => {
    if (!isGroupAssignRowActive(sec, row)) return false;
    if (!groupAssignRowMatchesHourType(sec, row, hourType)) return false;
    if (!getGroupAssignTeachers(row).length) return false;
    if (groupId === '__course__') return true;
    return groupAssignRowMatchesGroup(row, groupId);
  });
}

/** 列出仍缺教师的 课程班/小组 × 学时类型（用于 Course List 提示） */
function listOfferingGroupingMissingTeacherGaps(sec) {
  if (!sec) return [{ groupLabel: '课程', hourType: '', label: '课程数据缺失' }];
  sanitizeSectionGroupAssignments(sec);
  const groups = sec.groups || [];
  const gaps = [];
  const pushGap = (groupLabel, hourType = '') => {
    const label = hourType ? `${groupLabel} · ${hourType}` : groupLabel;
    if (gaps.some(g => g.label === label)) return;
    gaps.push({ groupLabel, hourType, label });
  };

  if (areSectionHourTypesAllZero(sec)) {
    if (!groups.length) {
      if (!hasAnyGroupAssignTeacher(sec)) pushGap(sec.name || '课程班');
      return gaps;
    }
    groups.forEach(g => {
      const hasTeacher = (sec.groupAssignments || []).some(row =>
        isGroupAssignRowActive(sec, row)
        && groupAssignRowMatchesGroup(row, g.id)
        && getGroupAssignTeachers(row).length > 0
      );
      if (!hasTeacher) pushGap(formatMajorOfferingGroupName(sec.name, g.name));
    });
    return gaps;
  }

  const hourTypes = getSectionGroupAssignRequiredModeHourTypes(sec);
  if (!hourTypes.length) {
    if (!hasAnyGroupAssignTeacher(sec)) pushGap(sec.name || '课程班');
    return gaps;
  }

  const targets = groups.length
    ? groups.map(g => ({ id: g.id, label: formatMajorOfferingGroupName(sec.name, g.name) }))
    : [{ id: '__course__', label: sec.name || '课程班' }];

  targets.forEach(target => {
    hourTypes.forEach(hourType => {
      if (groupHasHourTypeAssignment(sec, target.id, hourType)) return;
      const typeLabel = getGroupAssignHourTypeDisplayLabel(sec, hourType) || hourType;
      pushGap(target.label, typeLabel);
    });
  });
  return gaps;
}

/** 任一课程班/小组缺少授课教师（含仅有安排行但未指定教师） */
function offeringGroupingSectionHasMissingTeacher(sec) {
  return listOfferingGroupingMissingTeacherGaps(sec).length > 0;
}

/** 有教师或已填课时，但尚未分配课程班/小组（可暂存，不可生效） */
function offeringGroupingSectionHasUnsetGroupAssignWithLoad(sec) {
  return (sec?.groupAssignments || []).some(row => {
    if (!isGroupAssignRowActive(sec, row)) return false;
    if (!isGroupAssignRowScopeUnset(row)) return false;
    if (getGroupAssignTeachers(row).length > 0) return true;
    const weekly = Number(row.weeklyHours);
    if (Number.isFinite(weekly) && weekly > 0) return true;
    return (typeof getGroupAssignRowRecordedHours === 'function'
      ? getGroupAssignRowRecordedHours(row, sec)
      : 0) > 0;
  });
}

/** 与分组状态表一致：任一课程班/小组在任一学时类型上已录 ≠ 计划 */
function offeringGroupingSectionHasRecordedHourMismatch(sec) {
  if (!sec) return false;
  const targets = (sec.groups || []).length
    ? sec.groups.map(g => g.id)
    : ['__course__'];
  const hourTypes = getSectionGroupAssignModeHourTypes(sec);
  return targets.some(groupId => hourTypes.some(hourType => {
    const planned = getGroupAssignHourTypeTotal(sec, hourType);
    const recorded = groupId === '__course__'
      ? sumGroupAssignRecordedHoursByType(sec, hourType, '')
      : sumGroupAssignRecordedHoursForGroupByType(sec, groupId, hourType, '');
    if (planned <= 0) return recorded > planned;
    return recorded !== planned;
  }));
}

function appendOfferingGroupingSaveGroupWarning(bucket, label, line) {
  if (!bucket.byGroup.has(label)) bucket.byGroup.set(label, []);
  const lines = bucket.byGroup.get(label);
  if (!lines.includes(line)) lines.push(line);
}

function appendGroupAssignRowCompletenessWarnings(bucket, label, row, sec) {
  if (isGroupAssignRowScopeUnset(row)) {
    appendOfferingGroupingSaveGroupWarning(bucket, label, `${row.hourType}：未选择课程班/小组。`);
  }
  if (!getGroupAssignTeachers(row).length) {
    appendOfferingGroupingSaveGroupWarning(bucket, label, `${row.hourType}：未指定授课教师。`);
  }
  if (!(row.weekRange || '').trim()) {
    appendOfferingGroupingSaveGroupWarning(bucket, label, `${row.hourType}：起止周不完整。`);
  }
  const wh = Number(row.weeklyHours);
  if (row.weeklyHours === '' || row.weeklyHours == null || !Number.isFinite(wh) || wh < 0) {
    appendOfferingGroupingSaveGroupWarning(bucket, label, `${row.hourType}：周学时不完整。`);
  }
}

function hasAnyGroupAssignTeacher(sec) {
  return (sec?.groupAssignments || []).some(row =>
    isGroupAssignRowActive(sec, row) && getGroupAssignTeachers(row).length > 0
  );
}

/** Course List 状态：ok 绿勾 / warn 橘勾 / missing 感叹号 */
function getOfferingGroupingCourseArrangeStatusKey(sec) {
  if (!sec) return 'missing';
  if (sec.offeringType === 'ge') ensureGeOfferingSectionFields(sec);
  else if (sec.offeringType === 'other') ensureOtherOfferingSectionFields(sec);
  else ensureSectionOfferingFields(sec);
  sanitizeSectionGroupAssignments(sec);
  // 任一课程班/小组未安排教师 → 感叹号（不可提交）
  if (offeringGroupingSectionHasMissingTeacher(sec)) return 'missing';
  // 有教师/课时但未分配课程班/小组 → 感叹号（可暂存，不可生效）
  if (offeringGroupingSectionHasUnsetGroupAssignWithLoad(sec)) return 'missing';
  const underBucket = collectOfferingGroupingSaveWarnings(sec);
  const overBucket = collectOfferingGroupingOverHourWarnings(sec);
  let hasHourIssue = countOfferingGroupingSaveWarnings(overBucket) > 0;
  underBucket.byGroup.forEach(lines => {
    (lines || []).forEach(line => {
      const text = String(line || '');
      if (/尚未安排教师|未指定授课教师|未选择课程班\/小组/.test(text)) return;
      hasHourIssue = true;
    });
  });
  // 老师已齐但学时少/超：橘勾（与右侧分组状态表 recorded≠planned 对齐）
  if (hasHourIssue || offeringGroupingSectionHasRecordedHourMismatch(sec)) return 'warn';
  return 'ok';
}

function formatOfferingGroupingCourseStatusMeta(statusKey) {
  if (statusKey === 'ok') {
    return {
      key: 'ok',
      symbol: '✓',
      title: '课程班/小组安排了老师，学时刚好'
    };
  }
  if (statusKey === 'warn') {
    return {
      key: 'warn',
      symbol: '✓',
      title: '存在课程班/小组学时不足/超出的情况'
    };
  }
  return {
    key: 'missing',
    symbol: '!',
    title: '存在课程班/小组未安排教师，或学时安排未分配课程班/小组'
  };
}

function getOfferingGroupingCourseListSections() {
  ensureCourseOfferingPlan();
  const page = offeringGroupingReturnPage || '';
  const excludeDemo = sec => !isTeacherTeachingLoadDemoSection(sec);
  if (page === 'course-major-offering-roster') {
    return getMajorOfferingSections().filter(sec =>
      excludeDemo(sec)
      && sec.submitStatus === 'submitted'
      && isMajorOfferingTaskArrangementSubmitted(sec)
    );
  }
  if (page === 'course-offering-ge' || page === 'course-ge-offering-task') {
    // course-ge-offering-task：旧入口兼容，已并入通识选修开课
    return getGeOfferingSections().filter(excludeDemo);
    // return getGeOfferingSections().filter(sec => sec.submitStatus === 'submitted'); // 原须先计划提交
  }
  if (page === 'course-ge-offering-roster') {
    return getGeOfferingSections().filter(sec =>
      excludeDemo(sec)
      && sec.submitStatus === 'submitted'
      && isMajorOfferingTaskArrangementSubmitted(sec)
    );
  }
  if (page === 'course-special-offering-task') {
    return getOtherOfferingSections().filter(sec =>
      excludeDemo(sec) && sec.submitStatus === 'submitted'
    );
  }
  if (page === 'course-special-offering-roster') {
    return getOtherOfferingSections().filter(sec =>
      excludeDemo(sec)
      && sec.submitStatus === 'submitted'
      && isMajorOfferingTaskArrangementSubmitted(sec)
    );
  }
  // 默认：专业开课任务安排可管理课程
  return getMajorOfferingSections().filter(sec =>
    excludeDemo(sec) && sec.submitStatus === 'submitted'
  );
}

function normalizeOfferingGroupingSidebarView(view) {
  if (view === 'course-list') return 'course-list';
  if (view === 'teacher-load') return 'teacher-load';
  if (view === 'teacher-confirmation') return 'teacher-confirmation';
  return 'course';
}

function syncOfferingGroupingSidebarViewChrome() {
  const row = document.getElementById('offering-grouping-page-row');
  const aside = document.getElementById('offering-grouping-course-list');
  const teacherLoad = document.getElementById('offering-grouping-teacher-load');
  const isGlobal = offeringGroupingSidebarView === 'course-list';
  const isTeacherLoad = offeringGroupingSidebarView === 'teacher-load';
  const isTeacherConfirmation = offeringGroupingSidebarView === 'teacher-confirmation';
  row?.classList.toggle('is-course-list-view', isGlobal);
  row?.classList.toggle('is-teacher-load-view', isTeacherLoad);
  row?.classList.toggle('is-teacher-confirmation-view', isTeacherConfirmation);
  if (teacherLoad) teacherLoad.hidden = !isTeacherLoad;
  const teacherConfirmation = document.getElementById('offering-grouping-teacher-confirmation');
  if (teacherConfirmation) teacherConfirmation.hidden = !isTeacherConfirmation;
  const courseListToolbar = document.getElementById('offering-grouping-course-list-toolbar');
  if (courseListToolbar) courseListToolbar.hidden = !isGlobal;
  aside?.setAttribute('aria-label', isGlobal ? 'Course List' : 'Course');
  document.querySelectorAll('.offering-grouping-view-tab').forEach(btn => {
    const active = btn.dataset.view === offeringGroupingSidebarView;
    btn.classList.toggle('is-active', active);
    btn.setAttribute('aria-selected', active ? 'true' : 'false');
  });
  syncOfferingGroupingHeaderActions();
}

function switchOfferingGroupingSidebarView(view) {
  const next = normalizeOfferingGroupingSidebarView(view);
  if (offeringGroupingSidebarView === next) {
    if (next === 'teacher-load') renderCourseTeacherTeachingLoadPage();
    else if (next === 'teacher-confirmation') renderOfferingGroupingTeacherConfirmationPage();
    else renderOfferingGroupingCourseList();
    return;
  }
  offeringGroupingSidebarView = next;
  syncOfferingGroupingSidebarViewChrome();
  if (next === 'teacher-load') {
    renderCourseTeacherTeachingLoadPage();
    return;
  }
  if (next === 'teacher-confirmation') {
    renderOfferingGroupingTeacherConfirmationPage();
    return;
  }
  renderOfferingGroupingCourseList();
}

/** 本课实时周学时（已安排优先；无安排则回落计划周学时） */
function getSectionRealtimeWeeklyWorkingHours(sec) {
  if (!sec) return 0;
  sanitizeSectionGroupAssignments(sec);
  const rows = (sec.groupAssignments || []).filter(row => isGroupAssignRowActive(sec, row));
  if (!rows.length) {
    const plan = Number(getSectionPlanWeeklyHours(sec));
    return Number.isFinite(plan) ? plan : 0;
  }
  let sum = 0;
  rows.forEach(row => {
    const weekly = Number(row.weeklyHours) || 0;
    if (weekly <= 0) return;
    if (row.simultaneousGroups) {
      sum += weekly;
      return;
    }
    const groupCount = Math.max(1, getGroupAssignRowGroupIds(row).length);
    sum += weekly * groupCount;
  });
  return sum;
}

function formatOfferingGroupingGlobalLecturersCell(sec) {
  const teachers = collectSectionAssignTeachers(sec);
  if (!teachers.length) return '<span class="text-muted">—</span>';
  const maxShow = 5;
  const shown = teachers.slice(0, maxShow);
  const extra = teachers.length - shown.length;
  const lines = shown.map(t => {
    const name = t.name || t.staffId || '—';
    const staffId = t.staffId || '';
    const link = !staffId
      ? escapeHtml(name)
      : `<button type="button" class="offering-group-status-teacher-link" title="查看该教师已分配课程与课时" onclick="openOfferingTeacherTermAssignModal('${escapeHtml(staffId)}')">${escapeHtml(name)}</button>`;
    return `<span class="offering-grouping-global-lecturer-line">${link}</span>`;
  });
  if (extra > 0) {
    lines.push(`<span class="offering-grouping-global-lecturer-more text-muted">+${extra}</span>`);
  }
  return `<div class="offering-grouping-global-lecturers">${lines.join('')}</div>`;
}

/** Course List 展开行：课内各组开课任务安排（对标「课程班/小组学时详情」安排表，只读） */
function renderOfferingGroupingGlobalAssignSubtable(sec) {
  const rawRows = getOfferingGroupStatusAssignRows(sec, '__course__');
  if (!rawRows.length) {
    return `<div class="offering-grouping-global-assign-empty">
      <span class="text-muted">暂无开课任务安排</span>
      <button type="button" class="btn btn-primary btn-sm" onclick="openOfferingGroupingCourseFromGlobalList('${escapeHtml(sec.id)}')">前往新增</button>
    </div>`;
  }
  const sortCols = getOfferingGroupStatusAssignSortColumns(sec);
  const rows = sortListWithState(rawRows, 'offeringGroupingGlobalAssign', sortCols);
  const body = rows.map((row, idx) => `<tr>
    <td class="col-index col-center">${idx + 1}</td>
    <td class="col-groups">${formatGroupAssignGroupsSummaryCell(row, sec)}</td>
    <td class="col-center col-hour-type">${escapeHtml(getGroupAssignHourTypeDisplayLabel(sec, row.hourType) || '—')}</td>
    <td class="col-center col-week"><code>${escapeHtml(clampGroupAssignWeekRangeToSection(sec, row.weekRange) || row.weekRange || '—')}</code></td>
    <td class="col-center col-weekly">${escapeHtml(formatGroupAssignWeeklyHoursDisplay(row))}</td>
    <td class="col-center col-total">${escapeHtml(formatGroupAssignRowTotalHoursDisplay(row, sec))}</td>
    <td class="col-teacher">${formatGroupAssignTeachersSummaryCell(row)}</td>
    <td class="col-center col-simul">${row.simultaneousGroups ? '是' : '否'}</td>
    <td class="col-center col-classroom-attr">${escapeHtml(formatAssignClassroomAttributeDisplay(row.classroomAttribute))}</td>
    <td class="col-center col-classroom-pref">${formatAssignClassroomPreferenceCellHtml(row.classroomPreferences, row.classroomAttribute)}</td>
  </tr>`).join('');
  return `<div class="offering-grouping-global-assign-panel">
    <div class="offering-grouping-global-assign-head">
      <strong>开课任务安排</strong>
      <button type="button" class="btn btn-outline btn-sm" onclick="openOfferingGroupingCourseFromGlobalList('${escapeHtml(sec.id)}')">前往修改</button>
    </div>
    <div class="table-scroll offering-grouping-global-assign-table-wrap">
      <table class="data-table compact offering-grouping-global-assign-table">
        <thead>
          <tr>
            <th class="col-center col-index">序号</th>
            ${renderListSortTh('offeringGroupingGlobalAssign', '课程班/小组', 'groups', { extraClass: 'col-groups' })}
            ${renderListSortTh('offeringGroupingGlobalAssign', '学时类型', 'hourType', { center: true, extraClass: 'col-hour-type' })}
            ${renderListSortTh('offeringGroupingGlobalAssign', '周次', 'weekRange', { center: true, extraClass: 'col-week' })}
            ${renderListSortTh('offeringGroupingGlobalAssign', '周学时', 'weeklyHours', { center: true, extraClass: 'col-weekly' })}
            ${renderListSortTh('offeringGroupingGlobalAssign', '总学时', 'totalHours', { center: true, extraClass: 'col-total' })}
            ${renderListSortTh('offeringGroupingGlobalAssign', '教师', 'teacher', { extraClass: 'col-teacher' })}
            ${renderOfferingGroupStatusAssignSimulSortTh('offeringGroupingGlobalAssign')}
            ${renderListSortTh('offeringGroupingGlobalAssign', '场地类型', 'classroomAttribute', { center: true, extraClass: 'col-classroom-attr' })}
            ${renderOfferingGroupStatusAssignClassroomPrefSortTh('offeringGroupingGlobalAssign')}
          </tr>
        </thead>
        <tbody>${body}</tbody>
      </table>
    </div>
  </div>`;
}

function toggleOfferingGroupingGlobalCourseExpand(sectionId, event) {
  event?.stopPropagation?.();
  const id = String(sectionId || '');
  if (!id) return;
  if (offeringGroupingGlobalExpandedIds.has(id)) offeringGroupingGlobalExpandedIds.delete(id);
  else offeringGroupingGlobalExpandedIds.add(id);
  renderOfferingGroupingGlobalCourseList();
}

function buildOfferingGroupingGlobalListRows() {
  return getOfferingGroupingCourseListSections()
    .slice()
    .map(sec => {
      if (sec.offeringType === 'ge') ensureGeOfferingSectionFields(sec);
      else if (sec.offeringType === 'other') ensureOtherOfferingSectionFields(sec);
      else ensureSectionOfferingFields(sec);
      sanitizeSectionGroupAssignments(sec);
      const statusKey = getOfferingGroupingCourseArrangeStatusKey(sec);
      return {
        sec,
        statusKey,
        status: formatOfferingGroupingCourseStatusMeta(statusKey),
        planned: getSectionPlannedStudentCount(sec),
        groupCount: getMajorOfferingSectionGroupCount(sec),
        batches: formatSectionMergedBatchLabelWithPlannedCounts(sec),
        classification: getOfferingSectionCategoryDisplay(sec),
        coordinator: getSectionCoordinatorDisplayName(sec)
      };
    });
}

function getOfferingGroupingGlobalCodeFilterQuery() {
  return String(offeringGroupingGlobalCodeFilter || '').trim().toLowerCase();
}

function filterOfferingGroupingGlobalListRows(rows) {
  const q = getOfferingGroupingGlobalCodeFilterQuery();
  if (!q) return rows || [];
  return (rows || []).filter(row => String(row.sec?.code || '').toLowerCase().includes(q));
}

function queryOfferingGroupingGlobalCourseList() {
  const input = document.getElementById('offering-grouping-global-code-filter');
  offeringGroupingGlobalCodeFilter = String(input?.value || '').trim();
  resetListPage('offeringGroupingGlobalCourse');
  renderOfferingGroupingGlobalCourseList();
}

function resetOfferingGroupingGlobalCourseListFilter() {
  offeringGroupingGlobalCodeFilter = '';
  const input = document.getElementById('offering-grouping-global-code-filter');
  if (input) input.value = '';
  resetListPage('offeringGroupingGlobalCourse');
  renderOfferingGroupingGlobalCourseList();
}

function defaultOfferingGroupingGlobalCourseCompare(a, b) {
  return (a.sec?.code || '').localeCompare(b.sec?.code || '')
    || (a.sec?.id || '').localeCompare(b.sec?.id || '');
}

const OFFERING_GROUPING_GLOBAL_COURSE_SORT_COLUMNS = {
  offeringStatus: { get: row => row.statusKey || '' },
  teacherConfirm: {
    get: row => {
      const p = getSectionTeacherConfirmationProgress(row.sec);
      if (!p.total) return -1;
      if (p.complete) return 2;
      if (p.confirmed > 0) return 1;
      return 0;
    },
    type: 'number'
  },
  taskSubmitStatus: { get: row => getMajorOfferingTaskSubmitStatusKey(row.sec) },
  code: { get: row => row.sec?.code || '' },
  name: { get: row => row.sec?.name || '' },
  classification: { get: row => row.classification || '' },
  enrollmentType: { get: row => formatMergeEnrollmentTypeLabel(row.sec?.enrollmentType || 'closed') },
  credits: { get: row => row.sec?.credits, type: 'number' },
  weekRange: { get: row => row.sec?.weekRange || '' },
  programmeBatch: {
    get: row => typeof getSectionMergedBatchLabelDisplayFull === 'function'
      ? getSectionMergedBatchLabelDisplayFull(row.sec)
      : (row.batches || '')
  },
  groupCount: { get: row => row.groupCount ?? 0, type: 'number' },
  planned: { get: row => row.planned ?? 0, type: 'number' },
  lecturer: {
    get: row => collectSectionAssignTeachers(row.sec)
      .map(t => t.name || t.staffId || '')
      .filter(Boolean)
      .join(', ')
  },
  coordinator: { get: row => row.coordinator || '' }
};

function renderOfferingGroupingCourseListSidebar() {
  const mount = document.getElementById('offering-grouping-course-list-body');
  const footText = document.getElementById('offering-grouping-course-list-foot-text');
  const footPager = document.getElementById('offering-grouping-global-course-pagination');
  if (!mount) return;
  mount.classList.remove('is-global-table');
  if (footText) footText.hidden = false;
  if (footPager) {
    footPager.hidden = true;
    footPager.innerHTML = '';
  }
  const list = getOfferingGroupingCourseListSections()
    .slice()
    .sort((a, b) => (a.code || '').localeCompare(b.code || '') || (a.id || '').localeCompare(b.id || ''));
  if (footText) footText.textContent = `共 ${list.length} 条`;
  if (!list.length) {
    mount.innerHTML = '<div class="offering-grouping-course-list-empty">暂无可管理课程</div>';
    return;
  }
  mount.innerHTML = list.map(sec => {
    const statusKey = getOfferingGroupingCourseArrangeStatusKey(sec);
    const status = formatOfferingGroupingCourseStatusMeta(statusKey);
    const active = sec.id === offeringGroupingSectionId ? ' is-active' : '';
    const submitted = isMajorOfferingTaskArrangementMarkedSubmitted(sec) ? ' is-submitted' : '';
    const code = escapeHtml(sec.code || '—');
    const name = escapeHtml(sec.name || '—');
    // 绿勾无需悬停提示；橘勾/感叹号保留
    const statusAttrs = status.key === 'ok'
      ? `class="offering-grouping-course-status is-${status.key}"`
      : `class="offering-grouping-course-status is-${status.key} cell-ellipsis-tip" data-tip="${escapeHtml(status.title)}" data-tip-tone="${status.key}" aria-label="${escapeHtml(status.title)}" tabindex="0"`;
    return `<button type="button" class="offering-grouping-course-item${active}${submitted}" onclick="selectOfferingGroupingCourse('${sec.id}')"${submitted ? ' data-submitted="1"' : ''}>
      <span class="offering-grouping-course-item-main">
        <span class="offering-grouping-course-item-code cell-ellipsis-tip" data-tip="${code}" tabindex="0">${code}</span>
        <span class="offering-grouping-course-item-name cell-ellipsis-tip" data-tip="${name}" tabindex="0">${name}</span>
      </span>
      <span ${statusAttrs}>${status.symbol}</span>
    </button>`;
  }).join('');
  bindCellFloatTips(mount, '.offering-grouping-course-item-code.cell-ellipsis-tip[data-tip], .offering-grouping-course-item-name.cell-ellipsis-tip[data-tip]');
  bindCellFloatTips(mount, '.offering-grouping-course-status.cell-ellipsis-tip[data-tip]', { alwaysShow: true });
}

function renderOfferingGroupingGlobalCourseList() {
  const mount = document.getElementById('offering-grouping-course-list-body');
  const footText = document.getElementById('offering-grouping-course-list-foot-text');
  const footPager = document.getElementById('offering-grouping-global-course-pagination');
  if (!mount) return;
  mount.classList.add('is-global-table');
  if (footText) footText.hidden = true;
  if (footPager) footPager.hidden = false;
  const codeInput = document.getElementById('offering-grouping-global-code-filter');
  if (codeInput && document.activeElement !== codeInput) {
    codeInput.value = offeringGroupingGlobalCodeFilter;
  }
  const rows = sortListWithState(
    filterOfferingGroupingGlobalListRows(buildOfferingGroupingGlobalListRows()),
    'offeringGroupingGlobalCourse',
    OFFERING_GROUPING_GLOBAL_COURSE_SORT_COLUMNS,
    defaultOfferingGroupingGlobalCourseCompare
  );
  const validIds = new Set(rows.map(r => r.sec?.id).filter(Boolean));
  [...offeringGroupingGlobalExpandedIds].forEach(id => {
    if (!validIds.has(id)) offeringGroupingGlobalExpandedIds.delete(id);
  });
  const paged = paginateListItems(rows, 'offeringGroupingGlobalCourse');
  const pageRows = paged.items;
  renderListPagination('offering-grouping-global-course-pagination', 'offeringGroupingGlobalCourse', paged.total);
  if (!paged.total) {
    const emptyText = getOfferingGroupingGlobalCodeFilterQuery() ? '暂无匹配课程' : '暂无可管理课程';
    mount.innerHTML = `<div class="offering-grouping-course-list-empty">${emptyText}</div>`;
    return;
  }
  const colCount = 14; // 小组数先隐藏；原 15
  const lk = 'offeringGroupingGlobalCourse';
  mount.innerHTML = `<div class="offering-grouping-global-table-wrap table-scroll">
    <table class="data-table compact offering-grouping-global-table">
      <thead>
        <tr>
          <th class="col-center col-expand"></th>
          ${renderListSortTh(lk, '状态', 'offeringStatus', { center: true })}
          ${renderListSortTh(lk, '授课确认状态', 'teacherConfirm', { center: true, extraClass: 'col-tcc-progress' })}
          ${renderListSortTh(lk, '生效状态', 'taskSubmitStatus', { center: true, extraClass: 'col-task-submit' })}
          ${renderListSortTh(lk, 'Course Code', 'code', { center: true })}
          ${renderListSortTh(lk, 'Course Name', 'name', { extraClass: 'col-name' })}
          ${renderListSortTh(lk, 'Classification', 'classification', { center: true })}
          ${renderListSortTh(lk, '选修/必修', 'enrollmentType', { center: true, extraClass: 'col-enrollment-type' })}
          ${renderListSortTh(lk, 'Credits', 'credits', { center: true })}
          ${renderListSortTh(lk, 'Teaching Week', 'weekRange', { center: true })}
          ${renderListSortTh(lk, 'Prog. Batch', 'programmeBatch', { extraClass: 'col-batch' })}
          ${'' /* renderListSortTh(lk, '小组数', 'groupCount', { center: true }) */}
          ${renderListSortTh(lk, '计划总人数', 'planned', { center: true })}
          ${renderListSortTh(lk, 'Lecturer', 'lecturer', { extraClass: 'col-lecturer' })}
          ${renderListSortTh(lk, 'Coordinator', 'coordinator', { center: true })}
        </tr>
      </thead>
      <tbody>
        ${pageRows.map((row) => {
          const sec = row.sec;
          const expanded = offeringGroupingGlobalExpandedIds.has(sec.id);
          const active = sec.id === offeringGroupingSectionId ? ' is-active-row' : '';
          const statusAttrs = row.status.key === 'ok'
            ? `class="offering-grouping-course-status is-${row.status.key}"`
            : `class="offering-grouping-course-status is-${row.status.key} cell-ellipsis-tip" data-tip="${escapeHtml(row.status.title)}" data-tip-tone="${row.status.key}" aria-label="${escapeHtml(row.status.title)}" tabindex="0"`;
          const expandBtn = `<button type="button" class="offering-grouping-global-expand-btn${expanded ? ' is-expanded' : ''}" aria-expanded="${expanded ? 'true' : 'false'}" aria-label="${expanded ? '收起安排' : '展开安排'}" title="${expanded ? '收起安排' : '展开安排'}" onclick="toggleOfferingGroupingGlobalCourseExpand('${escapeHtml(sec.id)}', event)">${expanded ? '−' : '+'}</button>`;
          const mainRow = `<tr class="offering-grouping-global-course-row${active}${expanded ? ' is-expanded' : ''}">
            <td class="col-center col-expand">${expandBtn}</td>
            <td class="col-center"><span ${statusAttrs}>${row.status.symbol}</span></td>
            <td class="col-center col-tcc-progress">${renderSectionTeacherConfirmationProgressCell(sec)}</td>
            <td class="col-center col-task-submit">${renderMajorOfferingTaskSubmitDisplay(sec)}</td>
            <td class="col-center">${escapeHtml(sec.code || '—')}</td>
            <td class="col-name">${escapeHtml(sec.name || '—')}</td>
            <td class="col-center">${escapeHtml(row.classification || '—')}</td>
            <td class="col-center col-enrollment-type">${renderMajorOfferingEnrollmentTypeDisplay(sec)}</td>
            <td class="col-center">${sec.credits ?? '—'}</td>
            <td class="col-center">${escapeHtml(sec.weekRange || '—')}</td>
            <td class="col-batch">${formatOfferingGroupingGlobalBatchCell(sec)}</td>
            ${'' /* <td class="col-center">${row.groupCount || '—'}</td> */}
            <td class="col-center">${formatNullableNumberDisplay(row.planned)}</td>
            <td class="col-lecturer">${formatOfferingGroupingGlobalLecturersCell(sec)}</td>
            <td class="col-center">${escapeHtml(row.coordinator || '—')}</td>
          </tr>`;
          if (!expanded) return mainRow;
          return `${mainRow}
          <tr class="offering-grouping-global-detail-row">
            <td colspan="${colCount}">${renderOfferingGroupingGlobalAssignSubtable(sec)}</td>
          </tr>`;
        }).join('')}
      </tbody>
    </table>
  </div>`;
  bindCellFloatTips(mount, '.offering-grouping-course-status.cell-ellipsis-tip[data-tip]', { alwaysShow: true });
  bindCellFloatTips(mount, '.offering-group-status-th-tip.cell-ellipsis-tip[data-tip]', { alwaysShow: true });
}

function renderOfferingGroupingCourseList() {
  syncOfferingGroupingSidebarViewChrome();
  if (offeringGroupingSidebarView === 'teacher-load') {
    renderCourseTeacherTeachingLoadPage();
    return;
  }
  if (offeringGroupingSidebarView === 'course-list') {
    renderOfferingGroupingGlobalCourseList();
    return;
  }
  renderOfferingGroupingCourseListSidebar();
}

function openOfferingGroupingCourseFromGlobalList(sectionId) {
  if (!sectionId) return;
  offeringGroupingSidebarView = 'course';
  syncOfferingGroupingSidebarViewChrome();
  openOfferingGroupingModal(sectionId, {
    returnPage: offeringGroupingReturnPage,
    tab: 'group-status'
  });
}

function switchOfferingGroupingCourse(sectionId) {
  if (!sectionId || sectionId === offeringGroupingSectionId) return;
  openOfferingGroupingModal(sectionId, {
    returnPage: offeringGroupingReturnPage,
    tab: offeringGroupingActiveTab || 'group-status'
  });
}

function selectOfferingGroupingCourse(sectionId) {
  // 分组/教师安排已自动保存，切换课程不再二次确认（与返回行为一致）
  switchOfferingGroupingCourse(sectionId);
}

function collectOfferingGroupingSaveWarnings(sec) {
  const bucket = { byGroup: new Map() };
  const groups = sec?.groups || [];
  sanitizeSectionGroupAssignments(sec);
  if (!groups.length) {
    const courseLabel = sec?.name || '课程班';
    if (areSectionHourTypesAllZero(sec) && !hasAnyGroupAssignTeacher(sec)) {
      appendOfferingGroupingSaveGroupWarning(bucket, courseLabel, '尚未安排教师。');
      return bucket;
    }
    if (isSectionGroupAssignHoursMerged(sec)) {
      const hourType = GROUP_ASSIGN_MERGED_HOUR_TYPE;
      const typeTotal = getOfferingSectionHoursTotalForAssign(sec);
      const rows = (sec.groupAssignments || []).filter(a => a.hourType === hourType);
      const recorded = sumGroupAssignRecordedHoursByType(sec, hourType, '');
      const hasTeacher = rows.some(row => getGroupAssignTeachers(row).length > 0);
      if (typeTotal > 0 && !hasTeacher) {
        appendOfferingGroupingSaveGroupWarning(bucket, courseLabel, `${hourType}尚未安排教师。`);
      } else if (typeTotal > 0 && recorded < typeTotal) {
        appendOfferingGroupingSaveGroupWarning(bucket, courseLabel, `${hourType}已录入学时 ${recorded}/${typeTotal}，尚未录满。`);
      }
      rows.forEach(row => appendGroupAssignRowCompletenessWarnings(bucket, courseLabel, row, sec));
      return bucket;
    }
    getSectionGroupAssignModeHourTypes(sec).forEach(hourType => {
      const typeTotal = getGroupAssignHourTypeTotal(sec, hourType);
      const rows = (sec.groupAssignments || []).filter(a => a.hourType === hourType);
      const recorded = sumGroupAssignRecordedHoursByType(sec, hourType, '');
      const hasTeacher = rows.some(row => getGroupAssignTeachers(row).length > 0);
      if (!hasTeacher) {
        if (isOfferingSectionHourTypeRequiredForSubmit(sec, hourType)) {
          appendOfferingGroupingSaveGroupWarning(bucket, courseLabel, `${hourType}尚未安排教师。`);
        }
        rows.forEach(row => appendGroupAssignRowCompletenessWarnings(bucket, courseLabel, row, sec));
        return;
      }
      if (typeTotal > 0 && recorded < typeTotal) {
        appendOfferingGroupingSaveGroupWarning(
          bucket,
          courseLabel,
          `${hourType}已录入学时 ${recorded}/${typeTotal}，尚未录满。`
        );
      }
      rows.forEach(row => appendGroupAssignRowCompletenessWarnings(bucket, courseLabel, row, sec));
    });
    return bucket;
  }
  if (areSectionHourTypesAllZero(sec)) {
    groups.forEach(g => {
      const label = formatMajorOfferingGroupName(sec.name, g.name);
      const hasTeacher = (sec.groupAssignments || []).some(row =>
        isGroupAssignRowActive(sec, row)
        && groupAssignRowMatchesGroup(row, g.id)
        && getGroupAssignTeachers(row).length > 0
      );
      if (!hasTeacher) {
        appendOfferingGroupingSaveGroupWarning(bucket, label, '尚未安排教师。');
      }
    });
    (sec.groupAssignments || []).forEach(row => {
      if (!isGroupAssignRowActive(sec, row)) return;
      const labels = getGroupAssignRowGroupLabels(row, sec);
      const targets = isGroupAssignRowScopeUnset(row)
        ? ['待选课程班/小组']
        : (labels.length
          ? labels
          : groups.map(g => formatMajorOfferingGroupName(sec.name, g.name)));
      targets.forEach(label => {
        appendGroupAssignRowCompletenessWarnings(bucket, label, row, sec);
      });
    });
    return bucket;
  }
  if (isSectionGroupAssignHoursMerged(sec)) {
    const hourType = GROUP_ASSIGN_MERGED_HOUR_TYPE;
    const typeTotal = getOfferingSectionHoursTotalForAssign(sec);
    const rows = (sec.groupAssignments || []).filter(a => a.hourType === hourType);
    if (!rows.length) {
      // 总学时为 0：可不安排；有学时时必须齐套
      if (typeTotal > 0) {
        groups.forEach(g => {
          const label = formatMajorOfferingGroupName(sec.name, g.name);
          appendOfferingGroupingSaveGroupWarning(bucket, label, `${hourType}尚未安排教师。`);
        });
      }
    } else {
      groups.forEach(g => {
        const label = formatMajorOfferingGroupName(sec.name, g.name);
        if (typeTotal > 0 && !groupHasHourTypeAssignment(sec, g.id, hourType)) {
          appendOfferingGroupingSaveGroupWarning(bucket, label, `${hourType}尚未安排教师。`);
        }
        if (typeTotal > 0) {
          const recorded = sumGroupAssignRecordedHoursForGroupByType(sec, g.id, hourType, '');
          if (recorded < typeTotal) {
            appendOfferingGroupingSaveGroupWarning(bucket, label, `${hourType}已录入学时 ${recorded}/${typeTotal}，尚未录满。`);
          }
          // if (recorded > typeTotal) { ... 已超过计划 } // 原作未完成警告阻断提交，改独立收集后提交时二次确认仍可过
        }
      });
    }
    (sec.groupAssignments || []).forEach(row => {
      if (row.hourType !== hourType) return;
      const labels = getGroupAssignRowGroupLabels(row, sec);
      const targets = isGroupAssignRowScopeUnset(row)
        ? ['待选课程班/小组']
        : (labels.length
          ? labels
          : groups.map(g => formatMajorOfferingGroupName(sec.name, g.name)));
      targets.forEach(label => {
        appendGroupAssignRowCompletenessWarnings(bucket, label, row, sec);
      });
    });
    return bucket;
  }
  getSectionGroupAssignModeHourTypes(sec).forEach(hourType => {
    const typeTotal = getGroupAssignHourTypeTotal(sec, hourType);
    const rows = (sec.groupAssignments || []).filter(a => a.hourType === hourType);
    if (!rows.length) {
      // 计划学时为 0：允许不安排；>0 必须安排
      if (!isOfferingSectionHourTypeRequiredForSubmit(sec, hourType)) return;
      groups.forEach(g => {
        const label = formatMajorOfferingGroupName(sec.name, g.name);
        appendOfferingGroupingSaveGroupWarning(bucket, label, `${hourType}尚未安排教师。`);
      });
      // bucket.courseLevel.push(`${hourType}尚未安排教师。`); // 原课程级提示，改按组列出
      return;
    }
    groups.forEach(g => {
      const label = formatMajorOfferingGroupName(sec.name, g.name);
      if (isOfferingSectionHourTypeRequiredForSubmit(sec, hourType)
          && !groupHasHourTypeAssignment(sec, g.id, hourType)) {
        appendOfferingGroupingSaveGroupWarning(bucket, label, `${hourType}尚未安排教师。`);
      }
      if (typeTotal > 0) {
        const recorded = sumGroupAssignRecordedHoursForGroupByType(sec, g.id, hourType, '');
        if (recorded < typeTotal) {
          appendOfferingGroupingSaveGroupWarning(
            bucket,
            label,
            `${hourType}已录入学时 ${recorded}/${typeTotal}，尚未录满。`
          );
        }
        // if (recorded > typeTotal) { ... 已超过计划 } // 原作未完成警告阻断提交，改独立收集后提交时二次确认仍可过
      }
    });
  });
  (sec.groupAssignments || []).forEach(row => {
    if (!isGroupAssignRowActive(sec, row)) return;
    const labels = getGroupAssignRowGroupLabels(row, sec);
    const targets = isGroupAssignRowScopeUnset(row)
      ? ['待选课程班/小组']
      : (labels.length
        ? labels
        : groups.map(g => formatMajorOfferingGroupName(sec.name, g.name)));
    targets.forEach(label => {
      appendGroupAssignRowCompletenessWarnings(bucket, label, row, sec);
    });
  });
  return bucket;
}

/** 学时超计划：仅二次确认提示，不阻断提交 */
function collectOfferingGroupingOverHourWarnings(sec) {
  const bucket = { byGroup: new Map() };
  const groups = sec?.groups || [];
  sanitizeSectionGroupAssignments(sec);
  // 无小组：与状态面板 `__course__` / saveWarnings 课程班路径对齐，按课程班合计判断超学时
  if (!groups.length) {
    const courseLabel = sec?.name || '课程班';
    if (isSectionGroupAssignHoursMerged(sec)) {
      const hourType = GROUP_ASSIGN_MERGED_HOUR_TYPE;
      const typeTotal = getOfferingSectionHoursTotalForAssign(sec);
      const recorded = sumGroupAssignRecordedHoursByType(sec, hourType, '');
      if (recorded > typeTotal) {
        appendOfferingGroupingSaveGroupWarning(
          bucket,
          courseLabel,
          `${hourType}已录入学时 ${recorded}/${typeTotal}，已超过计划。`
        );
      }
      return bucket;
    }
    getSectionGroupAssignModeHourTypes(sec).forEach(hourType => {
      const typeTotal = getGroupAssignHourTypeTotal(sec, hourType);
      const recorded = sumGroupAssignRecordedHoursByType(sec, hourType, '');
      if (recorded > typeTotal) {
        appendOfferingGroupingSaveGroupWarning(
          bucket,
          courseLabel,
          `${hourType}已录入学时 ${recorded}/${typeTotal}，已超过计划。`
        );
      }
    });
    return bucket;
  }
  if (isSectionGroupAssignHoursMerged(sec)) {
    const hourType = GROUP_ASSIGN_MERGED_HOUR_TYPE;
    const typeTotal = getOfferingSectionHoursTotalForAssign(sec);
    groups.forEach(g => {
      const recorded = sumGroupAssignRecordedHoursForGroupByType(sec, g.id, hourType, '');
      // 计划 0 亦可超学时提醒
      if (recorded > typeTotal) {
        appendOfferingGroupingSaveGroupWarning(
          bucket,
          formatMajorOfferingGroupName(sec.name, g.name),
          `${hourType}已录入学时 ${recorded}/${typeTotal}，已超过计划。`
        );
      }
    });
    return bucket;
  }
  getSectionGroupAssignModeHourTypes(sec).forEach(hourType => {
    const typeTotal = getGroupAssignHourTypeTotal(sec, hourType);
    groups.forEach(g => {
      const recorded = sumGroupAssignRecordedHoursForGroupByType(sec, g.id, hourType, '');
      if (recorded > typeTotal) {
        appendOfferingGroupingSaveGroupWarning(
          bucket,
          formatMajorOfferingGroupName(sec.name, g.name),
          `${hourType}已录入学时 ${recorded}/${typeTotal}，已超过计划。`
        );
      }
    });
  });
  return bucket;
}

function countOfferingGroupingSaveWarnings(bucket) {
  let count = 0;
  bucket.byGroup.forEach(lines => { count += lines.length; });
  return count;
  // let count = bucket.courseLevel.length; // 原含课程级条目
}

function isOfferingGroupingUnderHourWarning(line) {
  return String(line || '').includes('尚未录满');
}

function filterOfferingGroupingWarningBucket(bucket, predicate) {
  const next = { byGroup: new Map() };
  bucket?.byGroup?.forEach((lines, label) => {
    const filtered = (lines || []).filter(predicate);
    if (filtered.length) next.byGroup.set(label, filtered);
  });
  return next;
}

function formatOfferingGroupingWarningBlocks(bucket, sec) {
  const groups = sec?.groups || [];
  const blocks = [];
  groups.forEach(g => {
    const label = formatMajorOfferingGroupName(sec.name, g.name);
    const lines = bucket.byGroup.get(label);
    if (!lines?.length) return;
    blocks.push(`${label}：\n${lines.map(line => `· ${line}`).join('\n')}`);
  });
  bucket.byGroup.forEach((lines, label) => {
    if (!lines.length || groups.some(g => formatMajorOfferingGroupName(sec.name, g.name) === label)) return;
    blocks.push(`${label}：\n${lines.map(line => `· ${line}`).join('\n')}`);
  });
  return blocks;
}

function formatOfferingGroupingSaveWarningHint(bucket, sec) {
  const blocks = formatOfferingGroupingWarningBlocks(bucket, sec);
  // if (bucket.courseLevel.length) {
  //   blocks.push(bucket.courseLevel.map(line => `· ${line}`).join('\n'));
  // } // 原课程级条目优先展示，改先按组再说具体学时类型
  if (!blocks.length) return '保存后将更新分组与教师安排。';
  return [
    '以下分组尚未安排完成，将保存当前进度，可后续继续完善：',
    // '以下分组尚未安排完成，将暂存当前进度，可后续继续完善：', // 原文案用「暂存」
    '',
    ...blocks
  ].join('\n');
  // return `以下分组或学时类型尚未安排完成...`; // 原组与课程级混排
}

function formatMajorOfferingTaskSubmitFailureMessage(bucket, sec) {
  const blocks = formatOfferingGroupingWarningBlocks(bucket, sec);
  if (!blocks.length) return '学时安排尚未完成，无法提交。';
  return `以下分组学时尚未安排完成：\n\n${blocks.join('\n\n')}`;
}

function validateMajorOfferingTaskArrangementSubmit(sec) {
  if (!sec) return { ok: false, message: '未找到开课任务。' };
  ensureSectionOfferingFields(sec);
  const structural = validateOfferingGroupingPageSave(sec);
  if (!structural.ok) {
    return {
      ok: false,
      message: structural.message.replace(/^无法保存，/, '提交失败，')
    };
  }
  const incompleteBucket = collectOfferingGroupingSaveWarnings(sec);
  const fatalBucket = filterOfferingGroupingWarningBucket(
    incompleteBucket,
    line => !isOfferingGroupingUnderHourWarning(line)
  );
  const underHourBucket = filterOfferingGroupingWarningBucket(
    incompleteBucket,
    line => isOfferingGroupingUnderHourWarning(line)
  );
  if (countOfferingGroupingSaveWarnings(fatalBucket) > 0) {
    return {
      ok: false,
      message: formatMajorOfferingTaskSubmitFailureMessage(fatalBucket, sec)
    };
  }
  let underHourWarning = '';
  if (countOfferingGroupingSaveWarnings(underHourBucket) > 0) {
    const blocks = formatOfferingGroupingWarningBlocks(underHourBucket, sec);
    underHourWarning = blocks.join('\n\n');
  }
  const overBucket = collectOfferingGroupingOverHourWarnings(sec);
  let overHourWarning = '';
  if (countOfferingGroupingSaveWarnings(overBucket) > 0) {
    const blocks = [];
    overBucket.byGroup.forEach((lines, label) => {
      if (!lines?.length) return;
      blocks.push(`${label}：\n${lines.map(line => `· ${line}`).join('\n')}`);
    });
    overHourWarning = blocks.join('\n\n');
  }
  return { ok: true, overHourWarning, underHourWarning };
}

function validateMajorOfferingTaskArrangementsSubmit(sections) {
  const failures = [];
  sections.forEach(sec => {
    const result = validateMajorOfferingTaskArrangementSubmit(sec);
    if (result.ok) return;
    const title = [sec.code, sec.name].filter(Boolean).join(' ') || '当前任务';
    failures.push(`${title}：\n${result.message}`);
  });
  if (!failures.length) return { ok: true };
  return {
    ok: false,
    message: `提交失败，请先完善学时安排：\n\n${failures.join('\n\n')}`
  };
}

function validateOfferingGroupingPageSave(sec) {
  const errors = [];
  // const warnings = []; // 原平铺 warnings，改 collectOfferingGroupingSaveWarnings 按组汇总
  if (!sec) {
    return { ok: false, message: '未找到当前课程分段。' };
  }
  const groups = sec.groups || [];
  // 无小组时允许直接按课程班安排教师/学时；提交校验由 collectOfferingGroupingSaveWarnings 处理。
  normalizeOfferingGroupCapacityLimits(sec);
  const nameSet = new Set();
  groups.forEach(g => {
    const name = (g.name || '').trim();
    const label = formatMajorOfferingGroupName(sec.name, name || g.name || '未命名');
    if (!name) errors.push(`${label}：分组名称不能为空。`);
    else if (nameSet.has(name)) errors.push(`分组名称「${name}」重复。`);
    else nameSet.add(name);
    const limit = Number(g.capacityLimit);
    if (!Number.isFinite(limit) || limit <= 0) {
      errors.push(`${label}：请设置有效的人数上限。`);
    }
  });
  validateSectionGroupCapacityTotals(sec).forEach(line => errors.push(line));
  sanitizeSectionGroupAssignments(sec);
  const warningBucket = collectOfferingGroupingSaveWarnings(sec);
  // getOfferingSectionArrangeableHourTypes ... recorded > typeTotal 原作 errors 阻断保存
  // 超计划学时：保存与任务提交均允许，提交时二次确认提示
  // getOfferingSectionArrangeableHourTypes ... warnings 原平铺收集，改 collectOfferingGroupingSaveWarnings 按组汇总
  // (sec.groupAssignments || []).forEach(row => { ... warnings ... });
  if (errors.length) {
    return {
      ok: false,
      message: `无法保存，请先完善以下内容：\n${errors.map(line => `· ${line}`).join('\n')}`
    };
  }
  const overBucket = collectOfferingGroupingOverHourWarnings(sec);
  const hasIncomplete = countOfferingGroupingSaveWarnings(warningBucket) > 0;
  const hasOverHour = countOfferingGroupingSaveWarnings(overBucket) > 0;
  let hint = formatOfferingGroupingSaveWarningHint(warningBucket, sec);
  if (hasOverHour) {
    const overHint = formatOfferingGroupingSaveWarningHint(overBucket, sec);
    hint = [hint, overHint ? `以下学时已超过计划（仍可保存）：\n${overHint.replace(/^学时安排尚未完成[^\n]*\n*/, '')}` : '']
      .filter(Boolean).join('\n\n');
  }
  // const hasIncomplete = warnings.length > 0;
  // const hint = hasIncomplete ? `以下分组或学时类型...` : ...; // 原平铺列表
  return { ok: true, hint, hasIncomplete, hasOverHour };
}

function applyOfferingGroupingPageSave({ hasIncomplete = false, closePage = true, notify = true, stamp = true } = {}) {
  const sec = getOfferingGroupingSection();
  if (!sec) return;
  sanitizeSectionGroupAssignments(sec);
  sec.isGrouped = (sec.groups?.length || 0) > 0;
  syncSectionCoordinatorsFromAssignments(sec);
  syncOfferingGroupStudentCounts(sec);
  invalidateTeacherCourseConfirmationsForSection(sec);
  refreshOfferingGroupingLeaveSnapshot();
  if (stamp) markOfferingGroupingLastSaved();
  if (!closePage) {
    if (notify) {
      const msg = hasIncomplete
        ? '分组与教师安排已保存，请后续继续完善未排完的小组与学时。'
        : '分组与教师安排已保存。';
      alert(msg);
    }
    return;
  }
  renderCourseMajorOfferingTaskPage();
  renderCourseOfferingMajorPage();
  const msg = hasIncomplete
    ? '分组与教师安排已保存，请后续继续完善未排完的小组与学时。'
    : '分组与教师安排已保存。';
  // renderOfferingGroupingPanel(); // 原保存后停留分组页重绘
  // alert(hasIncomplete ? '分组与教师安排已保存，请后续继续完善未排完的小组与学时。' : '分组与教师安排已保存。'); // 原 alert 后仍停留分组页
  performCloseOfferingGroupingPage();
  if (notify) alert(msg);
  // alert(hasIncomplete ? '分组与教师安排已暂存...' : ...); // 原未完成时提示「已暂存」
}

/** 分组/教师安排变更后自动落盘：刷新离开快照；显式「保存」仍走 saveOfferingGroupingPage */
function autosaveOfferingGroupingStructure() {
  if (!offeringGroupingSectionId || offeringGroupingReadOnly) {
    refreshOfferingGroupingLeaveSnapshot();
    return;
  }
  if (isOfferingGroupingStudentRosterMode()) {
    refreshOfferingGroupingLeaveSnapshot();
    return;
  }
  applyOfferingGroupingPageSave({
    closePage: false,
    notify: false,
    stamp: offeringGroupingAutosaveStampReady
  });
}

function saveOfferingGroupingPage() {
  if (!assertOfferingGroupingEditable('保存')) return;
  const sec = getOfferingGroupingSection();
  if (!sec) return;
  const validation = validateOfferingGroupingPageSave(sec);
  if (!validation.ok) {
    alert(validation.message);
    return;
  }
  const title = `${escapeHtml(sec.code || '')} ${escapeHtml(sec.name || '')}`.trim() || '当前课程';
  const incomplete = !!validation.hasIncomplete;
  openDeleteConfirm({
    title: '确认保存',
    message: `确定保存<strong>${title}</strong>的分组与教师安排吗？`,
    hint: validation.hint || '',
    confirmLabel: '保存',
    onConfirm: () => applyOfferingGroupingPageSave({
      hasIncomplete: incomplete,
      closePage: false,
      notify: true
    })
  });
}

function finalizeOfferingGroupingAfterTaskSubmit(submittedSecs) {
  if (!isOfferingGroupingPageActive()) return;
  const currentId = offeringGroupingSectionId;
  if (!currentId || !(submittedSecs || []).some(s => s.id === currentId)) return;
  const sec = getOfferingGroupingSection();
  offeringGroupingReadOnly = isMajorOfferingSectionStructureLocked(sec);
  // offeringGroupingLeaveSnapshot = null;
  // performCloseOfferingGroupingPage(); // 原提交后返回列表，改停留本页并切只读
  updateOfferingGroupingPageTitle(sec);
  syncOfferingGroupingBreadcrumb();
  syncOfferingGroupingHeaderActions();
  renderOfferingGroupingPanel();
  refreshOfferingGroupingLeaveSnapshot();
}

function syncOfferingGroupingRosterSaveState({ refreshSnapshot = false } = {}) {
  const sec = getOfferingGroupingSection();
  const sectionId = offeringGroupingSectionId;
  if (!sec || !sectionId) return false;
  getMajorOfferingStudentRoster(sectionId);
  syncOfferingGroupStudentCounts(sec);
  syncSectionEstimatedStudentsFromRoster(sectionId);
  sec.rosterScheduleStatus = 'draft';
  persistMajorOfferingStudentRosterStore();
  if (refreshSnapshot) refreshOfferingGroupingLeaveSnapshot();
  return true;
}

function applyOfferingGroupingRosterSave() {
  const sec = getOfferingGroupingSection();
  if (!syncOfferingGroupingRosterSaveState({ refreshSnapshot: true })) return;
  if (offeringGroupingOpenedAsPopup) {
    syncOfferingGroupingPopupBackToOpener({ includeRoster: true });
  }
  if (isOfferingGroupingStudentRosterMode(sec)) {
    performCloseOfferingGroupingPage({ syncRoster: true });
    alert('学生名单已保存。');
    return;
  }
  // if (isOfferingGroupingRosterContext()) { ... } // 原仅名单管理入口保存后返回
  refreshOfferingGroupingPanelsIfOpen();
  renderCourseMajorOfferingRosterPage();
  alert('学生名单已保存。');
}

function saveOfferingGroupingRosterPage() {
  if (!assertOfferingGroupingStudentEditable('保存名单')) return;
  if (!ensureOfferingGroupingStudentOpsContext()) return;
  const sec = getOfferingGroupingSection();
  if (!sec) return;
  const capacityIssues = validateOfferingGroupingRosterGroupCapacities(sec, offeringGroupingSectionId);
  if (capacityIssues.length) {
    openOfferingGroupCapacityAlert(capacityIssues.join('\n'));
    return;
  }
  const title = `${escapeHtml(sec.code || '')} ${escapeHtml(sec.name || '')}`.trim() || '当前课程';
  openDeleteConfirm({
    title: '确认保存',
    message: `确定保存<strong>${title}</strong>的学生名单吗？`,
    hint: '保存后名单状态仍为草稿，可在「专业开课学生名单管理」中继续维护或提交排课。',
    confirmLabel: '保存',
    onConfirm: () => applyOfferingGroupingRosterSave()
  });
}

function validateOfferingGroupingRosterGroupCapacities(sec, sectionId = sec?.id) {
  if (!sec?.groups?.length) return [];
  const issues = [];
  sec.groups.forEach(group => {
    const limit = getOfferingGroupCapacityLimitValue(group);
    if (limit === Infinity) return;
    const current = countOfferingGroupRosterStudents(group, sec, sectionId);
    if (current > limit) {
      const label = formatMajorOfferingGroupName(sec.name, group.name);
      const capLabel = formatOfferingGroupCapacityLimit(group) || `≤${limit}人`;
      issues.push(`分组「${label}」${capLabel}，当前已有 ${current} 人，超出人数上限。`);
    }
  });
  return issues;
}

function updateOfferingGroupingPageTitle(sec) {
  const el = document.getElementById('offering-grouping-page-title');
  if (!el) return;
  if (!sec) {
    el.textContent = isOfferingGroupingStudentRosterMode() || isOfferingGroupingManifestViewContext()
      ? '管理名单'
      : '分组';
    updateOfferingGroupingGeQuotaHint(null);
    return;
  }
  const courseLabel = `${sec.code || '—'} ${sec.name || ''}`.trim();
  if (isOfferingGroupingStudentRosterMode(sec) || isOfferingGroupingManifestViewContext()) {
    el.textContent = `管理名单 · ${courseLabel}`;
  } else {
    el.textContent = `分组 · ${courseLabel}`;
  }
  updateOfferingGroupingGeQuotaHint(sec);
}

function updateOfferingGroupingGeQuotaHint(sec) {
  const el = document.getElementById('offering-grouping-ge-quota-hint');
  if (!el) return;
  const isGe = sec?.offeringType === 'ge'
    || offeringGroupingReturnPage === 'course-offering-ge'
    || offeringGroupingReturnPage === 'course-ge-offering-task'
    || offeringGroupingReturnPage === 'course-ge-offering-roster';
  if (!isGe || !sec) {
    el.hidden = true;
    el.innerHTML = '';
    el.classList.remove('is-met', 'is-short');
    return;
  }
  ensureGeOfferingSectionFields(sec);
  const termCode = sec.termCode
    || COURSE_OFFERING_PLAN_STORE?.termCode
    || getGeOfferingViewTermCode()
    || getDefaultOfferingTermCode();
  const unit = resolveGeOfferingSectionOfferingUnit(sec);
  const courseGroups = getGeOfferingSectionPlannedGroupCount(sec);
  const groupLen = Array.isArray(sec.groups) ? sec.groups.length : 0;
  if (!termCode || !unit) {
    el.hidden = false;
    el.classList.remove('is-met', 'is-short');
    el.innerHTML = `<span class="text-muted">本课当前 ${courseGroups || groupLen || 0} 组；开课单位或学期未齐，暂无法对照 AC 保底下限。</span>`;
    return;
  }
  ensureGeOfferingQuota(termCode);
  const progress = getGeOfferingQuotaProgressRows(termCode).find(r => r.schoolCode === unit);
  if (!progress) {
    el.hidden = false;
    el.classList.remove('is-met', 'is-short');
    el.innerHTML = `<span>本课当前 <strong>${courseGroups}</strong> 组（${escapeHtml(unit)}）</span>`
      + '<span class="text-muted"> · 该学院尚未维护 AC 保底下限</span>';
    return;
  }
  const statusHtml = progress.met
    ? (progress.actualGroups > progress.minGroups
      ? '<span class="offering-status-pill is-on">已达标（超额）</span>'
      : '<span class="offering-status-pill is-on">已达标</span>')
    : `<span class="offering-status-pill is-off">差 ${progress.shortfall} 组</span>`;
  el.hidden = false;
  el.classList.toggle('is-met', !!progress.met);
  el.classList.toggle('is-short', !progress.met);
  el.innerHTML = `<span>本课当前 <strong>${courseGroups}</strong> 组</span>`
    + `<span class="offering-grouping-ge-quota-sep">·</span>`
    + `<span>${escapeHtml(unit)} 学院已开 <strong>${progress.actualGroups}</strong> / AC 保底 <strong>${progress.minGroups}</strong></span>`
    + `<span class="offering-grouping-ge-quota-sep">·</span>`
    + statusHtml
    + (progress.met
      ? ''
      : '<span class="text-muted">（提交前须达到 AC 设定的目标下限）</span>');
}

function isOfferingGroupingPageActive() {
  return document.getElementById('page-offering-grouping')?.classList.contains('active');
}

function getOfferingGroupingBodyEl() {
  return document.querySelector('#page-offering-grouping .offering-grouping-body');
}

function getOfferingGroupingShellEl() {
  return document.querySelector('#page-offering-grouping .offering-grouping-shell');
}

function getOfferingGroupingSection() {
  return COURSE_OFFERING_PLAN_STORE?.sections.find(s => s.id === offeringGroupingSectionId);
}

function getOfferingGroupingSelectedGroup(sec = getOfferingGroupingSection()) {
  if (!sec?.groups?.length || !offeringGroupingSelectedGroupId) return null;
  return sec.groups.find(g => g.id === offeringGroupingSelectedGroupId) || null;
}

function studentMatchesOfferingGroup(stu, group, sec) {
  if (!stu || !group || !sec) return false;
  const fullName = formatMajorOfferingGroupName(sec.name, group.name);
  return getStudentGroupNames(stu).some(name =>
    name === group.name
    || name === fullName
    || formatStudentCourseGroupLabel(sec.name, name) === fullName
  );
}

function ensureOfferingGroupingGroupSelection(sec = getOfferingGroupingSection()) {
  if (!sec?.groups?.length) {
    offeringGroupingSelectedGroupId = null;
    return;
  }
  if (offeringGroupingSelectedGroupId && !sec.groups.some(g => g.id === offeringGroupingSelectedGroupId)) {
    offeringGroupingSelectedGroupId = sec.groups[0]?.id || null;
  }
  // if (!offeringGroupingSelectedGroupId || !sec.groups.some(...)) offeringGroupingSelectedGroupId = sec.groups[0].id; // 原 null 时强制选中首组，改允许选中课程根节点
}

function selectOfferingCourseRoot() {
  if (!isOfferingGroupingStudentRosterMode()) return;
  if (!offeringGroupingSelectedGroupId) return;
  offeringGroupingSelectedGroupId = null;
  offeringGroupingStudentSelected.clear();
  offeringGroupingAssignSelected.clear();
  resetListPage('offeringGroupingStudent');
  renderOfferingGroupingPanel();
}

function toggleOfferingGroupTreeExpand(ev) {
  ev?.stopPropagation?.();
  ev?.preventDefault?.();
  offeringGroupTreeExpanded = !offeringGroupTreeExpanded;
  const branch = document.querySelector('#offering-group-tree .group-tree-branch');
  if (!branch) return;
  branch.classList.toggle('is-expanded', offeringGroupTreeExpanded);
  branch.classList.toggle('is-collapsed', !offeringGroupTreeExpanded);
  const children = branch.querySelector('.group-tree-children');
  if (children) children.toggleAttribute('hidden', !offeringGroupTreeExpanded);
  const btn = branch.querySelector('.group-tree-toggle');
  if (btn) {
    btn.setAttribute('aria-expanded', offeringGroupTreeExpanded ? 'true' : 'false');
    btn.setAttribute('aria-label', offeringGroupTreeExpanded ? '收起分组' : '展开分组');
  }
}

function toggleOfferingGroupSidebar() {
  offeringGroupSidebarCollapsed = !offeringGroupSidebarCollapsed;
  const layout = document.getElementById('offering-grouping-layout');
  const btn = document.getElementById('offering-group-sidebar-toggle');
  const sidebar = document.getElementById('offering-group-sidebar');
  if (layout) {
    layout.classList.add('is-sidebar-animating');
    layout.classList.toggle('is-sidebar-collapsed', offeringGroupSidebarCollapsed);
    window.setTimeout(() => layout.classList.remove('is-sidebar-animating'), 400);
  }
  if (btn) {
    btn.setAttribute('aria-expanded', offeringGroupSidebarCollapsed ? 'false' : 'true');
    btn.setAttribute('aria-label', offeringGroupSidebarCollapsed ? '展开分组信息' : '收起分组信息');
  }
  sidebar?.setAttribute('aria-hidden', offeringGroupSidebarCollapsed ? 'true' : 'false');
}

function syncOfferingGroupSidebarCollapseState() {
  const layout = document.getElementById('offering-grouping-layout');
  const btn = document.getElementById('offering-group-sidebar-toggle');
  const sidebar = document.getElementById('offering-group-sidebar');
  layout?.classList.toggle('is-sidebar-collapsed', offeringGroupSidebarCollapsed);
  if (btn) {
    btn.setAttribute('aria-expanded', offeringGroupSidebarCollapsed ? 'false' : 'true');
    btn.setAttribute('aria-label', offeringGroupSidebarCollapsed ? '展开分组信息' : '收起分组信息');
  }
  sidebar?.setAttribute('aria-hidden', offeringGroupSidebarCollapsed ? 'true' : 'false');
}

function selectOfferingGroup(groupId) {
  if (!isOfferingGroupingStudentRosterMode()) return;
  if (offeringGroupingSelectedGroupId === groupId) return;
  offeringGroupingSelectedGroupId = groupId;
  offeringGroupingStudentSelected.clear();
  offeringGroupingAssignSelected.clear();
  resetListPage('offeringGroupingStudent');
  renderOfferingGroupingPanel();
}

function isOfferingGroupingStudentTabEnabled() {
  const sec = getOfferingGroupingSection();
  if (isOfferingGroupingManifestViewContext()) {
    return isMajorOfferingTaskArrangementSubmitted(sec);
  }
  // if (isOfferingGroupingManifestViewContext() || isOfferingGroupingGeRosterViewContext()) { ... } // 原 GE 单独分支，改纳入 rosterContext
  return isOfferingGroupingStudentRosterMode(sec);
  // return offeringGroupingReturnPage === 'course-major-offering-roster'; // 原仅名单管理入口
}

function syncOfferingGroupingTabVisibility() {
  const sec = getOfferingGroupingSection();
  const studentTabEnabled = isOfferingGroupingStudentTabEnabled();
  if (!studentTabEnabled && offeringGroupingActiveTab === 'student') {
    offeringGroupingActiveTab = 'group-status';
  }
  offeringGroupingActiveTab = normalizeOfferingGroupingTab(offeringGroupingActiveTab);
  document.querySelectorAll('.offering-group-tab').forEach(el => {
    const tab = el.dataset.tab;
    if (tab === 'student') {
      el.toggleAttribute('hidden', !studentTabEnabled);
    }
    // 名单模式也可查看「课程班/小组学时详情」（只读）；summary 仍随既有展示规则
    el.classList.toggle('is-active', tab === offeringGroupingActiveTab);
    el.classList.toggle('is-muted', tab !== offeringGroupingActiveTab);
  });
  document.getElementById('offering-group-teacher-panel')?.toggleAttribute('hidden', true); // 原「安排总览」面板已下线
  document.getElementById('offering-group-student-panel')?.toggleAttribute('hidden', offeringGroupingActiveTab !== 'student');
  document.getElementById('offering-group-hour-summary-panel')?.toggleAttribute('hidden', offeringGroupingActiveTab !== 'summary');
  document.getElementById('offering-group-group-status-panel')?.toggleAttribute('hidden', offeringGroupingActiveTab !== 'group-status');
  // Coordinator 仅「课程班/小组学时详情」可见；全选/删除随「安排总览」一并下线
  document.getElementById('offering-group-assign-toolbar')
    ?.toggleAttribute('hidden', offeringGroupingActiveTab !== 'group-status');
  document.getElementById('ogg-btn-set-coordinator')?.toggleAttribute('hidden', offeringGroupingActiveTab !== 'group-status');
  document.getElementById('ogg-btn-revoke-assign')?.toggleAttribute('hidden', true);
  document.getElementById('oga-check-all-wrap')?.toggleAttribute('hidden', true);
}

function renderActiveOfferingGroupingTabPanel() {
  if (offeringGroupingActiveTab === 'student') renderOfferingGroupingStudentPanel();
  else if (offeringGroupingActiveTab === 'summary') renderOfferingGroupingHourSummaryPanel();
  else renderOfferingGroupingGroupStatusPanel();
}

function switchOfferingGroupingTab(tab) {
  if (tab === 'student' && !isOfferingGroupingStudentTabEnabled()) return;
  // offeringGroupingActiveTab = tab === 'student' ? 'student' : 'teacher'; // 原仅教师/学生两 Tab
  offeringGroupingActiveTab = normalizeOfferingGroupingTab(tab);
  // offeringGroupingActiveTab = ['student', 'summary'].includes(tab) ? tab : 'teacher'; // 原不含小组学时 Tab
  syncOfferingGroupingTabVisibility();
  renderActiveOfferingGroupingTabPanel();
  syncOfferingGroupingReadOnly();
  document.querySelector('#offering-group-teacher-panel thead .col-check')?.toggleAttribute('hidden', offeringGroupingReadOnly);
  document.querySelector('#offering-group-teacher-panel thead .col-sticky-actions')?.toggleAttribute('hidden', offeringGroupingReadOnly);
  document.querySelector('#offering-group-student-panel thead .col-check')?.toggleAttribute('hidden', !isOfferingGroupingStudentEditable());
  // renderOfferingGroupingPanel(); // 原全量重绘三 Tab，切换时易拖影
}

function refreshOfferingGroupingPanelsIfOpen() {
  if (!offeringGroupingSectionId) return;
  if (!isOfferingGroupingPageActive()) return;
  renderOfferingGroupingPanel();
  // if (!document.getElementById('modal-offering-grouping')?.classList.contains('open')) return; // 原弹窗检测
}

function ensureOfferingGroupingStudentOpsContext() {
  if (!offeringGroupingSectionId) return false;
  majorOfferingStudentRosterSectionId = offeringGroupingSectionId;
  return true;
}

/** 是否已分入该开课任务下的某个真实小组（不含仅在课程班） */
function isStudentAssignedToAnyOfferingGroup(stu, sec) {
  return (sec?.groups || []).some(g => studentMatchesOfferingGroup(stu, g, sec));
}

function getFilteredOfferingGroupingStudents() {
  const sec = getOfferingGroupingSection();
  const group = getOfferingGroupingSelectedGroup(sec);
  if (!sec) return [];
  const roster = getMajorOfferingStudentRoster(offeringGroupingSectionId);
  const hasGroups = !!(sec.groups || []).length;
  const isCourseRootSelected = hasGroups && !group && isOfferingGroupingStudentRosterMode(sec);
  const isCourseClassView = !hasGroups || isCourseRootSelected;
  const nameQ = (document.getElementById('ogg-filter-name')?.value || '').trim().toLowerCase();
  const studentNoQ = (document.getElementById('ogg-filter-student-no')?.value || '').trim().toLowerCase();
  const genderQ = document.getElementById('ogg-filter-gender')?.value || '';
  return roster.filter(stu => {
    // 课程班视角：名单含全部学生（含已入组）；小组视角：仅该组
    // // 原课程班视角排除已入组学生，导致全部入组后显示「该课程班暂无学生」
    if (!isCourseClassView && (!group || !studentMatchesOfferingGroup(stu, group, sec))) {
      return false;
    }
    if (genderQ && getStudentGender(stu) !== genderQ) return false;
    if (studentNoQ && !stu.studentNo.toLowerCase().includes(studentNoQ)) return false;
    if (nameQ && !stu.name.toLowerCase().includes(nameQ)) return false;
    return true;
  });
}

