function renderGroupAssignExistingAssignments() {
  const sec = getOfferingGroupingSection();
  const tbody = document.getElementById('group-assign-existing-assign-body');
  if (!tbody || !sec) return;
  sanitizeSectionGroupAssignments(sec);
  const editId = document.getElementById('group-assign-edit-id')?.value || '';
  const entries = [];
  filterActiveGroupAssignments(sec, sec.groupAssignments).forEach(row => {
    const teachers = getGroupAssignTeachers(row);
    const week = clampGroupAssignWeekRangeToSection(sec, row.weekRange) || row.weekRange || '—';
    const groups = formatGroupAssignGroupsLabel(row, sec) || '—';
    const hourType = getGroupAssignHourTypeDisplayLabel(sec, row.hourType) || row.hourType || '—';
    const weekly = formatGroupAssignWeeklyHoursDisplay(row);
    const totalHours = formatGroupAssignRowTotalHoursDisplay(row, sec);
    const simultaneous = formatGroupAssignSimultaneousGroupsDisplay(row);
    const editing = !!(editId && row.id === editId);
    const teacherList = teachers.length ? teachers : [{ name: '—', staffId: '' }];
    teacherList.forEach(t => {
      entries.push({
        teacherName: t.name || t.staffId || '—',
        staffId: t.staffId || '',
        groups,
        week,
        weekly,
        totalHours,
        hourType,
        simultaneous,
        editing,
        assignId: row.id
      });
    });
  });
  entries.sort((a, b) => {
    const byName = String(a.teacherName).localeCompare(String(b.teacherName), 'zh');
    if (byName) return byName;
    return String(a.week).localeCompare(String(b.week));
  });
  tbody.innerHTML = entries.length
    ? entries.map((entry, idx) => `<tr class="${entry.editing ? 'is-editing' : ''}"${entry.editing ? ' title="当前正在编辑这条安排"' : ''}>
          <td class="col-index col-center">${idx + 1}</td>
          <td title="${escapeHtml(entry.teacherName)}">${escapeHtml(entry.teacherName)}</td>
          <td title="${escapeHtml(entry.groups)}">${escapeHtml(entry.groups)}</td>
          <td class="col-center"><code>${escapeHtml(entry.week)}</code></td>
          <td class="col-center">${escapeHtml(entry.weekly)}</td>
          <td class="col-center">${escapeHtml(entry.totalHours)}</td>
          <td class="col-center">${escapeHtml(entry.hourType)}</td>
          <td class="col-center">${escapeHtml(entry.simultaneous)}</td>
        </tr>`).join('')
    : '<tr><td colspan="8" class="text-muted" style="text-align:center;padding:12px">暂无已保存的教师学时安排</td></tr>';
}

function isGroupAssignFormGroupPicksLocked() {
  return groupAssignFormTeachers.length > 0;
}

function syncGroupAssignGroupPicksLockState() {
  const locked = isGroupAssignFormGroupPicksLocked();
  const wrap = document.getElementById('group-assign-groups-wrap');
  const hint = document.getElementById('group-assign-groups-hint');
  const tableWrap = document.querySelector('#group-assign-group-picks .group-assign-group-picks-table-wrap');
  wrap?.classList.toggle('is-group-picks-locked', locked);
  tableWrap?.classList.toggle('is-group-picks-locked', locked);
  document.querySelectorAll('.group-assign-group-check, #group-assign-groups-check-all').forEach(el => {
    el.disabled = locked;
  });
  if (hint) {
    hint.textContent = locked
      ? '已安排教师后不可改选小组；请先移除全部授课教师后再调整'
      : '可多选合班；未分组时按课程整体安排';
  }
}

function compareOfferingTermCodes(a, b) {
  return String(a || '').localeCompare(String(b || ''));
}

function getMostRecentPriorOfferingTermCode(currentTermCode) {
  const cur = String(currentTermCode || '');
  const terms = [...new Set([
    ...(COURSE_TIME_SETTINGS || []).map(r => r.termCode),
    ...Object.keys(COURSE_OFFERING_PLAN_BY_TERM || {})
  ])].filter(Boolean).sort(compareOfferingTermCodes);
  const earlier = terms.filter(t => compareOfferingTermCodes(t, cur) < 0);
  return earlier.length ? earlier[earlier.length - 1] : '';
}

function collectCourseAssignTeachersFromStore(store, courseCode) {
  const map = new Map();
  (store?.sections || []).forEach(sec => {
    if ((sec.code || '') !== courseCode) return;
    (sec.groupAssignments || []).forEach(row => {
      getGroupAssignTeachers(row).forEach(t => {
        const staffId = String(t.staffId || '').trim();
        const name = String(t.name || '').trim();
        if (!staffId && !name) return;
        const key = staffId || name;
        if (!map.has(key)) {
          map.set(key, {
            staffId,
            name: name || '—',
            teacherType: t.teacherType || '',
            departmentCode: t.departmentCode || '',
            hourTypes: new Set(),
            courseHours: 0
          });
        }
        const entry = map.get(key);
        if (row.hourType) entry.hourTypes.add(row.hourType);
        if (!entry.teacherType && t.teacherType) entry.teacherType = t.teacherType;
        if (!entry.departmentCode && t.departmentCode) entry.departmentCode = t.departmentCode;
        if (staffId && !(typeof isGroupAssignRowScopeUnset === 'function' && isGroupAssignRowScopeUnset(row))) {
          entry.courseHours += getGroupAssignRowTeacherShareHours(row, sec);
        }
      });
    });
  });
  return [...map.values()].map(row => ({
    staffId: row.staffId,
    name: row.name,
    teacherType: row.teacherType,
    departmentCode: row.departmentCode,
    hourTypes: [...row.hourTypes],
    courseHours: row.courseHours
  }));
}

function buildMockPriorTermTeachersForCourse(courseCode, priorTermCode, sec) {
  const pool = buildMockTeacherPickerPool();
  if (!pool.length || !priorTermCode) return [];
  const hash = [...String(courseCode || 'X')].reduce((n, ch) => n + ch.charCodeAt(0), 0);
  const offeringUnit = resolveSectionOfferingUnitForTeacherPicker(sec);
  const homePool = offeringUnit
    ? pool.filter(t => t.departmentCode === offeringUnit)
    : pool.slice();
  const otherPool = offeringUnit
    ? pool.filter(t => t.departmentCode && t.departmentCode !== offeringUnit)
    : [];
  const pickFrom = (list, count, seed) => {
    if (!list.length || count <= 0) return [];
    const out = [];
    const seen = new Set();
    for (let i = 0; i < list.length && out.length < count; i += 1) {
      const t = list[(seed + i * 3) % list.length];
      if (!t || seen.has(t.staffId)) continue;
      seen.add(t.staffId);
      out.push(t);
    }
    return out;
  };
  // 多数本学院 + 少量表外院（示意往期跨院任课）
  const homeCount = Math.min(3, Math.max(2, homePool.length ? 2 + (hash % 2) : 0));
  const selected = [
    ...pickFrom(homePool.length ? homePool : pool, homeCount, hash),
    ...pickFrom(otherPool, otherPool.length ? 1 : 0, hash + 17)
  ].filter((t, idx, arr) => arr.findIndex(x => x.staffId === t.staffId) === idx);
  return selected.map((t, i) => {
    const courseHours = 28 + ((hash + i * 11) % 21);
    const totalHours = courseHours + 24 + ((hash + i * 7) % 48);
    return {
      staffId: t.staffId,
      name: t.name,
      teacherType: t.teacherType || '',
      departmentCode: t.departmentCode || '',
      hourTypes: [],
      courseHours,
      totalHours
    };
  });
}

/** 上学期参考教师是否可选：须在教师库，且所属单位为本开课单位或已申请 Support 学院 */
function canSelectGroupAssignPriorTeacher(sec, teacher) {
  if (!teacher?.staffId) return false;
  const pick = buildMockTeacherPickerPool().find(t => t.staffId === teacher.staffId);
  if (!pick) return false;
  const allowed = getGroupAssignTeacherPickerAllowedUnits();
  if (!allowed.length) return true;
  const dept = teacher.departmentCode || pick.departmentCode || '';
  return allowed.includes(dept);
}

function isGroupAssignPriorTeacherExternal(sec, teacher) {
  const offeringUnit = resolveSectionOfferingUnitForTeacherPicker(sec);
  const dept = teacher?.departmentCode || '';
  return !!(offeringUnit && dept && dept !== offeringUnit);
}

/** 取该课程最近一次往期开课的任课教师（优先真实 store，原型无数据时回落示意） */
function getGroupAssignPriorTermTeachers(sec) {
  const courseCode = sec?.code || '';
  const currentTerm = COURSE_OFFERING_PLAN_STORE?.termCode || getDefaultOfferingTermCode() || '';
  if (!courseCode || !currentTerm) return { termCode: '', teachers: [] };

  let bestTerm = '';
  let bestTeachers = [];
  Object.entries(COURSE_OFFERING_PLAN_BY_TERM || {}).forEach(([termCode, store]) => {
    if (compareOfferingTermCodes(termCode, currentTerm) >= 0) return;
    const teachers = collectCourseAssignTeachersFromStore(store, courseCode);
    if (!teachers.length) return;
    if (!bestTerm || compareOfferingTermCodes(termCode, bestTerm) > 0) {
      bestTerm = termCode;
      bestTeachers = teachers;
    }
  });
  if (bestTeachers.length) {
    const offeringUnit = resolveSectionOfferingUnitForTeacherPicker(sec);
    const enriched = bestTeachers.map(t => ({
      ...t,
      totalHours: t.staffId
        ? sumTeacherOfferingTeachingLoadHours(t.staffId, bestTerm)
        : (Number(t.courseHours) || 0)
    }));
    // 本学院在前，外院在后
    enriched.sort((a, b) => {
      const aHome = offeringUnit && a.departmentCode === offeringUnit ? 0 : 1;
      const bHome = offeringUnit && b.departmentCode === offeringUnit ? 0 : 1;
      return aHome - bHome || String(a.name || '').localeCompare(String(b.name || ''), 'zh');
    });
    return { termCode: bestTerm, teachers: enriched, source: 'store' };
  }

  const priorTerm = getMostRecentPriorOfferingTermCode(currentTerm);
  const mockTeachers = buildMockPriorTermTeachersForCourse(courseCode, priorTerm, sec);
  return { termCode: priorTerm, teachers: mockTeachers, source: mockTeachers.length ? 'mock' : '' };
}

function isGroupAssignPriorTeacherSelectedInPicker(staffId) {
  if (!staffId) return false;
  const pick = buildMockTeacherPickerPool().find(t => t.staffId === staffId);
  if (pick && majorOfferingTeacherPickerSelected.has(pick.key)) return true;
  for (const key of majorOfferingTeacherPickerSelected) {
    if (key === staffId || String(key).startsWith(`${staffId}|`)) return true;
  }
  return false;
}

function syncGroupAssignPriorTeacherChipSelection() {
  if (teacherPickerContext !== 'groupAssign') return;
  const sec = getOfferingGroupingSection();
  document.querySelectorAll('#group-assign-prior-teachers-list .group-assign-prior-teacher-card[data-staff-id]').forEach(card => {
    const staffId = card.getAttribute('data-staff-id') || '';
    const selected = isGroupAssignPriorTeacherSelectedInPicker(staffId);
    const canPick = card.dataset.canPick === '1';
    card.classList.toggle('is-selected', selected && canPick);
    const check = card.querySelector('.group-assign-prior-teacher-check');
    if (check) {
      check.checked = selected && canPick;
      check.indeterminate = false;
    }
    if (!canPick) return;
    card.title = selected ? '点击取消勾选（同步取消下方列表）' : '点击勾选（同步勾选下方列表）';
  });
}

