  //   // if (savePageBtn) savePageBtn.disabled = structureLocked; // 原不可用时置灰，改不可用时隐藏
  // }
  // if (saveRosterBtn) saveRosterBtn.hidden = !canSaveRoster;
  // if (adjustBtn) adjustBtn.disabled = locked; // 原与学生操作同锁，改名单管理模式下可维护学生
