function syncSidebarNavActive(pageId) {
  let navPage = pageId;
  if (pageId === 'offering-grouping') {
    navPage = offeringGroupingReturnPage || 'course-major-offering-task-style2';
    if (navPage === 'course-major-offering-task') navPage = 'course-major-offering-task-style2';
  }
  if (navPage === 'course-ge-offering-task') navPage = 'course-offering-ge'; // 旧任务入口高亮合页菜单
  if (navPage === 'course-ge-offering-demand') navPage = 'course-ge-offering-quota'; // 旧需求入口高亮配额合页
  if (pageId === 'schedule-time-detail' || pageId === 'schedule-room-detail') {
    const ctx = scheduleBatchDetailContext;
    const phase = ctx?.phase || (pageId === 'schedule-room-detail' ? 'room' : 'time');
    navPage = getScheduleDetailListPageId(phase, getScheduleScopeType(ctx));
  }
  document.querySelectorAll('.nav-item').forEach(n => {
    n.classList.toggle('active', n.dataset.page === navPage);
  });
  expandSidebarNavSectionForPage(navPage);
}

function toggleSidebarNavSection(titleEl) {
  const section = titleEl?.closest?.('.nav-section');
  if (!section) return;
  const collapsed = section.classList.toggle('is-collapsed');
  titleEl.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
}

function expandSidebarNavSectionForPage(navPage) {
  if (!navPage) return;
  const activeItem = document.querySelector(`.nav-item[data-page="${CSS.escape(navPage)}"].active`)
    || document.querySelector(`.nav-item[data-page="${CSS.escape(navPage)}"]`);
  const section = activeItem?.closest?.('.nav-section');
  if (!section) return;
  section.classList.remove('is-collapsed');
  const titleEl = section.querySelector('.nav-section-title');
  if (titleEl) titleEl.setAttribute('aria-expanded', 'true');
}

let activeModule = 'curriculum';
let portalActiveTab = 'all';

function getPageModule(pageId) {
  if (COURSE_PAGE_IDS.has(pageId)) return 'course';
  if (SCHEDULE_PAGE_IDS.has(pageId)) return 'schedule';
  if (pageId === 'portal') return null;
  return 'curriculum';
}

function setActiveModule(moduleId) {
  if (!MODULES[moduleId]) return;
  activeModule = moduleId;
  const cfg = MODULES[moduleId];
  const titleEl = document.getElementById('sidebar-brand-title');
  const subEl = document.getElementById('sidebar-brand-sub');
  if (titleEl) titleEl.textContent = cfg.titleZh;
  if (subEl) subEl.textContent = cfg.titleEn;
  const navCurriculum = document.getElementById('sidebar-nav-curriculum');
  const navCourse = document.getElementById('sidebar-nav-course');
  const navSchedule = document.getElementById('sidebar-nav-schedule');
  if (navCurriculum) navCurriculum.hidden = moduleId !== 'curriculum';
  if (navCourse) navCourse.hidden = moduleId !== 'course';
  if (navSchedule) navSchedule.hidden = moduleId !== 'schedule';
}

